# API Server Script `arinox_engine`: the production ledger and its flow rules, in one place, for a site that cannot import code.
# Document scripts call it with run_script("arinox_engine", action=..., ...). The app's reference implementation is
# production/ledger.py + production/flow.py; the same tests are the specification.
#
# actions:  post   card, rows (JSON), source_doctype, source_name, posting_date, override (0/1), check (0/1)
#           unpost source_doctype, source_name
#           total  card, stage, colour, size, purpose        -> frappe.flags.arinox_total
#           check  card, rows (JSON), override                -> raises if a row exceeds its limit
#           bulk_gate sales_order, style, colour, stage ("pilot" or "bulk")  -> arinox_result {applies, style, colour, blockers, warnings}
#                  (production/gate.py: buyer approvals, PP meeting, materials, and for "bulk" the pilot run)
# Everything sits inside main(): in the sandbox module-level functions cannot see each other.

def main():
    form = frappe.form_dict
    action = form.get("action")
    STAGES = ("CUT", "CUT_REJECT", "SEW_IN", "SEW_OUT", "SEW_REJECT", "SC_OUT", "SC_BACK_GOOD", "SC_BACK_REJECT_VENDOR",
              "SC_BACK_REJECT_FACTORY", "FIN_IN", "FIN_A", "FIN_B", "FIN_REJECT", "SAMPLE_OUT", "PACKED", "SHIPPED")
    REJECT_STAGES = ("CUT_REJECT", "SEW_REJECT", "SC_BACK_REJECT_VENDOR", "SC_BACK_REJECT_FACTORY", "FIN_REJECT")
    CUT_PURPOSES = ("Bulk", "Pilot", "Sample")
    STATUS_BY_STAGE = (("SHIPPED", "Shipped"), ("PACKED", "Packed"), ("FIN_IN", "In Finishing"), ("SC_OUT", "At Subcontractor"),
                       ("SEW_IN", "In Sewing"), ("CUT", "In Cutting"))

    def num(n):
        if float(n) == int(n):
            return str(int(n))
        return str(round(n, 2))

    def sval(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        if v is None or v == "":
            return default
        return v

    def repair_accepted(card, colour, size):
        r = frappe.db.sql(
            "select ifnull(sum(r.accepted_for_repair), 0) from `tabSubcontract Return Row` r "
            "join `tabSubcontract Return` p on p.name = r.parent "
            "where p.docstatus = 1 and r.production_card = %s and r.colour = %s and r.size = %s", (card, colour, size))
        return r[0][0] or 0

    def make_flow(card):
        """Totals of one card, loaded once; limit() and apply() answer and absorb rows so a document's rows count together."""
        doc = frappe.get_doc("Production Card", card)
        T = {}
        for r in frappe.db.sql(
                "select colour, size, stage, ifnull(purpose, ''), ifnull(subcontract_process, ''), sum(qty) from `tabProduction Movement` "
                "where production_card = %s group by colour, size, stage, purpose, subcontract_process", card):
            T[r[0], r[1], r[2], r[3], r[4]] = r[5] or 0
        lines = {}
        for l in doc.lines:
            lines[l.colour, l.size] = l
        route = sorted(doc.processes, key=lambda p: (0 if p.position == "Before Sewing" else 1, int(p.sequence or 0), p.idx))

        def t(colour, size, stage, purpose=None, process=None):
            total = 0
            for k in T:
                if k[0] == colour and k[1] == size and k[2] == stage:
                    if (purpose is None or k[3] == purpose) and (process is None or k[4] == process):
                        total = total + T[k]
            return total

        def apply(row):
            k = (row["colour"], row["size"], row["stage"], row.get("purpose") or "Bulk", row.get("process") or "")
            T[k] = T.get(k, 0) + row["qty"]

        def good_cut(colour, size):
            return t(colour, size, "CUT") - t(colour, size, "CUT_REJECT")

        def route_for(colour, position):
            out = []
            for p in route:
                c = (p.colour or "").strip()
                if p.position == position and (not c or c.upper() == colour.strip().upper()):
                    out.append(p)
            return out

        def back_good(colour, size, process):
            return t(colour, size, "SC_BACK_GOOD", process=process)

        def after_output(colour, size):
            after = route_for(colour, "After Sewing")
            if after:
                return back_good(colour, size, after[-1].subcontract_process)
            return t(colour, size, "SEW_OUT")

        def limit(row):
            """(max qty the row may add, 'block' or 'warn'), or (None, None) when no rule applies."""
            stage = row["stage"]
            colour = row["colour"]
            size = row["size"]
            purpose = row.get("purpose") or "Bulk"
            process = row.get("process") or ""
            if stage == "CUT":
                line = lines.get((colour, size))
                if purpose == "Re-cut":
                    lost = 0
                    for s in REJECT_STAGES:
                        lost = lost + t(colour, size, s)
                    return lost - t(colour, size, "CUT", purpose="Re-cut"), "block"
                if not line:
                    frappe.throw("%s %s is not on production card %s." % (colour, size, card))
                cap = (line.planned_cut_qty or 0) + int(sval("cut_cap_extra_pcs", 3))
                done = 0
                for p in CUT_PURPOSES:
                    done = done + t(colour, size, "CUT", purpose=p)
                mode = sval("cut_cap_mode", "Block")
                if mode == "Off":
                    return None, None
                return cap - done, ("warn" if mode == "Warn" else "block")
            if stage == "SEW_IN":
                avail = good_cut(colour, size)
                for p in route_for(colour, "Before Sewing"):
                    avail = min(avail, back_good(colour, size, p.subcontract_process))
                return avail - t(colour, size, "SEW_IN"), "block"
            if stage == "SEW_OUT" or stage == "SEW_REJECT":
                return t(colour, size, "SEW_IN") - t(colour, size, "SEW_OUT") - t(colour, size, "SEW_REJECT"), "block"
            if stage == "SC_OUT":
                full = route_for(colour, "Before Sewing") + route_for(colour, "After Sewing")
                names = [p.subcontract_process for p in full]
                if process not in names:
                    frappe.throw("%s is not on the route of production card %s for colour %s." % (process, card, colour))
                i = names.index(process)
                before = full[i].position == "Before Sewing"
                if i == 0 or full[i - 1].position != full[i].position:
                    prior = good_cut(colour, size) if before else t(colour, size, "SEW_OUT")
                else:
                    prior = back_good(colour, size, full[i - 1].subcontract_process)
                return prior - t(colour, size, "SC_OUT", process=process), "block"
            if stage == "FIN_IN":
                return after_output(colour, size) + repair_accepted(card, colour, size) - t(colour, size, "FIN_IN"), "block"
            if stage == "FIN_A" or stage == "FIN_B" or stage == "FIN_REJECT":
                return t(colour, size, "FIN_IN") - t(colour, size, "FIN_A") - t(colour, size, "FIN_B") - t(colour, size, "FIN_REJECT"), "block"
            if stage == "SAMPLE_OUT" or stage == "PACKED":
                return t(colour, size, "FIN_A") - t(colour, size, "SAMPLE_OUT") - t(colour, size, "PACKED"), "block"
            if stage == "SHIPPED":
                return t(colour, size, "PACKED") - t(colour, size, "SHIPPED"), "block"
            return None, None   # SC_BACK_* are limited per challan row by the Subcontract Return itself

        def check(rows, override):
            problems = []
            for row in rows:
                if row["qty"] > 0 and not override:
                    lim = limit(row)
                    if lim[0] is not None and row["qty"] > lim[0] + 0.000000001:
                        msg = "%s: %s %s %s - %s entered, %s available." % (
                            row["stage"], row["colour"], row["size"], row.get("process") or "", num(row["qty"]), num(max(lim[0], 0)))
                        if lim[1] == "warn":
                            frappe.msgprint(msg, indicator="orange", title="Production Flow")
                        else:
                            problems.append(msg)
                apply(row)
            if problems:
                frappe.throw("<br>".join(problems), title="Production Flow")

        return {"check": check, "t": t}

    def clean_rows(rows):
        out = []
        for r in rows:
            if not r.get("qty"):
                continue
            if r["stage"] not in STAGES:
                frappe.throw("Unknown production stage %s." % r["stage"])
            row = dict(r)
            row["colour"] = (r.get("colour") or "").strip()
            row["size"] = (r.get("size") or "").strip()
            row["qty"] = float(r["qty"])
            if not row.get("purpose"):
                row["purpose"] = "Bulk"
            out.append(row)
        return out

    def refresh_card_status(card):
        """Card status follows the furthest stage that has quantities. Closed, Superseded and Cancelled cards are left alone."""
        row = frappe.db.get_value("Production Card", card, ["docstatus", "status"], as_dict=True)
        if not row or row.docstatus != 1 or row.status in ("Superseded", "Cancelled", "Closed"):
            return
        present = [r[0] for r in frappe.db.sql("select distinct stage from `tabProduction Movement` where production_card = %s", card)]
        status = "Issued"
        for pair in STATUS_BY_STAGE:
            if pair[0] in present:
                status = pair[1]
                break
        if status != row.status:
            frappe.db.set_value("Production Card", card, "status", status, update_modified=False)

    def post():
        card = form.get("card")
        rows = clean_rows(json.loads(form.get("rows") or "[]"))
        if not rows:
            return
        if form.get("check") is None or int(form.get("check")):
            make_flow(card)["check"](rows, int(form.get("override") or 0))
        head = frappe.db.get_value("Production Card", card, ["sales_order", "style_item"], as_dict=True)
        when = frappe.utils.getdate(form.get("posting_date") or frappe.utils.nowdate())
        for r in rows:
            mv = frappe.get_doc({
                "doctype": "Production Movement", "production_card": card, "sales_order": head.sales_order, "style_item": head.style_item,
                "colour": r["colour"], "size": r["size"], "stage": r["stage"], "purpose": r["purpose"],
                "subcontract_process": r.get("process") or None, "qty": r["qty"], "posting_date": when, "line": r.get("line") or None,
                "supplier": r.get("supplier") or None, "shade_band": r.get("shade_band") or None,
                "fault_source": r.get("fault_source") or None, "source_doctype": form.get("source_doctype"),
                "source_name": form.get("source_name"), "source_row": r.get("source_row")})
            mv.insert(ignore_permissions=True, ignore_links=True)    # the source document is mid-submit; the ledger never blocks on it
        refresh_card_status(card)

    def unpost():
        src = form.get("source_doctype")
        name = form.get("source_name")
        cards = [r[0] for r in frappe.db.sql(
            "select distinct production_card from `tabProduction Movement` where source_doctype = %s and source_name = %s", (src, name))]
        for mv in frappe.get_all("Production Movement", {"source_doctype": src, "source_name": name}, pluck="name"):
            frappe.delete_doc("Production Movement", mv, force=1, ignore_permissions=True)
        for c in cards:
            refresh_card_status(c)

    def transfer():
        """A revision of a production card keeps the history: every ledger row and stage document that points at the old card is
        pointed at the new one. Submitted documents are not edited, only their link moves."""
        old = form.get("old")
        new = form.get("new")
        if not old or old == new:
            return
        done = []
        for dt in frappe.get_all("DocField", {"fieldname": "production_card", "fieldtype": "Link", "options": "Production Card"}, pluck="parent"):
            if dt == "Production Card" or dt == "Production Card Line" or dt in done:
                continue
            done.append(dt)
            for n in frappe.get_all(dt, {"production_card": old}, pluck="name"):
                frappe.db.set_value(dt, n, "production_card", new, update_modified=False)

    def totals():
        out = {}
        for r in frappe.db.sql("select colour, size, stage, sum(qty) from `tabProduction Movement` where production_card = %s group by colour, size, stage", form.get("card")):
            out[r[0] + "|" + r[1] + "|" + r[2]] = r[3] or 0
        frappe.flags.arinox_result = out

    def bulk_gate():
        # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
        # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
        APPROVED = ("Approved", "Approved with Comments")
        GATE_OK = ("Approved", "Approved with Comments", "Not Required")
        MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
        # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
        DEFAULT_RULES = {
            "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
            "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
            "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
            "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
            "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
        }


        def norm(colour):
            return (colour or "").strip().upper()


        def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
            return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                    "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                    "chargeback_amount": frappe.utils.flt(chargeback_amount)}


        def get_rules(customer, sales_order, style_item):
            """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
            an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
            rules = {}
            for t in DEFAULT_RULES:
                d = DEFAULT_RULES[t]
                rules[t] = make_rule(d[0], d[1], d[2], d[3])
            for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                    fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
                rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
            if sales_order and not customer:
                customer = frappe.db.get_value("Sales Order", sales_order, "customer")
            scored = []
            for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
                score = 0
                for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                    if q.get(field):
                        if q.get(field) != value:
                            score = None
                            break
                        score += weight
                if score:
                    scored.append([score, q])
            for entry in sorted(scored, key=lambda x: x[0]):
                q = entry[1]
                rule = rules.get(q.sample_type)
                if not rule:
                    rule = make_rule()
                    rules[q.sample_type] = rule
                if q.gate:
                    rule["gate"] = q.gate
                if q.per_colour:
                    rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
                if q.due_basis:   # basis and offset travel together
                    rule["due_basis"] = q.due_basis
                    rule["days_before"] = frappe.utils.cint(q.days_before)
                if frappe.utils.cint(q.qty):
                    rule["qty"] = frappe.utils.cint(q.qty)
                if q.sample_size:
                    rule["sample_size"] = q.sample_size
                if frappe.utils.cint(q.split_po_exempt):
                    rule["split_po_exempt"] = 1
                if frappe.utils.flt(q.chargeback_amount):
                    rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
            return rules


        def is_split_po(sales_order):
            """An order that ships to more than one destination."""
            dests = []
            for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
                if (d or "").strip() and (d or "").strip().upper() not in dests:
                    dests.append((d or "").strip().upper())
            return len(dests) > 1


        def effective_gate(rule, sales_order):
            """The gate after the split-PO exemption."""
            if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
                return "No"
            return rule["gate"]


        def scope_filters(sales_order, style_item):
            """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
            return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


        def get_style_dates(sales_order, style_item, colour):
            """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
            pcd = None
            ex_factory = None
            in_warehouse = None
            if not sales_order:
                return [pcd, ex_factory, in_warehouse]
            fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
            if fa:
                for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                    if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                        pcd = r.pcd
                        break
            contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
            if not pcd and contract:
                for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                    if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                        pcd = r.pcd
                        break
            for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                     fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
                if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                    if colour and norm(it.apparel_colour) != norm(colour):
                        continue
                    ex_factory = ex_factory or it.delivery_date
                    in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                    if ex_factory and in_warehouse:
                        break
            return [pcd, ex_factory, in_warehouse]


        def fit_approved_on(sales_order, style_item):
            """Latest approval date of the Fit samples of this style that apply to the order."""
            f = scope_filters(sales_order, style_item)
            f["sample_type"] = "Fit"
            f["status"] = ["in", list(APPROVED)]
            rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
            return max(rows) if rows else None
        # shared helpers from pp_meeting.py: the departments that must attend, the buyer comments still open on a style, and the open cutting actions
        def required_departments(meeting_type, is_washed):
            """Departments that must attend, from Apparel Settings (one per line). Washing joins when the garment is washed."""
            field = "pilot_required_departments" if meeting_type == "Pilot Run" else "pp_required_departments"
            default = "Cutting\nSewing\nQC\nCAD" if meeting_type == "Pilot Run" else "Planning\nPurchasing\nCutting\nSewing\nQC"
            names = [d.strip() for d in (frappe.db.get_single_value("Apparel Settings", field) or default).splitlines() if d.strip()]
            if frappe.utils.cint(is_washed) and meeting_type != "Pilot Run" and "Washing" not in names:
                names.append("Washing")
            return names


        def open_buyer_comments(sales_order, style_item):
            """Open comments on every sample of this style that applies to the order (each a dict)."""
            rows = []
            for s in frappe.get_all("Sample Approval", filters=scope_filters(sales_order, style_item), fields=["name", "sample_type", "colour"]):
                for c in frappe.get_all("Sample Approval Comment", filters={"parent": s.name, "parenttype": "Sample Approval", "status": "Open"},
                                        fields=["name", "category", "comment", "relevant_to_cutting"]):
                    d = dict(c)
                    d["sample_approval"] = s.name
                    d["sample_type"] = s.sample_type
                    d["colour"] = s.colour
                    rows.append(d)
            return rows


        def cutting_actions_open(sales_order, style_item):
            """[PP meetings held, open cutting-related actions]. Actions of pilot runs count too; only a PP Meeting counts as the meeting being held."""
            open_rows = []
            all_meetings = frappe.get_all("PP Meeting", filters={"sales_order": sales_order, "style_item": style_item, "docstatus": 1}, fields=["name", "meeting_type"])
            meetings = [m for m in all_meetings if m.meeting_type == "PP Meeting"]
            for m in all_meetings:
                open_rows = open_rows + frappe.get_all("PP Meeting Action", filters={"parent": m.name, "relevant_to_cutting": 1, "status": "Open"}, fields=["comment"])
            return [meetings, open_rows]
        # shared helpers from materials/status.py: the material gate that holds bulk production, and trim readiness (the rest of status.py is not ported yet)
        def material_gate(sales_order, style_item, colour):
            """[blockers, warnings] for bulk production of a style x colour: every requisition line must have its accepted quantity in.
            Trims that only matter later (finishing, packing) never hold cutting."""
            flt = frappe.utils.flt
            fab = frappe.db.get_single_value("Apparel Settings", "material_gate_fabric") or "Block"
            trim = frappe.db.get_single_value("Apparel Settings", "material_gate_trims") or "Warn"
            min_pct = flt(frappe.db.get_single_value("Apparel Settings", "material_gate_min_pct") or 100)
            blockers = []
            warnings = []
            if fab != "Off":
                fab_lines = frappe.db.sql("""select c.parent, c.fabric_item, c.net_qty, c.accepted_qty from `tabFabric Requisition Item` c join `tabFabric Requisition` p on p.name = c.parent
                    where p.docstatus = 1 and p.status not in ('Superseded', 'Cancelled') and c.sales_order = %s and c.style_item = %s
                    and upper(c.colour) = upper(%s) and c.net_qty > 0""", (sales_order, style_item, colour or ""), as_dict=True)
                if not fab_lines:
                    # nothing to hold the gate on: say so, so an order never starts bulk with no fabric ordered by oversight (free-issue fabric is the one good reason)
                    warnings.append("Fabric: no approved Fabric Requisition covers %s yet. Fine only if the buyer supplies the fabric." % (colour or "this colour"))
                for r in fab_lines:
                    need = flt(r.net_qty) * min_pct / 100
                    if flt(r.accepted_qty) + 0.0005 < need:
                        msg = "Fabric %s: %s m of %s m accepted (%s)." % (r.fabric_item, flt(r.accepted_qty, 1), flt(r.net_qty, 1), r.parent)
                        if fab == "Block":
                            blockers.append(msg)
                        else:
                            warnings.append(msg)
            if trim != "Off":
                for r in frappe.db.sql("""select c.parent, c.trim_item, c.net_qty, c.accepted_qty, c.trim_category from `tabTrim Requisition Item` c join `tabTrim Requisition` p on p.name = c.parent
                    left join `tabTrim Category` k on k.name = c.trim_category
                    where p.docstatus = 1 and p.status not in ('Superseded', 'Cancelled') and c.sales_order = %s and c.style_item = %s
                    and (c.colour is null or c.colour = '' or upper(c.colour) = upper(%s)) and c.net_qty > 0 and coalesce(k.needed_for, 'Sewing') in ('Cutting', 'Sewing')""",
                                       (sales_order, style_item, colour or ""), as_dict=True):
                    need = flt(r.net_qty) * min_pct / 100
                    if flt(r.accepted_qty) + 0.0005 < need:
                        msg = "Trim %s: %s of %s accepted (%s)." % (r.trim_item, flt(r.accepted_qty, 1), flt(r.net_qty, 1), r.parent)
                        if trim == "Block":
                            blockers.append(msg)
                        else:
                            warnings.append(msg)
            return [blockers, warnings]


        def trim_readiness(sales_order, style_item, needed_for):
            """Available / Partial / Not Available for the trims of one need (Sewing or Packing); None when there are none."""
            flt = frappe.utils.flt
            rows = frappe.db.sql("""select c.net_qty, c.received_qty, c.accepted_qty from `tabTrim Requisition Item` c join `tabTrim Requisition` p on p.name = c.parent
                left join `tabTrim Category` k on k.name = c.trim_category where p.docstatus = 1 and p.status not in ('Superseded', 'Cancelled')
                and c.sales_order = %s and c.style_item = %s and c.net_qty > 0 and coalesce(k.needed_for, 'Sewing') = %s""", (sales_order, style_item, needed_for), as_dict=True)
            if not rows:
                return None
            min_pct = flt(frappe.db.get_single_value("Apparel Settings", "material_gate_min_pct") or 100)
            if len([r for r in rows if flt(r.accepted_qty) + 0.0005 >= flt(r.net_qty) * min_pct / 100]) == len(rows):
                return "Available"
            if [r for r in rows if flt(r.received_qty) > 0 or flt(r.accepted_qty) > 0]:
                return "Partial"
            return "Not Available"
        cint = frappe.utils.cint
        sales_order = form.get("sales_order")
        style = form.get("style")
        colour = form.get("colour")
        stage = form.get("stage") or "bulk"
        if not style or not sales_order:
            frappe.flags.arinox_result = {"applies": False, "blockers": [], "warnings": []}
            return
        rules = get_rules(None, sales_order, style)
        samples = frappe.get_all("Sample Approval", filters=scope_filters(sales_order, style), fields=["name", "sample_type", "status", "colour"])
        blockers = []
        for stype in rules:
            rule = rules[stype]
            gate = effective_gate(rule, sales_order)
            if gate == "No":
                continue
            mine = [x for x in samples if x.sample_type == stype and (not rule["per_colour"] or not (x.colour or "").strip() or norm(x.colour) == norm(colour))]
            where = stype + (" (%s)" % colour if rule["per_colour"] and colour else "")
            if gate == "Required" and not mine:
                blockers.append("%s: no approval record yet." % where)
            for x in mine:
                if x.status not in GATE_OK:
                    blockers.append("%s: %s is %s." % (where, x.name, x.status))
        if cint(frappe.db.get_single_value("Apparel Settings", "require_pp_meeting")):
            held = cutting_actions_open(sales_order, style)
            if not held[0]:
                blockers.append("PP Meeting: not held (no submitted PP Meeting for this style on this order).")
            for r in held[1]:
                blockers.append("PP Meeting: cutting comment still open: %s" % (r.comment or "")[:80])
        mat = material_gate(sales_order, style, colour)
        blockers = blockers + mat[0]
        if stage == "bulk":
            # the pilot run, only when a live production card requires one
            cards = frappe.get_all("Production Card", filters={"sales_order": sales_order, "style_item": style, "docstatus": 1, "status": ["not in", ("Superseded", "Cancelled")]},
                                   fields=["name", "pilot_required", "pilot_waiver"], order_by="creation desc", limit=1)
            if cards and cint(cards[0].pilot_required) and not cint(cards[0].pilot_waiver):
                runs = frappe.get_all("Pilot Run", filters={"production_card": cards[0].name, "docstatus": 1}, fields=["name", "status"])
                if not runs:
                    blockers.append("Pilot Run: no pilot run recorded for production card %s." % cards[0].name)
                else:
                    good = []
                    for r in runs:
                        if r.status not in ("Approved", "Approved with Comments"):
                            continue
                        cols = [norm(c) for c in frappe.get_all("Pilot Run Colour", filters={"parent": r.name}, pluck="colour")]
                        if not cols or not colour or norm(colour) in cols:
                            good.append(r.name)
                    if not good:
                        blockers.append("Pilot Run: no approved pilot run for %s (production card %s)." % (colour or "this colour", cards[0].name))
        frappe.flags.arinox_result = {"applies": True, "style": style, "colour": colour, "blockers": blockers, "warnings": mat[1]}

    if action == "totals":
        totals()
    elif action == "transfer":
        transfer()
    elif action == "post":
        post()
    elif action == "unpost":
        unpost()
    elif action == "check":
        make_flow(form.get("card"))["check"](clean_rows(json.loads(form.get("rows") or "[]")), int(form.get("override") or 0))
    elif action == "total":
        f = make_flow(form.get("card"))
        frappe.flags.arinox_total = f["t"](form.get("colour"), form.get("size"), form.get("stage"), form.get("purpose") or None)
    elif action == "bulk_gate":
        bulk_gate()
    else:
        frappe.throw("arinox_engine: unknown action %s" % action)


main()

# Production Adjustment, Before Save: a manager's correction of a counting mistake needs an open card, a quantity and a reason.
def run(doc):
    card = frappe.db.get_value("Production Card", doc.production_card, ["docstatus", "status"], as_dict=True)
    if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
        frappe.throw("Production card %s must be issued and open." % doc.production_card)
    if not frappe.utils.flt(doc.qty):
        frappe.throw("Enter a quantity other than zero.")
    if not (doc.reason or "").strip():
        frappe.throw("Enter the reason for the adjustment.")
    if doc.stage in ("SC_OUT", "SC_BACK_GOOD", "SC_BACK_REJECT_VENDOR", "SC_BACK_REJECT_FACTORY") and not doc.subcontract_process:
        frappe.throw("Choose the process for stage %s." % doc.stage)
    if not frappe.db.exists("Production Card Line", {"parent": doc.production_card, "colour": doc.colour, "size": doc.size}):
        frappe.throw("%s %s is not on production card %s." % (doc.colour, doc.size, doc.production_card))


run(doc)

# Production Adjustment, Before Submit: a negative adjustment cannot take off more than the ledger holds.
def run(doc):
    qty = frappe.utils.flt(doc.qty)
    if qty < 0:
        out = run_script("arinox_engine", action="total", card=doc.production_card, stage=doc.stage, colour=doc.colour, size=doc.size,
                         purpose=doc.purpose or "Bulk")
        have = out.get("arinox_total") or 0
        if have + qty < -0.000000001:
            frappe.throw("Only %s recorded for %s; cannot take off %s." % (have, doc.stage, abs(qty)))


run(doc)

# Production Card, Before Save (validate): check the order, fill the header, compute the lines, fabrics and route, set pilot rules.
def run(doc):
    # shared helpers: pure production maths (production/maths.py)
    def planned_cut(order_qty, extra_pct):
        q = float(order_qty or 0)
        if q <= 0:
            return 0
        return int(frappe.utils.ceil(round(q * (1 + float(extra_pct or 0) / 100.0), 6)))


    def max_ship_qty(order_qty, tolerance_pct):
        return int(frappe.utils.floor(round(float(order_qty or 0) * (1 + float(tolerance_pct or 0) / 100.0), 6)))


    def norm(text):
        return (text or "").strip().upper()


    def to_metres(qty, uom, gsm, width_cm):
        kind = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd",
                "yard": "yd", "yards": "yd", "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}.get((uom or "").strip().lower())
        q = frappe.utils.flt(qty)
        if kind == "m":
            return q
        if kind == "yd":
            return q * 0.9144
        if kind == "kg":
            if not frappe.utils.flt(gsm) or not frappe.utils.flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return q * 1000 / (frappe.utils.flt(gsm) * frappe.utils.flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def my_roles():
        return (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))


    def has_any_role(names):
        mine = my_roles()
        for n in names:
            if n in mine:
                return True
        return False
    # shared helpers: the order matrix and style dates (production_card.order_matrix, sample_approval.get_style_dates)
    def order_matrix(sales_order, style_item):
        """({(colour, size): {order_qty, tolerance_pct}}, earliest ex-factory date, [buyer POs]) for one style on an order."""
        cells = {}
        ex_factory = None
        pos = []
        for it in frappe.get_all("Sales Order Item", {"parent": sales_order},
                                 ["item_code", "qty", "apparel_colour", "apparel_size", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            if style != style_item:
                continue
            key = ((it.apparel_colour or "").strip(), (it.apparel_size or "").strip())
            if key not in cells:
                cells[key] = {"order_qty": 0, "tolerance_pct": 0}
            cells[key]["order_qty"] = cells[key]["order_qty"] + int(it.qty or 0)
            cells[key]["tolerance_pct"] = max(frappe.utils.flt(cells[key]["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not ex_factory or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(ex_factory)):
                ex_factory = frappe.utils.getdate(it.delivery_date)
            if it.apparel_buyer_po and it.apparel_buyer_po not in pos:
                pos.append(it.apparel_buyer_po)
        return cells, ex_factory, pos


    def get_pcd(sales_order, style_item):
        """Planned cut date from the Factory Allocation, then the contract line."""
        if not sales_order:
            return None
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", {"parent": fa, "style_item": style_item}, ["pcd"], order_by="pcd"):
                if r.pcd:
                    return r.pcd
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if contract:
            for r in frappe.get_all("Sales Contract Item", {"parent": contract, "style_item": style_item}, ["pcd"], order_by="pcd"):
                if r.pcd:
                    return r.pcd
        return None


    def setting(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        if v is None or v == "":
            return default
        return v
    flt = frappe.utils.flt
    cint = frappe.utils.cint

    so = frappe.db.get_value("Sales Order", doc.sales_order, ["docstatus", "customer", "company"], as_dict=True)
    if not so or so.docstatus != 1:
        frappe.throw("Sales Order %s must be submitted." % doc.sales_order)
    if so.customer != doc.customer:
        frappe.throw("Sales Order %s belongs to %s, not %s." % (doc.sales_order, so.customer, doc.customer))
    if so.company != doc.company:
        frappe.throw("Sales Order %s belongs to company %s." % (doc.sales_order, so.company))

    # ---- header
    item = frappe.db.get_value("Item", doc.style_item, ["item_name"], as_dict=True)
    if not item:
        frappe.throw("Style item %s not found." % doc.style_item)
    tp = frappe.db.get_value("Tech Pack", {"style_item": doc.style_item}, ["style_no", "style_name", "season"], as_dict=True)
    doc.style_name = doc.style_name or (tp.style_name if tp else None) or item.item_name
    doc.style_no = doc.style_no or (tp.style_no if tp else None) or doc.style_item
    contract = frappe.db.get_value("Sales Order", doc.sales_order, "apparel_sales_contract")
    doc.sales_contract = contract
    doc.season = doc.season or (frappe.db.get_value("Sales Contract", contract, "season") if contract else None) or (tp.season if tp else None)
    matrix = order_matrix(doc.sales_order, doc.style_item)
    cells = matrix[0]
    doc.buyer_pos = "\n".join(matrix[2])
    doc.ex_factory_date = doc.ex_factory_date or matrix[1]
    doc.pcd = doc.pcd or get_pcd(doc.sales_order, doc.style_item)
    if doc.default_extra_cut_pct is None or doc.default_extra_cut_pct == "":
        doc.default_extra_cut_pct = flt(setting("default_extra_cut_pct", 5))
    if doc.trim_allowance_pct is None or doc.trim_allowance_pct == "":
        doc.trim_allowance_pct = flt(setting("trim_allowance_pct", 2))
    doc.bundle_size = cint(doc.bundle_size) or cint(setting("bundle_size", 20))
    if not doc.factory or not doc.line:
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": doc.sales_order}, "name")
        if fa:
            rows = frappe.get_all("Factory Allocation Line", {"parent": fa, "style_item": doc.style_item}, ["factory", "line"], limit=1)
            if rows:
                doc.factory = doc.factory or rows[0].factory
                doc.line = doc.line or rows[0].line
    doc.made_by = doc.made_by or frappe.session.user
    if cint(doc.revision_no) > 0 and not (doc.revision_reason or "").strip():
        frappe.throw("Enter the reason for this revision.")

    # ---- one live card per order x style x ex-factory date (a revision chain shares the key)
    others = frappe.get_all("Production Card", {"sales_order": doc.sales_order, "style_item": doc.style_item, "ex_factory_date": doc.ex_factory_date,
                                                 "docstatus": 1, "status": ["not in", ["Superseded", "Cancelled"]], "name": ["!=", doc.name or ""]}, pluck="name")
    others = [n for n in others if n != doc.previous_card]
    if others:
        frappe.throw("Production card %s already covers this order, style and ex-factory date. Use Revise on it." % others[0])

    # ---- lines
    flags = []
    if not cells:
        frappe.throw("Style %s has no lines on Sales Order %s." % (doc.style_item, doc.sales_order))
    seen = []
    max_extra = flt(setting("max_extra_cut_pct", 8))
    is_manager = has_any_role(["Apparel Production Manager", "Apparel Merchandising Manager", "System Manager"])
    for r in doc.lines:
        key = ((r.colour or "").strip(), (r.size or "").strip())
        if key in seen:
            frappe.throw("Row %s: %s %s appears twice." % (r.idx, key[0], key[1]))
        seen.append(key)
        cell = cells.get(key)
        if not cell:
            frappe.throw("Row %s: %s %s is not on Sales Order %s. Check the colour and size spelling." % (r.idx, key[0], key[1], doc.sales_order))
        r.colour = key[0]
        r.size = key[1]
        r.order_qty = cell["order_qty"]
        r.max_qty = max_ship_qty(cell["order_qty"], cell["tolerance_pct"])
        if r.extra_cut_pct is None or r.extra_cut_pct == "":
            r.extra_cut_pct = doc.default_extra_cut_pct
        if flt(r.extra_cut_pct) < 0:
            frappe.throw("Row %s: extra cut cannot be negative." % r.idx)
        if flt(r.extra_cut_pct) > max_extra:
            if not is_manager:
                frappe.throw("Row %s: extra cut %s%% is above the limit of %s%%. A production manager can allow it." % (r.idx, r.extra_cut_pct, max_extra))
            flags.append("Extra cut above %s%% on %s %s." % (max_extra, r.colour, r.size))
        r.planned_cut_qty = planned_cut(r.order_qty, r.extra_cut_pct)
    for key in cells:
        if key not in seen:
            flags.append("%s %s is on the Sales Order but not on this card." % (key[0], key[1]))
    source = doc.name if (doc.name and not doc.is_new()) else doc.previous_card
    if source:
        cut_over = []
        for r in doc.lines:
            done = frappe.db.sql("select ifnull(sum(qty),0) from `tabProduction Movement` where production_card=%s and colour=%s and size=%s and stage='CUT' and purpose != 'Re-cut'",
                                 (source, r.colour, r.size))[0][0]
            if done > r.planned_cut_qty:
                cut_over.append("%s %s: cut %s > plan %s" % (r.colour, r.size, int(done), r.planned_cut_qty))
        if cut_over:
            flags.append("Cut exceeds the revised plan: " + "; ".join(cut_over))

    # ---- fabrics
    def colour_cut(colour):
        total = 0
        for l in doc.lines:
            if norm(l.colour) == norm(colour):
                total = total + cint(l.planned_cut_qty)
        return total

    for r in doc.fabrics:
        if flt(r.consumption) <= 0:
            frappe.throw("Fabric row %s: consumption must be above zero." % r.idx)
        on_card = False
        for l in doc.lines:
            if norm(l.colour) == norm(r.colour):
                on_card = True
        if not on_card:
            frappe.throw("Fabric row %s: colour %s is not on the size breakup." % (r.idx, r.colour))
        gsm = None
        width = None
        if r.fabric_item:
            vals = frappe.db.get_value("Item", r.fabric_item, ["apparel_fabric_gsm", "apparel_fabric_width_cm"])
            if vals:
                gsm = vals[0]
                width = vals[1]
        per_garment_m = to_metres(flt(r.consumption), r.consumption_uom or "Meter", gsm, width)
        r.required_m = round(colour_cut(r.colour) * per_garment_m, 3)
        if r.fabric_requisition_item:
            fr = frappe.db.get_value("Fabric Requisition Item", r.fabric_requisition_item, ["net_qty", "accepted_qty"], as_dict=True)
            if fr:
                r.fr_net_m = flt(fr.net_qty)
                r.accepted_m = flt(fr.accepted_qty)
                if r.fr_net_m and r.required_m > r.fr_net_m * 1.01:
                    flags.append("%s %s: card needs %s m but the requisition covers %s m." % (r.colour, r.fabric_item or "", round(r.required_m, 1), round(r.fr_net_m, 1)))
        if r.fabric_item and doc.name and not doc.is_new():
            moved = frappe.db.sql("select ifnull(sum(d.qty), 0) from `tabStock Entry Detail` d join `tabStock Entry` s on s.name = d.parent "
                                  "where s.docstatus = 1 and s.apparel_production_card = %s and s.apparel_issue_kind = 'Fabric Issue' and d.item_code = %s",
                                  (doc.name, r.fabric_item))
            r.issued_m = flt(moved[0][0])
        r.shortage_m = round(max(flt(r.required_m) - flt(r.accepted_m), 0), 3) if r.accepted_m else flt(r.required_m)
        if r.shortage_m > 0 and doc.docstatus == 1:
            flags.append("%s: %s m of fabric still to be accepted." % (r.colour, round(r.shortage_m, 1)))

    # ---- route
    route_seen = []
    for p in doc.processes:
        key = (p.subcontract_process, (p.colour or "").strip().upper())
        if key in route_seen:
            frappe.throw("Process %s appears twice on the route." % p.subcontract_process)
        route_seen.append(key)
        info = frappe.db.get_value("Subcontract Process", p.subcontract_process, ["default_position", "item_state"], as_dict=True)
        if not p.item_state and info:
            p.item_state = info.item_state
        if p.position == "Before Sewing" and p.item_state == "Garments":
            frappe.throw("%s: garments cannot go out before sewing; choose Cut Panels or After Sewing." % p.subcontract_process)
        if p.position == "After Sewing" and p.item_state == "Cut Panels":
            frappe.throw("%s: cut panels cannot be sent after sewing; choose Garments or Before Sewing." % p.subcontract_process)

    # ---- pilot run
    total = 0
    for r in doc.lines:
        total = total + cint(r.order_qty)
    by_qty = total >= cint(setting("pilot_min_order_qty", 1000))
    rule = frappe.db.get_value("Apparel Sample Rule", {"parent": "Apparel Settings", "sample_type": "Pilot Run"}, "gate")
    doc.pilot_required = 1 if (by_qty or rule == "Required") else 0
    if cint(doc.pilot_waiver):
        if not has_any_role(["Apparel Production Manager", "System Manager"]) and doc.has_value_changed("pilot_waiver"):
            frappe.throw("Only a production manager can waive the pilot run.")
        if not (doc.pilot_waiver_reason or "").strip():
            frappe.throw("Enter the reason for waiving the pilot run.")
    unique = []
    for f in flags:
        if f not in unique:
            unique.append(f)
    doc.red_flags = "\n".join(unique)


run(doc)

# Production Card, Before Submit: the breakup is required; list what is still open (it never blocks issuing).
def run(doc):
    if not doc.lines:
        frappe.throw("Add the colour x size breakup before issuing.")
    missing = []
    if not frappe.db.exists("Factory Allocation", {"sales_order": doc.sales_order}):
        missing.append("No Factory Allocation for this order.")
    if not frappe.db.exists("Tech Pack", {"style_item": doc.style_item, "docstatus": ["<", 2]}):
        missing.append("No Tech Pack for this style.")
    if not frappe.db.exists("Fabric Requisition Item", {"sales_order": doc.sales_order, "style_item": doc.style_item, "docstatus": 1}):
        missing.append("No approved Fabric Requisition.")
    if not frappe.db.exists("Trim Requisition Item", {"sales_order": doc.sales_order, "style_item": doc.style_item, "docstatus": 1}):
        missing.append("No approved Trim Requisition.")
    if not doc.packing_instruction:
        missing.append("No Packing Instruction.")
    if missing:
        frappe.msgprint("<br>• ".join(["Issued with these still open:"] + missing), indicator="orange", title="Production Card")


run(doc)

# Production Card, After Submit: mark issued; a revision supersedes its predecessor and takes over its history.
def run(doc):
    doc.db_set({"issue_date": frappe.utils.nowdate(), "status": "Issued"})
    if doc.previous_card:
        frappe.db.set_value("Production Card", doc.previous_card, "status", "Superseded")
        run_script("arinox_engine", action="transfer", old=doc.previous_card, new=doc.name)
    for name in frappe.get_all("PP Meeting", {"sales_order": doc.sales_order, "style_item": doc.style_item, "docstatus": 0}, pluck="name"):
        frappe.db.set_value("PP Meeting", name, {"production_card_ref": doc.name, "production_card_issued_on": frappe.utils.nowdate()}, update_modified=False)


run(doc)

# Production Card, Before Cancel: a card with quantities cannot be cancelled.
def run(doc):
    if frappe.db.exists("Production Movement", {"production_card": doc.name}):
        frappe.throw("Production card %s already has cutting, sewing or packing quantities and cannot be cancelled. "
                     "Use Revise, or a Production Adjustment to correct a count." % doc.name)


run(doc)

# Delivery Note, Before Save: copy the production card and contract down from the packing list on each row.
def run(doc):
    first = None
    has_lists = False
    for it in doc.items:
        if it.get("apparel_packing_list"):
            has_lists = True
            it.apparel_production_card = frappe.db.get_value("Packing List", it.apparel_packing_list, "production_card")
        if not first and it.get("against_sales_order"):
            first = it.against_sales_order
    if first and has_lists:
        doc.apparel_sales_contract = frappe.db.get_value("Sales Order", first, "apparel_sales_contract") or None


run(doc)

# Delivery Note, Before Submit: the final-inspection ship gate and the over-ship check (per size, in total, or both).
def run(doc):
    flt = frappe.utils.flt
    lists = []
    unlisted = []      # rows of an apparel order (one with a Production Card) that name no packing list: nothing shows they were packed and inspected
    for it in doc.items:
        if it.get("apparel_packing_list"):
            if it.apparel_packing_list not in lists:
                lists.append(it.apparel_packing_list)
        elif it.get("against_sales_order") and frappe.db.exists("Production Card", {"sales_order": it.against_sales_order, "docstatus": 1}):
            unlisted.append(it.idx)
    if not lists and not unlisted:
        return
    managers = (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))
    is_manager = "Apparel Production Manager" in managers or "Apparel Merchandising Manager" in managers or "System Manager" in managers

    def setting(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        if v is None or v == "":
            return default
        return v

    lists = sorted(lists)
    for pl in lists:
        row = frappe.db.get_value("Packing List", pl, ["docstatus", "status"], as_dict=True)
        if not row or row.docstatus != 1:
            frappe.throw("Packing list %s must be submitted before it ships." % pl)
        if row.status == "Shipped":
            frappe.throw("Packing list %s has already shipped." % pl)

    # ---- the final-inspection gate
    mode = setting("ship_gate_final_inspection", "Block")
    if mode != "Off":
        problems = []
        if unlisted:
            problems.append("Row(s) %s are for an apparel order but name no packing list, so the final inspection cannot be checked. Make the delivery note from the Shipment, or pick the packing list on each row." % ", ".join([str(n) for n in unlisted]))
        for pl in lists:
            rows = frappe.db.sql(
                "select i.name, i.result from `tabFinal Inspection` i join `tabFinal Inspection Lot` l on l.parent = i.name "
                "where l.packing_list = %s and i.docstatus = 1 and i.inspection_type in ('Final', 'Re-inspection', '2nd Re-inspection') "
                "order by i.inspection_date desc, i.creation desc limit 1", pl, as_dict=True)
            if not rows:
                problems.append("%s has no final inspection." % pl)
            elif rows[0].result not in ("Accepted", "Accepted with Concession"):
                problems.append("%s: the latest inspection %s is %s." % (pl, rows[0].name, rows[0].result or "undecided"))
        if problems:
            if doc.get("apparel_gate_override"):
                if not is_manager:
                    frappe.throw("Only a manager can override the inspection gate.")
                if not (doc.get("apparel_gate_override_reason") or "").strip():
                    frappe.throw("Write the reason for overriding the inspection gate.")
            elif mode == "Block":
                frappe.throw("<br>".join(problems), title="Final inspection")
            else:
                frappe.msgprint("<br>".join(problems), indicator="orange", title="Final inspection")

    # ---- the over-ship check
    basis = setting("ship_tolerance_basis", "Both")
    by_row = {}
    for it in doc.items:
        if not it.get("so_detail") or not it.get("apparel_packing_list"):
            continue
        by_row[it.so_detail] = by_row.get(it.so_detail, 0) + flt(it.stock_qty or it.qty)
    problems = []
    ordered_total = {}
    shipped_total = {}
    tol_by_order = {}
    orders = []
    for d in by_row:
        parent = frappe.db.get_value("Sales Order Item", d, "parent")
        if parent not in orders:
            orders.append(parent)
    for so in orders:    # the whole order, not only the lines on this note
        ordered_total[so] = flt(frappe.db.sql("select ifnull(sum(qty), 0) from `tabSales Order Item` where parent = %s", so)[0][0])
        shipped_total[so] = flt(frappe.db.sql("select ifnull(sum(i.stock_qty), 0) from `tabDelivery Note Item` i where i.against_sales_order = %s and i.docstatus = 1 and i.parent != %s",
                                              (so, doc.name or ""))[0][0])
    for so_detail in by_row:
        qty = by_row[so_detail]
        line = frappe.db.get_value("Sales Order Item", so_detail, ["parent", "qty", "apparel_qty_tolerance_pct", "apparel_colour", "apparel_size"], as_dict=True)
        if not line:
            continue
        before = frappe.db.sql("select ifnull(sum(stock_qty), 0) from `tabDelivery Note Item` where so_detail = %s and docstatus = 1 and parent != %s",
                               (so_detail, doc.name or ""))[0][0]
        shipped = flt(before) + qty
        limit = int(frappe.utils.floor(round(float(line.qty or 0) * (1 + float(line.apparel_qty_tolerance_pct or 0) / 100.0), 6)))
        if (basis == "Each Size" or basis == "Both") and shipped > limit + 0.000000001:
            problems.append("%s %s: %s shipped against %s ordered (allowed up to %s)." % (line.apparel_colour, line.apparel_size, int(shipped), int(line.qty), limit))
        shipped_total[line.parent] = shipped_total[line.parent] + qty
        tol_by_order[line.parent] = flt(line.apparel_qty_tolerance_pct)
    if basis == "Total" or basis == "Both":
        for so in shipped_total:
            limit = int(frappe.utils.floor(round(float(ordered_total[so] or 0) * (1 + float(tol_by_order.get(so, 0) or 0) / 100.0), 6)))
            if shipped_total[so] > limit + 0.000000001:
                problems.append("%s: %s shipped in all against %s ordered (allowed up to %s)." % (so, int(shipped_total[so]), int(ordered_total[so]), limit))
    if problems:
        if doc.get("apparel_over_ship_override"):
            if not is_manager:
                frappe.throw("Only a manager can approve shipping outside the allowance.")
            if not (doc.get("apparel_over_ship_override_reason") or "").strip():
                frappe.throw("Write the reason for shipping outside the allowance.")
        else:
            frappe.throw("<br>".join(problems), title="Over-shipment")


run(doc)

# Delivery Note, After Submit: write SHIPPED to the ledger, mark the packing lists shipped, refresh the shipment status.
def run(doc):
    lists = []
    for it in doc.items:
        if it.get("apparel_packing_list") and it.apparel_packing_list not in lists:
            lists.append(it.apparel_packing_list)
    if not lists:
        return
    by_card = {}
    for it in doc.items:
        card = it.get("apparel_production_card")
        if not card or not it.get("so_detail"):
            continue
        cs = frappe.db.get_value("Sales Order Item", it.so_detail, ["apparel_colour", "apparel_size"])
        if card not in by_card:
            by_card[card] = {}
        key = cs[0] + "\t" + cs[1]
        by_card[card][key] = by_card[card].get(key, 0) + int(it.stock_qty or it.qty or 0)
    for card in by_card:
        rows = []
        for key in by_card[card]:
            parts = key.split("\t")
            rows.append({"stage": "SHIPPED", "colour": parts[0], "size": parts[1], "qty": by_card[card][key]})
        run_script("arinox_engine", action="post", card=card, rows=json.dumps(rows), source_doctype="Delivery Note", source_name=doc.name,
                   posting_date=str(doc.posting_date), check="1")
    for pl in lists:
        frappe.db.set_value("Packing List", pl, "status", "Shipped", update_modified=False)


run(doc)

# Delivery Note, Before Cancel: submitted invoices of the shipment must be cancelled first.
def run(doc):
    has_lists = False
    for it in doc.items:
        if it.get("apparel_packing_list"):
            has_lists = True
    if not has_lists:
        return
    if frappe.db.exists("Sales Invoice Item", {"delivery_note": doc.name, "docstatus": 1}) or (
            doc.get("apparel_shipment") and frappe.db.exists("Sales Invoice", {"apparel_shipment": doc.apparel_shipment, "docstatus": 1})):
        frappe.throw("Invoices of this shipment are submitted. Cancel them before cancelling the Delivery Note.")


run(doc)

# Delivery Note, After Cancel: take SHIPPED back out of the ledger and reopen the packing lists.
def run(doc):
    lists = []
    for it in doc.items:
        if it.get("apparel_packing_list") and it.apparel_packing_list not in lists:
            lists.append(it.apparel_packing_list)
    if not lists:
        return
    run_script("arinox_engine", action="unpost", source_doctype="Delivery Note", source_name=doc.name)
    for pl in lists:
        shipment = frappe.db.get_value("Packing List", pl, "shipment")
        frappe.db.set_value("Packing List", pl, "status", "On Shipment" if shipment else "Open", update_modified=False)


run(doc)

# Sales Contract, Before Save (validate): template, bank account, revision, tolerance bands, lines, price lock, sizes, totals.
def run(doc):
    cint = frappe.utils.cint
    flt = frappe.utils.flt
    TERM_FIELDS = ("incoterm", "named_place", "shipment_mode", "port_of_loading", "port_of_discharge", "days_ex_factory_to_etd", "transit_days",
                   "late_shipment_terms", "quantity_claim_days", "quality_claim_days", "aql_level", "inspection_terms", "packing_instructions",
                   "shipping_marks", "payment_terms_template", "terms_and_conditions", "arbitration", "country_of_origin", "freight_by",
                   "insurance_by", "delay_days_allowed", "objection_days", "discrepancy_days", "payment_basis", "payment_days", "documents_list")

    def in_band(qty, b):
        return qty >= cint(b.from_qty) and (not cint(b.to_qty) or qty <= cint(b.to_qty))

    def tolerance_for(qty):
        for b in sorted(doc.tolerance_bands, key=lambda b: cint(b.from_qty)):
            if in_band(qty, b):
                return flt(b.tolerance_pct)
        return 0

    def tolerance_covers(qty):
        for b in doc.tolerance_bands:
            if in_band(qty, b):
                return True
        return False

    if not doc.company:
        doc.company = frappe.db.get_value("Company", {}, "name")
    # ---- template: fill the terms the contract has not set, once
    if doc.contract_template and not doc.tolerance_bands:
        tpl = frappe.get_doc("Sales Contract Template", doc.contract_template)
        for f in TERM_FIELDS:
            if not doc.get(f):
                doc.set(f, tpl.get(f))
        for b in tpl.tolerance_bands:
            doc.append("tolerance_bands", {"from_qty": b.from_qty, "to_qty": b.to_qty, "tolerance_pct": b.tolerance_pct})
        if doc.terms_and_conditions and not doc.terms:
            doc.terms = frappe.db.get_value("Terms and Conditions", doc.terms_and_conditions, "terms")
    if not doc.bank_account and doc.company:
        default_bank = frappe.db.get_value("Company", doc.company, "default_bank_account")
        if default_bank and frappe.db.exists("Bank Account", default_bank):      # a default that names a missing account would block the submit
            doc.bank_account = default_bank
    if doc.amended_from:
        prev = frappe.db.get_value("Sales Contract", doc.amended_from, "revision_no") or 0
        doc.revision_no = cint(prev) + 1
        doc.revision_date = doc.revision_date or frappe.utils.nowdate()
    elif not doc.revision_no:
        doc.revision_no = 0

    # ---- bands must not overlap
    bands = sorted(doc.tolerance_bands, key=lambda b: cint(b.from_qty))
    for b in bands:
        if cint(b.to_qty) and cint(b.to_qty) < cint(b.from_qty):
            frappe.throw("Tolerance band row %s: To Qty is below From Qty." % b.idx)
    for i in range(len(bands) - 1):
        if not cint(bands[i].to_qty) or cint(bands[i].to_qty) >= cint(bands[i + 1].from_qty):
            frappe.throw("Tolerance bands %s and %s overlap." % (bands[i].idx, bands[i + 1].idx))

    # ---- lines
    max_skus = cint(frappe.db.get_single_value("Apparel Settings", "max_skus_per_contract")) or 8
    keys = []
    for it in doc.items:
        # a line is style x colour x buyer PO: the real S14 contract has one line per PO for the same style and colour
        key = (it.style_item, (it.colour or "").strip().upper(), (it.buyer_po_code or "").strip().upper())
        if key in keys:
            frappe.throw("Row %s: %s / %s is already on this contract for PO %s. One line per style, colour and PO." % (it.idx, it.style_item, it.colour, it.buyer_po_code or "-"))
        keys.append(key)
        if not it.style_no:
            it.style_no = frappe.db.get_value("Item", it.style_item, "item_name")
        it.amount = flt(cint(it.qty) * flt(it.rate), 2)
        it.tolerance_pct = tolerance_for(cint(it.qty))
        if doc.tolerance_bands and not tolerance_covers(cint(it.qty)):
            frappe.msgprint("Row %s: quantity %s is above the highest tolerance band, so no tolerance applies. Add a band for it." % (it.idx, cint(it.qty)), indicator="orange")
        if it.ex_factory_date and not it.etd:
            it.etd = frappe.utils.add_days(it.ex_factory_date, cint(doc.days_ex_factory_to_etd))
        if it.etd and not it.in_warehouse_date:
            it.in_warehouse_date = frappe.utils.add_days(it.etd, cint(doc.transit_days))
        if it.ex_factory_date and it.etd and frappe.utils.getdate(it.etd) < frappe.utils.getdate(it.ex_factory_date):
            frappe.throw("Row %s: ETD is before the ex-factory date." % it.idx)
        if it.etd and it.in_warehouse_date and frappe.utils.getdate(it.in_warehouse_date) < frappe.utils.getdate(it.etd):
            frappe.throw("Row %s: in-warehouse date is before ETD." % it.idx)
    if len(keys) > max_skus:
        frappe.throw("This contract has %s SKUs. The maximum is %s; put the rest on a new contract." % (len(keys), max_skus), title="Too Many SKUs")
    doc.sku_count = len(keys)

    # ---- price lock: the price agreed on the quotation is the price on the contract
    if doc.quotation:
        q = frappe.db.get_value("Quotation", doc.quotation, ["docstatus", "party_name", "currency"], as_dict=True)
        if not q or q.docstatus != 1:
            frappe.throw("Quotation %s must be submitted before it can become a contract." % doc.quotation)
        if q.party_name != doc.customer:
            frappe.throw("Quotation %s is for %s, not %s." % (doc.quotation, q.party_name, doc.customer))
        if q.currency != doc.currency:
            frappe.throw("Quotation %s is in %s, not %s." % (doc.quotation, q.currency, doc.currency))
        quoted = {}
        for r in frappe.get_all("Quotation Item", filters={"parent": doc.quotation}, fields=["apparel_cost_sheet", "rate"]):
            if r.apparel_cost_sheet:
                quoted[r.apparel_cost_sheet] = flt(r.rate)
        for it in doc.items:
            if not it.cost_sheet:
                continue
            if it.cost_sheet not in quoted:
                frappe.throw("Row %s: Cost Sheet %s is not on Quotation %s." % (it.idx, it.cost_sheet, doc.quotation))
            if abs(flt(it.rate) - quoted[it.cost_sheet]) > 0.0001:
                frappe.throw("Row %s: rate %s differs from the quoted %s. A contract carries the locked price; amend the Quotation to change it." % (it.idx, flt(it.rate), quoted[it.cost_sheet]),
                             title="Price Lock")

    # ---- sizes: each belongs to one contract line (style x colour x PO), once per ship-to
    def line_index(style_item, colour, po):
        """Index of the line a size row belongs to; None = no such line, -1 = several lines and no PO to tell them apart."""
        cands = []
        n = 0
        for it in doc.items:
            if it.style_item == style_item and (it.colour or "").strip().upper() == (colour or "").strip().upper():
                if not po or (it.buyer_po_code or "").strip().upper() == po.strip().upper():
                    cands.append(n)
            n = n + 1
        if not cands:
            return None
        if len(cands) == 1:
            return cands[0]
        return -1

    seen = []
    for s in doc.sizes:
        i = line_index(s.style_item, s.colour, s.buyer_po_no)
        if i is None:
            frappe.throw("Size row %s: %s / %s (PO %s) is not a line on this contract." % (s.idx, s.style_item, s.colour, s.buyer_po_no or "-"))
        if i == -1:
            frappe.throw("Size row %s: %s / %s is on several lines (one per PO). Enter the buyer PO on the size row." % (s.idx, s.style_item, s.colour))
        k2 = (i, s.size.strip().upper(), (s.ship_to or "").strip().upper())
        if k2 in seen:
            frappe.throw("Size row %s: size %s is entered twice for %s / %s to the same ship-to and PO." % (s.idx, s.size, s.style_item, s.colour))
        seen.append(k2)
        if cint(s.qty) < 0:
            frappe.throw("Size row %s: quantity cannot be negative." % s.idx)

    # ---- totals
    total = 0
    amount = 0
    for it in doc.items:
        total = total + cint(it.qty)
        amount = amount + flt(it.amount)
    doc.total_qty = total
    doc.total_amount = flt(amount, 2)
    if doc.docstatus == 0:
        doc.status = "Draft"


run(doc)

# Sales Contract, Before Submit: drop empty size rows, check the contract is ready to sign, and that nothing is left as a placeholder.
def run(doc):
    cint = frappe.utils.cint
    flt = frappe.utils.flt
    doc.set("sizes", [s for s in doc.sizes if cint(s.qty)])
    n = 1
    for s in doc.sizes:
        s.idx = n
        n = n + 1

    def line_index(style_item, colour, po):
        cands = []
        n = 0
        for it in doc.items:
            if it.style_item == style_item and (it.colour or "").strip().upper() == (colour or "").strip().upper():
                if not po or (it.buyer_po_code or "").strip().upper() == po.strip().upper():
                    cands.append(n)
            n = n + 1
        if len(cands) == 1:
            return cands[0]
        return None

    problems = []
    by_line = {}
    for s in doc.sizes:
        k = line_index(s.style_item, s.colour, s.buyer_po_no)
        by_line[k] = by_line.get(k, 0) + cint(s.qty)
    position = 0
    for it in doc.items:
        position = position + 1
        label = "%s / %s" % (it.style_no or it.style_item, it.colour or "-")
        if not it.colour:
            problems.append("%s: colour is missing" % label)
        if cint(it.qty) <= 0:
            problems.append("%s: quantity is missing" % label)
        if not flt(it.rate):
            problems.append("%s: rate is missing" % label)
        for f in (("ex_factory_date", "ex-factory date"), ("etd", "ETD"), ("in_warehouse_date", "in-warehouse date")):
            if not it.get(f[0]):
                problems.append("%s: %s is missing" % (label, f[1]))
        sized = by_line.get(position - 1, 0)
        if sized != cint(it.qty):
            problems.append("%s: size breakdown totals %s, line quantity is %s" % (label, sized, cint(it.qty)))
    for f in (("incoterm", "Incoterm"), ("port_of_loading", "Port of loading")):
        if not doc.get(f[0]):
            problems.append("%s is missing" % f[1])
    if not ((doc.payment_basis and cint(doc.payment_days)) or doc.payment_basis == "Advance" or doc.payment_terms_template):
        problems.append("Payment terms are missing (basis and days, or a payment terms template)")
    if problems:
        frappe.throw("<br>".join(problems), title="Contract not ready to sign")

    # ---- nothing is left TBA on a signed contract
    raw = frappe.db.get_single_value("Apparel Settings", "placeholder_words") or ""
    words = []
    for w in raw.splitlines():
        if w.strip():
            words.append(w.strip().upper())
    if not words:
        return
    hits = []
    text_types = ("Data", "Small Text", "Text", "Long Text")
    allowed_tba = ("shipping_marks",)      # advised at booking; the real contracts print TBA here

    def scan(d, label):
        for df in d.meta.fields:
            if df.fieldtype not in text_types or df.fieldname in allowed_tba:
                continue
            val = (d.get(df.fieldname) or "").strip()
            if not val:
                continue
            bad = val.upper() in words
            if not bad:
                for tok in val.upper().replace(",", " ").split():
                    if len(tok) > 2 and tok in words:
                        bad = True
            if bad:
                hits.append("%s%s: %s" % (label, df.label, val))

    scan(doc, "")
    for it in doc.items:
        scan(it, "Row %s " % it.idx)
    if hits:
        frappe.throw("Nothing may be left as a placeholder on a signed contract:<br>" + "<br>".join(hits), title="Placeholders found")


run(doc)

# Sales Contract, Before Cancel: the order must be cancelled first.
if doc.sales_order and frappe.db.get_value("Sales Order", doc.sales_order, "docstatus") == 1:
    frappe.throw("Cancel Sales Order %s before cancelling this contract." % doc.sales_order)

# Sales Order, Before Save: (1) an order made from a Sales Contract keeps its link and a contract has at most one live order;
# (2) fill what the production card, the packing list and the delivery gate read from each row (colour, size, buyer PO, dates,
# tolerance) when the order was typed by hand instead of made with the contract button.
def run(doc):
    def norm(x):
        return (x or "").strip().upper()

    name = doc.get("apparel_sales_contract")
    lines = []
    if name:
        sc = frappe.db.get_value("Sales Contract", name, ["docstatus", "customer", "sales_order"], as_dict=True)
        if not sc or sc.docstatus != 1:
            frappe.throw("Sales Contract %s is not signed (submitted)." % name)
        if sc.customer != doc.customer:
            frappe.throw("Sales Contract %s is for %s." % (name, sc.customer))
        if sc.sales_order and sc.sales_order != doc.name and frappe.db.get_value("Sales Order", sc.sales_order, "docstatus") != 2:
            frappe.throw("Sales Contract %s already has Sales Order %s." % (name, sc.sales_order))
        lines = frappe.get_all("Sales Contract Item", {"parent": name},
                               ["style_item", "colour", "buyer_po_code", "etd", "in_warehouse_date", "tolerance_pct", "cost_sheet"])

    colour_attr = frappe.db.get_single_value("Apparel Settings", "colour_attribute") or "Colour"
    size_attr = frappe.db.get_single_value("Apparel Settings", "size_attribute") or "Size"
    for it in doc.items:
        style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
        if not it.apparel_colour or not it.apparel_size:
            for a in frappe.get_all("Item Variant Attribute", {"parent": it.item_code}, ["attribute", "attribute_value"]):
                if a.attribute == colour_attr and not it.apparel_colour:
                    it.apparel_colour = a.attribute_value
                if a.attribute == size_attr and not it.apparel_size:
                    it.apparel_size = a.attribute_value
        if lines:
            cands = []
            for l in lines:
                if l.style_item == style and norm(l.colour) == norm(it.apparel_colour):
                    if not it.apparel_buyer_po or norm(l.buyer_po_code) == norm(it.apparel_buyer_po):
                        cands.append(l)
            if len(cands) == 1:          # only when it is unambiguous which contract line the row belongs to
                l = cands[0]
                it.apparel_buyer_po = it.apparel_buyer_po or l.buyer_po_code
                it.apparel_etd = it.apparel_etd or l.etd
                it.apparel_in_warehouse_date = it.apparel_in_warehouse_date or l.in_warehouse_date
                if it.apparel_qty_tolerance_pct is None or it.apparel_qty_tolerance_pct == 0:
                    it.apparel_qty_tolerance_pct = l.tolerance_pct
                it.apparel_cost_sheet = it.apparel_cost_sheet or l.cost_sheet


run(doc)

# Sales Order, After Submit: the contract is now Ordered and points at this order.
if doc.get("apparel_sales_contract"):
    frappe.db.set_value("Sales Contract", doc.apparel_sales_contract, {"sales_order": doc.name, "status": "Ordered"})

# Sales Order, After Cancel: the contract is Signed again and free for a new order.
if doc.get("apparel_sales_contract"):
    frappe.db.set_value("Sales Contract", doc.apparel_sales_contract, {"sales_order": None, "status": "Signed"})

# Cost Sheet, Before Save (validate): revision number, sign-off rows, the costing parameter and charge rows, material and charge checks,
# then the whole build-up: materials -> cost heads in sequence -> FOB (grossed up for price-based charges) -> margin at the quoted price.
def run(doc):
    # shared helpers: cost heads, the costing parameter that applies, and the charge rows built from it (cost_sheet.py)
    def get_cost_heads():
        return frappe.get_all("Cost Head", filters={"enabled": 1}, fields=["name", "head_group", "calc_type", "material_scope", "sequence", "is_mandatory"], order_by="sequence asc")


    def find_costing_parameter(customer, product_type, on_date, currency):
        """Most specific enabled parameter valid on the date: customer+type > customer > type > generic."""
        on = frappe.utils.getdate(on_date or frappe.utils.nowdate())
        filters = {"enabled": 1, "effective_from": ["<=", on]}
        if currency:
            filters["currency"] = currency
        rows = frappe.get_all("Costing Parameter", filters=filters, fields=["name", "customer", "product_type", "effective_from", "effective_to"], order_by="effective_from desc")
        best = None
        best_score = -1
        for r in rows:
            if r.effective_to and frappe.utils.getdate(r.effective_to) < on:
                continue
            if r.customer and r.customer != customer:
                continue
            if r.product_type and r.product_type != product_type:
                continue
            score = (2 if r.customer else 0) + (1 if r.product_type else 0)
            if score > best_score:
                best = r.name
                best_score = score
        return best


    def charge_rows(param):
        """One charge row per enabled non-material cost head, with the parameter's rates."""
        rates = {}
        if param:
            for r in frappe.get_all("Costing Parameter Rate", filters={"parent": param, "parenttype": "Costing Parameter"}, fields=["cost_head", "rate", "not_applicable"]):
                rates[r.cost_head] = r
        out = []
        for head in get_cost_heads():
            if head.calc_type == "From Materials":
                continue
            r = rates.get(head.name)
            out.append({"cost_head": head.name, "calc_type": head.calc_type, "sequence": head.sequence, "head_group": head.head_group,
                        "rate": frappe.utils.flt(r.rate) if r else 0, "not_applicable": r.not_applicable if r else 0, "source": "Parameter" if r else "Manual"})
        return out
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    COSTING_MANAGER = "Apparel Costing Manager"
    FABRIC_TYPES = ("Fabric", "Lining", "Contrast Fabric")
    SIGNOFF_STEPS = ("Fabric Cost Checked", "First Costing Done", "Second Round Checked", "Final Checked & Approved")
    METRES_PER = {"meter": 1, "metre": 1, "mtr": 1, "m": 1, "yard": 0.9144, "yd": 0.9144, "yds": 0.9144, "cm": 0.01, "inch": 0.0254, "in": 0.0254}

    def to_metres(uom):
        return METRES_PER.get((uom or "Meter").strip().lower())

    def my_roles():
        return (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))

    # ---- revision
    if doc.amended_from:
        prev = frappe.db.get_value("Cost Sheet", doc.amended_from, "revision_no") or 1
        doc.revision_no = prev + 1
    elif not doc.revision_no:
        doc.revision_no = 1
    if not doc.company:
        doc.company = frappe.db.get_value("Company", {}, "name")

    # ---- the four sign-off steps exist, in order, keeping who signed
    saved = {}
    for r in doc.signoffs:
        saved[r.step] = {"step": r.step, "signed_by": r.signed_by, "signed_on": r.signed_on, "remarks": r.remarks}
    rows = []
    for step in SIGNOFF_STEPS:
        rows.append(saved.get(step) or {"step": step})
    doc.set("signoffs", rows)

    # ---- parameter and charges
    if not doc.costing_parameter:
        doc.costing_parameter = find_costing_parameter(doc.customer, doc.product_type, doc.costing_date, doc.currency)
    if not doc.charges:
        doc.set("charges", charge_rows(doc.costing_parameter))
    # a mandatory head left out of the table is a cost left out: put the row back (rate from the parameter if it has one) so it is visible;
    # submit then asks for a rate or Not Applicable on it
    have_heads = [c.cost_head for c in doc.charges]
    for head in get_cost_heads():
        if head.is_mandatory and head.calc_type != "From Materials" and head.name not in have_heads:
            prm = frappe.db.get_value("Costing Parameter Rate", {"parent": doc.costing_parameter, "parenttype": "Costing Parameter", "cost_head": head.name}, ["rate", "not_applicable"], as_dict=True) if doc.costing_parameter else None
            doc.append("charges", {"cost_head": head.name, "rate": flt(prm.rate) if prm else 0, "not_applicable": prm.not_applicable if prm else 0, "source": "Parameter" if prm else "Manual"})

    # ---- materials
    groups = {}
    for m in doc.materials:
        if m.per_carton and not cint(doc.pcs_per_carton):
            frappe.throw("Row %s: set Pcs per Carton to cost a carton per piece." % m.idx)
        if flt(m.conversion_factor) < 0 or flt(m.exchange_rate) < 0:
            frappe.throw("Row %s: conversion factor and exchange rate cannot be negative." % m.idx)
        # the exchange rate converts ONE unit of the rate currency into the sheet currency (CNY -> USD is about 0.14, not 7.3). A currency worth
        # far less than one USD / EUR / GBP / CHF with a rate above 1 is the rate the wrong way round: it would cost the line many times over.
        if m.price_currency and m.price_currency != doc.currency and flt(m.exchange_rate) > 1 and doc.currency in ("USD", "EUR", "GBP", "CHF") and m.price_currency in ("VND", "INR", "JPY", "CNY", "HKD", "AED", "PKR", "BDT", "LKR", "THB", "IDR", "KRW"):
            frappe.throw("Row %s (%s): the exchange rate for %s is %s, which values 1 %s at more than 1 %s. Enter how many %s ONE %s is worth (about %s), not the other way round." % (m.idx, m.description, m.price_currency, flt(m.exchange_rate), m.price_currency, doc.currency, doc.currency, m.price_currency, flt(1 / flt(m.exchange_rate), 4)))
        if flt(m.wastage_pct) < 0 or flt(m.wastage_pct) >= 100:
            frappe.throw("Row %s: wastage %% must be between 0 and 100." % m.idx)
        if flt(m.wastage_pct) and not (m.wastage_reason or "").strip():
            frappe.throw("Row %s (%s): wastage %s%% needs a reason. Wastage is set per order, never by default." % (m.idx, m.description, flt(m.wastage_pct)))
        if m.option_group:
            key = m.option_group.strip().lower()
            if key not in groups:
                groups[key] = []
            groups[key].append(m)
        else:
            m.is_selected = 1
    for key in groups:
        g = groups[key]
        if len(g) > 4:
            frappe.throw("Option group %s has %s options. The maximum is 4." % (g[0].option_group, len(g)))
        selected = [r for r in g if r.is_selected]
        if len(g) > 1 and len(selected) != 1:
            frappe.throw("Option group %s: select exactly one option to price the garment (now %s)." % (g[0].option_group, len(selected)))
        if len(g) == 1:
            g[0].is_selected = 1

    # ---- charges
    seen = []
    for c in doc.charges:
        if c.cost_head in seen:
            frappe.throw("Cost head %s appears twice." % c.cost_head)
        seen.append(c.cost_head)
        head = frappe.db.get_value("Cost Head", c.cost_head, ["calc_type", "sequence", "head_group"], as_dict=True)
        c.calc_type = head.calc_type
        c.sequence = head.sequence
        c.head_group = head.head_group
        if c.calc_type == "From Materials":
            frappe.throw("%s is calculated from the materials table and cannot be a charge row." % c.cost_head)
        if c.not_applicable:
            c.rate = 0

    # ---- the maths
    fabric = 0.0
    other = 0.0
    fabric_m = 0.0
    unknown_length = False
    for m in doc.materials:
        cons = (1.0 / cint(doc.pcs_per_carton)) if m.per_carton else flt(m.consumption)
        qty = cons * (1 + flt(m.wastage_pct) / 100)
        factor = flt(m.conversion_factor) or 1
        fx = (flt(m.exchange_rate) or 1) if (m.price_currency and m.price_currency != doc.currency) else 1
        m.amount = flt(qty * factor * flt(m.rate) * fx, 6)
        if not m.is_selected:
            continue
        if m.material_type in FABRIC_TYPES:
            fabric = fabric + m.amount
            per_unit = to_metres(m.uom)
            if per_unit:
                fabric_m = fabric_m + qty * per_unit
            else:
                unknown_length = True
        else:
            other = other + m.amount
    doc.fabric_cost = flt(fabric, 6)
    doc.trim_cost = flt(other, 6)
    doc.material_cost = flt(fabric + other, 6)
    doc.fabric_metres = flt(fabric_m, 6)

    charges = sorted(doc.charges, key=lambda r: ((r.sequence or 0), r.idx))
    direct = 0.0
    for c in charges:
        rate = 0 if c.not_applicable else flt(c.rate)
        if c.calc_type == "Per Piece":
            c.amount = rate
        elif c.calc_type == "Per SAM Minute":
            c.amount = rate * flt(doc.sam)
        elif c.calc_type == "Per Metre of Fabric":
            if unknown_length:
                frappe.throw("A selected fabric row has a UOM that is not a length. Use Meter, Yard, cm or inch.")
            c.amount = rate * flt(doc.fabric_metres)
        elif c.calc_type == "Percent of Material":
            c.amount = doc.material_cost * rate / 100
        else:
            continue
        c.amount = flt(c.amount, 6)
        if c.head_group != "Profit":
            direct = direct + c.amount
    doc.product_cost = flt(doc.material_cost + direct, 6)

    running = doc.material_cost
    profit_amount = 0.0
    price_pct = 0.0
    profit_pct = 0.0
    price_rows = []
    for c in charges:
        rate = 0 if c.not_applicable else flt(c.rate)
        if c.calc_type in ("Per Piece", "Per SAM Minute", "Per Metre of Fabric", "Percent of Material"):
            pass
        elif c.calc_type == "Percent of Product Cost":
            c.amount = flt(doc.product_cost * rate / 100, 6)
        elif c.calc_type == "Percent of Subtotal":
            c.amount = flt(running * rate / 100, 6)
        elif c.calc_type == "Percent of Price":
            price_rows.append(c)
            if c.head_group == "Profit":
                profit_pct = profit_pct + rate
            else:
                price_pct = price_pct + rate
            continue
        if c.head_group == "Profit":
            profit_amount = profit_amount + c.amount
        else:
            running = running + c.amount

    doc.subtotal = flt(running, 6)
    doc.conversion_cost = flt(running - doc.material_cost, 6)
    doc.profit_amount = flt(profit_amount, 6)
    doc.price_cost_pct = price_pct
    doc.profit_pct = profit_pct
    total_pct = price_pct + profit_pct
    if total_pct >= 100:
        frappe.throw("Price-based charges add up to %s%%. They must be below 100%%." % total_pct)
    doc.computed_price = flt((doc.subtotal + doc.profit_amount) / (1 - total_pct / 100.0), 6)
    if not flt(doc.quoted_price):
        doc.quoted_price = flt(doc.computed_price, 2)
    for c in price_rows:
        c.amount = flt(flt(doc.quoted_price) * (0 if c.not_applicable else flt(c.rate)) / 100, 6)

    # margin at the quoted price: price-based charges other than profit scale with the price
    price = flt(doc.quoted_price)
    cost = flt(doc.subtotal) + price * flt(doc.price_cost_pct) / 100
    margin = price - cost
    doc.total_cost_at_quote = flt(cost, 6)
    doc.margin_amount = flt(margin, 6)
    doc.margin_pct = flt(margin / price * 100, 2) if price else 0
    doc.markup_pct = flt(margin / cost * 100, 2) if cost else 0
    floor = None
    if doc.costing_parameter:
        floor = frappe.db.get_value("Costing Parameter", doc.costing_parameter, "margin_floor_pct")
    if floor is None or floor == 0:
        floor = frappe.db.get_single_value("Apparel Settings", "default_margin_floor_pct")
    doc.margin_floor_pct = flt(floor)
    doc.below_floor = 1 if doc.margin_pct < flt(doc.margin_floor_pct) else 0
    doc.order_value = flt(doc.quoted_price) * (doc.order_qty or 0)
    if doc.local_currency and flt(doc.local_exchange_rate):
        doc.quoted_price_local = flt(flt(doc.quoted_price) * flt(doc.local_exchange_rate), 2)
    else:
        doc.quoted_price_local = 0

    # ---- approval: below the floor needs a Costing Manager; a price move after approval resets it
    if not doc.below_floor:
        if doc.approval_status == "Pending" or doc.approval_status == "Rejected":
            doc.approval_status = "Not Required"
    else:
        if doc.approval_status == "Approved":
            tol = flt(frappe.db.get_single_value("Apparel Settings", "approval_tolerance_pct"))
            old = flt(doc.approved_price)
            moved = True
            if old:
                moved = abs(flt(doc.quoted_price) - old) / old * 100 > tol
            if moved:
                doc.approval_status = "Pending"
                doc.approved_by = None
                doc.approved_on = None
                doc.approved_price = None
                frappe.msgprint("Quoted price changed after approval. Margin approval reset to Pending.", indicator="orange", alert=True)
        elif doc.approval_status == "Not Required":
            doc.approval_status = "Pending"

    # ---- advisory: lines left unpriced and BOM lines missing from this sheet. A save is never blocked by these.
    notes = []
    unpriced = [m for m in doc.materials if m.is_selected and flt(m.consumption) and not flt(m.rate)]
    if unpriced:
        names = [(u.description or u.material_type) for u in unpriced]
        notes.append("%s material line(s) have no rate and are costed at 0: %s%s." % (len(unpriced), ", ".join(names[:6]), " ..." if len(names) > 6 else ""))
    if doc.tech_pack:
        bom = len(frappe.get_all("Tech Pack Material", {"parent": doc.tech_pack, "parenttype": "Tech Pack"}, pluck="name"))
        if len(doc.materials) < bom:
            notes.append("The Tech Pack %s has %s material lines but this sheet has %s. Lines left out of a costing are costs left out of the price." % (doc.tech_pack, bom, len(doc.materials)))
    if notes:
        frappe.msgprint("<br>".join(notes), title="Check the costing", indicator="orange")


run(doc)

# Cost Sheet, Before Submit: every mandatory cost head is priced (a cost left out comes straight out of margin), the sign-off chain is
# complete when the settings ask for it, and a margin below the floor needs a Costing Manager.
def run(doc):
    # shared helpers: cost heads, the costing parameter that applies, and the charge rows built from it (cost_sheet.py)
    def get_cost_heads():
        return frappe.get_all("Cost Head", filters={"enabled": 1}, fields=["name", "head_group", "calc_type", "material_scope", "sequence", "is_mandatory"], order_by="sequence asc")


    def find_costing_parameter(customer, product_type, on_date, currency):
        """Most specific enabled parameter valid on the date: customer+type > customer > type > generic."""
        on = frappe.utils.getdate(on_date or frappe.utils.nowdate())
        filters = {"enabled": 1, "effective_from": ["<=", on]}
        if currency:
            filters["currency"] = currency
        rows = frappe.get_all("Costing Parameter", filters=filters, fields=["name", "customer", "product_type", "effective_from", "effective_to"], order_by="effective_from desc")
        best = None
        best_score = -1
        for r in rows:
            if r.effective_to and frappe.utils.getdate(r.effective_to) < on:
                continue
            if r.customer and r.customer != customer:
                continue
            if r.product_type and r.product_type != product_type:
                continue
            score = (2 if r.customer else 0) + (1 if r.product_type else 0)
            if score > best_score:
                best = r.name
                best_score = score
        return best


    def charge_rows(param):
        """One charge row per enabled non-material cost head, with the parameter's rates."""
        rates = {}
        if param:
            for r in frappe.get_all("Costing Parameter Rate", filters={"parent": param, "parenttype": "Costing Parameter"}, fields=["cost_head", "rate", "not_applicable"]):
                rates[r.cost_head] = r
        out = []
        for head in get_cost_heads():
            if head.calc_type == "From Materials":
                continue
            r = rates.get(head.name)
            out.append({"cost_head": head.name, "calc_type": head.calc_type, "sequence": head.sequence, "head_group": head.head_group,
                        "rate": frappe.utils.flt(r.rate) if r else 0, "not_applicable": r.not_applicable if r else 0, "source": "Parameter" if r else "Manual"})
        return out
    flt = frappe.utils.flt
    mine = (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))
    FABRIC_TYPES = ("Fabric", "Lining", "Contrast Fabric")

    present = {}
    for c in doc.charges:
        present[c.cost_head] = c
    missing = []
    zero = []
    for head in get_cost_heads():
        if not head.is_mandatory:
            continue
        if head.calc_type == "From Materials":
            found = False
            for m in doc.materials:
                in_fabric = m.material_type in FABRIC_TYPES
                if head.material_scope == "Fabric" and in_fabric:
                    found = True
                elif head.material_scope == "Non-Fabric" and not in_fabric:
                    found = True
                elif head.material_scope not in ("Fabric", "Non-Fabric"):
                    found = True
            if not found:
                missing.append(head.name)
            continue
        row = present.get(head.name)
        if not row:
            missing.append(head.name)
        elif not flt(row.rate) and not row.not_applicable:
            zero.append(head.name)
    if missing or zero:
        msg = []
        if missing:
            msg.append("Missing: " + ", ".join(missing))
        if zero:
            msg.append("Zero rate without N/A: " + ", ".join(zero))
        frappe.throw("<br>".join(msg), title="Cost Sheet Incomplete")

    if frappe.db.get_single_value("Apparel Settings", "require_costing_signoff"):
        open_steps = [r.step for r in doc.signoffs if not r.signed_by]
        if open_steps:
            frappe.throw("Costing sign-off incomplete. Still to sign: " + ", ".join(open_steps), title="Sign-off Required")

    if doc.below_floor and doc.approval_status != "Approved":
        if "Apparel Costing Manager" in mine:
            doc.approval_status = "Approved"
            doc.approved_by = frappe.session.user
            doc.approved_on = frappe.utils.now_datetime()
            doc.approved_price = doc.quoted_price
            if not doc.approval_remarks:
                doc.approval_remarks = "Approved at submit by Costing Manager"
        else:
            frappe.throw("Margin %s%% is below the floor of %s%%. A Costing Manager must approve this Cost Sheet before it can be submitted." % (flt(doc.margin_pct, 2), flt(doc.margin_floor_pct, 2)),
                         title="Below Margin Floor")


run(doc)

