# API arinox_cost_sheet_sign_off: record the current user against one sign-off step. Steps are signed in order; the last needs a Costing Manager.
def main():
    steps = ("Fabric Cost Checked", "First Costing Done", "Second Round Checked", "Final Checked & Approved")
    name = frappe.form_dict.get("name")
    step = frappe.form_dict.get("step")
    doc = frappe.get_doc("Cost Sheet", name)
    doc.check_permission("write")
    if doc.docstatus != 0:
        frappe.throw("Only a draft Cost Sheet can be signed off.")
    if step not in steps:
        frappe.throw("Unknown sign-off step %s." % step)
    rows = {}
    for r in doc.signoffs:
        rows[r.step] = r
    if step in rows and rows[step].signed_by:
        frappe.throw("%s is already signed by %s." % (step, rows[step].signed_by))
    for earlier in steps[:steps.index(step)]:
        if earlier not in rows or not rows[earlier].signed_by:
            frappe.throw("Sign %s first." % earlier)
    mine = (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))
    if step == steps[-1] and "Apparel Costing Manager" not in mine:
        frappe.throw("Final approval needs the Apparel Costing Manager role.")
    if step not in rows:
        doc.append("signoffs", {"step": step})
        rows[step] = doc.signoffs[-1]
    rows[step].signed_by = frappe.session.user
    rows[step].signed_on = frappe.utils.now_datetime()
    if frappe.form_dict.get("remarks"):
        rows[step].remarks = frappe.form_dict.get("remarks")
    doc.save()
    frappe.flags.arinox_result = step


main()

# Packing List, Before Save: the card must be open; carton rows are contiguous, never overlap, start at the start number and have contents;
# totals and the packed-versus-ordered summary are computed here.
def run(doc):
    # shared helpers: carton planning and the packing-list rules that need no document (production/packing.py, production/maths.py)
    def carton_cbm(length_cm, width_cm, height_cm):
        return float(length_cm) * float(width_cm) * float(height_cm) / 1000000.0


    def over_short_pct(shipped, ordered):
        o = float(ordered or 0)
        if not o:
            return None
        return (float(shipped) - o) / o * 100.0


    def full_packs(qty_by_size, ratio_by_size):
        """Complete ratio packs available: min over sizes of floor(qty / ratio)."""
        packs = None
        for size in ratio_by_size:
            r = ratio_by_size[size]
            if not r:
                continue
            n = int(frappe.utils.floor(float(qty_by_size.get(size, 0)) / float(r)))
            if packs is None or n < packs:
                packs = n
        return packs or 0


    def gs1_check_digit(body):
        """GS1 mod-10 check digit for a numeric body (the 17-digit SSCC body)."""
        digits = [int(c) for c in str(body)]
        digits.reverse()
        total = 0
        i = 0
        for d in digits:
            total = total + d * (3 if i % 2 == 0 else 1)
            i = i + 1
        return (10 - total % 10) % 10


    def sscc_number(prefix, serial):
        """18-digit SSCC: extension digit 0 + company prefix + serial padded to 17 digits, then the GS1 check digit."""
        prefix = str(prefix)
        room = 16 - len(prefix)
        if not prefix.isdigit() or len(prefix) < 7 or len(prefix) > 10:
            frappe.throw("The GS1 company prefix must be 7 to 10 digits.")
        if len(str(serial)) > room:
            frappe.throw("The SSCC serial %s no longer fits after the prefix." % serial)
        body = "0" + prefix + str(serial).zfill(room)
        return body + str(gs1_check_digit(body))


    def check_ranges(ranges):
        """ranges: [(from, to)] in any order. Problems: a row ending before it starts, overlaps, gaps."""
        problems = []
        rows = sorted([(int(r[0]), int(r[1])) for r in ranges])
        for r in rows:
            if r[1] < r[0]:
                problems.append("Carton range %s~%s ends before it starts." % (r[0], r[1]))
        for i in range(len(rows) - 1):
            a = rows[i]
            b = rows[i + 1]
            if b[0] <= a[1]:
                problems.append("Carton %s is in two rows (%s~%s and %s~%s)." % (b[0], a[0], a[1], b[0], b[1]))
            elif b[0] != a[1] + 1:
                problems.append("Cartons %s to %s are missing between %s~%s and %s~%s." % (a[1] + 1, b[0] - 1, a[0], a[1], b[0], b[1]))
        return problems


    def tail_cartons(pool, rule, capacity):
        """Fill the leftover pieces into cartons of `capacity` pieces by the tail rule. Pool items are [colour, size, qty]."""
        out = []
        if rule == "Own Carton":
            for p in pool:
                out.append([[p[0], p[1], p[2]]])
            return out
        groups = [pool]
        if rule == "Mixed Size Only":
            by = {}
            order = []
            for p in pool:
                if p[0] not in by:
                    by[p[0]] = []
                    order.append(p[0])
                by[p[0]].append(p)
            groups = [by[c] for c in order]
        for group in groups:
            cur = []
            room = capacity
            for p in group:
                q = p[2]
                while q > 0:
                    take = min(q, room)
                    cur.append([p[0], p[1], take])
                    q = q - take
                    room = room - take
                    if room == 0:
                        out.append(cur)
                        cur = []
                        room = capacity
            if cur:
                out.append(cur)
        return out


    def plan_cartons(items, pack_type, pcs_per_carton, ratio, tail_rule, start):
        """items: [[colour, size, pieces]] in packing order; ratio: {size: pieces per pack}.
        Returns rows {carton_from, carton_to, tail, pieces_per_carton, contents: [[colour, size, qty_per_carton]]}."""
        cap = int(pcs_per_carton or 0)
        if cap <= 0:
            frappe.throw("Pieces per carton must be above zero.")
        full = []
        pool = []
        items = [[i[0], i[1], int(i[2])] for i in items if int(i[2]) > 0]
        if pack_type == "Solid Colour Solid Size":
            for i in items:
                n = i[2] // cap
                rem = i[2] % cap
                if n:
                    full.append([[[i[0], i[1], cap]], n])
                if rem:
                    pool.append([i[0], i[1], rem])
        elif pack_type == "Solid Colour Assorted Size":
            ratio = dict([(s, int(ratio[s])) for s in (ratio or {}) if int(ratio[s])])
            if not ratio:
                frappe.throw("Enter the ratio for assorted packs.")
            pack = sum([ratio[s] for s in ratio])
            if cap % pack:
                frappe.throw("Pieces per carton (%s) must be a multiple of the pack size (%s)." % (cap, pack))
            per_carton = cap // pack
            colours = []
            for i in items:
                if i[0] not in colours:
                    colours.append(i[0])
            for c in colours:
                by_size = {}
                for i in items:
                    if i[0] == c:
                        by_size[i[1]] = i[2]
                cartons = full_packs(by_size, ratio) // per_carton
                if cartons:
                    full.append([[[c, s, ratio[s] * per_carton] for s in ratio], cartons])
                for i in items:
                    if i[0] == c:
                        used = cartons * per_carton * ratio.get(i[1], 0)
                        if i[2] - used > 0:
                            pool.append([c, i[1], i[2] - used])
        elif pack_type == "Assorted":
            pool = items
        else:
            frappe.throw("Unknown pack type %s." % pack_type)
        rows = []
        n = int(start)
        for f in full:
            rows.append({"carton_from": n, "carton_to": n + f[1] - 1, "tail": 0, "pieces_per_carton": sum([c[2] for c in f[0]]), "contents": f[0]})
            n = n + f[1]
        tail_flag = 0 if pack_type == "Assorted" else 1
        for contents in tail_cartons(pool, (tail_rule or "Mixed Colour and Size") if pack_type != "Assorted" else "Mixed Colour and Size", cap):
            rows.append({"carton_from": n, "carton_to": n, "tail": tail_flag, "pieces_per_carton": sum([c[2] for c in contents]), "contents": contents})
            n = n + 1
        return rows


    def size_summary(packed, ordered):
        """Lines 'colour size: packed / ordered (+x %)' and the total, like the company's OVERAGES / SHORTAGES rows."""
        lines = []
        tp = 0
        to = 0
        for key in sorted(set(packed) | set(ordered)):
            p = packed.get(key, 0)
            o = ordered.get(key, 0)
            tp = tp + p
            to = to + o
            pc = over_short_pct(p, o)
            lines.append("%s %s: %s / %s" % (key[0], key[1], int(p), int(o)) + ((" (%+.2f %%)" % pc) if pc is not None else ""))
        total = over_short_pct(tp, to)
        lines.append("Total: %s / %s" % (int(tp), int(to)) + ((" (%+.2f %%)" % total) if total is not None else ""))
        return ["\n".join(lines), total]


    def packed_by_key(card, exclude, states, ship_to):
        """Pieces on other packing lists of the card by (colour, size). states: docstatus values to count."""
        cond = " and p.ship_to = %(ship_to)s" if ship_to else ""
        rows = frappe.db.sql(
            "select c.colour, c.size, sum(c.pieces_total) from `tabPacking List Content` c join `tabPacking List` p on p.name = c.parent "
            "where p.production_card = %(card)s and p.docstatus in %(states)s and p.name != %(exclude)s" + cond + " group by c.colour, c.size",
            {"card": card, "states": tuple(states), "exclude": exclude or "", "ship_to": ship_to})
        out = {}
        for r in rows:
            out[(r[0], r[1])] = r[2] or 0
        return out
    cint = frappe.utils.cint
    flt = frappe.utils.flt

    card = frappe.db.get_value("Production Card", doc.production_card, ["sales_order", "sales_contract", "customer", "style_item", "status", "docstatus"], as_dict=True)
    if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
        frappe.throw("Production card %s must be issued and open." % doc.production_card)
    doc.sales_contract = card.sales_contract
    doc.sales_order = card.sales_order
    doc.customer = card.customer
    doc.style_item = card.style_item
    if not cint(doc.pcs_per_carton) or cint(doc.pcs_per_carton) <= 0:
        frappe.throw("Enter the pieces per carton.")

    default = None
    if doc.carton_type:
        default = frappe.db.get_value("Shipment Parcel Template", doc.carton_type, ["length", "width", "height"], as_dict=True)
    for c in doc.cartons:
        if default and not (flt(c.length_cm) and flt(c.width_cm) and flt(c.height_cm)):
            c.length_cm = default.length
            c.width_cm = default.width
            c.height_cm = default.height
        if not c.carton_type:
            c.carton_type = doc.carton_type

    if doc.cartons or doc.docstatus == 1:
        if not doc.cartons:
            frappe.throw("Add the cartons, or use Generate Cartons.")
        problems = check_ranges([[c.carton_from, c.carton_to] for c in doc.cartons])
        first = min([cint(c.carton_from) for c in doc.cartons])
        if first != cint(doc.carton_start or 1):
            problems.append("Cartons must start at %s." % cint(doc.carton_start or 1))
        if problems:
            frappe.throw("<br>".join(problems), title="Carton numbers")
        for c in doc.cartons:
            c.carton_count = cint(c.carton_to) - cint(c.carton_from) + 1
            c.cbm_per_carton = round(carton_cbm(c.length_cm or 0, c.width_cm or 0, c.height_cm or 0), 6)
            c.total_cbm = round(c.cbm_per_carton * c.carton_count, 6)

        items = frappe.get_all("Sales Order Item", {"parent": doc.sales_order}, ["name", "item_code", "apparel_colour", "apparel_size", "apparel_ship_to", "apparel_buyer_po"])
        on_card = []
        for l in frappe.get_all("Production Card Line", {"parent": doc.production_card}, ["colour", "size"]):
            on_card.append((l.colour, l.size))
        by_row = {}
        for ct in doc.contents:
            ct.qty_per_carton = cint(ct.qty_per_carton)
            if ct.qty_per_carton <= 0:
                frappe.throw("Carton content row %s: enter a quantity above zero." % ct.idx)
            if (ct.colour, ct.size) not in on_card:
                frappe.throw("Carton content row %s: %s %s is not on production card %s." % (ct.idx, ct.colour, ct.size, doc.production_card))
            cands = [i for i in items if i.apparel_colour == ct.colour and i.apparel_size == ct.size]
            if doc.style_item and len([i for i in cands if (frappe.db.get_value("Item", i.item_code, "variant_of") or i.item_code) == doc.style_item]):
                cands = [i for i in cands if (frappe.db.get_value("Item", i.item_code, "variant_of") or i.item_code) == doc.style_item]     # two styles on one order can share a colour and size
            if doc.ship_to and [i for i in cands if i.apparel_ship_to]:
                cands = [i for i in cands if (i.apparel_ship_to or "") == doc.ship_to]
            if doc.buyer_po and [i for i in cands if i.apparel_buyer_po]:
                cands = [i for i in cands if (i.apparel_buyer_po or "") == doc.buyer_po]
            if not cands:
                frappe.throw("%s %s (ship to %s) is not on Sales Order %s." % (ct.colour, ct.size, doc.ship_to or "-", doc.sales_order))
            ct.sales_order_item = cands[0].name
            by_row[cint(ct.carton_from)] = by_row.get(cint(ct.carton_from), 0) + ct.qty_per_carton
        for c in doc.cartons:
            got = by_row.get(cint(c.carton_from), 0)
            if not got:
                frappe.throw("Cartons %s~%s have no contents." % (c.carton_from, c.carton_to))
            c.pieces_per_carton = got
            c.total_pieces = got * c.carton_count
        known = [cint(c.carton_from) for c in doc.cartons]
        for k in by_row:
            if k not in known:
                frappe.throw("Contents point at carton row %s, which does not exist." % k)
        for ct in doc.contents:
            for c in doc.cartons:
                if cint(c.carton_from) == cint(ct.carton_from):
                    ct.pieces_total = ct.qty_per_carton * c.carton_count

    doc.total_cartons = sum([c.carton_count or 0 for c in doc.cartons])
    doc.total_pieces = sum([c.total_pieces or 0 for c in doc.cartons])
    doc.total_net_kg = round(sum([flt(c.net_weight_kg) * (c.carton_count or 0) for c in doc.cartons]), 3)
    doc.total_gross_kg = round(sum([flt(c.gross_weight_kg) * (c.carton_count or 0) for c in doc.cartons]), 3)
    doc.total_cbm = round(sum([c.total_cbm or 0 for c in doc.cartons]), 6)

    packed = packed_by_key(doc.production_card, doc.name, [0, 1], None)
    for ct in doc.contents:
        k = (ct.colour, ct.size)
        packed[k] = packed.get(k, 0) + cint(ct.pieces_total)
    ordered = {}
    on_lines = []
    for l in frappe.get_all("Production Card Line", {"parent": doc.production_card}, ["colour", "size"]):
        on_lines.append((l.colour, l.size))
    for i in frappe.get_all("Sales Order Item", {"parent": doc.sales_order}, ["apparel_colour", "apparel_size", "qty"]):
        k = (i.apparel_colour, i.apparel_size)
        if k in on_lines:
            ordered[k] = ordered.get(k, 0) + flt(i.qty)
    summary = size_summary(packed, ordered)
    doc.size_summary = summary[0]
    doc.total_vs_order_pct = summary[1]


run(doc)

# Packing List, Before Submit: every carton row has a gross weight (net not above gross), a heavy carton warns, and a failed or missing
# needle-detector check blocks packing (or warns) as the settings say.
def run(doc):
    flt = frappe.utils.flt
    if not doc.cartons:
        frappe.throw("Add the cartons, or use Generate Cartons.")
    for c in doc.cartons:
        if flt(c.gross_weight_kg) <= 0:
            frappe.throw("Enter the gross weight of every carton row (row %s)." % c.idx)
    maxkg = flt(frappe.db.get_single_value("Apparel Settings", "carton_max_gross_kg") or 0)
    for c in doc.cartons:
        if flt(c.net_weight_kg) > flt(c.gross_weight_kg):
            frappe.throw("Carton row %s: net weight is more than gross." % c.idx)
        if maxkg and flt(c.gross_weight_kg) > maxkg:
            frappe.msgprint("Carton row %s: %s kg gross is above the %s kg limit." % (c.idx, c.gross_weight_kg, maxkg), indicator="orange")

    mode = frappe.db.get_single_value("Apparel Settings", "needle_check_required") or "Off"
    if mode != "Off":
        line = frappe.db.get_value("Production Card", doc.production_card, "line")
        day = frappe.utils.getdate(doc.packing_date)
        problems = []
        base = {"line": line} if line else {}
        passed = dict(base)
        passed["check_date"] = day
        passed["result"] = "Pass"
        if not frappe.db.exists("Needle Detector Log", passed):
            problems.append("No passing needle detector check is logged for %s on %s." % (line or "any line", day))
        failed_filter = dict(base)
        failed_filter["result"] = "Fail"
        failed_filter["rescan_done"] = 0
        failed_filter["check_date"] = [">=", frappe.utils.add_days(day, -7)]
        failed = frappe.get_all("Needle Detector Log", failed_filter, pluck="name")
        if failed:
            problems.append("Failed detector check(s) %s have no re-scan logged." % ", ".join(failed))
        if problems:
            if mode == "Block":
                frappe.throw("<br>".join(problems), title="Needle detector")
            frappe.msgprint("<br>".join(problems), indicator="orange", title="Needle detector")


run(doc)

# Packing List, After Submit: PACKED goes to the production ledger (checked against what finishing passed as A-grade), one SSCC per carton from a
# counter that never goes back, and a draft Material Receipt of the packed pieces into Finished Goods so the Delivery Note has stock.
def run(doc):
    # shared helpers: carton planning and the packing-list rules that need no document (production/packing.py, production/maths.py)
    def carton_cbm(length_cm, width_cm, height_cm):
        return float(length_cm) * float(width_cm) * float(height_cm) / 1000000.0


    def over_short_pct(shipped, ordered):
        o = float(ordered or 0)
        if not o:
            return None
        return (float(shipped) - o) / o * 100.0


    def full_packs(qty_by_size, ratio_by_size):
        """Complete ratio packs available: min over sizes of floor(qty / ratio)."""
        packs = None
        for size in ratio_by_size:
            r = ratio_by_size[size]
            if not r:
                continue
            n = int(frappe.utils.floor(float(qty_by_size.get(size, 0)) / float(r)))
            if packs is None or n < packs:
                packs = n
        return packs or 0


    def gs1_check_digit(body):
        """GS1 mod-10 check digit for a numeric body (the 17-digit SSCC body)."""
        digits = [int(c) for c in str(body)]
        digits.reverse()
        total = 0
        i = 0
        for d in digits:
            total = total + d * (3 if i % 2 == 0 else 1)
            i = i + 1
        return (10 - total % 10) % 10


    def sscc_number(prefix, serial):
        """18-digit SSCC: extension digit 0 + company prefix + serial padded to 17 digits, then the GS1 check digit."""
        prefix = str(prefix)
        room = 16 - len(prefix)
        if not prefix.isdigit() or len(prefix) < 7 or len(prefix) > 10:
            frappe.throw("The GS1 company prefix must be 7 to 10 digits.")
        if len(str(serial)) > room:
            frappe.throw("The SSCC serial %s no longer fits after the prefix." % serial)
        body = "0" + prefix + str(serial).zfill(room)
        return body + str(gs1_check_digit(body))


    def check_ranges(ranges):
        """ranges: [(from, to)] in any order. Problems: a row ending before it starts, overlaps, gaps."""
        problems = []
        rows = sorted([(int(r[0]), int(r[1])) for r in ranges])
        for r in rows:
            if r[1] < r[0]:
                problems.append("Carton range %s~%s ends before it starts." % (r[0], r[1]))
        for i in range(len(rows) - 1):
            a = rows[i]
            b = rows[i + 1]
            if b[0] <= a[1]:
                problems.append("Carton %s is in two rows (%s~%s and %s~%s)." % (b[0], a[0], a[1], b[0], b[1]))
            elif b[0] != a[1] + 1:
                problems.append("Cartons %s to %s are missing between %s~%s and %s~%s." % (a[1] + 1, b[0] - 1, a[0], a[1], b[0], b[1]))
        return problems


    def tail_cartons(pool, rule, capacity):
        """Fill the leftover pieces into cartons of `capacity` pieces by the tail rule. Pool items are [colour, size, qty]."""
        out = []
        if rule == "Own Carton":
            for p in pool:
                out.append([[p[0], p[1], p[2]]])
            return out
        groups = [pool]
        if rule == "Mixed Size Only":
            by = {}
            order = []
            for p in pool:
                if p[0] not in by:
                    by[p[0]] = []
                    order.append(p[0])
                by[p[0]].append(p)
            groups = [by[c] for c in order]
        for group in groups:
            cur = []
            room = capacity
            for p in group:
                q = p[2]
                while q > 0:
                    take = min(q, room)
                    cur.append([p[0], p[1], take])
                    q = q - take
                    room = room - take
                    if room == 0:
                        out.append(cur)
                        cur = []
                        room = capacity
            if cur:
                out.append(cur)
        return out


    def plan_cartons(items, pack_type, pcs_per_carton, ratio, tail_rule, start):
        """items: [[colour, size, pieces]] in packing order; ratio: {size: pieces per pack}.
        Returns rows {carton_from, carton_to, tail, pieces_per_carton, contents: [[colour, size, qty_per_carton]]}."""
        cap = int(pcs_per_carton or 0)
        if cap <= 0:
            frappe.throw("Pieces per carton must be above zero.")
        full = []
        pool = []
        items = [[i[0], i[1], int(i[2])] for i in items if int(i[2]) > 0]
        if pack_type == "Solid Colour Solid Size":
            for i in items:
                n = i[2] // cap
                rem = i[2] % cap
                if n:
                    full.append([[[i[0], i[1], cap]], n])
                if rem:
                    pool.append([i[0], i[1], rem])
        elif pack_type == "Solid Colour Assorted Size":
            ratio = dict([(s, int(ratio[s])) for s in (ratio or {}) if int(ratio[s])])
            if not ratio:
                frappe.throw("Enter the ratio for assorted packs.")
            pack = sum([ratio[s] for s in ratio])
            if cap % pack:
                frappe.throw("Pieces per carton (%s) must be a multiple of the pack size (%s)." % (cap, pack))
            per_carton = cap // pack
            colours = []
            for i in items:
                if i[0] not in colours:
                    colours.append(i[0])
            for c in colours:
                by_size = {}
                for i in items:
                    if i[0] == c:
                        by_size[i[1]] = i[2]
                cartons = full_packs(by_size, ratio) // per_carton
                if cartons:
                    full.append([[[c, s, ratio[s] * per_carton] for s in ratio], cartons])
                for i in items:
                    if i[0] == c:
                        used = cartons * per_carton * ratio.get(i[1], 0)
                        if i[2] - used > 0:
                            pool.append([c, i[1], i[2] - used])
        elif pack_type == "Assorted":
            pool = items
        else:
            frappe.throw("Unknown pack type %s." % pack_type)
        rows = []
        n = int(start)
        for f in full:
            rows.append({"carton_from": n, "carton_to": n + f[1] - 1, "tail": 0, "pieces_per_carton": sum([c[2] for c in f[0]]), "contents": f[0]})
            n = n + f[1]
        tail_flag = 0 if pack_type == "Assorted" else 1
        for contents in tail_cartons(pool, (tail_rule or "Mixed Colour and Size") if pack_type != "Assorted" else "Mixed Colour and Size", cap):
            rows.append({"carton_from": n, "carton_to": n, "tail": tail_flag, "pieces_per_carton": sum([c[2] for c in contents]), "contents": contents})
            n = n + 1
        return rows


    def size_summary(packed, ordered):
        """Lines 'colour size: packed / ordered (+x %)' and the total, like the company's OVERAGES / SHORTAGES rows."""
        lines = []
        tp = 0
        to = 0
        for key in sorted(set(packed) | set(ordered)):
            p = packed.get(key, 0)
            o = ordered.get(key, 0)
            tp = tp + p
            to = to + o
            pc = over_short_pct(p, o)
            lines.append("%s %s: %s / %s" % (key[0], key[1], int(p), int(o)) + ((" (%+.2f %%)" % pc) if pc is not None else ""))
        total = over_short_pct(tp, to)
        lines.append("Total: %s / %s" % (int(tp), int(to)) + ((" (%+.2f %%)" % total) if total is not None else ""))
        return ["\n".join(lines), total]


    def packed_by_key(card, exclude, states, ship_to):
        """Pieces on other packing lists of the card by (colour, size). states: docstatus values to count."""
        cond = " and p.ship_to = %(ship_to)s" if ship_to else ""
        rows = frappe.db.sql(
            "select c.colour, c.size, sum(c.pieces_total) from `tabPacking List Content` c join `tabPacking List` p on p.name = c.parent "
            "where p.production_card = %(card)s and p.docstatus in %(states)s and p.name != %(exclude)s" + cond + " group by c.colour, c.size",
            {"card": card, "states": tuple(states), "exclude": exclude or "", "ship_to": ship_to})
        out = {}
        for r in rows:
            out[(r[0], r[1])] = r[2] or 0
        return out
    cint = frappe.utils.cint
    flt = frappe.utils.flt
    sums = {}
    for ct in doc.contents:
        k = ct.colour + "\t" + ct.size
        sums[k] = sums.get(k, 0) + cint(ct.pieces_total)
    rows = []
    for k in sums:
        parts = k.split("\t")
        rows.append({"stage": "PACKED", "colour": parts[0], "size": parts[1], "qty": sums[k]})
    run_script("arinox_engine", action="post", card=doc.production_card, rows=json.dumps(rows), source_doctype="Packing List", source_name=doc.name,
               posting_date=str(doc.packing_date), check="1")

    prefix = frappe.db.get_single_value("Apparel Settings", "gs1_company_prefix")
    if prefix:
        idx = 0
        for c in doc.cartons:
            for n in range(cint(c.carton_from), cint(c.carton_to) + 1):
                series = "SSCC-" + str(prefix) + "-"
                drawn = frappe.get_doc({"doctype": "Arinox Number", "prefix": series}).insert(ignore_permissions=True)
                serial = int(drawn.name[len(series):])
                idx = idx + 1
                frappe.get_doc({"doctype": "Packing List SSCC", "parent": doc.name, "parenttype": "Packing List", "parentfield": "sscc", "idx": idx,
                                "carton_no": n, "sscc": sscc_number(prefix, serial)}).insert(ignore_permissions=True)

    receive = frappe.db.get_single_value("Apparel Settings", "post_fg_receipt")
    if receive is None or receive == "":
        receive = 1
    wh = frappe.db.get_single_value("Apparel Settings", "fg_warehouse")
    if cint(receive) and wh:
        items = frappe.get_all("Sales Order Item", {"parent": doc.sales_order}, ["name", "item_code", "rate", "apparel_cost_sheet"])
        by_name = {}
        for i in items:
            by_name[i.name] = i
        qty = {}
        rate = {}
        for ct in doc.contents:
            i = by_name.get(ct.sales_order_item)
            if not i:
                continue
            qty[i.item_code] = qty.get(i.item_code, 0) + cint(ct.pieces_total)
            cost = frappe.db.get_value("Cost Sheet", i.apparel_cost_sheet, "product_cost") if i.apparel_cost_sheet else None
            rate[i.item_code] = flt(cost) or flt(frappe.db.get_value("Item", i.item_code, "valuation_rate")) or flt(i.rate)
        if qty:
            try:
                se = frappe.new_doc("Stock Entry")
                se.stock_entry_type = "Material Receipt"
                se.purpose = "Material Receipt"
                se.company = frappe.db.get_value("Production Card", doc.production_card, "company")
                se.apparel_production_card = doc.production_card
                se.apparel_issue_kind = "Finished Goods Receipt"
                for code in qty:
                    se.append("items", {"item_code": code, "qty": qty[code], "t_warehouse": wh, "basic_rate": rate[code], "allow_zero_valuation_rate": 0 if rate[code] else 1})
                se.remarks = "Packed on %s. Rate from the Cost Sheet cost (or the order rate when none): check before submitting." % doc.name
                se.insert(ignore_permissions=True)
                if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_stock_entries")):
                    se.submit()
                doc.db_set("fg_stock_entry", se.name)
            except Exception:
                frappe.msgprint("The finished-goods receipt could not be drafted. Packing itself is saved.", indicator="orange")
    elif cint(receive):
        frappe.msgprint("Set the Finished Goods warehouse in Apparel Settings to receive packed pieces into stock.", indicator="orange")


run(doc)

# Packing List, Before Cancel: not while it is on a shipment or used by a submitted Delivery Note.
if doc.shipment:
    frappe.throw("%s is on shipment %s. Remove it from the shipment first." % (doc.name, doc.shipment))
if frappe.db.exists("Delivery Note Item", {"apparel_packing_list": doc.name, "docstatus": 1}):
    frappe.throw("A submitted Delivery Note uses this packing list.")
lots = frappe.get_all("Final Inspection Lot", {"packing_list": doc.name}, pluck="parent")
if lots and frappe.db.exists("Final Inspection", {"name": ["in", lots], "docstatus": 1, "result": ["in", ["Accepted", "Accepted with Concession"]]}):
    frappe.msgprint("An accepted final inspection covers this list; a new inspection is needed after repacking.", indicator="orange")

# Packing List, After Cancel: take PACKED out of the ledger and cancel the finished-goods receipt. SSCC numbers already drawn stay retired.
run_script("arinox_engine", action="unpost", source_doctype="Packing List", source_name=doc.name)
if doc.fg_stock_entry:
    se = frappe.get_doc("Stock Entry", doc.fg_stock_entry)
    if se.docstatus == 1:
