# API arinox_packing_list_generate_cartons: the carton rows and contents for an unsaved Packing List (form sends it as JSON in `doc`).
# `quantities` ({"colour|size": pieces}) overrides what is packable; otherwise everything finished into A-grade and not yet packed is used.
def main():
    # shared helpers: carton planning and the packing-list rules that need no document (production/packing.py, production/maths.py)
    def carton_cbm(length_cm, width_cm, height_cm):
        return float(length_cm) * float(width_cm) * float(height_cm) / 1000000.0


    def over_short_pct(shipped, ordered):
        o = float(ordered or 0)
        if not o:
            return None
        return (float(shipped) - o) / o * 100.0


    def full_packs(qty_by_size, ratio_by_size):
        """Complete ratio packs available: min over sizes of floor(qty / ratio)."""
        packs = None
        for size in ratio_by_size:
            r = ratio_by_size[size]
            if not r:
                continue
            n = int(frappe.utils.floor(float(qty_by_size.get(size, 0)) / float(r)))
            if packs is None or n < packs:
                packs = n
        return packs or 0


    def gs1_check_digit(body):
        """GS1 mod-10 check digit for a numeric body (the 17-digit SSCC body)."""
        digits = [int(c) for c in str(body)]
        digits.reverse()
        total = 0
        i = 0
        for d in digits:
            total = total + d * (3 if i % 2 == 0 else 1)
            i = i + 1
        return (10 - total % 10) % 10


    def sscc_number(prefix, serial):
        """18-digit SSCC: extension digit 0 + company prefix + serial padded to 17 digits, then the GS1 check digit."""
        prefix = str(prefix)
        room = 16 - len(prefix)
        if not prefix.isdigit() or len(prefix) < 7 or len(prefix) > 10:
            frappe.throw("The GS1 company prefix must be 7 to 10 digits.")
        if len(str(serial)) > room:
            frappe.throw("The SSCC serial %s no longer fits after the prefix." % serial)
        body = "0" + prefix + str(serial).zfill(room)
        return body + str(gs1_check_digit(body))


    def check_ranges(ranges):
        """ranges: [(from, to)] in any order. Problems: a row ending before it starts, overlaps, gaps."""
        problems = []
        rows = sorted([(int(r[0]), int(r[1])) for r in ranges])
        for r in rows:
            if r[1] < r[0]:
                problems.append("Carton range %s~%s ends before it starts." % (r[0], r[1]))
        for i in range(len(rows) - 1):
            a = rows[i]
            b = rows[i + 1]
            if b[0] <= a[1]:
                problems.append("Carton %s is in two rows (%s~%s and %s~%s)." % (b[0], a[0], a[1], b[0], b[1]))
            elif b[0] != a[1] + 1:
                problems.append("Cartons %s to %s are missing between %s~%s and %s~%s." % (a[1] + 1, b[0] - 1, a[0], a[1], b[0], b[1]))
        return problems


    def tail_cartons(pool, rule, capacity):
        """Fill the leftover pieces into cartons of `capacity` pieces by the tail rule. Pool items are [colour, size, qty]."""
        out = []
        if rule == "Own Carton":
            for p in pool:
                out.append([[p[0], p[1], p[2]]])
            return out
        groups = [pool]
        if rule == "Mixed Size Only":
            by = {}
            order = []
            for p in pool:
                if p[0] not in by:
                    by[p[0]] = []
                    order.append(p[0])
                by[p[0]].append(p)
            groups = [by[c] for c in order]
        for group in groups:
            cur = []
            room = capacity
            for p in group:
                q = p[2]
                while q > 0:
                    take = min(q, room)
                    cur.append([p[0], p[1], take])
                    q = q - take
                    room = room - take
                    if room == 0:
                        out.append(cur)
                        cur = []
                        room = capacity
            if cur:
                out.append(cur)
        return out


    def plan_cartons(items, pack_type, pcs_per_carton, ratio, tail_rule, start):
        """items: [[colour, size, pieces]] in packing order; ratio: {size: pieces per pack}.
        Returns rows {carton_from, carton_to, tail, pieces_per_carton, contents: [[colour, size, qty_per_carton]]}."""
        cap = int(pcs_per_carton or 0)
        if cap <= 0:
            frappe.throw("Pieces per carton must be above zero.")
        full = []
        pool = []
        items = [[i[0], i[1], int(i[2])] for i in items if int(i[2]) > 0]
        if pack_type == "Solid Colour Solid Size":
            for i in items:
                n = i[2] // cap
                rem = i[2] % cap
                if n:
                    full.append([[[i[0], i[1], cap]], n])
                if rem:
                    pool.append([i[0], i[1], rem])
        elif pack_type == "Solid Colour Assorted Size":
            ratio = dict([(s, int(ratio[s])) for s in (ratio or {}) if int(ratio[s])])
            if not ratio:
                frappe.throw("Enter the ratio for assorted packs.")
            pack = sum([ratio[s] for s in ratio])
            if cap % pack:
                frappe.throw("Pieces per carton (%s) must be a multiple of the pack size (%s)." % (cap, pack))
            per_carton = cap // pack
            colours = []
            for i in items:
                if i[0] not in colours:
                    colours.append(i[0])
            for c in colours:
                by_size = {}
                for i in items:
                    if i[0] == c:
                        by_size[i[1]] = i[2]
                cartons = full_packs(by_size, ratio) // per_carton
                if cartons:
                    full.append([[[c, s, ratio[s] * per_carton] for s in ratio], cartons])
                for i in items:
                    if i[0] == c:
                        used = cartons * per_carton * ratio.get(i[1], 0)
                        if i[2] - used > 0:
                            pool.append([c, i[1], i[2] - used])
        elif pack_type == "Assorted":
            pool = items
        else:
            frappe.throw("Unknown pack type %s." % pack_type)
        rows = []
        n = int(start)
        for f in full:
            rows.append({"carton_from": n, "carton_to": n + f[1] - 1, "tail": 0, "pieces_per_carton": sum([c[2] for c in f[0]]), "contents": f[0]})
            n = n + f[1]
        tail_flag = 0 if pack_type == "Assorted" else 1
        for contents in tail_cartons(pool, (tail_rule or "Mixed Colour and Size") if pack_type != "Assorted" else "Mixed Colour and Size", cap):
            rows.append({"carton_from": n, "carton_to": n, "tail": tail_flag, "pieces_per_carton": sum([c[2] for c in contents]), "contents": contents})
            n = n + 1
        return rows


    def size_summary(packed, ordered):
        """Lines 'colour size: packed / ordered (+x %)' and the total, like the company's OVERAGES / SHORTAGES rows."""
        lines = []
        tp = 0
        to = 0
        for key in sorted(set(packed) | set(ordered)):
            p = packed.get(key, 0)
            o = ordered.get(key, 0)
            tp = tp + p
            to = to + o
            pc = over_short_pct(p, o)
            lines.append("%s %s: %s / %s" % (key[0], key[1], int(p), int(o)) + ((" (%+.2f %%)" % pc) if pc is not None else ""))
        total = over_short_pct(tp, to)
        lines.append("Total: %s / %s" % (int(tp), int(to)) + ((" (%+.2f %%)" % total) if total is not None else ""))
        return ["\n".join(lines), total]


    def packed_by_key(card, exclude, states, ship_to):
        """Pieces on other packing lists of the card by (colour, size). states: docstatus values to count."""
        cond = " and p.ship_to = %(ship_to)s" if ship_to else ""
        rows = frappe.db.sql(
            "select c.colour, c.size, sum(c.pieces_total) from `tabPacking List Content` c join `tabPacking List` p on p.name = c.parent "
            "where p.production_card = %(card)s and p.docstatus in %(states)s and p.name != %(exclude)s" + cond + " group by c.colour, c.size",
            {"card": card, "states": tuple(states), "exclude": exclude or "", "ship_to": ship_to})
        out = {}
        for r in rows:
            out[(r[0], r[1])] = r[2] or 0
        return out
    cint = frappe.utils.cint
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    if cint(d.get("docstatus")):
        frappe.throw("Only a draft can be regenerated.")
    items = []
    given = frappe.form_dict.get("quantities")
    if given:
        q = json.loads(given) if isinstance(given, str) else given
        for k in q:
            parts = k.split("|", 1)
            items.append([parts[0], parts[1], cint(q[k])])
    else:
        card = d.get("production_card")
        res = run_script("arinox_engine", action="totals", card=card)
        t = res.get("arinox_result") or {}
        drafts = packed_by_key(card, d.get("name"), [0], None)
        others = packed_by_key(card, d.get("name"), [0, 1], d.get("ship_to"))
        so = frappe.db.get_value("Production Card", card, "sales_order")
        so_items = frappe.get_all("Sales Order Item", {"parent": so}, ["apparel_colour", "apparel_size", "apparel_ship_to", "qty", "apparel_qty_tolerance_pct"])
        for l in frappe.get_all("Production Card Line", {"parent": card}, ["colour", "size"], order_by="idx"):
            key = (l.colour, l.size)
            base = l.colour + "|" + l.size + "|"
            avail = t.get(base + "FIN_A", 0) - t.get(base + "SAMPLE_OUT", 0) - t.get(base + "PACKED", 0) - drafts.get(key, 0)
            rows = [i for i in so_items if i.apparel_colour == l.colour and i.apparel_size == l.size and (not d.get("ship_to") or not i.apparel_ship_to or i.apparel_ship_to == d.get("ship_to"))]
            if rows:
                cap = sum([int(frappe.utils.floor(round(float(i.qty or 0) * (1 + float(i.apparel_qty_tolerance_pct or 0) / 100.0), 6))) for i in rows])
                avail = min(avail, cap - others.get(key, 0))
            if avail > 0:
                items.append([l.colour, l.size, int(avail)])
    if not items:
        frappe.throw("Nothing is available to pack: finish pieces into A-grade first.")
    ratio = {}
    for r in d.get("ratios") or []:
        ratio[r.get("size")] = cint(r.get("pieces_per_pack"))
    plan = plan_cartons(items, d.get("pack_type"), cint(d.get("pcs_per_carton")), ratio, d.get("tail_carton_rule"), cint(d.get("carton_start") or 1))
    cartons = []
    contents = []
    for row in plan:
        cartons.append({"carton_from": row["carton_from"], "carton_to": row["carton_to"], "tail": row["tail"], "carton_type": d.get("carton_type")})
        for c in row["contents"]:
            contents.append({"carton_from": row["carton_from"], "colour": c[0], "size": c[1], "qty_per_carton": c[2]})
    frappe.flags.arinox_result = {"arinox_doc": {"cartons": cartons, "contents": contents}, "rows": len(plan), "plan": plan}


main()

# API arinox_scripts_switch  (state = off | on | status): the kill switch. Turns every Arinox RULE script off or on in one call, so a faulty
# script can be stopped without server access. The naming scripts, the ledger engine and this switch stay on: without them the numbered
# documents could not even be created, and a document-event script that is off simply stops enforcing its rule.
# Needs System Manager or Script Manager. Also possible by hand: Server Script list -> select -> Disable.
def main():
    mine = frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
    if frappe.session.user != "Administrator" and "System Manager" not in mine and "Script Manager" not in mine:
        frappe.throw("Only a System Manager or Script Manager can use the kill switch.")
    state = frappe.form_dict.get("state") or "status"
    if state not in ("off", "on", "status"):
        frappe.throw("state must be off, on or status.")
    keep = ("arinox_engine", "arinox_scripts_switch")
    rules = []
    for r in frappe.get_all("Server Script", {"name": ["like", "arinox_%"]}, ["name", "disabled"]):
        if r.name in keep or r.name.startswith("arinox_naming_"):
            continue
        rules.append(r)
    if state != "status":
        want = 1 if state == "off" else 0
        for r in rules:
            if r.disabled != want:
                doc = frappe.get_doc("Server Script", r.name)       # a save, not db.set_value: saving clears the script cache
                doc.disabled = want
                doc.save(ignore_permissions=True)
        rules = frappe.get_all("Server Script", {"name": ["in", [x.name for x in rules]]}, ["name", "disabled"])
    off = len([r for r in rules if r.disabled])
    frappe.flags.arinox_result = {"rule_scripts": len(rules), "off": off, "on": len(rules) - off}


main()

# Final Inspection, Before Submit: a result is chosen and the cartons to open have been drawn (once each, from the lot).
def run(doc):
    cint = frappe.utils.cint
    if not doc.result:
        frappe.throw("Choose the result.")
    if doc.inspection_type in ("Final", "Re-inspection", "2nd Re-inspection") and len(doc.cartons_picked) < min(cint(doc.inspected_cartons), cint(doc.total_cartons)):
        frappe.throw("Draw the %s cartons to inspect (Pick Cartons) before submitting." % doc.inspected_cartons)
    seen = []
    in_lot = [l.packing_list for l in doc.lots]
    for c in doc.cartons_picked:
        k = (c.packing_list, c.carton_no)
        if k in seen:
            frappe.throw("Carton %s of %s is drawn twice." % (c.carton_no, c.packing_list))
        seen.append(k)
        if c.packing_list not in in_lot:
            frappe.throw("Carton %s: %s is not in the lot." % (c.carton_no, c.packing_list))


run(doc)

# Final Inspection, After Submit: each packing list points at the inspection that covers it; a rejection is announced.
for l in doc.lots:
    frappe.db.set_value("Packing List", l.packing_list, "final_inspection", doc.name, update_modified=False)
if doc.result == "Rejected":
    frappe.msgprint("Rejected: %s critical, %s major, %s minor. Repack or rework, then inspect again." % (doc.critical_found, doc.major_found, doc.minor_found), indicator="red")

# Final Inspection, After Cancel: the packing lists it covered are free of it.
for l in doc.lots:
    if frappe.db.get_value("Packing List", l.packing_list, "final_inspection") == doc.name:
        frappe.db.set_value("Packing List", l.packing_list, "final_inspection", None, update_modified=False)

# API arinox_final_inspection_pick_cartons: draw the cartons to open, at random from the lot's own carton numbers. The seed comes back so the
# draw is stored and can be repeated. The form sends the unsaved inspection as JSON in `doc`.
def main():
    # shared helpers: the AQL row for a lot size, and the seeded carton draw (production/packing.draw_cartons, without `random`)
    def aql_row(plan, lot_size):
        """The plan row whose lot range holds `lot_size`, or None."""
        for r in frappe.get_all("AQL Plan Row", {"parent": plan}, ["lot_from", "lot_to", "code_letter", "sample_size", "critical_ac", "critical_re", "major_ac", "major_re", "minor_ac", "minor_re", "confirmed"], order_by="lot_from"):
            if frappe.utils.cint(r.lot_from) <= lot_size and lot_size <= frappe.utils.cint(r.lot_to):
                return r
        return None


    def next_random(state):
        """One step of a linear congruential generator (31 bits). The same seed always gives the same draw."""
        return (state * 1103515245 + 12345) % 2147483648


    def draw_cartons(cartons, how_many, seed):
        """Pick `how_many` of `cartons` = [[packing_list, carton_no, is_tail]] without repeats, the same draw for the same seed. A tail carton is
        always included when the lot has one, because mixed cartons are where packing errors hide."""
        pool = sorted(cartons)
        how_many = min(int(how_many), len(pool))
        state = int(seed) % 2147483648
        bag = list(pool)
        picked = []
        while len(picked) < how_many:
            state = next_random(state)
            picked.append(bag.pop((state // 65536) % len(bag)))
        tails = [c for c in pool if c[2]]
        if tails and how_many:
            has_tail = False
            for c in picked:
                if c[2]:
                    has_tail = True
            if not has_tail:
                state = next_random(state)
                picked[-1] = tails[(state // 65536) % len(tails)]
        return sorted(picked)
    cint = frappe.utils.cint
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    if cint(d.get("docstatus")):
        frappe.throw("Cartons can only be drawn on a draft.")
    lots = [l.get("packing_list") for l in (d.get("lots") or [])]
    if not lots:
        frappe.throw("Add the packing lists in the lot.")
    pool = []
    cartons = 0
    for pl in lots:
        for c in frappe.get_all("Packing List Carton", {"parent": pl}, ["carton_from", "carton_to", "tail"]):
            for n in range(cint(c.carton_from), cint(c.carton_to) + 1):
                pool.append([pl, n, cint(c.tail)])
                cartons = cartons + 1
    how_many = int(frappe.utils.ceil(cartons ** 0.5)) if cartons > 0 else 0
    now = frappe.utils.now_datetime()
    seed = frappe.form_dict.get("seed") or (now.microsecond * 997 + now.second * 31 + now.minute) % 2147483647 + 1
    picked = draw_cartons(pool, how_many, int(seed))
    sscc = {}
    for r in frappe.get_all("Packing List SSCC", {"parent": ["in", lots]}, ["parent", "carton_no", "sscc"]):
        sscc[(r.parent, r.carton_no)] = r.sscc
    rows = [{"packing_list": p[0], "carton_no": p[1], "sscc": sscc.get((p[0], p[1]))} for p in picked]
    frappe.flags.arinox_result = {"arinox_doc": {"cartons_picked": rows, "draw_seed": int(seed)}, "picked": len(rows)}


main()

# API arinox_sales_contract_apply_template: the terms and tolerance bands of the contract's template, for the form to fill in.
def main():
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    if not d.get("contract_template"):
        return
    tpl = frappe.get_doc("Sales Contract Template", d.get("contract_template"))
    fields = ("incoterm", "named_place", "shipment_mode", "port_of_loading", "port_of_discharge", "days_ex_factory_to_etd", "transit_days", "late_shipment_terms",
              "quantity_claim_days", "quality_claim_days", "aql_level", "inspection_terms", "packing_instructions", "shipping_marks", "payment_terms_template",
              "terms_and_conditions", "arbitration", "country_of_origin", "freight_by", "insurance_by", "delay_days_allowed", "objection_days", "discrepancy_days",
              "payment_basis", "payment_days", "documents_list")
    out = {}
    for f in fields:
        out[f] = tpl.get(f)
    out["tolerance_bands"] = [{"from_qty": b.from_qty, "to_qty": b.to_qty, "tolerance_pct": b.tolerance_pct} for b in tpl.tolerance_bands]
    if tpl.get("terms_and_conditions"):
        out["terms"] = frappe.db.get_value("Terms and Conditions", tpl.terms_and_conditions, "terms")
    frappe.flags.arinox_result = {"arinox_doc": out}


main()

# API arinox_production_card_get_card_lines: colour x size rows for a new card, straight from the Sales Order.
def main():
    # shared helpers: the order matrix and style dates (production_card.order_matrix, sample_approval.get_style_dates)
    def order_matrix(sales_order, style_item):
        """({(colour, size): {order_qty, tolerance_pct}}, earliest ex-factory date, [buyer POs]) for one style on an order."""
        cells = {}
        ex_factory = None
        pos = []
        for it in frappe.get_all("Sales Order Item", {"parent": sales_order},
                                 ["item_code", "qty", "apparel_colour", "apparel_size", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            if style != style_item:
                continue
            key = ((it.apparel_colour or "").strip(), (it.apparel_size or "").strip())
            if key not in cells:
                cells[key] = {"order_qty": 0, "tolerance_pct": 0}
            cells[key]["order_qty"] = cells[key]["order_qty"] + int(it.qty or 0)
            cells[key]["tolerance_pct"] = max(frappe.utils.flt(cells[key]["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not ex_factory or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(ex_factory)):
                ex_factory = frappe.utils.getdate(it.delivery_date)
            if it.apparel_buyer_po and it.apparel_buyer_po not in pos:
                pos.append(it.apparel_buyer_po)
        return cells, ex_factory, pos


    def get_pcd(sales_order, style_item):
        """Planned cut date from the Factory Allocation, then the contract line."""
        if not sales_order:
            return None
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", {"parent": fa, "style_item": style_item}, ["pcd"], order_by="pcd"):
                if r.pcd:
                    return r.pcd
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if contract:
            for r in frappe.get_all("Sales Contract Item", {"parent": contract, "style_item": style_item}, ["pcd"], order_by="pcd"):
                if r.pcd:
                    return r.pcd
        return None


    def setting(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        if v is None or v == "":
            return default
        return v
    so = frappe.form_dict.get("sales_order")
    frappe.get_doc("Sales Order", so).check_permission("read")
    m = order_matrix(so, frappe.form_dict.get("style_item"))
    cells = m[0]
    keys = sorted(cells.keys())
    frappe.flags.arinox_result = {"lines": [{"colour": k[0], "size": k[1], "order_qty": cells[k]["order_qty"]} for k in keys],
                                  "ex_factory_date": str(m[1]) if m[1] else None, "buyer_pos": m[2]}


main()

# API arinox_production_card_get_summary: stage totals per colour x size for one card, with the plan next to them.
def main():
    card = frappe.form_dict.get("name")
    doc = frappe.get_doc("Production Card", card)
    res = run_script("arinox_engine", action="totals", card=card)
    t = res.get("arinox_result") or {}
    rows = []
