        v = frappe.db.get_value("Sales Contract", contract, ["payment_basis", "payment_days", "transit_days"])
        return [v[0], v[1], v[2]] if v else [None, 0, 0]


    def refresh_invoice(name):
        """Recompute the expected due date of one invoice from its contract terms and its shipment's dates."""
        si = frappe.db.get_value("Sales Invoice", name, ["apparel_sales_contract", "apparel_shipment", "posting_date", "docstatus", "apparel_route_leg", "is_internal_customer"], as_dict=True)
        if not si or si.docstatus == 2 or frappe.utils.cint(si.is_internal_customer):
            return None
        terms = contract_terms(si.apparel_sales_contract)
        ship = None
        if si.apparel_shipment:
            ship = frappe.db.get_value("Shipment", si.apparel_shipment, ["apparel_on_board_date", "apparel_eta", "apparel_delivery_date", "apparel_arrival_date"], as_dict=True)
        arrival = (ship.apparel_arrival_date or ship.apparel_eta) if ship else None
        buffer_days = frappe.db.get_single_value("Apparel Settings", "rog_buffer_days")
        if buffer_days is None or buffer_days == "":
            buffer_days = 5
        got = expected_due(terms[0], terms[1], si.posting_date, ship.apparel_on_board_date if ship else None, arrival, ship.apparel_delivery_date if ship else None, buffer_days, terms[2])
        frappe.db.set_value("Sales Invoice", name, {"apparel_due_basis": terms[0] or "", "apparel_basis_date": got[0], "apparel_expected_due_date": got[2], "apparel_basis_source": got[1]}, update_modified=False)
        return got[2]


    def status_for(outstanding, grand_total, due, today, promise, disputed, soon_days):
        """[status, days overdue] for one invoice."""
        flt = frappe.utils.flt
        getdate = frappe.utils.getdate
        today = getdate(today)
        if flt(outstanding) <= 0.005:
            return ["Paid", 0]
        overdue = (today - getdate(due)).days if due else 0
        if disputed:
            return ["Disputed", max(overdue, 0)]
        if overdue > 0:
            if promise and getdate(promise) >= today:
                return ["Promised", overdue]
            return ["Overdue", overdue]
        if flt(outstanding) < flt(grand_total) - 0.005:
            return ["Partly Paid", 0]
        if due and (getdate(due) - today).days <= soon_days:
            return ["Due Soon", 0]
        return ["Not Due", 0]
    cint = frappe.utils.cint
    flt = frappe.utils.flt

    def setting(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        if v is None or v == "":
            return default
        return v

    today = frappe.utils.getdate(frappe.utils.nowdate())
    soon = cint(setting("reminder_days_before_due", 7))
    levels = [[cint(setting("escalation_days_1", 15)), "Send a payment reminder (Dunning level 1)"], [cint(setting("escalation_days_2", 30)), "Second reminder and manager attention"],
              [cint(setting("escalation_days_3", 60)), "Escalate to management"]]

    def todo(si, description, key):
        ref = si.name + ":" + key
        if frappe.db.exists("ToDo", {"reference_type": "Sales Invoice", "reference_name": si.name, "description": ["like", "%[" + ref + "]%"]}):
            return
        frappe.get_doc({"doctype": "ToDo", "allocated_to": si.owner, "reference_type": "Sales Invoice", "reference_name": si.name,
                        "description": description + " [" + ref + "]", "priority": "Medium"}).insert(ignore_permissions=True)

    rows = frappe.get_all("Sales Invoice", {"docstatus": 1, "is_internal_customer": 0, "is_return": 0},
                          ["name", "outstanding_amount", "grand_total", "apparel_expected_due_date", "apparel_promise_date", "apparel_dispute_reason", "customer", "owner", "apparel_followup_status"],
                          or_filters=[["apparel_shipment", "is", "set"], ["apparel_is_sample_invoice", "=", 1]])
    for si in rows:
        if flt(si.outstanding_amount) <= 0 and si.apparel_followup_status == "Paid":
            continue
        if not si.apparel_expected_due_date:
            refresh_invoice(si.name)
            si.apparel_expected_due_date = frappe.db.get_value("Sales Invoice", si.name, "apparel_expected_due_date")
        got = status_for(si.outstanding_amount, si.grand_total, si.apparel_expected_due_date, today, si.apparel_promise_date, bool(si.apparel_dispute_reason), soon)
        frappe.db.set_value("Sales Invoice", si.name, {"apparel_followup_status": got[0], "apparel_days_overdue": got[1]}, update_modified=False)
        if got[0] == "Due Soon":
            todo(si, "Payment of %s from %s falls due on %s: send a reminder." % (si.name, si.customer, si.apparel_expected_due_date), "due-soon")
        if got[0] == "Overdue":
            hit = [l for l in levels if got[1] >= l[0]]
            if hit:
                last = hit[len(hit) - 1]
                todo(si, "%s: %s is %s days overdue (%s)." % (si.name, si.customer, got[1], last[1]), "overdue-" + str(last[0]))


main()

