                                "item": m.item, "uom": m.uom, "consumption": flt(m.consumption), "conversion_factor": 1, "supplier": m.nominated_supplier,
                                "rate": buying_rate(m.item), "is_selected": 1})
    cs.set("charges", [])
    for row in charge_rows(cs.costing_parameter):
        cs.append("charges", row)
    frappe.flags.arinox_result = cs.as_dict()


main()

# Price Negotiation, Before Save: each round is checked against its Cost Sheet and given the margin its price would leave;
# the style table summarises the last offers and the agreed price; the status follows the styles.
def run(doc):
    # shared helper: the margin if a costed garment sells at a price (Cost Sheet.margin_at_price in the app)
    def margin_at_price(cs, price):
        """Price-based charges other than profit scale with the price. `cs` is a Cost Sheet document."""
        flt = frappe.utils.flt
        price = flt(price)
        cost = flt(cs.subtotal) + price * flt(cs.price_cost_pct) / 100
        margin = price - cost
        return {"cost": flt(cost, 6), "margin": flt(margin, 6), "margin_pct": flt(margin / price * 100, 2) if price else 0,
                "markup_pct": flt(margin / cost * 100, 2) if cost else 0}
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    getdate = frappe.utils.getdate
    OUR = ("Our Offer", "Our Counter")
    BUYER = ("Buyer Target", "Buyer Counter")
    MANUAL_STATUS = ("On Hold", "Lost")

    cache = {}
    for r in doc.rounds:
        cs = cache.get(r.cost_sheet) or frappe.get_doc("Cost Sheet", r.cost_sheet)
        cache[r.cost_sheet] = cs
        if cs.customer != doc.customer:
            frappe.throw("Round %s: Cost Sheet %s belongs to another customer." % (r.idx, cs.name))
        if cs.currency != doc.currency:
            frappe.throw("Round %s: Cost Sheet %s is in %s, not %s." % (r.idx, cs.name, cs.currency, doc.currency))
        if cs.docstatus == 2:
            frappe.throw("Round %s: Cost Sheet %s is cancelled. Use its amended revision." % (r.idx, cs.name))
        r.style_no = cs.style_no
        if r.direction != "Dropped" and not flt(r.price):
            frappe.throw("Round %s: enter the price." % r.idx)
        if flt(r.price):
            m = margin_at_price(cs, r.price)
            r.margin_pct = m["margin_pct"]
            r.below_floor = 1 if m["margin_pct"] < flt(cs.margin_floor_pct) else 0
        if not r.recorded_by:
            r.recorded_by = frappe.session.user
        if r.direction == "Agreed" and r.below_floor:
            frappe.msgprint("Style %s agreed at %s, margin %s%% is below the floor. The Quotation will need an approved Cost Sheet revision." % (r.style_no, r.price, r.margin_pct),
                            indicator="orange")
        if not [s for s in doc.styles if s.cost_sheet == r.cost_sheet]:
            doc.append("styles", {"cost_sheet": r.cost_sheet, "qty": r.qty or cs.order_qty})

    rounds = sorted(doc.rounds, key=lambda r: (getdate(r.round_date), r.idx))
    for s in doc.styles:
        cs = frappe.get_doc("Cost Sheet", s.cost_sheet)
        s.style_no = cs.style_no
        s.cost_price = cs.quoted_price
        s.our_last_offer = 0
        s.buyer_last_offer = 0
        s.agreed_price = 0
        s.margin_at_agreed = 0
        status = "Open"
        for r in rounds:
            if r.cost_sheet != s.cost_sheet:
                continue
            if r.direction in OUR:
                s.our_last_offer = r.price
            elif r.direction in BUYER:
                s.buyer_last_offer = r.price
            elif r.direction == "Agreed":
                s.agreed_price = r.price
                s.margin_at_agreed = r.margin_pct
                status = "Agreed"
            elif r.direction == "Dropped":
                status = "Dropped"
            if r.qty:
                s.qty = r.qty
        s.style_status = status

    doc.total_qty = sum([cint(s.qty) for s in doc.styles if s.style_status != "Dropped"])
    doc.total_value = flt(sum([cint(s.qty) * flt(s.agreed_price) for s in doc.styles if s.style_status == "Agreed"]), 2)

    if doc.status not in MANUAL_STATUS:
        live = [s for s in doc.styles if s.style_status != "Dropped"]
        agreed = [s for s in live if s.style_status == "Agreed"]
        if live and len(agreed) == len(live):
            doc.status = "Agreed"
        elif agreed:
            doc.status = "Partly Agreed"
        else:
            doc.status = "Open"


run(doc)

# Quotation, Before Save: lines that carry a Cost Sheet are held to its margin floor (a submitted costing, the right customer and currency).
def run(doc):
    # shared helper: the margin if a costed garment sells at a price (Cost Sheet.margin_at_price in the app)
    def margin_at_price(cs, price):
        """Price-based charges other than profit scale with the price. `cs` is a Cost Sheet document."""
        flt = frappe.utils.flt
        price = flt(price)
        cost = flt(cs.subtotal) + price * flt(cs.price_cost_pct) / 100
        margin = price - cost
        return {"cost": flt(cost, 6), "margin": flt(margin, 6), "margin_pct": flt(margin / price * 100, 2) if price else 0,
                "markup_pct": flt(margin / cost * 100, 2) if cost else 0}
    flt = frappe.utils.flt
    for it in doc.items:
        if not it.get("apparel_cost_sheet"):
            continue
        cs = frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        if cs.docstatus != 1:
            frappe.throw("Row %s: Cost Sheet %s is not submitted. Only a submitted costing can be quoted." % (it.idx, cs.name))
        if doc.quotation_to == "Customer" and cs.customer != doc.party_name:
            frappe.throw("Row %s: Cost Sheet %s belongs to %s." % (it.idx, cs.name, cs.customer))
        if cs.currency != doc.currency:
            frappe.throw("Row %s: Cost Sheet %s is in %s, the Quotation in %s." % (it.idx, cs.name, cs.currency, doc.currency))
        it.apparel_style_item = it.apparel_style_item or cs.style_item
        it.apparel_style_no = it.apparel_style_no or cs.style_no
        margin = margin_at_price(cs, it.rate)["margin_pct"]
        approved_at = flt(cs.approved_price) if cs.approval_status == "Approved" else None
        if margin < flt(cs.margin_floor_pct) and not (approved_at and flt(it.rate) >= approved_at - 0.0001):
            frappe.throw("Row %s (%s): %s leaves a margin of %s%%, below the floor of %s%%. Amend the Cost Sheet at this price and get it approved first." %
                         (it.idx, cs.style_no, flt(it.rate), margin, flt(cs.margin_floor_pct)), title="Below Margin Floor")


run(doc)

# API arinox_cost_sheet_make_price_negotiation: add this costing to the customer's open negotiation for the inquiry, or start one. Answers its name.
def main():
    cs = frappe.get_doc("Cost Sheet", frappe.form_dict.get("source_name"))
