        listed = [a.comment_ref for a in doc.actions if a.comment_ref]
        unlisted = [c for c in open_buyer_comments(doc.sales_order, doc.style_item) if c["name"] not in listed]
        if unlisted:
            frappe.throw("Every buyer comment must be reviewed. %s open comment(s) are not in the action list, for example: %s. Use Get Buyer Comments." %
                         (len(unlisted), (unlisted[0]["comment"] or "")[:80]))


run(doc)

# PP Meeting, After Submit and After Save (Submitted Document): the buyer comment of each action follows the action (closed in this meeting, or open again).
def run(doc):
    for a in doc.actions:
        if a.comment_ref and frappe.db.exists("Sample Approval Comment", a.comment_ref):
            closed = a.status == "Closed"
            frappe.db.set_value("Sample Approval Comment", a.comment_ref, {"status": "Closed" if closed else "Open", "closed_in": doc.name if closed else None})


run(doc)

# PP Meeting, Before Save (Submitted Document): actions stay editable so they can be closed later; stamp them and keep the status in step.
def run(doc):
    for a in doc.actions:
        if a.status == "Closed" and not a.closed_on:
            a.closed_on = frappe.utils.nowdate()
        elif a.status == "Open":
            a.closed_on = None
    doc.status = "Open Actions" if [a for a in doc.actions if a.status == "Open"] else "Closed"
    for a in doc.actions:
        if not (a.action_taken and a.action_owner and a.target_date):
            frappe.throw("Action row %s needs the action, an owner and a target date." % a.idx)


run(doc)

