    def open_buyer_comments(sales_order, style_item):
        """Open comments on every sample of this style that applies to the order (each a dict)."""
        rows = []
        for s in frappe.get_all("Sample Approval", filters=scope_filters(sales_order, style_item), fields=["name", "sample_type", "colour"]):
            for c in frappe.get_all("Sample Approval Comment", filters={"parent": s.name, "parenttype": "Sample Approval", "status": "Open"},
                                    fields=["name", "category", "comment", "relevant_to_cutting"]):
                d = dict(c)
                d["sample_approval"] = s.name
                d["sample_type"] = s.sample_type
                d["colour"] = s.colour
                rows.append(d)
        return rows


    def cutting_actions_open(sales_order, style_item):
        """[PP meetings held, open cutting-related actions]. Actions of pilot runs count too; only a PP Meeting counts as the meeting being held."""
        open_rows = []
        all_meetings = frappe.get_all("PP Meeting", filters={"sales_order": sales_order, "style_item": style_item, "docstatus": 1}, fields=["name", "meeting_type"])
        meetings = [m for m in all_meetings if m.meeting_type == "PP Meeting"]
        for m in all_meetings:
            open_rows = open_rows + frappe.get_all("PP Meeting Action", filters={"parent": m.name, "relevant_to_cutting": 1, "status": "Open"}, fields=["comment"])
        return [meetings, open_rows]
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    actions = list(d.get("actions") or [])
    listed = [a.get("comment_ref") for a in actions if a.get("comment_ref")]
    added = 0
    for c in open_buyer_comments(d.get("sales_order"), d.get("style_item")):
        if c["name"] in listed:
            continue
        label = c["sample_type"] + (" / %s" % c["colour"] if c["colour"] else "")
        actions.append({"sample_approval": c["sample_approval"], "comment_ref": c["name"], "source": "Buyer Comment", "category": c["category"],
                        "comment": "[%s] %s" % (label, c["comment"]), "relevant_to_cutting": c["relevant_to_cutting"]})
        added = added + 1
    frappe.flags.arinox_result = {"arinox_doc": {"actions": actions}, "count": added}


main()

# API arinox_pp_meeting_load_from_requisitions: fabric required and received, shade count and trim readiness per colour, from the requisitions of this order and style.
def main():
    # shared helpers from materials/status.py: the material gate that holds bulk production, and trim readiness (the rest of status.py is not ported yet)
    def material_gate(sales_order, style_item, colour):
        """[blockers, warnings] for bulk production of a style x colour: every requisition line must have its accepted quantity in.
        Trims that only matter later (finishing, packing) never hold cutting."""
        flt = frappe.utils.flt
        fab = frappe.db.get_single_value("Apparel Settings", "material_gate_fabric") or "Block"
        trim = frappe.db.get_single_value("Apparel Settings", "material_gate_trims") or "Warn"
        min_pct = flt(frappe.db.get_single_value("Apparel Settings", "material_gate_min_pct") or 100)
        blockers = []
        warnings = []
        if fab != "Off":
            fab_lines = frappe.db.sql("""select c.parent, c.fabric_item, c.net_qty, c.accepted_qty from `tabFabric Requisition Item` c join `tabFabric Requisition` p on p.name = c.parent
                where p.docstatus = 1 and p.status not in ('Superseded', 'Cancelled') and c.sales_order = %s and c.style_item = %s
                and upper(c.colour) = upper(%s) and c.net_qty > 0""", (sales_order, style_item, colour or ""), as_dict=True)
            if not fab_lines:
                # nothing to hold the gate on: say so, so an order never starts bulk with no fabric ordered by oversight (free-issue fabric is the one good reason)
                warnings.append("Fabric: no approved Fabric Requisition covers %s yet. Fine only if the buyer supplies the fabric." % (colour or "this colour"))
            for r in fab_lines:
                need = flt(r.net_qty) * min_pct / 100
                if flt(r.accepted_qty) + 0.0005 < need:
                    msg = "Fabric %s: %s m of %s m accepted (%s)." % (r.fabric_item, flt(r.accepted_qty, 1), flt(r.net_qty, 1), r.parent)
                    if fab == "Block":
                        blockers.append(msg)
                    else:
                        warnings.append(msg)
        if trim != "Off":
            for r in frappe.db.sql("""select c.parent, c.trim_item, c.net_qty, c.accepted_qty, c.trim_category from `tabTrim Requisition Item` c join `tabTrim Requisition` p on p.name = c.parent
                left join `tabTrim Category` k on k.name = c.trim_category
                where p.docstatus = 1 and p.status not in ('Superseded', 'Cancelled') and c.sales_order = %s and c.style_item = %s
                and (c.colour is null or c.colour = '' or upper(c.colour) = upper(%s)) and c.net_qty > 0 and coalesce(k.needed_for, 'Sewing') in ('Cutting', 'Sewing')""",
                                   (sales_order, style_item, colour or ""), as_dict=True):
                need = flt(r.net_qty) * min_pct / 100
                if flt(r.accepted_qty) + 0.0005 < need:
                    msg = "Trim %s: %s of %s accepted (%s)." % (r.trim_item, flt(r.accepted_qty, 1), flt(r.net_qty, 1), r.parent)
                    if trim == "Block":
                        blockers.append(msg)
                    else:
                        warnings.append(msg)
        return [blockers, warnings]


    def trim_readiness(sales_order, style_item, needed_for):
        """Available / Partial / Not Available for the trims of one need (Sewing or Packing); None when there are none."""
        flt = frappe.utils.flt
        rows = frappe.db.sql("""select c.net_qty, c.received_qty, c.accepted_qty from `tabTrim Requisition Item` c join `tabTrim Requisition` p on p.name = c.parent
            left join `tabTrim Category` k on k.name = c.trim_category where p.docstatus = 1 and p.status not in ('Superseded', 'Cancelled')
            and c.sales_order = %s and c.style_item = %s and c.net_qty > 0 and coalesce(k.needed_for, 'Sewing') = %s""", (sales_order, style_item, needed_for), as_dict=True)
        if not rows:
            return None
        min_pct = flt(frappe.db.get_single_value("Apparel Settings", "material_gate_min_pct") or 100)
        if len([r for r in rows if flt(r.accepted_qty) + 0.0005 >= flt(r.net_qty) * min_pct / 100]) == len(rows):
            return "Available"
        if [r for r in rows if flt(r.received_qty) > 0 or flt(r.accepted_qty) > 0]:
            return "Partial"
        return "Not Available"
    flt = frappe.utils.flt
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    if d.get("name") and frappe.db.exists("PP Meeting", d.get("name")):
        frappe.get_doc("PP Meeting", d.get("name")).check_permission("write")
    rows = frappe.db.sql("""select c.colour, sum(c.net_qty) net, sum(c.accepted_qty) accepted, group_concat(distinct i.shade_bands_found) shades
        from `tabFabric Requisition Item` c join `tabFabric Requisition` p on p.name = c.parent
        left join `tabFabric Inspection` i on i.fabric_requisition = p.name and i.docstatus = 1 and i.colour = c.colour
        where p.docstatus = 1 and p.status not in ('Superseded', 'Cancelled') and c.sales_order = %s and c.style_item = %s group by c.colour""",
                         (d.get("sales_order"), d.get("style_item")), as_dict=True)
    colours = list(d.get("colours") or [])
    for r in rows:
        row = None
        for c in colours:
            if (c.get("colour") or "").strip().upper() == (r.colour or "").strip().upper():
                row = c
        if not row:
            row = {"colour": r.colour}
            colours.append(row)
        row["fabric_required_m"] = flt(r.net, 2)
        row["fabric_received_m"] = flt(r.accepted, 2)
        bands = []
        for b in (r.shades or "").replace(";", ",").split(","):
            if b.strip() and b.strip() not in bands:
                bands.append(b.strip())
        row["no_of_shades"] = len(bands) or row.get("no_of_shades")
    out = {"colours": colours}
    for field, need in (("sewing_trims", "Sewing"), ("packing_trims", "Packing")):
        status = trim_readiness(d.get("sales_order"), d.get("style_item"), need)
        if status:
            out[field] = status
    frappe.flags.arinox_result = {"arinox_doc": out, "count": len(rows)}


main()

# Work Order, Before Save: the bulk gate (G3) can be overridden only by an Apparel Merchandising Manager, with a reason.
def run(doc):
    if not frappe.utils.cint(doc.get("apparel_gate_override")):
        return
    if not doc.is_new() and not doc.has_value_changed("apparel_gate_override"):
        return
    roles = frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
    if not [r for r in roles if r in ("Apparel Merchandising Manager", "System Manager")]:
        frappe.throw("Only an Apparel Merchandising Manager can override the bulk gate.")
    if not (doc.get("apparel_gate_override_reason") or "").strip():
        frappe.throw("Enter the reason for overriding the bulk gate.")


run(doc)

# Cost Head, Before Save: material scope only for heads priced from materials; Profit must be a percentage; a head used by an enabled Costing Parameter cannot be disabled.
def run(doc):
    if doc.calc_type != "From Materials":
        doc.material_scope = None
    if doc.head_group == "Profit" and doc.calc_type not in ("Percent of Subtotal", "Percent of Product Cost", "Percent of Price"):
        frappe.throw("Profit must be a percentage: Percent of Subtotal (markup on cost, as on the costing sheet), Percent of Product Cost, or Percent of Price.")
    if not doc.enabled and not doc.is_new():
        used = frappe.db.sql("""select p.name from `tabCosting Parameter Rate` r join `tabCosting Parameter` p on p.name = r.parent
            where r.cost_head = %s and p.enabled = 1 limit 1""", doc.name)
        if used:
            frappe.throw("Cost head is used by enabled Costing Parameter %s." % used[0][0])


run(doc)

# Costing Parameter, Before Save: dates in order, one rate per cost head and none for heads priced from materials, a title, and no overlap with another enabled
# parameter for the same customer, product type and currency.
def run(doc):
    getdate = frappe.utils.getdate
    if doc.effective_to and getdate(doc.effective_to) < getdate(doc.effective_from):
        frappe.throw("Effective To is before Effective From.")
    seen = []
    for r in doc.rates:
        if r.cost_head in seen:
            frappe.throw("Cost head %s appears twice." % r.cost_head)
        seen.append(r.cost_head)
        if frappe.db.get_value("Cost Head", r.cost_head, "calc_type") == "From Materials":
            frappe.throw("%s is priced from materials and takes no rate here." % r.cost_head)
        if r.not_applicable:
            r.rate = 0
    doc.title = " · ".join([doc.customer or "All customers", doc.product_type or "All product types", doc.currency])
    if doc.enabled:
        far = "9999-12-31"
        others = frappe.get_all("Costing Parameter", fields=["name", "effective_from", "effective_to"],
                                filters={"enabled": 1, "name": ("!=", doc.name), "currency": doc.currency, "customer": doc.customer or ("is", "not set"),
                                         "product_type": doc.product_type or ("is", "not set")})
        for o in others:
            if getdate(o.effective_from) <= getdate(doc.effective_to or far) and getdate(doc.effective_from) <= getdate(o.effective_to or far):
                frappe.throw("Overlaps %s for the same customer, product type and currency. Close that one with an Effective To date first." % o.name)


run(doc)

# API arinox_sales_contract_make_sales_contract: Quotation -> Sales Contract (unsaved). One line per quoted style and tech-pack colour, with the size rows pre-filled
# from the tech pack, the line quantity split across the sizes (see lib_contract_sizes.py). The contract template's terms and bands are applied the way the Apply Template button does.
# A Quotation carries few of a contract's fields, so what it lacks is filled in this order, never over a value already set: the Quotation (contact, address,
# terms), the contract template, the customer's most recent earlier contract (terms, bands, brand, division, contact, merchant), then the Customer,
# Tech Pack and Cost Sheet (customer name, payment terms, season, division, in-warehouse date).
def main():
    # shared helper: split a contract line's quantity across the Tech Pack's sizes
    def size_split(qty, sizes, ratios, customer, style_item, colour):
        """{size: pieces}, adding up to exactly `qty`. `sizes` are the Tech Pack's size names and `ratios` {size: ratio} its size ratios.
        The proportions come from the buyer's own most recent earlier contract for the same style (same colour when it has one); with no earlier
        contract they come from the Tech Pack ratios. A size the earlier contract never ordered gets nothing. Returns (split, where the proportions came from)."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        qty = cint(qty)
        weights = {}
        where = "Tech Pack ratios"
        for name in frappe.get_all("Sales Contract", filters={"customer": customer, "docstatus": ["<", 2]}, order_by="contract_date desc, creation desc", pluck="name"):
            rows = frappe.get_all("Sales Contract Size Qty", filters={"parent": name, "parenttype": "Sales Contract", "style_item": style_item}, fields=["size", "colour", "qty"])
            same = [r for r in rows if (r.colour or "").strip().upper() == (colour or "").strip().upper()]
            use = same or rows
            if use and sum([cint(r.qty) for r in use]) > 0:
                for r in use:
                    key = (r.size or "").strip().upper()
                    weights[key] = weights.get(key, 0) + cint(r.qty)
                where = "contract " + name
                break
        if not weights:
            for s in sizes:
                weights[(s or "").strip().upper()] = flt(ratios.get(s))
        listed = [s for s in sizes if flt(weights.get((s or "").strip().upper())) > 0]
        total = sum([flt(weights.get((s or "").strip().upper())) for s in listed])
        split = {}
        for s in sizes:
            split[s] = 0
        if not qty or not total:
            return split, where
        exact = {}
        for s in listed:
            exact[s] = qty * flt(weights.get((s or "").strip().upper())) / total
            split[s] = int(frappe.utils.floor(exact[s]))
        left = qty - sum([split[s] for s in listed])
        for s in sorted(listed, key=lambda x: exact[x] - split[x], reverse=True)[:left]:
            split[s] = split[s] + 1
        return split, where
    cint = frappe.utils.cint
    flt = frappe.utils.flt
    q = frappe.get_doc("Quotation", frappe.form_dict.get("source_name"))
    q.check_permission("read")
    if q.docstatus != 1:
        frappe.throw("Submit the Quotation first.")
    if q.quotation_to != "Customer":
        frappe.throw("The Quotation must be addressed to a Customer.")

    template = (frappe.db.get_value("Sales Contract Template", {"customer": q.party_name, "is_default": 1, "enabled": 1}, "name")
                or frappe.db.get_value("Sales Contract Template", {"customer": q.party_name, "enabled": 1}, "name")
                or frappe.db.get_single_value("Apparel Settings", "default_contract_template"))
    fixed = []      # header fields set by the Quotation or the template: the earlier contract never replaces these
    sc = frappe.new_doc("Sales Contract")
    sc.update({"customer": q.party_name, "quotation": q.name, "price_negotiation": q.get("apparel_price_negotiation"), "opportunity": q.opportunity,
               "currency": q.currency, "company": q.company, "contract_template": template})
    if template:
        res = run_script("arinox_sales_contract_api_apply_template", doc=json.dumps({"contract_template": template})).get("arinox_result")
        terms = (res or {}).get("arinox_doc") or {}
        for f in terms:
            if f != "tolerance_bands":
                sc.set(f, terms[f])
                if terms[f]:
                    fixed.append(f)
        if terms.get("tolerance_bands"):
            fixed.append("tolerance_bands")
        sc.set("tolerance_bands", [])
        for b in terms.get("tolerance_bands") or []:
            sc.append("tolerance_bands", b)
    if q.incoterm:
        sc.incoterm = q.incoterm
        fixed.append("incoterm")
    if q.payment_terms_template:
        fixed = fixed + ["payment_terms_template", "payment_basis", "payment_days"]
        sc.payment_terms_template = q.payment_terms_template
        first = frappe.db.get_value("Payment Terms Template Detail", {"parent": q.payment_terms_template}, ["credit_days", "due_date_based_on"], as_dict=True)
        if first and not sc.payment_basis:
            sc.payment_days = cint(first.credit_days)
            sc.payment_basis = "Days after Invoice Date"

    # ---- what the Quotation does carry that the contract has a place for
    cust = frappe.db.get_value("Customer", q.party_name, ["customer_name", "payment_terms"], as_dict=True)
    if cust:
        sc.customer_name = cust.customer_name
    if q.get("customer_address"):
        sc.customer_address = q.customer_address
        fixed.append("customer_address")
    if q.get("contact_display"):
        sc.buyer_contact = q.contact_display
        fixed.append("buyer_contact")
    if q.get("tc_name"):
        sc.terms_and_conditions = q.tc_name
        sc.terms = q.get("terms")
        fixed = fixed + ["terms_and_conditions", "terms"]
    if q.owner:
        sc.merchant = frappe.db.get_value("User", q.owner, "full_name")      # the merchandiser is whoever raised the quotation
        fixed.append("merchant")
    if cust and cust.payment_terms and not sc.payment_terms_template:
        fixed = fixed + ["payment_terms_template", "payment_basis", "payment_days"]
        sc.payment_terms_template = cust.payment_terms
        first_term = frappe.db.get_value("Payment Terms Template Detail", {"parent": cust.payment_terms}, ["credit_days"], as_dict=True)
        if first_term and not sc.payment_basis:
            sc.payment_days = cint(first_term.credit_days)
            sc.payment_basis = "Days after Invoice Date"

    # ---- this customer's most recent earlier contract fills whatever is still blank (the same buyer repeats the same terms)
    earlier = frappe.get_all("Sales Contract", filters={"customer": q.party_name, "docstatus": ["<", 2]}, order_by="contract_date desc, creation desc", limit_page_length=1, pluck="name")
    if earlier:
        prev = frappe.get_doc("Sales Contract", earlier[0])
        for f in ("brand", "division", "buyer_contact", "merchant", "customer_address", "bank_account", "incoterm", "named_place", "shipment_mode", "country_of_origin",
                  "freight_by", "insurance_by", "port_of_loading", "port_of_discharge", "days_ex_factory_to_etd", "transit_days", "delay_days_allowed",
                  "late_shipment_terms", "quantity_claim_days", "quality_claim_days", "objection_days", "discrepancy_days", "aql_level", "inspection_terms",
                  "packing_instructions", "payment_basis", "payment_days", "payment_terms_template", "documents_list", "terms_and_conditions", "terms", "arbitration"):
            if f in fixed or not prev.get(f):
                continue
            current = sc.get(f)
            default = frappe.db.get_value("DocField", {"parent": "Sales Contract", "fieldname": f}, "default")
            if not current or (default not in (None, "") and str(current) == str(default)):      # blank, or still the form's own default
                sc.set(f, prev.get(f))
        if not sc.tolerance_bands and "tolerance_bands" not in fixed:
            for b in prev.tolerance_bands:
                sc.append("tolerance_bands", {"from_qty": b.from_qty, "to_qty": b.to_qty, "tolerance_pct": b.tolerance_pct})

    for qi in q.items:
        cs = frappe.get_doc("Cost Sheet", qi.apparel_cost_sheet) if qi.get("apparel_cost_sheet") else None
        style_item = qi.get("apparel_style_item") or (cs.style_item if cs else None) or qi.item_code
        tp = frappe.get_doc("Tech Pack", cs.tech_pack) if cs and cs.tech_pack else None
        colours = [c.colour for c in tp.colours] if tp and tp.colours else [None]
        if not sc.season:
            sc.season = (tp.season if tp else None) or (cs.season if cs else None)
        if tp and not sc.division:
            sc.division = tp.division
        # dates for the line: the buyer's own lead time for this style (contract date -> ex-factory, and -> PCD) from their most recent earlier
        # contract that has them, else the contract's production lead days. A date the merchandiser can change; ETD and in-warehouse follow below.
        ex_lead = None
        pcd_lead = None
        for r in frappe.get_all("Sales Contract Item", filters={"style_item": style_item, "parenttype": "Sales Contract", "ex_factory_date": ["is", "set"]},
                                fields=["parent", "ex_factory_date", "pcd"], order_by="creation desc", limit_page_length=20):
            pc = frappe.db.get_value("Sales Contract", r.parent, ["customer", "contract_date", "docstatus"], as_dict=True)
            if pc and pc.customer == q.party_name and pc.docstatus < 2 and pc.contract_date:
                ex_lead = frappe.utils.date_diff(r.ex_factory_date, pc.contract_date)
                if r.pcd:
                    pcd_lead = frappe.utils.date_diff(r.pcd, pc.contract_date)
                break
        if ex_lead is None and cint(sc.production_lead_days):
            ex_lead = cint(sc.production_lead_days)
        for colour in colours:
            line_qty = qi.qty if len(colours) == 1 else 0
            sc.append("items", {"style_item": style_item, "style_no": qi.get("apparel_style_no") or (cs.style_no if cs else qi.item_name), "colour": colour,
                                "qty": line_qty, "rate": qi.rate, "description": qi.description,
                                "cost_sheet": cs.name if cs else None, "tech_pack": tp.name if tp else None,
                                "in_warehouse_date": cs.in_warehouse_date if cs else None,
                                "ex_factory_date": frappe.utils.add_days(sc.contract_date, ex_lead) if ex_lead is not None and ex_lead > 0 else None,
                                "pcd": frappe.utils.add_days(sc.contract_date, pcd_lead) if pcd_lead is not None and pcd_lead > 0 else None})
            names = [z.size for z in tp.sizes] if tp else []
            ratios = {}
            for z in (tp.sizes if tp else []):
                ratios[z.size] = z.ratio
            split = size_split(line_qty, names, ratios, q.party_name, style_item, colour)[0] if names else {}
            for size in names:
                sc.append("sizes", {"style_item": style_item, "colour": colour, "size": size, "qty": split.get(size, 0)})
    # the figures the save script would work out, so the form opens with prices, tolerances and totals instead of zeros
    total_qty = 0
    total_amount = 0
    for it in sc.items:
        it.amount = flt(cint(it.qty) * flt(it.rate), 2)
        it.tolerance_pct = 0
        for b in sorted(sc.tolerance_bands, key=lambda b: cint(b.from_qty)):
            if cint(it.qty) >= cint(b.from_qty) and (not cint(b.to_qty) or cint(it.qty) <= cint(b.to_qty)):
                it.tolerance_pct = flt(b.tolerance_pct)
                break
        if it.ex_factory_date and not it.etd:
            it.etd = frappe.utils.add_days(it.ex_factory_date, cint(sc.days_ex_factory_to_etd))
        if it.etd and not it.in_warehouse_date:
            it.in_warehouse_date = frappe.utils.add_days(it.etd, cint(sc.transit_days))
        total_qty = total_qty + cint(it.qty)
        total_amount = total_amount + flt(it.amount)
    sc.total_qty = total_qty
    sc.total_amount = flt(total_amount, 2)
    sc.sku_count = len(sc.items)
    frappe.flags.arinox_result = sc.as_dict()


main()

# API Server Script `arinox_tna`: the time-and-action stamping used by many documents (tna/events.py + status.py), in one place because the sandbox cannot import.
# Callers: run_script("arinox_tna", action=..., ...) inside try/except (a T&A problem must never block a purchase, a receipt or an approval).
#   stamp    sales_order, style_item, colour, code, date, source_doctype, source_name, partial (0/1), planned (0/1)
#   unstamp  source_doctype, source_name
#   refresh  order_tna
#   samples  order_tna        (set the approval milestones from the Sample Approvals that apply)
#   refind   order_tna        (pick up FR / TR raised and fabric booked from documents that already exist)
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from tna/status.py: the state of a milestone and of an order, computed from today's date and never trusted from a stored value
    COLOURS = {"Done": "#2f855a", "In Progress": "#2b6cb0", "Late": "#c53030", "Not Started": "#718096", "Not Applicable": "#cbd5e0"}


    def milestone_state(not_applicable, actual_date, partial, planned_date, revised_date):
        """[status, delay_days, progress]. Late = the current target (revised, else planned) has passed and it is not done.
        Delay is measured against the baseline: days late if done late, days overdue if still open, days slipped if revised."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cint(not_applicable):
            return ["Not Applicable", 0, 0]
        due = getdate(revised_date or planned_date) if (revised_date or planned_date) else None
        base = getdate(planned_date) if planned_date else None
        if actual_date:
            return ["Done", max(frappe.utils.date_diff(actual_date, base), 0) if base else 0, 100]
        if due and due < today:
            return ["Late", max(frappe.utils.date_diff(today, base), 0) if base else 0, 50 if cint(partial) else 0]
        delay = max(frappe.utils.date_diff(due, base), 0) if (revised_date and base and due) else 0
        return ["In Progress" if cint(partial) else "Not Started", delay, 50 if cint(partial) else 0]


    def order_state(milestones, plan_feasible, cancelled):
        """[status, critical_delay_days] of an order from its milestone dicts."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cancelled:
            return ["Cancelled", 0]
        live = [m for m in milestones if not cint(m.get("not_applicable"))]
        if live and len([m for m in live if m.get("actual_date")]) == len(live):
            return ["Completed", 0]
        crit_late = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                     and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        delays = [max(frappe.utils.date_diff(m.get("actual_date") or today, m["planned_date"]), 0) for m in live
                  if cint(m.get("is_critical")) and m.get("planned_date") and (m.get("actual_date") or m in crit_late)]
        worst = max(delays) if delays else 0
        if crit_late:
            return ["Late", worst]
        other_late = [m for m in live if not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date")) and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        soon = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                and 0 <= frappe.utils.date_diff(m.get("revised_date") or m.get("planned_date"), today) <= 3]
        if other_late or soon or not cint(plan_feasible):
            return ["At Risk", worst]
        return ["On Track", worst]


    def refresh_order_tna(name):
        """Recompute and store every milestone's status and the order's status."""
        if not frappe.db.exists("Order TNA", name):
            return
        t = frappe.db.get_value("Order TNA", name, ["status", "plan_feasible", "critical_delay_days"], as_dict=True)
        ms = frappe.get_all("TNA Milestone", filters={"order_tna": name}, fields=["name", "not_applicable", "actual_date", "partial", "planned_date", "revised_date", "is_critical",
                                                                                  "status", "delay_days", "color", "progress"])
        for m in ms:
            st = milestone_state(m.not_applicable, m.actual_date, m.partial, m.planned_date, m.revised_date)
            colour = COLOURS[st[0]]
            if m.status != st[0] or m.delay_days != st[1] or m.progress != st[2] or m.color != colour:
                frappe.db.set_value("TNA Milestone", m.name, {"status": st[0], "delay_days": st[1], "progress": st[2], "color": colour}, update_modified=False)
            m["status"] = st[0]
        if t.status == "Cancelled":
            return
        o = order_state(ms, t.plan_feasible, False)
        if o[0] != t.status or o[1] != t.critical_delay_days:
            frappe.db.set_value("Order TNA", name, {"status": o[0], "critical_delay_days": o[1]}, update_modified=False)
    cint = frappe.utils.cint
    getdate = frappe.utils.getdate
    form = frappe.form_dict
    action = form.get("action")
    SAMPLE_CODES = {"Lab Dip": "LAB_DIP", "Fit": "FIT", "Bulk Trim": "TRIMS_APPROVED", "Bulk Fabric": "BULK_FABRIC_APPROVED", "Fabric Test (FPT)": "FPT_PASSED", "TOP": "TOP", "Size Set": "TOP"}
    PP_TYPES = ("PP", "Garment Test (GPT)")

    def tnas_for(sales_order, style_item, colour):
        filters = {"style_item": style_item, "status": ["!=", "Cancelled"]}
        if sales_order:
            filters["sales_order"] = sales_order
        rows = frappe.get_all("Order TNA", filters=filters, fields=["name", "colour", "sales_order", "style_item"])
        return [r for r in rows if not colour or not norm(r.colour) or norm(r.colour) == norm(colour)]

    def milestone(tna, code):
        name = frappe.db.get_value("TNA Milestone", {"order_tna": tna, "milestone_type": code}, "name")
        return frappe.get_doc("TNA Milestone", name) if name else None

    def save(ms):
        ms.flags.ignore_permissions = True
        ms.save()

    def stamp(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        for t in tnas_for(sales_order, style_item, colour):
            ms = milestone(t.name, code)
            if not ms or cint(ms.not_applicable):
                continue
            changed = False
            if planned:
                if not ms.actual_date and date and getdate(date) != getdate(ms.planned_date):
                    ms.revised_date = getdate(date)
                    ms.revision_reason = ms.revision_reason or "Supplier plan (%s)" % source_name
                    changed = True
            elif partial:
                if not ms.actual_date and not cint(ms.partial):
                    ms.partial = 1
                    ms.source_doctype = source_doctype
                    ms.source_name = source_name
                    changed = True
            else:
                same = ms.source_doctype == source_doctype and ms.source_name == source_name
                if not ms.actual_date or same:
                    ms.actual_date = getdate(date or frappe.utils.nowdate())
                    ms.partial = 0
                    ms.source_doctype = source_doctype
                    ms.source_name = source_name
                    changed = True
            if changed:
                save(ms)

    def refind(ms):
        """Best-effort: set `ms` from another live document of the right kind."""
        tna = frappe.db.get_value("Order TNA", ms.order_tna, ["sales_order", "style_item", "colour"], as_dict=True)
        found = None
        code = ms.milestone_type
        if code == "FR_RAISED" or code == "TR_RAISED":
            dt = "Fabric Requisition" if code == "FR_RAISED" else "Trim Requisition"
            child = "Fabric Requisition Item" if code == "FR_RAISED" else "Trim Requisition Item"
            r = frappe.db.sql("select p.name, date(p.approved_on) from `tab%s` p join `tab%s` c on c.parent = p.name where p.docstatus = 1 and p.status != 'Cancelled' "
                              "and c.sales_order = %%s and c.style_item = %%s and (c.colour is null or c.colour = '' or upper(c.colour) = upper(%%s)) order by p.approved_on limit 1" % (dt, child),
                              (tna.sales_order, tna.style_item, tna.colour or ""))
            found = [dt, r[0][0], r[0][1]] if r else None
        elif code == "FABRIC_BOOKED":
            r = frappe.db.sql("select o.name, o.transaction_date from `tabPurchase Order` o join `tabPurchase Order Item` i on i.parent = o.name where o.docstatus = 1 "
                              "and i.apparel_requisition_type = 'FR' and i.sales_order = %s and upper(i.apparel_colour) = upper(%s) order by o.creation limit 1", (tna.sales_order, tna.colour or ""))
            found = ["Purchase Order", r[0][0], r[0][1]] if r else None
        if found:
            ms.reload()
            ms.actual_date = getdate(found[2])
            ms.source_doctype = found[0]
            ms.source_name = found[1]
            save(ms)

    def unstamp(source_doctype, source_name):
        for name in frappe.get_all("TNA Milestone", filters={"source_doctype": source_doctype, "source_name": source_name}, pluck="name"):
            ms = frappe.get_doc("TNA Milestone", name)
            ms.actual_date = None
            ms.partial = 0
            ms.source_doctype = None
            ms.source_name = None
            save(ms)
            refind(ms)

    def sync_samples(tna_name):
        so = frappe.db.get_value("Order TNA", tna_name, ["sales_order", "style_item", "colour", "customer"], as_dict=True)

        def approval_ok(stype):
            """Does the gate let this sample type pass for the style x colour (an approval, or one not required / not raised and not Required)?"""
            rule = get_rules(so.customer, so.sales_order, so.style_item).get(stype)
            gate = effective_gate(rule, so.sales_order) if rule else "No"
            f = scope_filters(so.sales_order, so.style_item)
            f["sample_type"] = stype
            rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
            if rule and rule["per_colour"]:
                rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(so.colour)]
            if not rows:
                return gate != "Required"
            return len([r for r in rows if r.status not in GATE_OK]) == 0

        def dates_for(types):
            f = scope_filters(so.sales_order, so.style_item)
            f["sample_type"] = ["in", list(types)]
            f["status"] = ["in", list(APPROVED)]
            rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "colour", "approved_on", "sample_type"])
            return [[r.name, r.approved_on] for r in rows if r.approved_on and (not norm(r.colour) or norm(r.colour) == norm(so.colour))]

        codes = []
        for t in SAMPLE_CODES:
            if SAMPLE_CODES[t] not in codes:
                codes.append(SAMPLE_CODES[t])
        codes.append("PP_GPT")
        for code in codes:
            ms = milestone(tna_name, code)
            if not ms or cint(ms.not_applicable):
                continue
            types = [t for t in SAMPLE_CODES if SAMPLE_CODES[t] == code] if code != "PP_GPT" else list(PP_TYPES)
            ok = len([t for t in types if approval_ok(t)]) == len(types)
            done = dates_for(types) if ok else []
            if code == "PP_GPT":
                ok = bool(dates_for(["PP"])) and approval_ok("Garment Test (GPT)")
                done = dates_for(PP_TYPES) if ok else []
            elif code == "TOP":
                ok = bool(done)
            if done and (ok or code != "PP_GPT"):
                best = sorted(done, key=lambda d: d[1])[-1]
                if not ms.actual_date or ms.source_doctype == "Sample Approval":
                    ms.actual_date = getdate(best[1])
                    ms.partial = 0
                    ms.source_doctype = "Sample Approval"
                    ms.source_name = best[0]
                    save(ms)
            elif ms.source_doctype == "Sample Approval" and ms.actual_date:
                ms.actual_date = None
                ms.source_doctype = None
                ms.source_name = None
                save(ms)

    if action == "stamp":
        stamp(form.get("sales_order"), form.get("style_item"), form.get("colour"), form.get("code"), form.get("date"), form.get("source_doctype"), form.get("source_name"),
              cint(form.get("partial")), cint(form.get("planned")))
        for t in tnas_for(form.get("sales_order"), form.get("style_item"), form.get("colour")):
            refresh_order_tna(t.name)
    elif action == "unstamp":
        unstamp(form.get("source_doctype"), form.get("source_name"))
    elif action == "refresh":
        refresh_order_tna(form.get("order_tna"))
    elif action == "refind":
        for code in ("FR_RAISED", "TR_RAISED", "FABRIC_BOOKED"):
            ms = milestone(form.get("order_tna"), code)
            if ms and not ms.actual_date and not cint(ms.not_applicable):
                refind(ms)
    elif action == "samples":
        sync_samples(form.get("order_tna"))
        refresh_order_tna(form.get("order_tna"))
    else:
        frappe.throw("arinox_tna: unknown action %s" % action)


main()

# API arinox_order_tna_replan: recompute the plan after the PCD or the sewing window changed.
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from tna/status.py: the state of a milestone and of an order, computed from today's date and never trusted from a stored value
    COLOURS = {"Done": "#2f855a", "In Progress": "#2b6cb0", "Late": "#c53030", "Not Started": "#718096", "Not Applicable": "#cbd5e0"}


    def milestone_state(not_applicable, actual_date, partial, planned_date, revised_date):
        """[status, delay_days, progress]. Late = the current target (revised, else planned) has passed and it is not done.
        Delay is measured against the baseline: days late if done late, days overdue if still open, days slipped if revised."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cint(not_applicable):
            return ["Not Applicable", 0, 0]
        due = getdate(revised_date or planned_date) if (revised_date or planned_date) else None
        base = getdate(planned_date) if planned_date else None
        if actual_date:
            return ["Done", max(frappe.utils.date_diff(actual_date, base), 0) if base else 0, 100]
        if due and due < today:
            return ["Late", max(frappe.utils.date_diff(today, base), 0) if base else 0, 50 if cint(partial) else 0]
        delay = max(frappe.utils.date_diff(due, base), 0) if (revised_date and base and due) else 0
        return ["In Progress" if cint(partial) else "Not Started", delay, 50 if cint(partial) else 0]


    def order_state(milestones, plan_feasible, cancelled):
        """[status, critical_delay_days] of an order from its milestone dicts."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cancelled:
            return ["Cancelled", 0]
        live = [m for m in milestones if not cint(m.get("not_applicable"))]
        if live and len([m for m in live if m.get("actual_date")]) == len(live):
            return ["Completed", 0]
        crit_late = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                     and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        delays = [max(frappe.utils.date_diff(m.get("actual_date") or today, m["planned_date"]), 0) for m in live
                  if cint(m.get("is_critical")) and m.get("planned_date") and (m.get("actual_date") or m in crit_late)]
        worst = max(delays) if delays else 0
        if crit_late:
            return ["Late", worst]
        other_late = [m for m in live if not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date")) and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        soon = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                and 0 <= frappe.utils.date_diff(m.get("revised_date") or m.get("planned_date"), today) <= 3]
        if other_late or soon or not cint(plan_feasible):
            return ["At Risk", worst]
        return ["On Track", worst]


    def refresh_order_tna(name):
        """Recompute and store every milestone's status and the order's status."""
        if not frappe.db.exists("Order TNA", name):
            return
        t = frappe.db.get_value("Order TNA", name, ["status", "plan_feasible", "critical_delay_days"], as_dict=True)
        ms = frappe.get_all("TNA Milestone", filters={"order_tna": name}, fields=["name", "not_applicable", "actual_date", "partial", "planned_date", "revised_date", "is_critical",
                                                                                  "status", "delay_days", "color", "progress"])
        for m in ms:
            st = milestone_state(m.not_applicable, m.actual_date, m.partial, m.planned_date, m.revised_date)
            colour = COLOURS[st[0]]
            if m.status != st[0] or m.delay_days != st[1] or m.progress != st[2] or m.color != colour:
                frappe.db.set_value("TNA Milestone", m.name, {"status": st[0], "delay_days": st[1], "progress": st[2], "color": colour}, update_modified=False)
            m["status"] = st[0]
        if t.status == "Cancelled":
            return
        o = order_state(ms, t.plan_feasible, False)
        if o[0] != t.status or o[1] != t.critical_delay_days:
            frappe.db.set_value("Order TNA", name, {"status": o[0], "critical_delay_days": o[1]}, update_modified=False)
    # shared helpers from tna/planner.py (+ backfill from tna/events.py): planning dates for an Order TNA, building and re-planning its milestones.
    # Needs lib_samples.py (rules) and lib_tna.py (refresh) included first.
    def holiday_dates(company):
        """List of non-working dates from the Company's default Holiday List; None when the company has no list."""
        hl = frappe.db.get_value("Company", company, "default_holiday_list") if company else None
        if not hl:
            return None
        return [frappe.utils.getdate(d) for d in frappe.get_all("Holiday", filters={"parent": hl}, pluck="holiday_date")]


    def working_day(d, holidays, direction):
        """Move `d` to the next (direction 1) or previous (-1) working day. With no Holiday List only Sundays are off."""
        d = frappe.utils.getdate(d)
        i = 0
        while i < 60:
            off = (d in holidays) if holidays is not None else d.weekday() == 6
            if not off:
                return d
            d = frappe.utils.getdate(frappe.utils.add_days(d, direction))
            i = i + 1
        return d


    def plan_dates(rows, order_received, ex_factory, qty, holidays, pcd, overrides, na):
        """rows: dicts with code, basis, after, offset_days, duration_rule, daily_output (in template order). Returns [dates, unresolved codes], dates = code -> {planned, start}
        in template order. A not-applicable milestone passes its predecessor's date through (offset 0) so a skipped step adds no days. `pcd` and `overrides` pin dates."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        ov = {}
        for k in (overrides or {}):
            if overrides[k]:
                ov[k] = getdate(overrides[k])
        if pcd and "PCD" not in ov:
            ov["PCD"] = getdate(pcd)
        dates = {}
        pending = list(rows)
        p = 0
        while p < len(rows) + 2:
            p = p + 1
            moved = False
            for r in list(pending):
                if r["basis"] == "Order Received":
                    base = order_received
                elif r["basis"] == "Ex-Factory":
                    base = ex_factory
                elif r["basis"] == "PCD":
                    base = (dates.get("PCD") or {}).get("planned") or pcd
                else:
                    base = (dates.get(r.get("after")) or {}).get("planned")
                if base is None:
                    continue
                offset = cint(r.get("offset_days"))
                if r.get("duration_rule") == "Qty / Daily Output" and cint(r.get("daily_output")):
                    offset = max(1, frappe.utils.ceil(frappe.utils.flt(qty) / cint(r["daily_output"])))
                if r["code"] in na:
                    offset = 0
                if r["code"] in ov:
                    planned = ov[r["code"]]
                else:
                    planned = working_day(frappe.utils.add_days(getdate(base), offset), holidays, -1 if offset < 0 else 1)
                start = getdate(base) if r["basis"] == "After Milestone" else planned
                dates[r["code"]] = {"planned": planned, "start": min(start, planned)}
                pending.remove(r)
                moved = True
            if not pending or not moved:
                break
        out = {}
        for r in rows:
            if r["code"] in dates:
                out[r["code"]] = dates[r["code"]]
        return [out, [r["code"] for r in pending]]


    def feasibility(dates, ex_factory):
        """[feasible, note]: the last milestone before Ex-Factory must not land after the ex-factory date."""
        if not dates or not ex_factory:
            return [True, None]
        body = {}
        for c in dates:
            if c != "EX_FACTORY":
                body[c] = dates[c]["planned"]
        if not body:
            return [True, None]
        code = sorted(body, key=lambda c: body[c])[-1]
        late = frappe.utils.date_diff(body[code], ex_factory)
        if late > 0:
            return [False, "Plan is %s days late against ex-factory (%s lands on %s)." % (late, code, body[code])]
        return [True, None]


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def applies(mtype, sales_order, style_item, customer):
        """Whether a milestone type applies to this style on this order."""
        when = mtype.applies_when or "Always"
        if when == "Always":
            return True
        if when == "Washed Only":
            tp = tech_pack_for(style_item)
            text = ("%s %s" % ((tp.wash_description or "") if tp else "", (tp.wash_code or "") if tp else "")).strip().lower()
            if text and "no wash" not in text:
                return True
            return bool(frappe.db.exists("Sample Approval", {"style_item": style_item, "is_washed": 1}))
        if when == "Printed Only":
            cs_name = None
            for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
                if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                    cs_name = it.apparel_cost_sheet
                    break
            if not cs_name:
                return False
            for ch in frappe.get_doc("Cost Sheet", cs_name).charges:
                if (ch.cost_head or "").lower() == "printing" and not ch.not_applicable and frappe.utils.flt(ch.rate):
                    return True
            return False
        rule = get_rules(customer, sales_order, style_item).get(mtype.sample_type)
        return bool(rule) and effective_gate(rule, sales_order) != "No"


    def pick_template(customer, product_type, shipment_mode):
        """Most specific template: customer + product type, customer, product type, then the default."""
        best = None
        score = -1
        for t in frappe.get_all("TNA Template", fields=["name", "customer", "product_type", "shipment_mode", "is_default"]):
            s = 0
            for f, v, w in (("customer", customer, 4), ("product_type", product_type, 2), ("shipment_mode", shipment_mode, 1)):
                if t.get(f):
                    if t.get(f) != v:
                        s = None
                        break
                    s += w
            if s is None:
                continue
            if not (t.customer or t.product_type or t.shipment_mode) and not frappe.utils.cint(t.is_default):
                continue
            if s > score:
                best = t.name
                score = s
        return best or frappe.db.get_single_value("Apparel Settings", "default_tna_template")


    def order_groups(sales_order):
        """Sales Order lines grouped to style x colour x ex-factory date (a list of dicts)."""
        groups = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "delivery_date"], order_by="idx"):
            key = "%s|%s|%s" % (style_of(it.item_code), (it.apparel_colour or "").strip(), str(frappe.utils.getdate(it.delivery_date)) if it.delivery_date else "")
            g = groups.get(key)
            if not g:
                g = {"style_item": style_of(it.item_code), "colour": (it.apparel_colour or "").strip(), "ex_factory": it.delivery_date, "qty": 0, "ship_tos": []}
                groups[key] = g
            g["qty"] = g["qty"] + frappe.utils.cint(it.qty)
            st = (it.apparel_ship_to or "").strip()
            if st and st not in g["ship_tos"]:
                g["ship_tos"].append(st)
        return [groups[k] for k in groups]


    def allocation_for(sales_order, style_item, colour):
        """[factory, pcd, sewing_end] from the Factory Allocation for a style x colour."""
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if not fa:
            return [None, None, None]
        for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "factory", "pcd", "sewing_end"], order_by="pcd"):
            if not colour or not (r.colour or "").strip() or r.colour.strip().upper() == colour.strip().upper():
                return [r.factory, r.pcd, r.sewing_end]
        return [None, None, None]


    def compute_plan(tna):
        """[dates, na codes, unresolved, rows] for an Order TNA document from its template."""
        t = frappe.get_doc("TNA Template", tna.template)
        rows = [{"code": r.milestone_type, "basis": r.basis, "after": r.after_milestone, "offset_days": r.offset_days, "duration_rule": r.duration_rule,
                 "daily_output": r.daily_output, "owner_role": r.owner_role} for r in t.milestones]
        so = frappe.db.get_value("Sales Order", tna.sales_order, ["customer", "company"], as_dict=True)
        na = []
        for r in rows:
            if applies(frappe.get_cached_doc("TNA Milestone Type", r["code"]), tna.sales_order, tna.style_item, so.customer):
                continue
            na.append(r["code"])
        al = allocation_for(tna.sales_order, tna.style_item, tna.colour)
        overrides = {}
        if al[2]:
            overrides["BULK_FINISH"] = al[2]
        res = plan_dates(rows, tna.order_received_date, tna.ex_factory_date, tna.order_qty, holiday_dates(so.company), tna.pcd or al[1], overrides, na)
        return [res[0], na, res[1], rows]


    def build_milestones(tna):
        plan = compute_plan(tna)
        dates = plan[0]
        na = plan[1]
        rows = plan[3]
        if plan[2]:
            frappe.msgprint("These milestones could not be dated (missing base): %s" % ", ".join(plan[2]), indicator="orange")
        meta = {}
        for r in rows:
            meta[r["code"]] = r
        names = {}
        seq = 0
        for r in rows:
            code = r["code"]
            if code not in dates:
                continue
            seq = seq + 10
            mt = frappe.get_cached_doc("TNA Milestone Type", code)
            ms = frappe.get_doc({"doctype": "TNA Milestone", "order_tna": tna.name, "milestone_type": code, "sequence": seq, "label": mt.label, "department": mt.department,
                                 "is_critical": mt.is_critical, "planned_start": dates[code]["start"], "planned_date": dates[code]["planned"], "not_applicable": 1 if code in na else 0})
            ms.flags.ignore_permissions = True
            ms.insert()
            names[code] = ms.name
        for code in names:
            after = meta[code]["after"] if meta[code]["basis"] == "After Milestone" else None
            if after and after in names:
                frappe.db.set_value("TNA Milestone", names[code], "depends_on_tasks", names[after], update_modified=False)
        live = {}
        for c in dates:
            if c not in na:
                live[c] = dates[c]
        fe = feasibility(live, tna.ex_factory_date)
        tna.db_set({"plan_feasible": 1 if fe[0] else 0, "feasibility_note": fe[1]})
        refresh_order_tna(tna.name)


    def replan(order_tna):
        """Recompute planned dates after the PCD or the sewing window changed. Before the baseline is locked the planned dates move;
        after it, only the revised dates do (the baseline stays as agreed)."""
        tna = frappe.get_doc("Order TNA", order_tna)
        if tna.status == "Cancelled":
            return
        al = allocation_for(tna.sales_order, tna.style_item, tna.colour)
        if al[0] and tna.factory != al[0]:
            tna.db_set("factory", al[0])
            tna.factory = al[0]
            for n in frappe.get_all("TNA Milestone", filters={"order_tna": order_tna}, pluck="name"):
                frappe.db.set_value("TNA Milestone", n, "factory", al[0], update_modified=False)
        if al[1] and (not tna.pcd or frappe.utils.getdate(tna.pcd) != frappe.utils.getdate(al[1])):
            tna.db_set("pcd", al[1])
            tna.pcd = al[1]
        plan = compute_plan(tna)
        dates = plan[0]
        locked = frappe.utils.cint(tna.baseline_locked)
        getdate = frappe.utils.getdate
        for ms in frappe.get_all("TNA Milestone", filters={"order_tna": order_tna}, fields=["name", "milestone_type", "actual_date", "planned_date", "revised_date", "not_applicable"]):
            d = dates.get(ms.milestone_type)
            if not d or ms.actual_date:
                continue
            if locked:
                if getdate(d["planned"]) != getdate(ms.planned_date):
                    frappe.db.set_value("TNA Milestone", ms.name, {"revised_date": d["planned"], "revision_reason": "Factory allocation / plan change"}, update_modified=False)
                elif ms.revised_date:
                    frappe.db.set_value("TNA Milestone", ms.name, {"revised_date": None}, update_modified=False)
            else:
                frappe.db.set_value("TNA Milestone", ms.name, {"planned_date": d["planned"], "planned_start": d["start"], "revised_date": None}, update_modified=False)
        live = {}
        for c in dates:
            if c not in plan[1]:
                live[c] = dates[c]
        fe = feasibility(live, tna.ex_factory_date)
        tna.db_set({"plan_feasible": 1 if fe[0] else 0, "feasibility_note": fe[1]})
        refresh_order_tna(order_tna)


    def backfill(order_tna):
        """A T&A made after the fact picks up what already happened (needs the arinox_tna script)."""
        tna = frappe.get_doc("Order TNA", order_tna)

        def st(code, date, dt, name):
            run_script("arinox_tna", action="stamp", sales_order=tna.sales_order, style_item=tna.style_item, colour=tna.colour, code=code, date=str(date), source_doctype=dt, source_name=name,
                       partial=0, planned=0)

        st("ORDER_RECEIVED", tna.order_received_date, "Sales Order", tna.sales_order)
        tp = frappe.db.get_value("Tech Pack", {"style_item": tna.style_item, "docstatus": 1}, ["name", "received_on", "buyer_bom_file"], as_dict=True, order_by="creation")
        if tp:
            st("TECH_PACK_RECEIVED", tp.received_on or frappe.utils.nowdate(), "Tech Pack", tp.name)
            if tp.buyer_bom_file:
                st("BOM_RECEIVED", tp.received_on or frappe.utils.nowdate(), "Tech Pack", tp.name)
        run_script("arinox_tna", action="samples", order_tna=tna.name)
        run_script("arinox_tna", action="refind", order_tna=tna.name)
        for m in frappe.get_all("PP Meeting", filters={"sales_order": tna.sales_order, "style_item": tna.style_item, "docstatus": 1}, fields=["name", "meeting_date", "meeting_type"]):
            st("PILOT_RUN" if m.meeting_type == "Pilot Run" else "PP_MEETING", m.meeting_date, "PP Meeting", m.name)
        refresh_order_tna(tna.name)
    frappe.get_doc("Order TNA", frappe.form_dict.get("name")).check_permission("write")
    replan(frappe.form_dict.get("name"))
    frappe.flags.arinox_result = 1


main()

# TNA Template, Before Save: each milestone once, "after" rows name another milestone of the template, no loops, daily output where the duration needs it, one default.
def run(doc):
    codes = [r.milestone_type for r in doc.milestones]
    for c in codes:
        if codes.count(c) > 1:
            frappe.throw("A milestone can appear only once in a template.")
    for r in doc.milestones:
        if r.basis == "After Milestone":
            if not r.after_milestone:
                frappe.throw("Row %s: choose the milestone this one follows." % r.idx)
            if r.after_milestone == r.milestone_type:
                frappe.throw("Row %s: a milestone cannot follow itself." % r.idx)
            if r.after_milestone not in codes:
                frappe.throw("Row %s: %s is not in this template." % (r.idx, r.after_milestone))
        if r.duration_rule == "Qty / Daily Output" and frappe.utils.cint(r.daily_output) <= 0:
            frappe.throw("Row %s: enter the daily output." % r.idx)
    after = {}
    for r in doc.milestones:
        if r.basis == "After Milestone":
            after[r.milestone_type] = r.after_milestone
    for start in after:
        seen = []
        cur = start
        while cur in after:
            if cur in seen:
                frappe.throw("The milestones %s follow each other in a loop." % ", ".join(sorted(seen)))
            seen.append(cur)
            cur = after[cur]
    if frappe.utils.cint(doc.is_default):
        for other in frappe.get_all("TNA Template", filters={"is_default": 1, "name": ["!=", doc.name or ""]}, pluck="name"):
            frappe.db.set_value("TNA Template", other, "is_default", 0)


run(doc)

# API arinox_planner_make_order_tnas: one Order TNA per style x colour x ex-factory date of a submitted Sales Order. Existing ones are left alone. Answers the names made.
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from tna/status.py: the state of a milestone and of an order, computed from today's date and never trusted from a stored value
    COLOURS = {"Done": "#2f855a", "In Progress": "#2b6cb0", "Late": "#c53030", "Not Started": "#718096", "Not Applicable": "#cbd5e0"}


    def milestone_state(not_applicable, actual_date, partial, planned_date, revised_date):
        """[status, delay_days, progress]. Late = the current target (revised, else planned) has passed and it is not done.
        Delay is measured against the baseline: days late if done late, days overdue if still open, days slipped if revised."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cint(not_applicable):
            return ["Not Applicable", 0, 0]
        due = getdate(revised_date or planned_date) if (revised_date or planned_date) else None
        base = getdate(planned_date) if planned_date else None
        if actual_date:
            return ["Done", max(frappe.utils.date_diff(actual_date, base), 0) if base else 0, 100]
        if due and due < today:
            return ["Late", max(frappe.utils.date_diff(today, base), 0) if base else 0, 50 if cint(partial) else 0]
        delay = max(frappe.utils.date_diff(due, base), 0) if (revised_date and base and due) else 0
        return ["In Progress" if cint(partial) else "Not Started", delay, 50 if cint(partial) else 0]


    def order_state(milestones, plan_feasible, cancelled):
        """[status, critical_delay_days] of an order from its milestone dicts."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cancelled:
            return ["Cancelled", 0]
        live = [m for m in milestones if not cint(m.get("not_applicable"))]
        if live and len([m for m in live if m.get("actual_date")]) == len(live):
            return ["Completed", 0]
        crit_late = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                     and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        delays = [max(frappe.utils.date_diff(m.get("actual_date") or today, m["planned_date"]), 0) for m in live
                  if cint(m.get("is_critical")) and m.get("planned_date") and (m.get("actual_date") or m in crit_late)]
        worst = max(delays) if delays else 0
        if crit_late:
            return ["Late", worst]
        other_late = [m for m in live if not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date")) and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        soon = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                and 0 <= frappe.utils.date_diff(m.get("revised_date") or m.get("planned_date"), today) <= 3]
        if other_late or soon or not cint(plan_feasible):
            return ["At Risk", worst]
        return ["On Track", worst]


    def refresh_order_tna(name):
        """Recompute and store every milestone's status and the order's status."""
        if not frappe.db.exists("Order TNA", name):
            return
        t = frappe.db.get_value("Order TNA", name, ["status", "plan_feasible", "critical_delay_days"], as_dict=True)
        ms = frappe.get_all("TNA Milestone", filters={"order_tna": name}, fields=["name", "not_applicable", "actual_date", "partial", "planned_date", "revised_date", "is_critical",
                                                                                  "status", "delay_days", "color", "progress"])
        for m in ms:
            st = milestone_state(m.not_applicable, m.actual_date, m.partial, m.planned_date, m.revised_date)
            colour = COLOURS[st[0]]
            if m.status != st[0] or m.delay_days != st[1] or m.progress != st[2] or m.color != colour:
                frappe.db.set_value("TNA Milestone", m.name, {"status": st[0], "delay_days": st[1], "progress": st[2], "color": colour}, update_modified=False)
            m["status"] = st[0]
        if t.status == "Cancelled":
            return
        o = order_state(ms, t.plan_feasible, False)
        if o[0] != t.status or o[1] != t.critical_delay_days:
            frappe.db.set_value("Order TNA", name, {"status": o[0], "critical_delay_days": o[1]}, update_modified=False)
    # shared helpers from tna/planner.py (+ backfill from tna/events.py): planning dates for an Order TNA, building and re-planning its milestones.
    # Needs lib_samples.py (rules) and lib_tna.py (refresh) included first.
    def holiday_dates(company):
        """List of non-working dates from the Company's default Holiday List; None when the company has no list."""
        hl = frappe.db.get_value("Company", company, "default_holiday_list") if company else None
        if not hl:
            return None
        return [frappe.utils.getdate(d) for d in frappe.get_all("Holiday", filters={"parent": hl}, pluck="holiday_date")]


    def working_day(d, holidays, direction):
        """Move `d` to the next (direction 1) or previous (-1) working day. With no Holiday List only Sundays are off."""
        d = frappe.utils.getdate(d)
        i = 0
        while i < 60:
            off = (d in holidays) if holidays is not None else d.weekday() == 6
            if not off:
                return d
            d = frappe.utils.getdate(frappe.utils.add_days(d, direction))
            i = i + 1
        return d


    def plan_dates(rows, order_received, ex_factory, qty, holidays, pcd, overrides, na):
        """rows: dicts with code, basis, after, offset_days, duration_rule, daily_output (in template order). Returns [dates, unresolved codes], dates = code -> {planned, start}
        in template order. A not-applicable milestone passes its predecessor's date through (offset 0) so a skipped step adds no days. `pcd` and `overrides` pin dates."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        ov = {}
        for k in (overrides or {}):
            if overrides[k]:
                ov[k] = getdate(overrides[k])
        if pcd and "PCD" not in ov:
            ov["PCD"] = getdate(pcd)
        dates = {}
        pending = list(rows)
        p = 0
        while p < len(rows) + 2:
            p = p + 1
            moved = False
            for r in list(pending):
                if r["basis"] == "Order Received":
                    base = order_received
                elif r["basis"] == "Ex-Factory":
                    base = ex_factory
                elif r["basis"] == "PCD":
                    base = (dates.get("PCD") or {}).get("planned") or pcd
                else:
                    base = (dates.get(r.get("after")) or {}).get("planned")
                if base is None:
                    continue
                offset = cint(r.get("offset_days"))
                if r.get("duration_rule") == "Qty / Daily Output" and cint(r.get("daily_output")):
                    offset = max(1, frappe.utils.ceil(frappe.utils.flt(qty) / cint(r["daily_output"])))
                if r["code"] in na:
                    offset = 0
                if r["code"] in ov:
                    planned = ov[r["code"]]
                else:
                    planned = working_day(frappe.utils.add_days(getdate(base), offset), holidays, -1 if offset < 0 else 1)
                start = getdate(base) if r["basis"] == "After Milestone" else planned
                dates[r["code"]] = {"planned": planned, "start": min(start, planned)}
                pending.remove(r)
                moved = True
            if not pending or not moved:
                break
        out = {}
        for r in rows:
            if r["code"] in dates:
                out[r["code"]] = dates[r["code"]]
        return [out, [r["code"] for r in pending]]


    def feasibility(dates, ex_factory):
        """[feasible, note]: the last milestone before Ex-Factory must not land after the ex-factory date."""
        if not dates or not ex_factory:
            return [True, None]
        body = {}
        for c in dates:
            if c != "EX_FACTORY":
                body[c] = dates[c]["planned"]
        if not body:
            return [True, None]
        code = sorted(body, key=lambda c: body[c])[-1]
        late = frappe.utils.date_diff(body[code], ex_factory)
        if late > 0:
            return [False, "Plan is %s days late against ex-factory (%s lands on %s)." % (late, code, body[code])]
        return [True, None]


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def applies(mtype, sales_order, style_item, customer):
        """Whether a milestone type applies to this style on this order."""
        when = mtype.applies_when or "Always"
        if when == "Always":
            return True
        if when == "Washed Only":
            tp = tech_pack_for(style_item)
            text = ("%s %s" % ((tp.wash_description or "") if tp else "", (tp.wash_code or "") if tp else "")).strip().lower()
            if text and "no wash" not in text:
                return True
            return bool(frappe.db.exists("Sample Approval", {"style_item": style_item, "is_washed": 1}))
        if when == "Printed Only":
            cs_name = None
            for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
                if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                    cs_name = it.apparel_cost_sheet
                    break
            if not cs_name:
                return False
            for ch in frappe.get_doc("Cost Sheet", cs_name).charges:
                if (ch.cost_head or "").lower() == "printing" and not ch.not_applicable and frappe.utils.flt(ch.rate):
                    return True
            return False
        rule = get_rules(customer, sales_order, style_item).get(mtype.sample_type)
        return bool(rule) and effective_gate(rule, sales_order) != "No"


    def pick_template(customer, product_type, shipment_mode):
        """Most specific template: customer + product type, customer, product type, then the default."""
        best = None
        score = -1
        for t in frappe.get_all("TNA Template", fields=["name", "customer", "product_type", "shipment_mode", "is_default"]):
            s = 0
            for f, v, w in (("customer", customer, 4), ("product_type", product_type, 2), ("shipment_mode", shipment_mode, 1)):
                if t.get(f):
                    if t.get(f) != v:
                        s = None
                        break
                    s += w
            if s is None:
                continue
            if not (t.customer or t.product_type or t.shipment_mode) and not frappe.utils.cint(t.is_default):
                continue
            if s > score:
                best = t.name
                score = s
        return best or frappe.db.get_single_value("Apparel Settings", "default_tna_template")


    def order_groups(sales_order):
        """Sales Order lines grouped to style x colour x ex-factory date (a list of dicts)."""
        groups = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "delivery_date"], order_by="idx"):
            key = "%s|%s|%s" % (style_of(it.item_code), (it.apparel_colour or "").strip(), str(frappe.utils.getdate(it.delivery_date)) if it.delivery_date else "")
            g = groups.get(key)
            if not g:
                g = {"style_item": style_of(it.item_code), "colour": (it.apparel_colour or "").strip(), "ex_factory": it.delivery_date, "qty": 0, "ship_tos": []}
                groups[key] = g
            g["qty"] = g["qty"] + frappe.utils.cint(it.qty)
            st = (it.apparel_ship_to or "").strip()
            if st and st not in g["ship_tos"]:
                g["ship_tos"].append(st)
        return [groups[k] for k in groups]


    def allocation_for(sales_order, style_item, colour):
        """[factory, pcd, sewing_end] from the Factory Allocation for a style x colour."""
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if not fa:
            return [None, None, None]
        for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "factory", "pcd", "sewing_end"], order_by="pcd"):
            if not colour or not (r.colour or "").strip() or r.colour.strip().upper() == colour.strip().upper():
                return [r.factory, r.pcd, r.sewing_end]
        return [None, None, None]


    def compute_plan(tna):
        """[dates, na codes, unresolved, rows] for an Order TNA document from its template."""
        t = frappe.get_doc("TNA Template", tna.template)
        rows = [{"code": r.milestone_type, "basis": r.basis, "after": r.after_milestone, "offset_days": r.offset_days, "duration_rule": r.duration_rule,
                 "daily_output": r.daily_output, "owner_role": r.owner_role} for r in t.milestones]
        so = frappe.db.get_value("Sales Order", tna.sales_order, ["customer", "company"], as_dict=True)
        na = []
        for r in rows:
            if applies(frappe.get_cached_doc("TNA Milestone Type", r["code"]), tna.sales_order, tna.style_item, so.customer):
                continue
            na.append(r["code"])
        al = allocation_for(tna.sales_order, tna.style_item, tna.colour)
        overrides = {}
        if al[2]:
            overrides["BULK_FINISH"] = al[2]
        res = plan_dates(rows, tna.order_received_date, tna.ex_factory_date, tna.order_qty, holiday_dates(so.company), tna.pcd or al[1], overrides, na)
        return [res[0], na, res[1], rows]


    def build_milestones(tna):
        plan = compute_plan(tna)
        dates = plan[0]
        na = plan[1]
        rows = plan[3]
        if plan[2]:
            frappe.msgprint("These milestones could not be dated (missing base): %s" % ", ".join(plan[2]), indicator="orange")
        meta = {}
        for r in rows:
            meta[r["code"]] = r
        names = {}
        seq = 0
        for r in rows:
            code = r["code"]
            if code not in dates:
                continue
            seq = seq + 10
            mt = frappe.get_cached_doc("TNA Milestone Type", code)
            ms = frappe.get_doc({"doctype": "TNA Milestone", "order_tna": tna.name, "milestone_type": code, "sequence": seq, "label": mt.label, "department": mt.department,
                                 "is_critical": mt.is_critical, "planned_start": dates[code]["start"], "planned_date": dates[code]["planned"], "not_applicable": 1 if code in na else 0})
            ms.flags.ignore_permissions = True
            ms.insert()
            names[code] = ms.name
        for code in names:
            after = meta[code]["after"] if meta[code]["basis"] == "After Milestone" else None
            if after and after in names:
                frappe.db.set_value("TNA Milestone", names[code], "depends_on_tasks", names[after], update_modified=False)
        live = {}
        for c in dates:
            if c not in na:
                live[c] = dates[c]
        fe = feasibility(live, tna.ex_factory_date)
        tna.db_set({"plan_feasible": 1 if fe[0] else 0, "feasibility_note": fe[1]})
        refresh_order_tna(tna.name)


    def replan(order_tna):
        """Recompute planned dates after the PCD or the sewing window changed. Before the baseline is locked the planned dates move;
        after it, only the revised dates do (the baseline stays as agreed)."""
        tna = frappe.get_doc("Order TNA", order_tna)
        if tna.status == "Cancelled":
            return
        al = allocation_for(tna.sales_order, tna.style_item, tna.colour)
        if al[0] and tna.factory != al[0]:
            tna.db_set("factory", al[0])
            tna.factory = al[0]
            for n in frappe.get_all("TNA Milestone", filters={"order_tna": order_tna}, pluck="name"):
                frappe.db.set_value("TNA Milestone", n, "factory", al[0], update_modified=False)
        if al[1] and (not tna.pcd or frappe.utils.getdate(tna.pcd) != frappe.utils.getdate(al[1])):
            tna.db_set("pcd", al[1])
            tna.pcd = al[1]
        plan = compute_plan(tna)
        dates = plan[0]
        locked = frappe.utils.cint(tna.baseline_locked)
        getdate = frappe.utils.getdate
        for ms in frappe.get_all("TNA Milestone", filters={"order_tna": order_tna}, fields=["name", "milestone_type", "actual_date", "planned_date", "revised_date", "not_applicable"]):
            d = dates.get(ms.milestone_type)
            if not d or ms.actual_date:
                continue
            if locked:
                if getdate(d["planned"]) != getdate(ms.planned_date):
                    frappe.db.set_value("TNA Milestone", ms.name, {"revised_date": d["planned"], "revision_reason": "Factory allocation / plan change"}, update_modified=False)
                elif ms.revised_date:
                    frappe.db.set_value("TNA Milestone", ms.name, {"revised_date": None}, update_modified=False)
            else:
                frappe.db.set_value("TNA Milestone", ms.name, {"planned_date": d["planned"], "planned_start": d["start"], "revised_date": None}, update_modified=False)
        live = {}
        for c in dates:
            if c not in plan[1]:
                live[c] = dates[c]
        fe = feasibility(live, tna.ex_factory_date)
        tna.db_set({"plan_feasible": 1 if fe[0] else 0, "feasibility_note": fe[1]})
        refresh_order_tna(order_tna)


    def backfill(order_tna):
        """A T&A made after the fact picks up what already happened (needs the arinox_tna script)."""
        tna = frappe.get_doc("Order TNA", order_tna)

        def st(code, date, dt, name):
            run_script("arinox_tna", action="stamp", sales_order=tna.sales_order, style_item=tna.style_item, colour=tna.colour, code=code, date=str(date), source_doctype=dt, source_name=name,
                       partial=0, planned=0)

        st("ORDER_RECEIVED", tna.order_received_date, "Sales Order", tna.sales_order)
        tp = frappe.db.get_value("Tech Pack", {"style_item": tna.style_item, "docstatus": 1}, ["name", "received_on", "buyer_bom_file"], as_dict=True, order_by="creation")
        if tp:
            st("TECH_PACK_RECEIVED", tp.received_on or frappe.utils.nowdate(), "Tech Pack", tp.name)
            if tp.buyer_bom_file:
                st("BOM_RECEIVED", tp.received_on or frappe.utils.nowdate(), "Tech Pack", tp.name)
        run_script("arinox_tna", action="samples", order_tna=tna.name)
        run_script("arinox_tna", action="refind", order_tna=tna.name)
        for m in frappe.get_all("PP Meeting", filters={"sales_order": tna.sales_order, "style_item": tna.style_item, "docstatus": 1}, fields=["name", "meeting_date", "meeting_type"]):
            st("PILOT_RUN" if m.meeting_type == "Pilot Run" else "PP_MEETING", m.meeting_date, "PP Meeting", m.name)
        refresh_order_tna(tna.name)
    sales_order = frappe.form_dict.get("sales_order")
    template = frappe.form_dict.get("template")
    so = frappe.get_doc("Sales Order", sales_order)
    so.check_permission("read")
    frappe.new_doc("Order TNA").check_permission("create")
    if so.docstatus != 1:
        frappe.throw("Submit the Sales Order first.")
    made = []
    for g in order_groups(sales_order):
        if not g["ex_factory"]:
            frappe.msgprint("Style %s %s has no delivery date on the Sales Order; no T&A was made for it." % (g["style_item"], g["colour"]))
            continue
        if frappe.db.exists("Order TNA", {"sales_order": sales_order, "style_item": g["style_item"], "colour": g["colour"], "ex_factory_date": frappe.utils.getdate(g["ex_factory"]),
                                          "status": ["!=", "Cancelled"]}):
            continue
        tp = tech_pack_for(g["style_item"])
        tpl = template or pick_template(so.customer, tp.product_type if tp else None, None)
        if not tpl:
            frappe.throw("No T&A template. Set a default in Apparel Settings.")
        al = allocation_for(sales_order, g["style_item"], g["colour"])
        doc = frappe.get_doc({"doctype": "Order TNA", "sales_order": sales_order, "style_item": g["style_item"], "style_no": tp.style_no if tp else g["style_item"],
                              "colour": g["colour"], "order_qty": g["qty"], "ship_tos": ", ".join(sorted(g["ship_tos"])), "merchant": frappe.session.user, "factory": al[0],
                              "order_received_date": so.po_date or so.transaction_date, "order_date_missing": 0 if so.po_date else 1, "pcd": al[1],
                              "ex_factory_date": frappe.utils.getdate(g["ex_factory"]), "template": tpl})
        doc.flags.ignore_permissions = True
        doc.insert()
        build_milestones(doc)
        backfill(doc.name)
        made.append(doc.name)
    frappe.flags.arinox_result = made


main()

