# Factory Allocation, After Save: re-plan every plan of the order (the PCD and the sewing window may have moved).
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from tna/status.py: the state of a milestone and of an order, computed from today's date and never trusted from a stored value
    COLOURS = {"Done": "#2f855a", "In Progress": "#2b6cb0", "Late": "#c53030", "Not Started": "#718096", "Not Applicable": "#cbd5e0"}


    def milestone_state(not_applicable, actual_date, partial, planned_date, revised_date):
        """[status, delay_days, progress]. Late = the current target (revised, else planned) has passed and it is not done.
        Delay is measured against the baseline: days late if done late, days overdue if still open, days slipped if revised."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cint(not_applicable):
            return ["Not Applicable", 0, 0]
        due = getdate(revised_date or planned_date) if (revised_date or planned_date) else None
        base = getdate(planned_date) if planned_date else None
        if actual_date:
            return ["Done", max(frappe.utils.date_diff(actual_date, base), 0) if base else 0, 100]
        if due and due < today:
            return ["Late", max(frappe.utils.date_diff(today, base), 0) if base else 0, 50 if cint(partial) else 0]
        delay = max(frappe.utils.date_diff(due, base), 0) if (revised_date and base and due) else 0
        return ["In Progress" if cint(partial) else "Not Started", delay, 50 if cint(partial) else 0]


    def order_state(milestones, plan_feasible, cancelled):
        """[status, critical_delay_days] of an order from its milestone dicts."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cancelled:
            return ["Cancelled", 0]
        live = [m for m in milestones if not cint(m.get("not_applicable"))]
        if live and len([m for m in live if m.get("actual_date")]) == len(live):
            return ["Completed", 0]
        crit_late = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                     and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        delays = [max(frappe.utils.date_diff(m.get("actual_date") or today, m["planned_date"]), 0) for m in live
                  if cint(m.get("is_critical")) and m.get("planned_date") and (m.get("actual_date") or m in crit_late)]
        worst = max(delays) if delays else 0
        if crit_late:
            return ["Late", worst]
        other_late = [m for m in live if not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date")) and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        soon = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                and 0 <= frappe.utils.date_diff(m.get("revised_date") or m.get("planned_date"), today) <= 3]
        if other_late or soon or not cint(plan_feasible):
            return ["At Risk", worst]
        return ["On Track", worst]


    def refresh_order_tna(name):
        """Recompute and store every milestone's status and the order's status."""
        if not frappe.db.exists("Order TNA", name):
            return
        t = frappe.db.get_value("Order TNA", name, ["status", "plan_feasible", "critical_delay_days"], as_dict=True)
        ms = frappe.get_all("TNA Milestone", filters={"order_tna": name}, fields=["name", "not_applicable", "actual_date", "partial", "planned_date", "revised_date", "is_critical",
                                                                                  "status", "delay_days", "color", "progress"])
        for m in ms:
            st = milestone_state(m.not_applicable, m.actual_date, m.partial, m.planned_date, m.revised_date)
            colour = COLOURS[st[0]]
            if m.status != st[0] or m.delay_days != st[1] or m.progress != st[2] or m.color != colour:
                frappe.db.set_value("TNA Milestone", m.name, {"status": st[0], "delay_days": st[1], "progress": st[2], "color": colour}, update_modified=False)
            m["status"] = st[0]
        if t.status == "Cancelled":
            return
        o = order_state(ms, t.plan_feasible, False)
        if o[0] != t.status or o[1] != t.critical_delay_days:
            frappe.db.set_value("Order TNA", name, {"status": o[0], "critical_delay_days": o[1]}, update_modified=False)
    # shared helpers from tna/planner.py (+ backfill from tna/events.py): planning dates for an Order TNA, building and re-planning its milestones.
    # Needs lib_samples.py (rules) and lib_tna.py (refresh) included first.
    def holiday_dates(company):
        """List of non-working dates from the Company's default Holiday List; None when the company has no list."""
        hl = frappe.db.get_value("Company", company, "default_holiday_list") if company else None
        if not hl:
            return None
        return [frappe.utils.getdate(d) for d in frappe.get_all("Holiday", filters={"parent": hl}, pluck="holiday_date")]


    def working_day(d, holidays, direction):
        """Move `d` to the next (direction 1) or previous (-1) working day. With no Holiday List only Sundays are off."""
        d = frappe.utils.getdate(d)
        i = 0
        while i < 60:
            off = (d in holidays) if holidays is not None else d.weekday() == 6
            if not off:
                return d
            d = frappe.utils.getdate(frappe.utils.add_days(d, direction))
            i = i + 1
        return d


    def plan_dates(rows, order_received, ex_factory, qty, holidays, pcd, overrides, na):
        """rows: dicts with code, basis, after, offset_days, duration_rule, daily_output (in template order). Returns [dates, unresolved codes], dates = code -> {planned, start}
        in template order. A not-applicable milestone passes its predecessor's date through (offset 0) so a skipped step adds no days. `pcd` and `overrides` pin dates."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        ov = {}
        for k in (overrides or {}):
            if overrides[k]:
                ov[k] = getdate(overrides[k])
        if pcd and "PCD" not in ov:
            ov["PCD"] = getdate(pcd)
        dates = {}
        pending = list(rows)
        p = 0
        while p < len(rows) + 2:
            p = p + 1
            moved = False
            for r in list(pending):
                if r["basis"] == "Order Received":
                    base = order_received
                elif r["basis"] == "Ex-Factory":
                    base = ex_factory
                elif r["basis"] == "PCD":
                    base = (dates.get("PCD") or {}).get("planned") or pcd
                else:
                    base = (dates.get(r.get("after")) or {}).get("planned")
                if base is None:
                    continue
                offset = cint(r.get("offset_days"))
                if r.get("duration_rule") == "Qty / Daily Output" and cint(r.get("daily_output")):
                    offset = max(1, frappe.utils.ceil(frappe.utils.flt(qty) / cint(r["daily_output"])))
                if r["code"] in na:
                    offset = 0
                if r["code"] in ov:
                    planned = ov[r["code"]]
                else:
                    planned = working_day(frappe.utils.add_days(getdate(base), offset), holidays, -1 if offset < 0 else 1)
                start = getdate(base) if r["basis"] == "After Milestone" else planned
                dates[r["code"]] = {"planned": planned, "start": min(start, planned)}
                pending.remove(r)
                moved = True
            if not pending or not moved:
                break
        out = {}
        for r in rows:
            if r["code"] in dates:
                out[r["code"]] = dates[r["code"]]
        return [out, [r["code"] for r in pending]]


    def feasibility(dates, ex_factory):
        """[feasible, note]: the last milestone before Ex-Factory must not land after the ex-factory date."""
        if not dates or not ex_factory:
            return [True, None]
        body = {}
        for c in dates:
            if c != "EX_FACTORY":
                body[c] = dates[c]["planned"]
        if not body:
            return [True, None]
        code = sorted(body, key=lambda c: body[c])[-1]
        late = frappe.utils.date_diff(body[code], ex_factory)
        if late > 0:
            return [False, "Plan is %s days late against ex-factory (%s lands on %s)." % (late, code, body[code])]
        return [True, None]


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def applies(mtype, sales_order, style_item, customer):
        """Whether a milestone type applies to this style on this order."""
        when = mtype.applies_when or "Always"
        if when == "Always":
            return True
        if when == "Washed Only":
            tp = tech_pack_for(style_item)
            text = ("%s %s" % ((tp.wash_description or "") if tp else "", (tp.wash_code or "") if tp else "")).strip().lower()
            if text and "no wash" not in text:
                return True
            return bool(frappe.db.exists("Sample Approval", {"style_item": style_item, "is_washed": 1}))
        if when == "Printed Only":
            cs_name = None
            for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
                if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                    cs_name = it.apparel_cost_sheet
                    break
            if not cs_name:
                return False
            for ch in frappe.get_doc("Cost Sheet", cs_name).charges:
                if (ch.cost_head or "").lower() == "printing" and not ch.not_applicable and frappe.utils.flt(ch.rate):
                    return True
            return False
        rule = get_rules(customer, sales_order, style_item).get(mtype.sample_type)
        return bool(rule) and effective_gate(rule, sales_order) != "No"


    def pick_template(customer, product_type, shipment_mode):
        """Most specific template: customer + product type, customer, product type, then the default."""
        best = None
        score = -1
        for t in frappe.get_all("TNA Template", fields=["name", "customer", "product_type", "shipment_mode", "is_default"]):
            s = 0
            for f, v, w in (("customer", customer, 4), ("product_type", product_type, 2), ("shipment_mode", shipment_mode, 1)):
                if t.get(f):
                    if t.get(f) != v:
                        s = None
                        break
                    s += w
            if s is None:
                continue
            if not (t.customer or t.product_type or t.shipment_mode) and not frappe.utils.cint(t.is_default):
                continue
            if s > score:
                best = t.name
                score = s
        return best or frappe.db.get_single_value("Apparel Settings", "default_tna_template")


    def order_groups(sales_order):
        """Sales Order lines grouped to style x colour x ex-factory date (a list of dicts)."""
        groups = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "delivery_date"], order_by="idx"):
            key = "%s|%s|%s" % (style_of(it.item_code), (it.apparel_colour or "").strip(), str(frappe.utils.getdate(it.delivery_date)) if it.delivery_date else "")
            g = groups.get(key)
            if not g:
                g = {"style_item": style_of(it.item_code), "colour": (it.apparel_colour or "").strip(), "ex_factory": it.delivery_date, "qty": 0, "ship_tos": []}
                groups[key] = g
            g["qty"] = g["qty"] + frappe.utils.cint(it.qty)
            st = (it.apparel_ship_to or "").strip()
            if st and st not in g["ship_tos"]:
                g["ship_tos"].append(st)
        return [groups[k] for k in groups]


    def allocation_for(sales_order, style_item, colour):
        """[factory, pcd, sewing_end] from the Factory Allocation for a style x colour."""
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if not fa:
            return [None, None, None]
        for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "factory", "pcd", "sewing_end"], order_by="pcd"):
            if not colour or not (r.colour or "").strip() or r.colour.strip().upper() == colour.strip().upper():
                return [r.factory, r.pcd, r.sewing_end]
        return [None, None, None]


    def compute_plan(tna):
        """[dates, na codes, unresolved, rows] for an Order TNA document from its template."""
        t = frappe.get_doc("TNA Template", tna.template)
        rows = [{"code": r.milestone_type, "basis": r.basis, "after": r.after_milestone, "offset_days": r.offset_days, "duration_rule": r.duration_rule,
                 "daily_output": r.daily_output, "owner_role": r.owner_role} for r in t.milestones]
        so = frappe.db.get_value("Sales Order", tna.sales_order, ["customer", "company"], as_dict=True)
        na = []
        for r in rows:
            if applies(frappe.get_cached_doc("TNA Milestone Type", r["code"]), tna.sales_order, tna.style_item, so.customer):
                continue
            na.append(r["code"])
        al = allocation_for(tna.sales_order, tna.style_item, tna.colour)
        overrides = {}
        if al[2]:
            overrides["BULK_FINISH"] = al[2]
        res = plan_dates(rows, tna.order_received_date, tna.ex_factory_date, tna.order_qty, holiday_dates(so.company), tna.pcd or al[1], overrides, na)
        return [res[0], na, res[1], rows]


    def build_milestones(tna):
        plan = compute_plan(tna)
        dates = plan[0]
        na = plan[1]
        rows = plan[3]
        if plan[2]:
            frappe.msgprint("These milestones could not be dated (missing base): %s" % ", ".join(plan[2]), indicator="orange")
        meta = {}
        for r in rows:
            meta[r["code"]] = r
        names = {}
        seq = 0
        for r in rows:
            code = r["code"]
            if code not in dates:
                continue
            seq = seq + 10
            mt = frappe.get_cached_doc("TNA Milestone Type", code)
            ms = frappe.get_doc({"doctype": "TNA Milestone", "order_tna": tna.name, "milestone_type": code, "sequence": seq, "label": mt.label, "department": mt.department,
                                 "is_critical": mt.is_critical, "planned_start": dates[code]["start"], "planned_date": dates[code]["planned"], "not_applicable": 1 if code in na else 0})
            ms.flags.ignore_permissions = True
            ms.insert()
            names[code] = ms.name
        for code in names:
            after = meta[code]["after"] if meta[code]["basis"] == "After Milestone" else None
            if after and after in names:
                frappe.db.set_value("TNA Milestone", names[code], "depends_on_tasks", names[after], update_modified=False)
        live = {}
        for c in dates:
            if c not in na:
                live[c] = dates[c]
        fe = feasibility(live, tna.ex_factory_date)
        tna.db_set({"plan_feasible": 1 if fe[0] else 0, "feasibility_note": fe[1]})
        refresh_order_tna(tna.name)


    def replan(order_tna):
        """Recompute planned dates after the PCD or the sewing window changed. Before the baseline is locked the planned dates move;
        after it, only the revised dates do (the baseline stays as agreed)."""
        tna = frappe.get_doc("Order TNA", order_tna)
        if tna.status == "Cancelled":
            return
        al = allocation_for(tna.sales_order, tna.style_item, tna.colour)
        if al[0] and tna.factory != al[0]:
            tna.db_set("factory", al[0])
            tna.factory = al[0]
            for n in frappe.get_all("TNA Milestone", filters={"order_tna": order_tna}, pluck="name"):
                frappe.db.set_value("TNA Milestone", n, "factory", al[0], update_modified=False)
        if al[1] and (not tna.pcd or frappe.utils.getdate(tna.pcd) != frappe.utils.getdate(al[1])):
            tna.db_set("pcd", al[1])
            tna.pcd = al[1]
        plan = compute_plan(tna)
        dates = plan[0]
        locked = frappe.utils.cint(tna.baseline_locked)
        getdate = frappe.utils.getdate
        for ms in frappe.get_all("TNA Milestone", filters={"order_tna": order_tna}, fields=["name", "milestone_type", "actual_date", "planned_date", "revised_date", "not_applicable"]):
            d = dates.get(ms.milestone_type)
            if not d or ms.actual_date:
                continue
            if locked:
                if getdate(d["planned"]) != getdate(ms.planned_date):
                    frappe.db.set_value("TNA Milestone", ms.name, {"revised_date": d["planned"], "revision_reason": "Factory allocation / plan change"}, update_modified=False)
                elif ms.revised_date:
                    frappe.db.set_value("TNA Milestone", ms.name, {"revised_date": None}, update_modified=False)
            else:
                frappe.db.set_value("TNA Milestone", ms.name, {"planned_date": d["planned"], "planned_start": d["start"], "revised_date": None}, update_modified=False)
        live = {}
        for c in dates:
            if c not in plan[1]:
                live[c] = dates[c]
        fe = feasibility(live, tna.ex_factory_date)
        tna.db_set({"plan_feasible": 1 if fe[0] else 0, "feasibility_note": fe[1]})
        refresh_order_tna(order_tna)


    def backfill(order_tna):
        """A T&A made after the fact picks up what already happened (needs the arinox_tna script)."""
        tna = frappe.get_doc("Order TNA", order_tna)

        def st(code, date, dt, name):
            run_script("arinox_tna", action="stamp", sales_order=tna.sales_order, style_item=tna.style_item, colour=tna.colour, code=code, date=str(date), source_doctype=dt, source_name=name,
                       partial=0, planned=0)

        st("ORDER_RECEIVED", tna.order_received_date, "Sales Order", tna.sales_order)
        tp = frappe.db.get_value("Tech Pack", {"style_item": tna.style_item, "docstatus": 1}, ["name", "received_on", "buyer_bom_file"], as_dict=True, order_by="creation")
        if tp:
            st("TECH_PACK_RECEIVED", tp.received_on or frappe.utils.nowdate(), "Tech Pack", tp.name)
            if tp.buyer_bom_file:
                st("BOM_RECEIVED", tp.received_on or frappe.utils.nowdate(), "Tech Pack", tp.name)
        run_script("arinox_tna", action="samples", order_tna=tna.name)
        run_script("arinox_tna", action="refind", order_tna=tna.name)
        for m in frappe.get_all("PP Meeting", filters={"sales_order": tna.sales_order, "style_item": tna.style_item, "docstatus": 1}, fields=["name", "meeting_date", "meeting_type"]):
            st("PILOT_RUN" if m.meeting_type == "Pilot Run" else "PP_MEETING", m.meeting_date, "PP Meeting", m.name)
        refresh_order_tna(tna.name)
    try:
        for name in frappe.get_all("Order TNA", filters={"sales_order": doc.sales_order, "status": ["!=", "Cancelled"]}, pluck="name"):
            replan(name)
    except Exception:
        frappe.log_error(title="T&A hook factory allocation failed", message=frappe.get_traceback())


run(doc)

# Work Order, After Save: the PCD milestone is the day cutting really started.
def run(doc):
    if not doc.get("sales_order") or not doc.get("actual_start_date"):
        return
    try:
        style = frappe.db.get_value("Item", doc.production_item, "variant_of")
        if style:
            attr = frappe.db.get_single_value("Apparel Settings", "colour_attribute") or "Colour"
            colour = frappe.db.get_value("Item Variant Attribute", {"parent": doc.production_item, "attribute": attr}, "attribute_value")
            run_script("arinox_tna", action="stamp", sales_order=doc.sales_order, style_item=style, colour=colour, code="PCD", date=str(frappe.utils.getdate(doc.actual_start_date)),
                       source_doctype="Work Order", source_name=doc.name, partial=0, planned=0)
    except Exception:
        frappe.log_error(title="T&A hook work order failed", message=frappe.get_traceback())


run(doc)

# Sales Order, After Submit: make the T&A plans when a default template is set and the order has a contract.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from tna/status.py: the state of a milestone and of an order, computed from today's date and never trusted from a stored value
    COLOURS = {"Done": "#2f855a", "In Progress": "#2b6cb0", "Late": "#c53030", "Not Started": "#718096", "Not Applicable": "#cbd5e0"}


    def milestone_state(not_applicable, actual_date, partial, planned_date, revised_date):
        """[status, delay_days, progress]. Late = the current target (revised, else planned) has passed and it is not done.
        Delay is measured against the baseline: days late if done late, days overdue if still open, days slipped if revised."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cint(not_applicable):
            return ["Not Applicable", 0, 0]
        due = getdate(revised_date or planned_date) if (revised_date or planned_date) else None
        base = getdate(planned_date) if planned_date else None
        if actual_date:
            return ["Done", max(frappe.utils.date_diff(actual_date, base), 0) if base else 0, 100]
        if due and due < today:
            return ["Late", max(frappe.utils.date_diff(today, base), 0) if base else 0, 50 if cint(partial) else 0]
        delay = max(frappe.utils.date_diff(due, base), 0) if (revised_date and base and due) else 0
        return ["In Progress" if cint(partial) else "Not Started", delay, 50 if cint(partial) else 0]


    def order_state(milestones, plan_feasible, cancelled):
        """[status, critical_delay_days] of an order from its milestone dicts."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        today = getdate(frappe.utils.nowdate())
        if cancelled:
            return ["Cancelled", 0]
        live = [m for m in milestones if not cint(m.get("not_applicable"))]
        if live and len([m for m in live if m.get("actual_date")]) == len(live):
            return ["Completed", 0]
        crit_late = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                     and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        delays = [max(frappe.utils.date_diff(m.get("actual_date") or today, m["planned_date"]), 0) for m in live
                  if cint(m.get("is_critical")) and m.get("planned_date") and (m.get("actual_date") or m in crit_late)]
        worst = max(delays) if delays else 0
        if crit_late:
            return ["Late", worst]
        other_late = [m for m in live if not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date")) and getdate(m.get("revised_date") or m.get("planned_date")) < today]
        soon = [m for m in live if cint(m.get("is_critical")) and not m.get("actual_date") and (m.get("revised_date") or m.get("planned_date"))
                and 0 <= frappe.utils.date_diff(m.get("revised_date") or m.get("planned_date"), today) <= 3]
        if other_late or soon or not cint(plan_feasible):
            return ["At Risk", worst]
        return ["On Track", worst]


    def refresh_order_tna(name):
        """Recompute and store every milestone's status and the order's status."""
        if not frappe.db.exists("Order TNA", name):
            return
        t = frappe.db.get_value("Order TNA", name, ["status", "plan_feasible", "critical_delay_days"], as_dict=True)
        ms = frappe.get_all("TNA Milestone", filters={"order_tna": name}, fields=["name", "not_applicable", "actual_date", "partial", "planned_date", "revised_date", "is_critical",
                                                                                  "status", "delay_days", "color", "progress"])
        for m in ms:
            st = milestone_state(m.not_applicable, m.actual_date, m.partial, m.planned_date, m.revised_date)
            colour = COLOURS[st[0]]
            if m.status != st[0] or m.delay_days != st[1] or m.progress != st[2] or m.color != colour:
                frappe.db.set_value("TNA Milestone", m.name, {"status": st[0], "delay_days": st[1], "progress": st[2], "color": colour}, update_modified=False)
            m["status"] = st[0]
        if t.status == "Cancelled":
            return
        o = order_state(ms, t.plan_feasible, False)
        if o[0] != t.status or o[1] != t.critical_delay_days:
            frappe.db.set_value("Order TNA", name, {"status": o[0], "critical_delay_days": o[1]}, update_modified=False)
    # shared helpers from tna/planner.py (+ backfill from tna/events.py): planning dates for an Order TNA, building and re-planning its milestones.
    # Needs lib_samples.py (rules) and lib_tna.py (refresh) included first.
    def holiday_dates(company):
        """List of non-working dates from the Company's default Holiday List; None when the company has no list."""
        hl = frappe.db.get_value("Company", company, "default_holiday_list") if company else None
        if not hl:
            return None
        return [frappe.utils.getdate(d) for d in frappe.get_all("Holiday", filters={"parent": hl}, pluck="holiday_date")]


    def working_day(d, holidays, direction):
        """Move `d` to the next (direction 1) or previous (-1) working day. With no Holiday List only Sundays are off."""
        d = frappe.utils.getdate(d)
        i = 0
        while i < 60:
            off = (d in holidays) if holidays is not None else d.weekday() == 6
            if not off:
                return d
            d = frappe.utils.getdate(frappe.utils.add_days(d, direction))
            i = i + 1
        return d


    def plan_dates(rows, order_received, ex_factory, qty, holidays, pcd, overrides, na):
        """rows: dicts with code, basis, after, offset_days, duration_rule, daily_output (in template order). Returns [dates, unresolved codes], dates = code -> {planned, start}
        in template order. A not-applicable milestone passes its predecessor's date through (offset 0) so a skipped step adds no days. `pcd` and `overrides` pin dates."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        ov = {}
        for k in (overrides or {}):
            if overrides[k]:
                ov[k] = getdate(overrides[k])
        if pcd and "PCD" not in ov:
            ov["PCD"] = getdate(pcd)
        dates = {}
        pending = list(rows)
        p = 0
        while p < len(rows) + 2:
            p = p + 1
            moved = False
            for r in list(pending):
                if r["basis"] == "Order Received":
                    base = order_received
                elif r["basis"] == "Ex-Factory":
                    base = ex_factory
                elif r["basis"] == "PCD":
                    base = (dates.get("PCD") or {}).get("planned") or pcd
                else:
                    base = (dates.get(r.get("after")) or {}).get("planned")
                if base is None:
                    continue
                offset = cint(r.get("offset_days"))
                if r.get("duration_rule") == "Qty / Daily Output" and cint(r.get("daily_output")):
                    offset = max(1, frappe.utils.ceil(frappe.utils.flt(qty) / cint(r["daily_output"])))
                if r["code"] in na:
                    offset = 0
                if r["code"] in ov:
                    planned = ov[r["code"]]
                else:
                    planned = working_day(frappe.utils.add_days(getdate(base), offset), holidays, -1 if offset < 0 else 1)
                start = getdate(base) if r["basis"] == "After Milestone" else planned
                dates[r["code"]] = {"planned": planned, "start": min(start, planned)}
                pending.remove(r)
                moved = True
            if not pending or not moved:
                break
        out = {}
        for r in rows:
            if r["code"] in dates:
                out[r["code"]] = dates[r["code"]]
        return [out, [r["code"] for r in pending]]


    def feasibility(dates, ex_factory):
        """[feasible, note]: the last milestone before Ex-Factory must not land after the ex-factory date."""
        if not dates or not ex_factory:
            return [True, None]
        body = {}
        for c in dates:
            if c != "EX_FACTORY":
                body[c] = dates[c]["planned"]
        if not body:
            return [True, None]
        code = sorted(body, key=lambda c: body[c])[-1]
        late = frappe.utils.date_diff(body[code], ex_factory)
        if late > 0:
            return [False, "Plan is %s days late against ex-factory (%s lands on %s)." % (late, code, body[code])]
        return [True, None]


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def applies(mtype, sales_order, style_item, customer):
        """Whether a milestone type applies to this style on this order."""
        when = mtype.applies_when or "Always"
        if when == "Always":
            return True
        if when == "Washed Only":
            tp = tech_pack_for(style_item)
            text = ("%s %s" % ((tp.wash_description or "") if tp else "", (tp.wash_code or "") if tp else "")).strip().lower()
            if text and "no wash" not in text:
                return True
            return bool(frappe.db.exists("Sample Approval", {"style_item": style_item, "is_washed": 1}))
        if when == "Printed Only":
            cs_name = None
            for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
                if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                    cs_name = it.apparel_cost_sheet
                    break
            if not cs_name:
                return False
            for ch in frappe.get_doc("Cost Sheet", cs_name).charges:
                if (ch.cost_head or "").lower() == "printing" and not ch.not_applicable and frappe.utils.flt(ch.rate):
                    return True
            return False
        rule = get_rules(customer, sales_order, style_item).get(mtype.sample_type)
        return bool(rule) and effective_gate(rule, sales_order) != "No"


    def pick_template(customer, product_type, shipment_mode):
        """Most specific template: customer + product type, customer, product type, then the default."""
        best = None
        score = -1
        for t in frappe.get_all("TNA Template", fields=["name", "customer", "product_type", "shipment_mode", "is_default"]):
            s = 0
            for f, v, w in (("customer", customer, 4), ("product_type", product_type, 2), ("shipment_mode", shipment_mode, 1)):
                if t.get(f):
                    if t.get(f) != v:
                        s = None
                        break
                    s += w
            if s is None:
                continue
            if not (t.customer or t.product_type or t.shipment_mode) and not frappe.utils.cint(t.is_default):
                continue
            if s > score:
                best = t.name
                score = s
        return best or frappe.db.get_single_value("Apparel Settings", "default_tna_template")


    def order_groups(sales_order):
        """Sales Order lines grouped to style x colour x ex-factory date (a list of dicts)."""
        groups = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "delivery_date"], order_by="idx"):
            key = "%s|%s|%s" % (style_of(it.item_code), (it.apparel_colour or "").strip(), str(frappe.utils.getdate(it.delivery_date)) if it.delivery_date else "")
            g = groups.get(key)
            if not g:
                g = {"style_item": style_of(it.item_code), "colour": (it.apparel_colour or "").strip(), "ex_factory": it.delivery_date, "qty": 0, "ship_tos": []}
                groups[key] = g
            g["qty"] = g["qty"] + frappe.utils.cint(it.qty)
            st = (it.apparel_ship_to or "").strip()
            if st and st not in g["ship_tos"]:
                g["ship_tos"].append(st)
        return [groups[k] for k in groups]


    def allocation_for(sales_order, style_item, colour):
        """[factory, pcd, sewing_end] from the Factory Allocation for a style x colour."""
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if not fa:
            return [None, None, None]
        for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "factory", "pcd", "sewing_end"], order_by="pcd"):
            if not colour or not (r.colour or "").strip() or r.colour.strip().upper() == colour.strip().upper():
                return [r.factory, r.pcd, r.sewing_end]
        return [None, None, None]


    def compute_plan(tna):
        """[dates, na codes, unresolved, rows] for an Order TNA document from its template."""
        t = frappe.get_doc("TNA Template", tna.template)
        rows = [{"code": r.milestone_type, "basis": r.basis, "after": r.after_milestone, "offset_days": r.offset_days, "duration_rule": r.duration_rule,
                 "daily_output": r.daily_output, "owner_role": r.owner_role} for r in t.milestones]
        so = frappe.db.get_value("Sales Order", tna.sales_order, ["customer", "company"], as_dict=True)
        na = []
        for r in rows:
            if applies(frappe.get_cached_doc("TNA Milestone Type", r["code"]), tna.sales_order, tna.style_item, so.customer):
                continue
            na.append(r["code"])
        al = allocation_for(tna.sales_order, tna.style_item, tna.colour)
        overrides = {}
        if al[2]:
            overrides["BULK_FINISH"] = al[2]
        res = plan_dates(rows, tna.order_received_date, tna.ex_factory_date, tna.order_qty, holiday_dates(so.company), tna.pcd or al[1], overrides, na)
        return [res[0], na, res[1], rows]


    def build_milestones(tna):
        plan = compute_plan(tna)
        dates = plan[0]
        na = plan[1]
        rows = plan[3]
        if plan[2]:
            frappe.msgprint("These milestones could not be dated (missing base): %s" % ", ".join(plan[2]), indicator="orange")
        meta = {}
        for r in rows:
            meta[r["code"]] = r
        names = {}
        seq = 0
        for r in rows:
            code = r["code"]
            if code not in dates:
                continue
            seq = seq + 10
            mt = frappe.get_cached_doc("TNA Milestone Type", code)
            ms = frappe.get_doc({"doctype": "TNA Milestone", "order_tna": tna.name, "milestone_type": code, "sequence": seq, "label": mt.label, "department": mt.department,
                                 "is_critical": mt.is_critical, "planned_start": dates[code]["start"], "planned_date": dates[code]["planned"], "not_applicable": 1 if code in na else 0})
            ms.flags.ignore_permissions = True
            ms.insert()
            names[code] = ms.name
        for code in names:
            after = meta[code]["after"] if meta[code]["basis"] == "After Milestone" else None
            if after and after in names:
                frappe.db.set_value("TNA Milestone", names[code], "depends_on_tasks", names[after], update_modified=False)
        live = {}
        for c in dates:
            if c not in na:
                live[c] = dates[c]
        fe = feasibility(live, tna.ex_factory_date)
        tna.db_set({"plan_feasible": 1 if fe[0] else 0, "feasibility_note": fe[1]})
        refresh_order_tna(tna.name)


    def replan(order_tna):
        """Recompute planned dates after the PCD or the sewing window changed. Before the baseline is locked the planned dates move;
        after it, only the revised dates do (the baseline stays as agreed)."""
        tna = frappe.get_doc("Order TNA", order_tna)
        if tna.status == "Cancelled":
            return
        al = allocation_for(tna.sales_order, tna.style_item, tna.colour)
        if al[0] and tna.factory != al[0]:
            tna.db_set("factory", al[0])
            tna.factory = al[0]
            for n in frappe.get_all("TNA Milestone", filters={"order_tna": order_tna}, pluck="name"):
                frappe.db.set_value("TNA Milestone", n, "factory", al[0], update_modified=False)
        if al[1] and (not tna.pcd or frappe.utils.getdate(tna.pcd) != frappe.utils.getdate(al[1])):
            tna.db_set("pcd", al[1])
            tna.pcd = al[1]
        plan = compute_plan(tna)
        dates = plan[0]
        locked = frappe.utils.cint(tna.baseline_locked)
        getdate = frappe.utils.getdate
        for ms in frappe.get_all("TNA Milestone", filters={"order_tna": order_tna}, fields=["name", "milestone_type", "actual_date", "planned_date", "revised_date", "not_applicable"]):
            d = dates.get(ms.milestone_type)
            if not d or ms.actual_date:
                continue
            if locked:
                if getdate(d["planned"]) != getdate(ms.planned_date):
                    frappe.db.set_value("TNA Milestone", ms.name, {"revised_date": d["planned"], "revision_reason": "Factory allocation / plan change"}, update_modified=False)
                elif ms.revised_date:
                    frappe.db.set_value("TNA Milestone", ms.name, {"revised_date": None}, update_modified=False)
            else:
                frappe.db.set_value("TNA Milestone", ms.name, {"planned_date": d["planned"], "planned_start": d["start"], "revised_date": None}, update_modified=False)
        live = {}
        for c in dates:
            if c not in plan[1]:
                live[c] = dates[c]
        fe = feasibility(live, tna.ex_factory_date)
        tna.db_set({"plan_feasible": 1 if fe[0] else 0, "feasibility_note": fe[1]})
        refresh_order_tna(order_tna)


    def backfill(order_tna):
        """A T&A made after the fact picks up what already happened (needs the arinox_tna script)."""
        tna = frappe.get_doc("Order TNA", order_tna)

        def st(code, date, dt, name):
            run_script("arinox_tna", action="stamp", sales_order=tna.sales_order, style_item=tna.style_item, colour=tna.colour, code=code, date=str(date), source_doctype=dt, source_name=name,
                       partial=0, planned=0)

        st("ORDER_RECEIVED", tna.order_received_date, "Sales Order", tna.sales_order)
        tp = frappe.db.get_value("Tech Pack", {"style_item": tna.style_item, "docstatus": 1}, ["name", "received_on", "buyer_bom_file"], as_dict=True, order_by="creation")
        if tp:
            st("TECH_PACK_RECEIVED", tp.received_on or frappe.utils.nowdate(), "Tech Pack", tp.name)
            if tp.buyer_bom_file:
                st("BOM_RECEIVED", tp.received_on or frappe.utils.nowdate(), "Tech Pack", tp.name)
        run_script("arinox_tna", action="samples", order_tna=tna.name)
        run_script("arinox_tna", action="refind", order_tna=tna.name)
        for m in frappe.get_all("PP Meeting", filters={"sales_order": tna.sales_order, "style_item": tna.style_item, "docstatus": 1}, fields=["name", "meeting_date", "meeting_type"]):
            st("PILOT_RUN" if m.meeting_type == "Pilot Run" else "PP_MEETING", m.meeting_date, "PP Meeting", m.name)
        refresh_order_tna(tna.name)
    if not (frappe.db.get_single_value("Apparel Settings", "default_tna_template") and doc.get("apparel_sales_contract")):
        return
    try:
        run_script("arinox_planner_api_make_order_tnas", sales_order=doc.name)
    except Exception:
        frappe.log_error(title="T&A hook sales order failed", message=frappe.get_traceback())


run(doc)

# Sales Order, After Cancel: the plans of the order are cancelled.
def run(doc):
    try:
        for name in frappe.get_all("Order TNA", filters={"sales_order": doc.name, "status": ["!=", "Cancelled"]}, pluck="name"):
            frappe.db.set_value("Order TNA", name, "status", "Cancelled", update_modified=False)
            for m in frappe.get_all("TNA Milestone", filters={"order_tna": name}, pluck="name"):
                frappe.db.set_value("TNA Milestone", m, {"status": "Not Applicable", "color": "#cbd5e0"}, update_modified=False)
    except Exception:
        frappe.log_error(title="T&A hook sales order cancel failed", message=frappe.get_traceback())


run(doc)

# Fabric Requisition, Before Save: lines checked against the order, approvals (lab dip hold), dates, allowance, stock claims, costing; totals are always computed here.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers: the Sales Order at the order grain, rolled up to style x colour, and the tolerance cap (factory_allocation.py)
    def norm(colour):
        return (colour or "").strip().upper()


    def get_order_lines(sales_order):
        """Sales Order grouped to (style, colour, ship-to, buyer PO) -> qty, tolerance %, earliest ex-factory date. A dict of dicts, in order of appearance."""
        lines = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order},
                                 fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            key = (style, norm(it.apparel_colour), norm(it.apparel_ship_to), norm(it.apparel_buyer_po))
            row = lines.get(key)
            if not row:
                row = {"style_item": style, "colour": (it.apparel_colour or "").strip(), "ship_to": (it.apparel_ship_to or "").strip(),
                       "buyer_po": (it.apparel_buyer_po or "").strip(), "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                lines[key] = row
            row["qty"] = row["qty"] + frappe.utils.cint(it.qty)
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not row["ex_factory_date"] or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = it.delivery_date
        return lines


    def colour_level(order):
        """The order lines rolled up to (style, colour)."""
        out = {}
        for key in order:
            o = order[key]
            ckey = (key[0], key[1])
            row = out.get(ckey)
            if not row:
                row = {"style_item": key[0], "colour": o["colour"], "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                out[ckey] = row
            row["qty"] = row["qty"] + o["qty"]
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(o["tolerance_pct"]))
            if o["ex_factory_date"] and (not row["ex_factory_date"] or frappe.utils.getdate(o["ex_factory_date"]) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = o["ex_factory_date"]
        return out


    def cap_of(qty, tolerance_pct):
        return int(qty * (1 + frappe.utils.flt(tolerance_pct) / 100))
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers of the Fabric and Trim Requisition: the garment quantity of an order colour, default terms, trim category rules, and the line builders that read
    # the Tech Pack and Sales Order. Needs lib_samples.py, lib_allocation.py, lib_mat.py.
    def default_terms():
        return ("<ol><li>Delivery: as per the schedule above.</li><li>Partial shipments: not allowed.</li><li>Quality: as per the buyer's quality standards.</li>"
                "<li>Quantity: as per our internal buying standards. Over and above the allowance, uncut fabric will be returned to the supplier.</li>"
                "<li>Quantity is in metres.</li><li>Bulk shrinkage should be as per the approved fabric data sheet.</li>"
                "<li>Cuttable width and GSM must match the approved fabric data sheet.</li></ol>")


    def uniq(items):
        out = []
        for i in items:
            if i not in out:
                out.append(i)
        return out


    def order_colour_qty(sales_order, style_item, colour):
        cl = colour_level(get_order_lines(sales_order))
        row = cl.get((style_item, (colour or "").strip().upper()))
        return frappe.utils.cint(row["qty"]) if row else 0


    def fr_lines_for_sales_order(sales_order, customer, company):
        """FR line dicts for one Sales Order from the Tech Pack materials (FR types only)."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        out = []
        cl = colour_level(get_order_lines(sales_order))
        for key in cl:
            style = key[0]
            o = cl[key]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no fabric lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type not in fr_types or not colour_matches(m.colour, o["colour"], all_colours):
                    continue
                cons = flt(m.consumption)
                uom = m.uom or "Meter"
                source = "Tech Pack"
                costed = None
                if cs:
                    for cm in cs.materials:
                        if cm.material_type == m.material_type and (cm.is_selected or cm.is_selected is None) and (
                                (cm.item and cm.item == m.item) or (cm.description or "").strip().lower() == (m.description or "").strip().lower()):
                            costed = flt(cm.consumption)
                            if not cons:
                                cons = costed
                                uom = cm.uom or uom
                                source = "Cost Sheet"
                            break
                width = parse_width_cm(m.width) or 0
                role = {"Lining": "Lining", "Contrast Fabric": "Contrast"}.get(m.material_type, "Shell")
                gsm = parse_width_cm(m.gsm) if m.gsm else 0
                out.append({"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "style_name": tp.style_name, "colour": o["colour"], "material_role": role,
                            "tech_pack_material": m.name, "fabric_item": m.item, "fabric_description": m.description, "fabric_colour": m.colour or o["colour"],
                            "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0, "cuttable_width_cm": width, "gsm": gsm,
                            "garment_qty": cint(o["qty"]), "consumption": cons, "consumption_uom": uom, "consumption_source": source, "costed_consumption": costed})
        return out


    def material_type_for(category):
        c = (category or "").lower()
        if "label" in c:
            return "Label"
        if "packaging" in c:
            return "Packaging"
        return "Trim"


    def guess_category(material_type, description):
        """Trim Category for a Tech Pack material row, from its type and words in the description."""
        d = (description or "").lower()
        for words, cat in ((("size label", "size tab", "size tag"), "Size Label"), (("care", "wash care"), "Care Label"), (("thread",), "Thread"),
                           (("fusing", "interlining", "keo"), "Fusing / Interlining"), (("security",), "Security Tag"), (("hang tag", "hangtag", "price ticket"), "Hang Tag"),
                           (("button",), "Button"), (("zip", "hook", "fastener", "velcro"), "Zipper / Hooks / Fasteners"), (("elastic", "tape", "drawcord", "cord"), "Elastic / Tape"),
                           (("label",), "Woven Label"), (("carton", "poly", "bag", "tissue", "silica", "sticker", "hanger"), "Packaging")):
            if [w for w in words if w in d]:
                return cat
        return "Packaging" if material_type == "Packaging" else "Others"


    def tr_lines_for_sales_order(sales_order, customer, company):
        """TR line dicts for one Sales Order from the Tech Pack materials that are not fabric."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        by_colour = colour_level(get_order_lines(sales_order))
        size_qty = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_size"]):
            k = (style_of(it.item_code), (it.apparel_size or "").strip())
            size_qty[k] = size_qty.get(k, 0) + cint(it.qty)
        styles = {}
        names = []
        for key in by_colour:
            sk = "s|" + key[0]       # a style code may start with an underscore, which the sandbox refuses as a key
            if sk not in styles:
                styles[sk] = []
                names.append(key[0])
            styles[sk].append(by_colour[key])
        out = []
        for style in names:
            colours = styles["s|" + style]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no trim lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            pcs = cint(cs.pcs_per_carton) if cs else 0
            total = sum([cint(c["qty"]) for c in colours])
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type in fr_types:
                    continue
                cat = guess_category(m.material_type, m.description)
                base = {"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "trim_category": cat, "trim_item": m.item, "buyer_item_code": m.buyer_item_code,
                        "description": m.description, "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0,
                        "customer_provided": 1 if m.buyer_supplied else 0}
                is_length = uom_kind(m.uom) in ("m", "yd")
                cons = flt(m.consumption) or 1
                dtm = "dtm" in (m.description or "").lower() or (m.colour or "").strip().upper() == "DTM"
                if cat == "Size Label":
                    for k in sorted(size_qty):
                        if k[0] == style and k[1]:
                            row = dict(base)
                            row.update({"size": k[1], "calc_basis": "Per Size", "garment_qty": size_qty[k], "qty_per_garment": cons if not is_length else 1})
                            out.append(row)
                elif cat == "Packaging" and "carton" in (m.description or "").lower():
                    if not pcs:
                        frappe.msgprint("Style %s: set the pieces per carton on the Cost Sheet to get the carton line." % style)
                        continue
                    row = dict(base)
                    row.update({"calc_basis": "Per Carton", "garment_qty": total, "qty_per_garment": cons, "pcs_per_carton": pcs})
                    out.append(row)
                elif dtm or ((m.colour or "").strip() and colour_matches(m.colour, "", all_colours) is False):
                    for c in colours:
                        if not dtm and (m.colour or "").strip().upper() != (c["colour"] or "").strip().upper():
                            continue
                        row = dict(base)
                        row.update({"colour": c["colour"], "trim_colour": c["colour"], "garment_qty": cint(c["qty"])})
                        if is_length:
                            row.update({"calc_basis": "By Length", "consumption": cons, "consumption_uom": m.uom or "Meter"})
                        else:
                            row.update({"calc_basis": "Per Garment", "qty_per_garment": cons})
                        out.append(row)
                elif is_length:
                    row = dict(base)
                    row.update({"calc_basis": "By Length", "garment_qty": total, "consumption": cons, "consumption_uom": m.uom})
                    out.append(row)
                else:
                    row = dict(base)
                    row.update({"calc_basis": "Per Garment", "garment_qty": total, "qty_per_garment": cons})
                    out.append(row)
        return out
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    getdate = frappe.utils.getdate
    add_days = frappe.utils.add_days
    if not doc.ordered_by:
        doc.ordered_by = frappe.session.user
    if not doc.terms:
        doc.terms = default_terms()
    if not doc.items:
        frappe.throw("Add at least one fabric line.")
    if cint(doc.revision_no) > 0 and not (doc.revision_reason or "").strip():
        frappe.throw("Enter the reason for this revision.")
    seen = {}
    for r in doc.items:
        if not r.fabric_item:
            continue
        k = fr_row_key(r)
        if k in seen:
            frappe.throw("Row %s repeats row %s: same order, style, colour, role and fabric." % (r.idx, seen[k]))
        seen[k] = r.idx

    flags = []
    hold_mode = frappe.db.get_single_value("Apparel Settings", "hold_po_until_approval") or "Warn"
    due_days = cint(frappe.db.get_single_value("Apparel Settings", "fabric_due_days_before_pcd") or 10)
    for r in doc.items:
        # ---- fill the row
        so = frappe.db.get_value("Sales Order", r.sales_order, ["docstatus", "customer", "company", "apparel_sales_contract"], as_dict=True)
        if not so:
            frappe.throw("Row %s: Sales Order %s does not exist." % (r.idx, r.sales_order))
        if so.docstatus != 1:
            frappe.throw("Row %s: Sales Order %s is not submitted." % (r.idx, r.sales_order))
        if so.customer != doc.customer or so.company != doc.company:
            frappe.throw("Row %s: Sales Order %s belongs to another buyer or company." % (r.idx, r.sales_order))
        r.sales_contract = so.apparel_sales_contract
        if frappe.db.get_value("Item", r.style_item, "variant_of"):
            frappe.throw("Row %s: pick the style (template item), not a variant." % r.idx)
        r.style_no = r.style_no or frappe.db.get_value("Tech Pack", {"style_item": r.style_item}, "style_no") or r.style_item
        order_qty = order_colour_qty(r.sales_order, r.style_item, r.colour)
        if not cint(r.garment_qty):
            r.garment_qty = order_qty
        elif order_qty and cint(r.garment_qty) != order_qty:
            flags.append("Row %s: garment qty %s differs from the Sales Order (%s)." % (r.idx, r.garment_qty, order_qty))
        if flt(r.consumption) <= 0:
            frappe.throw("Row %s: consumption must be more than zero." % r.idx)
        if flt(r.cuttable_width_cm) <= 0:
            frappe.throw("Row %s: enter the cuttable width." % r.idx)
        if not r.consumption_source:
            frappe.throw("Row %s: say where the consumption comes from (marker, cost sheet, tech pack or manual)." % r.idx)
        if uom_kind(r.consumption_uom) == "kg" and not flt(r.gsm):
            frappe.throw("Row %s: a kg line needs the GSM." % r.idx)
        if r.fabric_item and not flt(r.gsm):
            r.gsm = flt(frappe.db.get_value("Item", r.fabric_item, "apparel_fabric_gsm"))
        ap = approval_info(r.sales_order, r.style_item, "Lab Dip", r.colour, doc.customer)
        r.lab_dip_status = ap[0]
        r.hold = 1 if (not ap[1] and hold_mode != "Off") else 0
        if not ap[1]:
            flags.append("Row %s: lab dip is %s; the purchase order will be held." % (r.idx, ap[0]))
        cw = cw_in(r.fabric_description)
        if cw is not None and abs(flt(cw) - flt(r.cuttable_width_cm)) > 0.5:
            flags.append("Row %s: the description says CW %s but the cuttable width is %s." % (r.idx, cw, r.cuttable_width_cm))
        pcd = get_style_dates(r.sales_order, r.style_item, r.colour)[0]
        if pcd and not r.required_by:
            r.required_by = add_days(pcd, -due_days)
        if pcd and r.required_by and getdate(r.required_by) > add_days(getdate(pcd), -due_days):
            flags.append("Row %s: required by %s is later than PCD %s minus %s days." % (r.idx, r.required_by, pcd, due_days))
        if not pcd:
            flags.append("Row %s: no planned cut date yet; set the Factory Allocation." % r.idx)
        if not r.supplier:
            flags.append("Row %s: no supplier chosen." % r.idx)

        # ---- compute the row
        cons_m = to_metres(r.consumption, r.consumption_uom, r.gsm, r.cuttable_width_cm)
        mtype = "Lining" if r.material_role == "Lining" else ("Contrast Fabric" if r.material_role == "Contrast" else "Fabric")
        rule = get_allowance(mtype, None, doc.customer, frappe.db.get_value("Item", r.fabric_item, "item_group") if r.fabric_item else None)
        default_pct = flt(rule["allowance_pct"])
        if r.allowance_pct is None:
            r.allowance_pct = default_pct
        elif flt(r.allowance_pct) != default_pct and not (r.allowance_reason or "").strip():
            frappe.throw("Row %s: the allowance %s%% differs from the rule (%s%%). Enter the reason." % (r.idx, r.allowance_pct, default_pct))
        r.pack_size = flt(rule["pack_size"])
        r.gross_qty = flt(cint(r.garment_qty) * cons_m * (1 + flt(r.allowance_pct) / 100), 4)
        if flt(r.stock_used) > 0:
            if not r.stock_warehouse or not r.fabric_item:
                frappe.throw("Row %s: choose the fabric item and warehouse to use leftover stock." % r.idx)
            free = free_stock(r.fabric_item, r.stock_warehouse, "Fabric Requisition", "Fabric Requisition Item", doc.name)
            if flt(r.stock_used) > free + 0.0001:
                frappe.throw("Row %s: only %s m of %s is free in %s (the rest is claimed by other requisitions)." % (r.idx, flt(free, 2), r.fabric_item, r.stock_warehouse))
        r.net_qty = flt(max(flt(r.gross_qty) - flt(r.stock_used), 0), 4)
        r.order_uom = r.order_uom or (frappe.db.get_value("Item", r.fabric_item, "stock_uom") if r.fabric_item else None) or "Meter"
        r.order_qty = round_up_to_pack(from_metres(r.net_qty, r.order_uom, r.gsm, r.cuttable_width_cm), r.pack_size) if r.net_qty > 0 else 0
        if r.net_qty > 0 and flt(rule["min_order_qty"]) and flt(r.order_qty) < flt(rule["min_order_qty"]):
            r.order_qty = flt(rule["min_order_qty"])
            flags.append("Row %s: raised to the minimum order of %s." % (r.idx, rule["min_order_qty"]))
        if r.costed_consumption and r.consumption:
            costed_m = to_metres(r.costed_consumption, r.consumption_uom, r.gsm, r.cuttable_width_cm)
            now_m = to_metres(r.consumption, r.consumption_uom, r.gsm, r.cuttable_width_cm)
            if costed_m and abs(now_m - costed_m) / costed_m > 0.05:
                flags.append("Row %s: consumption %s is more than 5%% %s than costed (%s)." % (r.idx, r.consumption, "less" if now_m < costed_m else "more", r.costed_consumption))

    # ---- revision: quantities cut back or lines removed against what was already requested
    if doc.previous_fr:
        chain = revision_chain("Fabric Requisition", "previous_fr", doc.previous_fr)
        mine = {}
        for r in doc.items:
            if r.fabric_item:
                mine[fr_row_key(r)] = r
        for k in mine:
            r = mine[k]
            before = requested_so_far("FR", chain, k)
            if before and flt(r.net_qty) + 0.0005 < before:
                flags.append("Row %s: reduced from %s m to %s m. Reduce the order with the supplier." % (r.idx, flt(before, 2), flt(r.net_qty, 2)))
        prev = frappe.db.sql("select i.apparel_requisition_item, sum(i.stock_qty) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = 'FR' and i.apparel_requisition in %s and m.docstatus < 2 group by i.apparel_requisition_item", (tuple(chain),))
        for p in prev:
            if p[0] not in mine and flt(p[1]) > 0:
                flags.append("Line removed (%s): %s m was already requested. Cancel or reduce the order with the supplier." % (p[0].replace("|", " / "), flt(p[1], 2)))

    # ---- summary per fabric and supplier
    doc.set("summary", [])
    groups = {}
    order = []
    for r in doc.items:
        if flt(r.net_qty) <= 0:
            continue
        gk = "k|%s|%s" % (r.fabric_item or r.fabric_description, r.supplier or "")
        if gk not in groups:
            groups[gk] = {"fabric_item": r.fabric_item, "fabric_description": r.fabric_description, "supplier": r.supplier, "total": 0, "uom": r.order_uom, "date": None, "n": 0}
            order.append(gk)
        g = groups[gk]
        g["total"] = g["total"] + flt(r.order_qty)
        g["n"] = g["n"] + 1
        if r.required_by and (not g["date"] or getdate(r.required_by) < getdate(g["date"])):
            g["date"] = r.required_by
    for gk in order:
        g = groups[gk]
        doc.append("summary", {"fabric_item": g["fabric_item"], "fabric_description": g["fabric_description"], "supplier": g["supplier"], "total_order_qty": flt(g["total"], 2),
                               "uom": g["uom"], "earliest_required_by": g["date"], "line_count": g["n"]})
    doc.total_order_m = sum([flt(r.net_qty) for r in doc.items])
    doc.red_flags = "\n".join(uniq(flags))
    doc.status = requisition_status(doc)


run(doc)

# Fabric Requisition, Before Submit: every line has its fabric item.
def run(doc):
    for r in doc.items:
        if not r.fabric_item:
            frappe.throw("Row %s: choose or create the fabric item before approving." % r.idx)


run(doc)

# Fabric Requisition, After Submit: approved. Material Requests (grouped by supplier, only the increase over earlier revisions), the previous revision is superseded,
# the FR_RAISED milestone is stamped.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    flt = frappe.utils.flt
    doc.db_set({"approved_by": frappe.session.user, "approved_on": frappe.utils.now_datetime()})
    chain = revision_chain("Fabric Requisition", "previous_fr", doc.name)[1:]
    lines = []
    for r in doc.items:
        if flt(r.net_qty) <= 0:
            continue
        key = fr_row_key(r)
        delta = flt(r.net_qty) - requested_so_far("FR", chain, key)
        if delta <= 0.0005:
            continue
        order_qty = round_up_to_pack(from_metres(delta, r.order_uom, r.gsm, r.cuttable_width_cm), r.pack_size)
        q = mr_line(r.fabric_item, delta, r.order_uom, order_qty)
        lines.append({"item_code": r.fabric_item, "qty": q[0], "uom": q[1], "conversion_factor": q[2], "supplier": r.supplier, "required_by": r.required_by, "key": key,
                      "style_no": r.style_no, "colour": r.colour, "sales_order": r.sales_order, "description": r.fabric_description,
                      "hold_reason": "Lab dip %s" % r.lab_dip_status if r.hold else None})
    create_material_requests(doc, lines, "FR", "Fabric")
    for r in doc.items:
        mri = frappe.db.sql("select i.name, i.parent from `tabMaterial Request Item` i where i.apparel_requisition_type = 'FR' and i.apparel_requisition = %s "
                            "and i.apparel_requisition_item = %s limit 1", (doc.name, fr_row_key(r)))
        if mri:
            r.db_set({"material_request": mri[0][1], "material_request_item": mri[0][0]})
    if doc.previous_fr:
        frappe.db.set_value("Fabric Requisition", doc.previous_fr, "status", "Superseded")
    stamp_safe_requisition(doc, "FR_RAISED")
    status = requisition_status(doc)
    doc.status = status
    doc.db_set("status", status, update_modified=False)


run(doc)

# Fabric Requisition, After Cancel: its Material Requests are cancelled, the previous revision is current again, the milestone is cleared.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    done = []
    for m in frappe.db.sql("select distinct i.parent from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                           "where i.apparel_requisition_type = 'FR' and i.apparel_requisition = %s and m.docstatus = 1", (doc.name,)):
        if m[0] in done:
            continue
        done.append(m[0])
        mr = frappe.get_doc("Material Request", m[0])
        mr.flags.ignore_permissions = True
        mr.cancel()
    if doc.previous_fr:
        frappe.db.set_value("Fabric Requisition", doc.previous_fr, "status", "Approved")
        prev = frappe.get_doc("Fabric Requisition", doc.previous_fr)
        prev.status = "Approved"
        frappe.db.set_value("Fabric Requisition", doc.previous_fr, "status", requisition_status(prev), update_modified=False)
    unstamp_safe("Fabric Requisition", doc.name)
    doc.db_set("status", "Cancelled")


run(doc)

# API arinox_fabric_requisition_get_lines_from_sales_orders: one row per style x colour x fabric of the Tech Pack, quantities from the Sales Order (appended to the form's rows).
# A row already on the form is recognised by its Tech Pack material row (or description), so two fabrics of one style and colour with no linked item are both kept.
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers: the Sales Order at the order grain, rolled up to style x colour, and the tolerance cap (factory_allocation.py)
    def norm(colour):
        return (colour or "").strip().upper()


    def get_order_lines(sales_order):
        """Sales Order grouped to (style, colour, ship-to, buyer PO) -> qty, tolerance %, earliest ex-factory date. A dict of dicts, in order of appearance."""
        lines = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order},
                                 fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            key = (style, norm(it.apparel_colour), norm(it.apparel_ship_to), norm(it.apparel_buyer_po))
            row = lines.get(key)
            if not row:
                row = {"style_item": style, "colour": (it.apparel_colour or "").strip(), "ship_to": (it.apparel_ship_to or "").strip(),
                       "buyer_po": (it.apparel_buyer_po or "").strip(), "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                lines[key] = row
            row["qty"] = row["qty"] + frappe.utils.cint(it.qty)
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not row["ex_factory_date"] or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = it.delivery_date
        return lines


    def colour_level(order):
        """The order lines rolled up to (style, colour)."""
        out = {}
        for key in order:
            o = order[key]
            ckey = (key[0], key[1])
            row = out.get(ckey)
            if not row:
                row = {"style_item": key[0], "colour": o["colour"], "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                out[ckey] = row
            row["qty"] = row["qty"] + o["qty"]
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(o["tolerance_pct"]))
            if o["ex_factory_date"] and (not row["ex_factory_date"] or frappe.utils.getdate(o["ex_factory_date"]) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = o["ex_factory_date"]
        return out


    def cap_of(qty, tolerance_pct):
        return int(qty * (1 + frappe.utils.flt(tolerance_pct) / 100))
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers of the Fabric and Trim Requisition: the garment quantity of an order colour, default terms, trim category rules, and the line builders that read
    # the Tech Pack and Sales Order. Needs lib_samples.py, lib_allocation.py, lib_mat.py.
    def default_terms():
        return ("<ol><li>Delivery: as per the schedule above.</li><li>Partial shipments: not allowed.</li><li>Quality: as per the buyer's quality standards.</li>"
                "<li>Quantity: as per our internal buying standards. Over and above the allowance, uncut fabric will be returned to the supplier.</li>"
                "<li>Quantity is in metres.</li><li>Bulk shrinkage should be as per the approved fabric data sheet.</li>"
                "<li>Cuttable width and GSM must match the approved fabric data sheet.</li></ol>")


    def uniq(items):
        out = []
        for i in items:
            if i not in out:
                out.append(i)
        return out


    def order_colour_qty(sales_order, style_item, colour):
        cl = colour_level(get_order_lines(sales_order))
        row = cl.get((style_item, (colour or "").strip().upper()))
        return frappe.utils.cint(row["qty"]) if row else 0


    def fr_lines_for_sales_order(sales_order, customer, company):
        """FR line dicts for one Sales Order from the Tech Pack materials (FR types only)."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        out = []
        cl = colour_level(get_order_lines(sales_order))
        for key in cl:
            style = key[0]
            o = cl[key]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no fabric lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type not in fr_types or not colour_matches(m.colour, o["colour"], all_colours):
                    continue
                cons = flt(m.consumption)
                uom = m.uom or "Meter"
                source = "Tech Pack"
                costed = None
                if cs:
                    for cm in cs.materials:
                        if cm.material_type == m.material_type and (cm.is_selected or cm.is_selected is None) and (
                                (cm.item and cm.item == m.item) or (cm.description or "").strip().lower() == (m.description or "").strip().lower()):
                            costed = flt(cm.consumption)
                            if not cons:
                                cons = costed
                                uom = cm.uom or uom
                                source = "Cost Sheet"
                            break
                width = parse_width_cm(m.width) or 0
                role = {"Lining": "Lining", "Contrast Fabric": "Contrast"}.get(m.material_type, "Shell")
                gsm = parse_width_cm(m.gsm) if m.gsm else 0
                out.append({"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "style_name": tp.style_name, "colour": o["colour"], "material_role": role,
                            "tech_pack_material": m.name, "fabric_item": m.item, "fabric_description": m.description, "fabric_colour": m.colour or o["colour"],
                            "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0, "cuttable_width_cm": width, "gsm": gsm,
                            "garment_qty": cint(o["qty"]), "consumption": cons, "consumption_uom": uom, "consumption_source": source, "costed_consumption": costed})
        return out


    def material_type_for(category):
        c = (category or "").lower()
        if "label" in c:
            return "Label"
        if "packaging" in c:
            return "Packaging"
        return "Trim"


    def guess_category(material_type, description):
        """Trim Category for a Tech Pack material row, from its type and words in the description."""
        d = (description or "").lower()
        for words, cat in ((("size label", "size tab", "size tag"), "Size Label"), (("care", "wash care"), "Care Label"), (("thread",), "Thread"),
                           (("fusing", "interlining", "keo"), "Fusing / Interlining"), (("security",), "Security Tag"), (("hang tag", "hangtag", "price ticket"), "Hang Tag"),
                           (("button",), "Button"), (("zip", "hook", "fastener", "velcro"), "Zipper / Hooks / Fasteners"), (("elastic", "tape", "drawcord", "cord"), "Elastic / Tape"),
                           (("label",), "Woven Label"), (("carton", "poly", "bag", "tissue", "silica", "sticker", "hanger"), "Packaging")):
            if [w for w in words if w in d]:
                return cat
        return "Packaging" if material_type == "Packaging" else "Others"


    def tr_lines_for_sales_order(sales_order, customer, company):
        """TR line dicts for one Sales Order from the Tech Pack materials that are not fabric."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        by_colour = colour_level(get_order_lines(sales_order))
        size_qty = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_size"]):
            k = (style_of(it.item_code), (it.apparel_size or "").strip())
            size_qty[k] = size_qty.get(k, 0) + cint(it.qty)
        styles = {}
        names = []
        for key in by_colour:
            sk = "s|" + key[0]       # a style code may start with an underscore, which the sandbox refuses as a key
            if sk not in styles:
                styles[sk] = []
                names.append(key[0])
            styles[sk].append(by_colour[key])
        out = []
        for style in names:
            colours = styles["s|" + style]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no trim lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            pcs = cint(cs.pcs_per_carton) if cs else 0
            total = sum([cint(c["qty"]) for c in colours])
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type in fr_types:
                    continue
                cat = guess_category(m.material_type, m.description)
                base = {"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "trim_category": cat, "trim_item": m.item, "buyer_item_code": m.buyer_item_code,
                        "description": m.description, "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0,
                        "customer_provided": 1 if m.buyer_supplied else 0}
                is_length = uom_kind(m.uom) in ("m", "yd")
                cons = flt(m.consumption) or 1
                dtm = "dtm" in (m.description or "").lower() or (m.colour or "").strip().upper() == "DTM"
                if cat == "Size Label":
                    for k in sorted(size_qty):
                        if k[0] == style and k[1]:
                            row = dict(base)
                            row.update({"size": k[1], "calc_basis": "Per Size", "garment_qty": size_qty[k], "qty_per_garment": cons if not is_length else 1})
                            out.append(row)
                elif cat == "Packaging" and "carton" in (m.description or "").lower():
                    if not pcs:
                        frappe.msgprint("Style %s: set the pieces per carton on the Cost Sheet to get the carton line." % style)
                        continue
                    row = dict(base)
                    row.update({"calc_basis": "Per Carton", "garment_qty": total, "qty_per_garment": cons, "pcs_per_carton": pcs})
                    out.append(row)
                elif dtm or ((m.colour or "").strip() and colour_matches(m.colour, "", all_colours) is False):
                    for c in colours:
                        if not dtm and (m.colour or "").strip().upper() != (c["colour"] or "").strip().upper():
                            continue
                        row = dict(base)
                        row.update({"colour": c["colour"], "trim_colour": c["colour"], "garment_qty": cint(c["qty"])})
                        if is_length:
                            row.update({"calc_basis": "By Length", "consumption": cons, "consumption_uom": m.uom or "Meter"})
                        else:
                            row.update({"calc_basis": "Per Garment", "qty_per_garment": cons})
                        out.append(row)
                elif is_length:
                    row = dict(base)
                    row.update({"calc_basis": "By Length", "garment_qty": total, "consumption": cons, "consumption_uom": m.uom})
                    out.append(row)
                else:
                    row = dict(base)
                    row.update({"calc_basis": "Per Garment", "garment_qty": total, "qty_per_garment": cons})
                    out.append(row)
        return out
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    sos = frappe.form_dict.get("sales_orders")
    sos = json.loads(sos) if isinstance(sos, str) else sos
    items = list(d.get("items") or [])
    have = ["|".join([i.get("sales_order") or "", i.get("style_item") or "", (i.get("colour") or "").strip().upper(), i.get("material_role") or "", i.get("fabric_item") or "", i.get("tech_pack_material") or i.get("fabric_description") or ""]) for i in items]
    added = 0
    for so in sos:
        for line in fr_lines_for_sales_order(so, d.get("customer"), d.get("company")):
            k = "|".join([line.get("sales_order") or "", line.get("style_item") or "", (line.get("colour") or "").strip().upper(), line.get("material_role") or "", line.get("fabric_item") or "", line.get("tech_pack_material") or line.get("fabric_description") or ""])
            if k in have:
                continue
            have.append(k)
            items.append(line)
            added = added + 1
    frappe.flags.arinox_result = {"arinox_doc": {"items": items}, "count": added}


main()

# API arinox_fabric_requisition_revise_fabric_requisition: a new draft revision of an approved requisition (unsaved). Quantities are refreshed from the order on save;
# only the increase is requested again when it is submitted.
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers: the Sales Order at the order grain, rolled up to style x colour, and the tolerance cap (factory_allocation.py)
    def norm(colour):
        return (colour or "").strip().upper()


    def get_order_lines(sales_order):
        """Sales Order grouped to (style, colour, ship-to, buyer PO) -> qty, tolerance %, earliest ex-factory date. A dict of dicts, in order of appearance."""
        lines = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order},
                                 fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            key = (style, norm(it.apparel_colour), norm(it.apparel_ship_to), norm(it.apparel_buyer_po))
            row = lines.get(key)
            if not row:
                row = {"style_item": style, "colour": (it.apparel_colour or "").strip(), "ship_to": (it.apparel_ship_to or "").strip(),
                       "buyer_po": (it.apparel_buyer_po or "").strip(), "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                lines[key] = row
            row["qty"] = row["qty"] + frappe.utils.cint(it.qty)
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not row["ex_factory_date"] or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = it.delivery_date
        return lines


    def colour_level(order):
        """The order lines rolled up to (style, colour)."""
        out = {}
        for key in order:
            o = order[key]
            ckey = (key[0], key[1])
            row = out.get(ckey)
            if not row:
                row = {"style_item": key[0], "colour": o["colour"], "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                out[ckey] = row
            row["qty"] = row["qty"] + o["qty"]
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(o["tolerance_pct"]))
            if o["ex_factory_date"] and (not row["ex_factory_date"] or frappe.utils.getdate(o["ex_factory_date"]) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = o["ex_factory_date"]
        return out


    def cap_of(qty, tolerance_pct):
        return int(qty * (1 + frappe.utils.flt(tolerance_pct) / 100))
    # shared helpers of the Fabric and Trim Requisition: the garment quantity of an order colour, default terms, trim category rules, and the line builders that read
    # the Tech Pack and Sales Order. Needs lib_samples.py, lib_allocation.py, lib_mat.py.
    def default_terms():
        return ("<ol><li>Delivery: as per the schedule above.</li><li>Partial shipments: not allowed.</li><li>Quality: as per the buyer's quality standards.</li>"
                "<li>Quantity: as per our internal buying standards. Over and above the allowance, uncut fabric will be returned to the supplier.</li>"
                "<li>Quantity is in metres.</li><li>Bulk shrinkage should be as per the approved fabric data sheet.</li>"
                "<li>Cuttable width and GSM must match the approved fabric data sheet.</li></ol>")


    def uniq(items):
        out = []
        for i in items:
            if i not in out:
                out.append(i)
        return out


    def order_colour_qty(sales_order, style_item, colour):
        cl = colour_level(get_order_lines(sales_order))
        row = cl.get((style_item, (colour or "").strip().upper()))
        return frappe.utils.cint(row["qty"]) if row else 0


    def fr_lines_for_sales_order(sales_order, customer, company):
        """FR line dicts for one Sales Order from the Tech Pack materials (FR types only)."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        out = []
        cl = colour_level(get_order_lines(sales_order))
        for key in cl:
            style = key[0]
            o = cl[key]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no fabric lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type not in fr_types or not colour_matches(m.colour, o["colour"], all_colours):
                    continue
                cons = flt(m.consumption)
                uom = m.uom or "Meter"
                source = "Tech Pack"
                costed = None
                if cs:
                    for cm in cs.materials:
                        if cm.material_type == m.material_type and (cm.is_selected or cm.is_selected is None) and (
                                (cm.item and cm.item == m.item) or (cm.description or "").strip().lower() == (m.description or "").strip().lower()):
                            costed = flt(cm.consumption)
                            if not cons:
                                cons = costed
                                uom = cm.uom or uom
                                source = "Cost Sheet"
                            break
                width = parse_width_cm(m.width) or 0
                role = {"Lining": "Lining", "Contrast Fabric": "Contrast"}.get(m.material_type, "Shell")
                gsm = parse_width_cm(m.gsm) if m.gsm else 0
                out.append({"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "style_name": tp.style_name, "colour": o["colour"], "material_role": role,
                            "tech_pack_material": m.name, "fabric_item": m.item, "fabric_description": m.description, "fabric_colour": m.colour or o["colour"],
                            "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0, "cuttable_width_cm": width, "gsm": gsm,
                            "garment_qty": cint(o["qty"]), "consumption": cons, "consumption_uom": uom, "consumption_source": source, "costed_consumption": costed})
        return out


    def material_type_for(category):
        c = (category or "").lower()
        if "label" in c:
            return "Label"
        if "packaging" in c:
            return "Packaging"
        return "Trim"


    def guess_category(material_type, description):
        """Trim Category for a Tech Pack material row, from its type and words in the description."""
        d = (description or "").lower()
        for words, cat in ((("size label", "size tab", "size tag"), "Size Label"), (("care", "wash care"), "Care Label"), (("thread",), "Thread"),
                           (("fusing", "interlining", "keo"), "Fusing / Interlining"), (("security",), "Security Tag"), (("hang tag", "hangtag", "price ticket"), "Hang Tag"),
                           (("button",), "Button"), (("zip", "hook", "fastener", "velcro"), "Zipper / Hooks / Fasteners"), (("elastic", "tape", "drawcord", "cord"), "Elastic / Tape"),
                           (("label",), "Woven Label"), (("carton", "poly", "bag", "tissue", "silica", "sticker", "hanger"), "Packaging")):
            if [w for w in words if w in d]:
                return cat
        return "Packaging" if material_type == "Packaging" else "Others"


    def tr_lines_for_sales_order(sales_order, customer, company):
        """TR line dicts for one Sales Order from the Tech Pack materials that are not fabric."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        by_colour = colour_level(get_order_lines(sales_order))
        size_qty = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_size"]):
            k = (style_of(it.item_code), (it.apparel_size or "").strip())
            size_qty[k] = size_qty.get(k, 0) + cint(it.qty)
        styles = {}
        names = []
        for key in by_colour:
            sk = "s|" + key[0]       # a style code may start with an underscore, which the sandbox refuses as a key
            if sk not in styles:
                styles[sk] = []
                names.append(key[0])
            styles[sk].append(by_colour[key])
        out = []
        for style in names:
            colours = styles["s|" + style]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no trim lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            pcs = cint(cs.pcs_per_carton) if cs else 0
            total = sum([cint(c["qty"]) for c in colours])
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type in fr_types:
                    continue
                cat = guess_category(m.material_type, m.description)
                base = {"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "trim_category": cat, "trim_item": m.item, "buyer_item_code": m.buyer_item_code,
                        "description": m.description, "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0,
                        "customer_provided": 1 if m.buyer_supplied else 0}
                is_length = uom_kind(m.uom) in ("m", "yd")
                cons = flt(m.consumption) or 1
                dtm = "dtm" in (m.description or "").lower() or (m.colour or "").strip().upper() == "DTM"
                if cat == "Size Label":
                    for k in sorted(size_qty):
                        if k[0] == style and k[1]:
                            row = dict(base)
                            row.update({"size": k[1], "calc_basis": "Per Size", "garment_qty": size_qty[k], "qty_per_garment": cons if not is_length else 1})
                            out.append(row)
                elif cat == "Packaging" and "carton" in (m.description or "").lower():
                    if not pcs:
                        frappe.msgprint("Style %s: set the pieces per carton on the Cost Sheet to get the carton line." % style)
                        continue
                    row = dict(base)
                    row.update({"calc_basis": "Per Carton", "garment_qty": total, "qty_per_garment": cons, "pcs_per_carton": pcs})
                    out.append(row)
                elif dtm or ((m.colour or "").strip() and colour_matches(m.colour, "", all_colours) is False):
                    for c in colours:
                        if not dtm and (m.colour or "").strip().upper() != (c["colour"] or "").strip().upper():
                            continue
                        row = dict(base)
                        row.update({"colour": c["colour"], "trim_colour": c["colour"], "garment_qty": cint(c["qty"])})
                        if is_length:
                            row.update({"calc_basis": "By Length", "consumption": cons, "consumption_uom": m.uom or "Meter"})
                        else:
                            row.update({"calc_basis": "Per Garment", "qty_per_garment": cons})
                        out.append(row)
                elif is_length:
                    row = dict(base)
                    row.update({"calc_basis": "By Length", "garment_qty": total, "consumption": cons, "consumption_uom": m.uom})
                    out.append(row)
                else:
                    row = dict(base)
                    row.update({"calc_basis": "Per Garment", "garment_qty": total, "qty_per_garment": cons})
                    out.append(row)
        return out
    src = frappe.get_doc("Fabric Requisition", frappe.form_dict.get("source_name"))
    src.check_permission("read")
    if src.docstatus != 1 or src.status in ("Superseded", "Cancelled"):
        frappe.throw("Only an approved, current requisition can be revised.")
    new = frappe.copy_doc(src)
    new.docstatus = 0
    for child in new.get_all_children():
        child.docstatus = 0
    new.previous_fr = src.name
    new.revision_no = frappe.utils.cint(src.revision_no) + 1
    new.status = "Draft"
    new.arinox_name = None            # a revision gets a new number
    new.set("summary", [])
    new.revision_reason = None
    new.approved_by = None
    new.approved_on = None
    for r in new.items:
        r.material_request = None
        r.material_request_item = None
        r.ordered_qty = 0
        r.received_qty = 0
        r.accepted_qty = 0
        r.rejected_qty = 0
        r.garment_qty = order_colour_qty(r.sales_order, r.style_item, r.colour) or r.garment_qty
    frappe.flags.arinox_result = new.as_dict()


main()

# API arinox_fabric_requisition_save_fabric_requisition: create or update a DRAFT fabric requisition. Validation runs. Never submits. Answers the name.
def main():
    data = frappe.form_dict.get("data")
    data = json.loads(data) if isinstance(data, str) else data
    if data.get("name") and frappe.db.exists("Fabric Requisition", data["name"]):
        doc = frappe.get_doc("Fabric Requisition", data["name"])
        if doc.docstatus != 0:
            frappe.throw("Only a draft can be changed. Use Revise on an approved requisition.")
        doc.check_permission("write")
        for k in data:
            if k not in ("name", "items", "doctype"):
                doc.set(k, data[k])
        if "items" in data:
            doc.set("items", data["items"])
        doc.save()
    else:
        d = {}
        for k in data:
            if k != "name":
                d[k] = data[k]
        d["doctype"] = "Fabric Requisition"
        doc = frappe.get_doc(d)
        doc.check_permission("create")
        doc.insert()
    frappe.flags.arinox_result = doc.name


main()

# Trim Requisition, Before Save: lines checked against the order, bulk-trim approval hold, dates, allowance, quantity by basis (per garment, size, colour, carton, length, fixed), stock claims.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers: the Sales Order at the order grain, rolled up to style x colour, and the tolerance cap (factory_allocation.py)
    def norm(colour):
        return (colour or "").strip().upper()


    def get_order_lines(sales_order):
        """Sales Order grouped to (style, colour, ship-to, buyer PO) -> qty, tolerance %, earliest ex-factory date. A dict of dicts, in order of appearance."""
        lines = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order},
                                 fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            key = (style, norm(it.apparel_colour), norm(it.apparel_ship_to), norm(it.apparel_buyer_po))
            row = lines.get(key)
            if not row:
                row = {"style_item": style, "colour": (it.apparel_colour or "").strip(), "ship_to": (it.apparel_ship_to or "").strip(),
                       "buyer_po": (it.apparel_buyer_po or "").strip(), "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                lines[key] = row
            row["qty"] = row["qty"] + frappe.utils.cint(it.qty)
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not row["ex_factory_date"] or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = it.delivery_date
        return lines


    def colour_level(order):
        """The order lines rolled up to (style, colour)."""
        out = {}
        for key in order:
            o = order[key]
            ckey = (key[0], key[1])
            row = out.get(ckey)
            if not row:
                row = {"style_item": key[0], "colour": o["colour"], "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                out[ckey] = row
            row["qty"] = row["qty"] + o["qty"]
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(o["tolerance_pct"]))
            if o["ex_factory_date"] and (not row["ex_factory_date"] or frappe.utils.getdate(o["ex_factory_date"]) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = o["ex_factory_date"]
        return out


    def cap_of(qty, tolerance_pct):
        return int(qty * (1 + frappe.utils.flt(tolerance_pct) / 100))
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers of the Fabric and Trim Requisition: the garment quantity of an order colour, default terms, trim category rules, and the line builders that read
    # the Tech Pack and Sales Order. Needs lib_samples.py, lib_allocation.py, lib_mat.py.
    def default_terms():
        return ("<ol><li>Delivery: as per the schedule above.</li><li>Partial shipments: not allowed.</li><li>Quality: as per the buyer's quality standards.</li>"
                "<li>Quantity: as per our internal buying standards. Over and above the allowance, uncut fabric will be returned to the supplier.</li>"
                "<li>Quantity is in metres.</li><li>Bulk shrinkage should be as per the approved fabric data sheet.</li>"
                "<li>Cuttable width and GSM must match the approved fabric data sheet.</li></ol>")


    def uniq(items):
        out = []
        for i in items:
            if i not in out:
                out.append(i)
        return out


    def order_colour_qty(sales_order, style_item, colour):
        cl = colour_level(get_order_lines(sales_order))
        row = cl.get((style_item, (colour or "").strip().upper()))
        return frappe.utils.cint(row["qty"]) if row else 0


    def fr_lines_for_sales_order(sales_order, customer, company):
        """FR line dicts for one Sales Order from the Tech Pack materials (FR types only)."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        out = []
        cl = colour_level(get_order_lines(sales_order))
        for key in cl:
            style = key[0]
            o = cl[key]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no fabric lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type not in fr_types or not colour_matches(m.colour, o["colour"], all_colours):
                    continue
                cons = flt(m.consumption)
                uom = m.uom or "Meter"
                source = "Tech Pack"
                costed = None
                if cs:
                    for cm in cs.materials:
                        if cm.material_type == m.material_type and (cm.is_selected or cm.is_selected is None) and (
                                (cm.item and cm.item == m.item) or (cm.description or "").strip().lower() == (m.description or "").strip().lower()):
                            costed = flt(cm.consumption)
                            if not cons:
                                cons = costed
                                uom = cm.uom or uom
                                source = "Cost Sheet"
                            break
                width = parse_width_cm(m.width) or 0
                role = {"Lining": "Lining", "Contrast Fabric": "Contrast"}.get(m.material_type, "Shell")
                gsm = parse_width_cm(m.gsm) if m.gsm else 0
                out.append({"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "style_name": tp.style_name, "colour": o["colour"], "material_role": role,
                            "tech_pack_material": m.name, "fabric_item": m.item, "fabric_description": m.description, "fabric_colour": m.colour or o["colour"],
                            "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0, "cuttable_width_cm": width, "gsm": gsm,
                            "garment_qty": cint(o["qty"]), "consumption": cons, "consumption_uom": uom, "consumption_source": source, "costed_consumption": costed})
        return out


    def material_type_for(category):
        c = (category or "").lower()
        if "label" in c:
            return "Label"
        if "packaging" in c:
            return "Packaging"
        return "Trim"


    def guess_category(material_type, description):
        """Trim Category for a Tech Pack material row, from its type and words in the description."""
        d = (description or "").lower()
        for words, cat in ((("size label", "size tab", "size tag"), "Size Label"), (("care", "wash care"), "Care Label"), (("thread",), "Thread"),
                           (("fusing", "interlining", "keo"), "Fusing / Interlining"), (("security",), "Security Tag"), (("hang tag", "hangtag", "price ticket"), "Hang Tag"),
                           (("button",), "Button"), (("zip", "hook", "fastener", "velcro"), "Zipper / Hooks / Fasteners"), (("elastic", "tape", "drawcord", "cord"), "Elastic / Tape"),
                           (("label",), "Woven Label"), (("carton", "poly", "bag", "tissue", "silica", "sticker", "hanger"), "Packaging")):
            if [w for w in words if w in d]:
                return cat
        return "Packaging" if material_type == "Packaging" else "Others"


    def tr_lines_for_sales_order(sales_order, customer, company):
        """TR line dicts for one Sales Order from the Tech Pack materials that are not fabric."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        by_colour = colour_level(get_order_lines(sales_order))
        size_qty = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_size"]):
            k = (style_of(it.item_code), (it.apparel_size or "").strip())
            size_qty[k] = size_qty.get(k, 0) + cint(it.qty)
        styles = {}
        names = []
        for key in by_colour:
            sk = "s|" + key[0]       # a style code may start with an underscore, which the sandbox refuses as a key
            if sk not in styles:
                styles[sk] = []
                names.append(key[0])
            styles[sk].append(by_colour[key])
        out = []
        for style in names:
            colours = styles["s|" + style]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no trim lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            pcs = cint(cs.pcs_per_carton) if cs else 0
            total = sum([cint(c["qty"]) for c in colours])
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type in fr_types:
                    continue
                cat = guess_category(m.material_type, m.description)
                base = {"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "trim_category": cat, "trim_item": m.item, "buyer_item_code": m.buyer_item_code,
                        "description": m.description, "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0,
                        "customer_provided": 1 if m.buyer_supplied else 0}
                is_length = uom_kind(m.uom) in ("m", "yd")
                cons = flt(m.consumption) or 1
                dtm = "dtm" in (m.description or "").lower() or (m.colour or "").strip().upper() == "DTM"
                if cat == "Size Label":
                    for k in sorted(size_qty):
                        if k[0] == style and k[1]:
                            row = dict(base)
                            row.update({"size": k[1], "calc_basis": "Per Size", "garment_qty": size_qty[k], "qty_per_garment": cons if not is_length else 1})
                            out.append(row)
                elif cat == "Packaging" and "carton" in (m.description or "").lower():
                    if not pcs:
                        frappe.msgprint("Style %s: set the pieces per carton on the Cost Sheet to get the carton line." % style)
                        continue
                    row = dict(base)
                    row.update({"calc_basis": "Per Carton", "garment_qty": total, "qty_per_garment": cons, "pcs_per_carton": pcs})
                    out.append(row)
                elif dtm or ((m.colour or "").strip() and colour_matches(m.colour, "", all_colours) is False):
                    for c in colours:
                        if not dtm and (m.colour or "").strip().upper() != (c["colour"] or "").strip().upper():
                            continue
                        row = dict(base)
                        row.update({"colour": c["colour"], "trim_colour": c["colour"], "garment_qty": cint(c["qty"])})
                        if is_length:
                            row.update({"calc_basis": "By Length", "consumption": cons, "consumption_uom": m.uom or "Meter"})
                        else:
                            row.update({"calc_basis": "Per Garment", "qty_per_garment": cons})
                        out.append(row)
                elif is_length:
                    row = dict(base)
                    row.update({"calc_basis": "By Length", "garment_qty": total, "consumption": cons, "consumption_uom": m.uom})
                    out.append(row)
                else:
                    row = dict(base)
                    row.update({"calc_basis": "Per Garment", "garment_qty": total, "qty_per_garment": cons})
                    out.append(row)
        return out
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    getdate = frappe.utils.getdate
    add_days = frappe.utils.add_days
    ceil = frappe.utils.ceil
    if not doc.ordered_by:
        doc.ordered_by = frappe.session.user
    if not doc.items:
        frappe.throw("Add at least one trim line.")
    if cint(doc.revision_no) > 0 and not (doc.revision_reason or "").strip():
        frappe.throw("Enter the reason for this revision.")
    seen = {}
    for r in doc.items:
        if not (r.trim_item or r.description):
            continue
        k = tr_row_key(r)
        if k in seen:
            frappe.throw("Row %s repeats row %s: same order, style, colour, size, category and trim." % (r.idx, seen[k]))
        seen[k] = r.idx

    flags = []
    hold_mode = frappe.db.get_single_value("Apparel Settings", "hold_po_until_approval") or "Warn"
    due_days = cint(frappe.db.get_single_value("Apparel Settings", "trim_due_days_before_pcd") or 7)
    for r in doc.items:
        so = frappe.db.get_value("Sales Order", r.sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so:
            frappe.throw("Row %s: Sales Order %s does not exist." % (r.idx, r.sales_order))
        if so.docstatus != 1:
            frappe.throw("Row %s: Sales Order %s is not submitted." % (r.idx, r.sales_order))
        if so.customer != doc.customer or so.company != doc.company:
            frappe.throw("Row %s: Sales Order %s belongs to another buyer or company." % (r.idx, r.sales_order))
        if frappe.db.get_value("Item", r.style_item, "variant_of"):
            frappe.throw("Row %s: pick the style (template item), not a variant." % r.idx)
        r.style_no = r.style_no or frappe.db.get_value("Tech Pack", {"style_item": r.style_item}, "style_no") or r.style_item
        if (r.trim_colour or "").strip().upper() in ("DTM", "DTM GROUND COLOR", "DYED TO MATCH") and r.colour:
            r.trim_colour = r.colour       # DTM resolves to the garment colour
        if not cint(r.garment_qty) and r.calc_basis != "Fixed Qty":
            total = 0
            for it in frappe.get_all("Sales Order Item", filters={"parent": r.sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_size"]):
                if style_of(it.item_code) != r.style_item:
                    continue
                if r.colour and (it.apparel_colour or "").strip().upper() != r.colour.strip().upper():
                    continue
                if r.size and (it.apparel_size or "").strip().upper() != r.size.strip().upper():
                    continue
                total = total + cint(it.qty)
            r.garment_qty = total
        ap = approval_info(r.sales_order, r.style_item, "Bulk Trim", None, doc.customer)
        r.approval_status = ap[0]
        r.hold = 1 if (not ap[1] and hold_mode != "Off" and not cint(r.customer_provided)) else 0
        if r.hold:
            flags.append("Row %s: bulk trim approval is %s; the purchase order will be held." % (r.idx, ap[0]))
        pcd = get_style_dates(r.sales_order, r.style_item, r.colour or None)[0]
        if pcd and not r.required_by:
            r.required_by = add_days(pcd, -due_days)
        if pcd and r.required_by and getdate(r.required_by) > add_days(getdate(pcd), -due_days):
            flags.append("Row %s: required by %s is later than PCD %s minus %s days." % (r.idx, r.required_by, pcd, due_days))
        if not pcd:
            flags.append("Row %s: no planned cut date yet; set the Factory Allocation." % r.idx)

        # ---- quantity by basis
        basis = r.calc_basis or "Per Garment"
        rule = get_allowance(material_type_for(r.trim_category), r.trim_category, doc.customer, None)
        default_pct = flt(rule["allowance_pct"])
        if r.allowance_pct is None:
            r.allowance_pct = default_pct
        elif flt(r.allowance_pct) != default_pct and not (r.allowance_reason or "").strip():
            frappe.throw("Row %s: the allowance %s%% differs from the rule (%s%%). Enter the reason." % (r.idx, r.allowance_pct, default_pct))
        if not flt(r.pack_size):
            r.pack_size = flt(rule["pack_size"])
        a = 1 + flt(r.allowance_pct) / 100
        gq = cint(r.garment_qty)
        qpg = flt(r.qty_per_garment)
        spare = flt(r.spare_per_garment)
        if basis == "Per Garment" or basis == "Per Size" or basis == "Per Colour":
            if basis == "Per Size" and not (r.size or "").strip():
                frappe.throw("Row %s: a per-size line needs the size." % r.idx)
            if basis == "Per Colour" and not (r.colour or "").strip():
                frappe.throw("Row %s: a per-colour line needs the colour." % r.idx)
            gross = gq * (qpg + spare) * a
        elif basis == "Per Carton":
            if cint(r.pcs_per_carton) <= 0:
                frappe.throw("Row %s: enter the pieces per carton." % r.idx)
            gross = ceil(gq / cint(r.pcs_per_carton)) * qpg * a
        elif basis == "By Length":
            if flt(r.consumption) <= 0 or not r.consumption_uom:
                frappe.throw("Row %s: enter the length per garment and its unit." % r.idx)
            gross = gq * flt(r.consumption) * a
        else:
            gross = qpg
        if qpg <= 0 and basis != "By Length":
            frappe.throw("Row %s: enter the quantity per garment (or carton)." % r.idx)
        r.gross_qty = flt(gross, 4)
        if flt(r.stock_used) > 0:
            if not r.stock_warehouse or not r.trim_item:
                frappe.throw("Row %s: choose the trim item and warehouse to use leftover stock." % r.idx)
            free = free_stock(r.trim_item, r.stock_warehouse, "Trim Requisition", "Trim Requisition Item", doc.name)
            if flt(r.stock_used) > free + 0.0001:
                frappe.throw("Row %s: only %s of %s is free in %s (the rest is claimed by other requisitions)." % (r.idx, flt(free, 2), r.trim_item, r.stock_warehouse))
        r.net_qty = flt(max(flt(r.gross_qty) - flt(r.stock_used), 0), 4)
        base_uom = r.consumption_uom if basis == "By Length" else (frappe.db.get_value("Item", r.trim_item, "stock_uom") if r.trim_item else None) or "Nos"
        r.order_uom = r.order_uom or base_uom
        qty = r.net_qty
        if r.order_uom != base_uom:
            if uom_kind(r.order_uom) and uom_kind(base_uom) in ("m", "yd"):
                qty = from_metres(to_metres(qty, base_uom, None, None), r.order_uom, None, None)
            else:
                frappe.throw("Row %s: cannot convert %s to %s. Use the same unit or a length unit." % (r.idx, base_uom, r.order_uom))
        if basis == "By Length":
            r.order_qty = round_up_to_pack(flt(qty, 2), r.pack_size) if r.net_qty > 0 else 0
        else:
            r.order_qty = round_up_to_pack(ceil(round(qty, 4)), r.pack_size) if r.net_qty > 0 else 0

    if doc.previous_tr:
        chain = revision_chain("Trim Requisition", "previous_tr", doc.previous_tr)
        for r in doc.items:
            before = requested_so_far("TR", chain, tr_row_key(r))
            if before and flt(r.net_qty) + 0.0005 < before:
                flags.append("Row %s: reduced from %s to %s. Reduce the order with the supplier." % (r.idx, flt(before, 2), flt(r.net_qty, 2)))
    doc.red_flags = "\n".join(uniq(flags))
    doc.status = requisition_status(doc)


run(doc)

# Trim Requisition, Before Submit: every line has its trim item and a supplier (or is buyer supplied).
def run(doc):
    for r in doc.items:
        if not r.trim_item:
            frappe.throw("Row %s: choose or create the trim item before approving." % r.idx)
        if not r.supplier and not frappe.utils.cint(r.customer_provided):
            frappe.throw("Row %s: choose a supplier, or mark the trim as buyer supplied." % r.idx)


run(doc)

# Trim Requisition, After Submit: approved. Material Requests (grouped by supplier, only the increase over earlier revisions), previous revision superseded, TR_RAISED stamped.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    doc.db_set({"approved_by": frappe.session.user, "approved_on": frappe.utils.now_datetime()})
    chain = revision_chain("Trim Requisition", "previous_tr", doc.name)[1:]
    lines = []
    for r in doc.items:
        if flt(r.net_qty) <= 0:
            continue
        key = tr_row_key(r)
        delta = flt(r.net_qty) - requested_so_far("TR", chain, key)
        if delta <= 0.0005:
            continue
        stock_uom = frappe.db.get_value("Item", r.trim_item, "stock_uom")
        order_qty = delta if r.order_uom == stock_uom else round_up_to_pack(delta, r.pack_size)
        q = mr_line(r.trim_item, delta, r.order_uom, order_qty)
        qty = q[0]
        if q[2] == 1 and q[1] == stock_uom:
            qty = frappe.utils.ceil(round(delta, 4)) if r.calc_basis != "By Length" else flt(delta, 2)
        lines.append({"item_code": r.trim_item, "qty": qty, "uom": q[1], "conversion_factor": q[2], "supplier": r.supplier, "required_by": r.required_by, "key": key,
                      "style_no": r.style_no, "colour": r.colour, "sales_order": r.sales_order, "description": r.description, "customer_provided": cint(r.customer_provided),
                      "hold_reason": "Trim approval %s" % r.approval_status if r.hold else None})
    create_material_requests(doc, lines, "TR", "Trim")
    for r in doc.items:
        mri = frappe.db.sql("select i.name, i.parent from `tabMaterial Request Item` i where i.apparel_requisition_type = 'TR' and i.apparel_requisition = %s "
                            "and i.apparel_requisition_item = %s limit 1", (doc.name, tr_row_key(r)))
        if mri:
            r.db_set({"material_request": mri[0][1], "material_request_item": mri[0][0]})
    if doc.previous_tr:
        frappe.db.set_value("Trim Requisition", doc.previous_tr, "status", "Superseded")
    stamp_safe_requisition(doc, "TR_RAISED")
    status = requisition_status(doc)
    doc.status = status
    doc.db_set("status", status, update_modified=False)


run(doc)

# Trim Requisition, After Cancel: its Material Requests are cancelled, the previous revision is current again, the milestone is cleared.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    done = []
    for m in frappe.db.sql("select distinct i.parent from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                           "where i.apparel_requisition_type = 'TR' and i.apparel_requisition = %s and m.docstatus = 1", (doc.name,)):
        if m[0] in done:
            continue
        done.append(m[0])
        mr = frappe.get_doc("Material Request", m[0])
        mr.flags.ignore_permissions = True
        mr.cancel()
    if doc.previous_tr:
        frappe.db.set_value("Trim Requisition", doc.previous_tr, "status", "Approved")
        prev = frappe.get_doc("Trim Requisition", doc.previous_tr)
        prev.status = "Approved"
        frappe.db.set_value("Trim Requisition", doc.previous_tr, "status", requisition_status(prev), update_modified=False)
    unstamp_safe("Trim Requisition", doc.name)
    doc.db_set("status", "Cancelled")


run(doc)

# API arinox_trim_requisition_get_lines_from_sales_orders: one row per non-fabric material of the Tech Pack (by size, colour, carton, length or per garment), quantities from the Sales Order (appended to the form's rows).
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers: the Sales Order at the order grain, rolled up to style x colour, and the tolerance cap (factory_allocation.py)
    def norm(colour):
        return (colour or "").strip().upper()


    def get_order_lines(sales_order):
        """Sales Order grouped to (style, colour, ship-to, buyer PO) -> qty, tolerance %, earliest ex-factory date. A dict of dicts, in order of appearance."""
        lines = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order},
                                 fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            key = (style, norm(it.apparel_colour), norm(it.apparel_ship_to), norm(it.apparel_buyer_po))
            row = lines.get(key)
            if not row:
                row = {"style_item": style, "colour": (it.apparel_colour or "").strip(), "ship_to": (it.apparel_ship_to or "").strip(),
                       "buyer_po": (it.apparel_buyer_po or "").strip(), "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                lines[key] = row
            row["qty"] = row["qty"] + frappe.utils.cint(it.qty)
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not row["ex_factory_date"] or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = it.delivery_date
        return lines


    def colour_level(order):
        """The order lines rolled up to (style, colour)."""
        out = {}
        for key in order:
            o = order[key]
            ckey = (key[0], key[1])
            row = out.get(ckey)
            if not row:
                row = {"style_item": key[0], "colour": o["colour"], "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                out[ckey] = row
            row["qty"] = row["qty"] + o["qty"]
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(o["tolerance_pct"]))
            if o["ex_factory_date"] and (not row["ex_factory_date"] or frappe.utils.getdate(o["ex_factory_date"]) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = o["ex_factory_date"]
        return out


    def cap_of(qty, tolerance_pct):
        return int(qty * (1 + frappe.utils.flt(tolerance_pct) / 100))
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers of the Fabric and Trim Requisition: the garment quantity of an order colour, default terms, trim category rules, and the line builders that read
    # the Tech Pack and Sales Order. Needs lib_samples.py, lib_allocation.py, lib_mat.py.
    def default_terms():
        return ("<ol><li>Delivery: as per the schedule above.</li><li>Partial shipments: not allowed.</li><li>Quality: as per the buyer's quality standards.</li>"
                "<li>Quantity: as per our internal buying standards. Over and above the allowance, uncut fabric will be returned to the supplier.</li>"
                "<li>Quantity is in metres.</li><li>Bulk shrinkage should be as per the approved fabric data sheet.</li>"
                "<li>Cuttable width and GSM must match the approved fabric data sheet.</li></ol>")


    def uniq(items):
        out = []
        for i in items:
            if i not in out:
                out.append(i)
        return out


    def order_colour_qty(sales_order, style_item, colour):
        cl = colour_level(get_order_lines(sales_order))
        row = cl.get((style_item, (colour or "").strip().upper()))
        return frappe.utils.cint(row["qty"]) if row else 0


    def fr_lines_for_sales_order(sales_order, customer, company):
        """FR line dicts for one Sales Order from the Tech Pack materials (FR types only)."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        out = []
        cl = colour_level(get_order_lines(sales_order))
        for key in cl:
            style = key[0]
            o = cl[key]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no fabric lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type not in fr_types or not colour_matches(m.colour, o["colour"], all_colours):
                    continue
                cons = flt(m.consumption)
                uom = m.uom or "Meter"
                source = "Tech Pack"
                costed = None
                if cs:
                    for cm in cs.materials:
                        if cm.material_type == m.material_type and (cm.is_selected or cm.is_selected is None) and (
                                (cm.item and cm.item == m.item) or (cm.description or "").strip().lower() == (m.description or "").strip().lower()):
                            costed = flt(cm.consumption)
                            if not cons:
                                cons = costed
                                uom = cm.uom or uom
                                source = "Cost Sheet"
                            break
                width = parse_width_cm(m.width) or 0
                role = {"Lining": "Lining", "Contrast Fabric": "Contrast"}.get(m.material_type, "Shell")
                gsm = parse_width_cm(m.gsm) if m.gsm else 0
                out.append({"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "style_name": tp.style_name, "colour": o["colour"], "material_role": role,
                            "tech_pack_material": m.name, "fabric_item": m.item, "fabric_description": m.description, "fabric_colour": m.colour or o["colour"],
                            "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0, "cuttable_width_cm": width, "gsm": gsm,
                            "garment_qty": cint(o["qty"]), "consumption": cons, "consumption_uom": uom, "consumption_source": source, "costed_consumption": costed})
        return out


    def material_type_for(category):
        c = (category or "").lower()
        if "label" in c:
            return "Label"
        if "packaging" in c:
            return "Packaging"
        return "Trim"


    def guess_category(material_type, description):
        """Trim Category for a Tech Pack material row, from its type and words in the description."""
        d = (description or "").lower()
        for words, cat in ((("size label", "size tab", "size tag"), "Size Label"), (("care", "wash care"), "Care Label"), (("thread",), "Thread"),
                           (("fusing", "interlining", "keo"), "Fusing / Interlining"), (("security",), "Security Tag"), (("hang tag", "hangtag", "price ticket"), "Hang Tag"),
                           (("button",), "Button"), (("zip", "hook", "fastener", "velcro"), "Zipper / Hooks / Fasteners"), (("elastic", "tape", "drawcord", "cord"), "Elastic / Tape"),
                           (("label",), "Woven Label"), (("carton", "poly", "bag", "tissue", "silica", "sticker", "hanger"), "Packaging")):
            if [w for w in words if w in d]:
                return cat
        return "Packaging" if material_type == "Packaging" else "Others"


    def tr_lines_for_sales_order(sales_order, customer, company):
        """TR line dicts for one Sales Order from the Tech Pack materials that are not fabric."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        so = frappe.db.get_value("Sales Order", sales_order, ["docstatus", "customer", "company"], as_dict=True)
        if not so or so.docstatus != 1 or so.customer != customer or so.company != company:
            frappe.throw("Sales Order %s must be submitted and belong to this buyer and company." % sales_order)
        fr_types = fr_material_types()
        by_colour = colour_level(get_order_lines(sales_order))
        size_qty = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "qty", "apparel_colour", "apparel_size"]):
            k = (style_of(it.item_code), (it.apparel_size or "").strip())
            size_qty[k] = size_qty.get(k, 0) + cint(it.qty)
        styles = {}
        names = []
        for key in by_colour:
            sk = "s|" + key[0]       # a style code may start with an underscore, which the sandbox refuses as a key
            if sk not in styles:
                styles[sk] = []
                names.append(key[0])
            styles[sk].append(by_colour[key])
        out = []
        for style in names:
            colours = styles["s|" + style]
            tp = tech_pack_for(style)
            if not tp:
                frappe.msgprint("Style %s has no submitted Tech Pack; no trim lines were made for it." % style)
                continue
            cs = cost_sheet_for(sales_order, style)
            pcs = cint(cs.pcs_per_carton) if cs else 0
            total = sum([cint(c["qty"]) for c in colours])
            all_colours = [c.colour for c in tp.colours]
            for m in tp.materials:
                if m.material_type in fr_types:
                    continue
                cat = guess_category(m.material_type, m.description)
                base = {"sales_order": sales_order, "style_item": style, "style_no": tp.style_no, "trim_category": cat, "trim_item": m.item, "buyer_item_code": m.buyer_item_code,
                        "description": m.description, "supplier": m.nominated_supplier, "nominated_by_buyer": 1 if m.nominated_supplier else 0,
                        "customer_provided": 1 if m.buyer_supplied else 0}
                is_length = uom_kind(m.uom) in ("m", "yd")
                cons = flt(m.consumption) or 1
                dtm = "dtm" in (m.description or "").lower() or (m.colour or "").strip().upper() == "DTM"
                if cat == "Size Label":
                    for k in sorted(size_qty):
                        if k[0] == style and k[1]:
                            row = dict(base)
                            row.update({"size": k[1], "calc_basis": "Per Size", "garment_qty": size_qty[k], "qty_per_garment": cons if not is_length else 1})
                            out.append(row)
                elif cat == "Packaging" and "carton" in (m.description or "").lower():
                    if not pcs:
                        frappe.msgprint("Style %s: set the pieces per carton on the Cost Sheet to get the carton line." % style)
                        continue
                    row = dict(base)
                    row.update({"calc_basis": "Per Carton", "garment_qty": total, "qty_per_garment": cons, "pcs_per_carton": pcs})
                    out.append(row)
                elif dtm or ((m.colour or "").strip() and colour_matches(m.colour, "", all_colours) is False):
                    for c in colours:
                        if not dtm and (m.colour or "").strip().upper() != (c["colour"] or "").strip().upper():
                            continue
                        row = dict(base)
                        row.update({"colour": c["colour"], "trim_colour": c["colour"], "garment_qty": cint(c["qty"])})
                        if is_length:
                            row.update({"calc_basis": "By Length", "consumption": cons, "consumption_uom": m.uom or "Meter"})
                        else:
                            row.update({"calc_basis": "Per Garment", "qty_per_garment": cons})
                        out.append(row)
                elif is_length:
                    row = dict(base)
                    row.update({"calc_basis": "By Length", "garment_qty": total, "consumption": cons, "consumption_uom": m.uom})
                    out.append(row)
                else:
                    row = dict(base)
                    row.update({"calc_basis": "Per Garment", "garment_qty": total, "qty_per_garment": cons})
                    out.append(row)
        return out
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    sos = frappe.form_dict.get("sales_orders")
    sos = json.loads(sos) if isinstance(sos, str) else sos
    items = list(d.get("items") or [])
    have = ["|".join([i.get("sales_order") or "", i.get("style_item") or "", (i.get("colour") or "").strip().upper(), (i.get("size") or "").strip().upper(), i.get("trim_category") or "", i.get("trim_item") or i.get("description") or "", (i.get("trim_colour") or "").strip().upper()]) for i in items]
    added = 0
    for so in sos:
        for line in tr_lines_for_sales_order(so, d.get("customer"), d.get("company")):
            k = "|".join([line.get("sales_order") or "", line.get("style_item") or "", (line.get("colour") or "").strip().upper(), (line.get("size") or "").strip().upper(), line.get("trim_category") or "", line.get("trim_item") or line.get("description") or "", (line.get("trim_colour") or "").strip().upper()])
            if k in have:
                continue
            have.append(k)
            items.append(line)
            added = added + 1
    frappe.flags.arinox_result = {"arinox_doc": {"items": items}, "count": added}


main()

# API arinox_trim_requisition_revise_trim_requisition: a new draft revision of an approved requisition (unsaved). Quantities are refreshed from the order on save;
# only the increase is requested again when it is submitted.
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
