                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/items.py (+ ensure_attribute_values from tech_pack.py): a template per fabric quality with the Colour attribute, a variant per colour,
    # and a plain stock item per trim code. Needs lib_mat.py (YARD_M).
    def ensure_attribute_values(attribute, values):
        if not frappe.db.exists("Item Attribute", attribute):
            frappe.get_doc({"doctype": "Item Attribute", "attribute_name": attribute, "item_attribute_values": []}).insert(ignore_permissions=True)
        adoc = frappe.get_doc("Item Attribute", attribute)
        existing = [v.attribute_value.strip().upper() for v in adoc.item_attribute_values]
        abbrs = [v.abbr.upper() for v in adoc.item_attribute_values]
        added = False
        for value in values:
            value = (value or "").strip()
            if not value or value.upper() in existing:
                continue
            abbr = "".join([ch for ch in value.upper() if ch.isalnum()])[:10] or value[:10]
            base = abbr
            n = 1
            while abbr in abbrs:
                n = n + 1
                abbr = "%s%s" % (base[:8], n)
            adoc.append("item_attribute_values", {"attribute_value": value, "abbr": abbr})
            existing.append(value.upper())
            abbrs.append(abbr)
            added = True
        if added:
            adoc.flags.ignore_permissions = True
            adoc.save()


    def canonical_attribute_value(attribute, value):
        """The attribute's own spelling of `value`, adding the value when it is new. ERPNext compares the exact text when it makes a variant, so 'BLACK' is
        refused where the attribute says 'Black'."""
        ensure_attribute_values(attribute, [value])
        want = (value or "").strip().upper()
        for v in frappe.get_all("Item Attribute Value", filters={"parent": attribute, "parenttype": "Item Attribute"}, pluck="attribute_value"):
            if (v or "").strip().upper() == want:
                return v
        return (value or "").strip()


    def ensure_uom(name):
        if not frappe.db.exists("UOM", name):
            frappe.get_doc({"doctype": "UOM", "uom_name": name}).insert(ignore_permissions=True)


    def material_item_group():
        for g in ("Raw Material", "Raw Materials"):
            if frappe.db.exists("Item Group", g):
                return g
        return frappe.db.get_single_value("Apparel Settings", "style_item_group") or frappe.db.get_value("Item Group", {"is_group": 0}, "name")


    def add_uom_rows(item_doc, gsm, width_cm):
        """Yard always (1 yd = 0.9144 m); Kg when GSM and width are known (1 kg = 1000 / (gsm x width_m) m)."""
        have = [u.uom for u in item_doc.get("uoms") or []]
        if "Yard" not in have:
            ensure_uom("Yard")
            item_doc.append("uoms", {"uom": "Yard", "conversion_factor": YARD_M})
        if frappe.utils.flt(gsm) and frappe.utils.flt(width_cm) and "Kg" not in have:
            ensure_uom("Kg")
            item_doc.append("uoms", {"uom": "Kg", "conversion_factor": round(1000 / (frappe.utils.flt(gsm) * frappe.utils.flt(width_cm) / 100), 6)})


    def ensure_fabric_item(quality_code, colour, description, gsm, width_cm):
        """Template `quality_code` (stock UOM Meter, batch tracked, Colour attribute) and its colour variant; returns the variant item code. Safe to call again."""
        quality_code = (quality_code or "").strip()
        if not quality_code:
            frappe.throw("Enter the fabric quality code.")
        attr = frappe.db.get_single_value("Apparel Settings", "colour_attribute") or "Colour"
        colour = canonical_attribute_value(attr, colour)
        ensure_uom("Meter")
        if not frappe.db.exists("Item", quality_code):
            tpl = frappe.get_doc({"doctype": "Item", "item_code": quality_code, "item_name": quality_code, "item_group": material_item_group(), "stock_uom": "Meter",
                                  "is_stock_item": 1, "is_purchase_item": 1, "is_sales_item": 0, "has_batch_no": 1, "has_variants": 1, "variant_based_on": "Item Attribute",
                                  "attributes": [{"attribute": attr}], "description": description or quality_code, "apparel_material_type": "Fabric",
                                  "apparel_fabric_gsm": gsm, "apparel_fabric_width_cm": width_cm})
            add_uom_rows(tpl, gsm, width_cm)
            tpl.flags.ignore_permissions = True
            tpl.insert()
        elif not frappe.db.get_value("Item", quality_code, "has_variants"):
            return quality_code   # a plain (non-variant) fabric item is used as it is
        args = {attr: colour}
        code = frappe.call("erpnext.controllers.item_variant.get_variant", template=quality_code, args=args)
        if not code:
            variant = frappe.call("erpnext.controllers.item_variant.create_variant", item=quality_code, args=args)
            variant.update({"has_batch_no": 1, "apparel_material_type": "Fabric", "apparel_fabric_gsm": gsm, "apparel_fabric_width_cm": width_cm})
            add_uom_rows(variant, gsm, width_cm)
            variant.flags.ignore_permissions = True
            variant.insert()
            code = variant.name
        return code


    def ensure_trim_item(item_code, description, trim_category, uom, customer, buyer_code, customer_provided):
        """A plain stock item per trim code. The buyer code goes on Item Customer Detail."""
        ensure_uom(uom)
        if frappe.db.exists("Item", item_code):
            return item_code
        item = frappe.get_doc({"doctype": "Item", "item_code": item_code, "item_name": description or item_code, "item_group": material_item_group(), "stock_uom": uom,
                               "is_stock_item": 1, "is_purchase_item": 0 if customer_provided else 1, "is_sales_item": 0,
                               "is_customer_provided_item": 1 if customer_provided else 0, "customer": customer if customer_provided else None,
                               "description": description or item_code, "apparel_material_type": "Trim", "apparel_trim_category": trim_category})
        if customer and buyer_code:
            item.append("customer_items", {"customer_name": customer, "ref_code": buyer_code})
        item.flags.ignore_permissions = True
        item.insert()
        return item.name
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    items = list(d.get("items") or [])
    made = []
    for r in items:
        if r.get("trim_item"):
            continue
        raw = (r.get("buyer_item_code") or r.get("description") or "").strip()
        code = ""
        dash = False
        for ch in raw:
            if ch.isalnum() and ch.isascii():
                code = code + ch
                dash = False
            elif not dash:
                code = code + "-"
                dash = True
        code = code.strip("-").upper()[:60]
        if not code:
            frappe.throw("Row %s: enter a buyer item code or a description first." % r.get("idx"))
        uom = r.get("consumption_uom") if r.get("calc_basis") == "By Length" and r.get("consumption_uom") else "Nos"
        r["trim_item"] = ensure_trim_item("TRIM-" + code, r.get("description"), r.get("trim_category"), uom, d.get("customer"), r.get("buyer_item_code"),
                                         frappe.utils.cint(r.get("customer_provided")))
        made.append(r["trim_item"])
    frappe.flags.arinox_result = {"arinox_doc": {"items": items}, "made": made}


main()

# API arinox_fabric_requisition_get_requisition_context: everything an agent needs to draft the FR and TR for an order.
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers: the Sales Order at the order grain, rolled up to style x colour, and the tolerance cap (factory_allocation.py)
    def norm(colour):
        return (colour or "").strip().upper()


    def get_order_lines(sales_order):
        """Sales Order grouped to (style, colour, ship-to, buyer PO) -> qty, tolerance %, earliest ex-factory date. A dict of dicts, in order of appearance."""
        lines = {}
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order},
                                 fields=["item_code", "qty", "apparel_colour", "apparel_ship_to", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            key = (style, norm(it.apparel_colour), norm(it.apparel_ship_to), norm(it.apparel_buyer_po))
            row = lines.get(key)
            if not row:
                row = {"style_item": style, "colour": (it.apparel_colour or "").strip(), "ship_to": (it.apparel_ship_to or "").strip(),
                       "buyer_po": (it.apparel_buyer_po or "").strip(), "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                lines[key] = row
            row["qty"] = row["qty"] + frappe.utils.cint(it.qty)
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not row["ex_factory_date"] or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = it.delivery_date
        return lines


    def colour_level(order):
        """The order lines rolled up to (style, colour)."""
        out = {}
        for key in order:
            o = order[key]
            ckey = (key[0], key[1])
            row = out.get(ckey)
            if not row:
                row = {"style_item": key[0], "colour": o["colour"], "qty": 0, "tolerance_pct": 0, "ex_factory_date": None}
                out[ckey] = row
            row["qty"] = row["qty"] + o["qty"]
            row["tolerance_pct"] = max(frappe.utils.flt(row["tolerance_pct"]), frappe.utils.flt(o["tolerance_pct"]))
            if o["ex_factory_date"] and (not row["ex_factory_date"] or frappe.utils.getdate(o["ex_factory_date"]) < frappe.utils.getdate(row["ex_factory_date"])):
                row["ex_factory_date"] = o["ex_factory_date"]
        return out


    def cap_of(qty, tolerance_pct):
        return int(qty * (1 + frappe.utils.flt(tolerance_pct) / 100))
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    sales_order = frappe.form_dict.get("sales_order")
    so = frappe.get_doc("Sales Order", sales_order)
    so.check_permission("read")
    styles = {}
    cl = colour_level(get_order_lines(sales_order))
    for key in cl:
        style = key[0]
        o = cl[key]
        tp = tech_pack_for(style)
        cs = cost_sheet_for(sales_order, style)
        d = get_style_dates(sales_order, style, o["colour"])
        if "s|" + style not in styles:
            styles["s|" + style] = {"style_item": style, "tech_pack": tp.name if tp else None, "cost_sheet": cs.name if cs else None, "colours": []}
        st = styles["s|" + style]
        st["colours"].append({"colour": o["colour"], "qty": frappe.utils.cint(o["qty"]), "pcd": str(d[0]) if d[0] else None, "ex_factory": str(d[1]) if d[1] else None,
                              "lab_dip": approval_info(sales_order, style, "Lab Dip", o["colour"], so.customer)[0], "bulk_trim": approval_info(sales_order, style, "Bulk Trim", None, so.customer)[0]})
        if tp and "materials" not in st:
            st["materials"] = [m.as_dict() for m in tp.materials]
    frappe.flags.arinox_result = {"sales_order": sales_order, "customer": so.customer, "company": so.company, "styles": [styles[s] for s in styles],
                                  "allowance_rules": frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["material_type", "trim_category", "customer", "allowance_pct", "pack_size"]),
                                  "fr_material_types": fr_material_types()}


main()

# Purchase Order, Before Save: link back to the requisition (copied from the Material Request row), supplier terms, the approval-hold override, ETD dates, warnings.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers of the Purchase Order hooks (overrides/purchase_order.py): the requisition row behind a PO row, approval-hold messages, cost warnings. Needs lib_samples.py, lib_mat.py.
    COPY_FIELDS = ("apparel_requisition_type", "apparel_requisition", "apparel_requisition_item", "apparel_style_no", "apparel_colour", "apparel_hold_reason")


    def my_roles():
        return (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))


    def is_manager():
        return bool([r for r in my_roles() if r in MANAGER_ROLES])


    def requisition_row(poi):
        """The FR / TR row behind a PO row (or None)."""
        if not poi.get("apparel_requisition"):
            return None
        dt = "Fabric Requisition Item" if poi.apparel_requisition_type == "FR" else "Trim Requisition Item"
        wording = "fabric_description" if poi.apparel_requisition_type == "FR" else "description"
        return frappe.db.get_value(dt, {"parent": poi.apparel_requisition, "material_request_item": poi.get("material_request_item")}, ["sales_order", "style_item", "colour", wording], as_dict=True)


    def hold_blockers(doc):
        """Messages for rows whose lab dip (FR) or trim approval (TR) is still missing, re-checked now."""
        out = []
        for poi in doc.items:
            if not poi.get("apparel_hold_reason"):
                continue
            r = requisition_row(poi)
            if not r:
                continue
            if poi.apparel_requisition_type == "FR":
                stype = "Lab Dip"
                colour = r.colour
            else:
                stype = "Bulk Trim"
                colour = None
            ap = approval_info(r.sales_order, r.style_item, stype, colour, frappe.db.get_value("Sales Order", r.sales_order, "customer"))
            if not ap[1]:
                out.append("Row %s (%s): %s is %s." % (poi.idx, poi.item_code, stype, ap[0]))
        return out


    def cost_warnings(doc):
        """PO rate against the Cost Sheet material rate (the line is found through the requisition row; yard/metre and the costing currency are converted)."""
        flt = frappe.utils.flt
        limit = flt(frappe.db.get_single_value("Apparel Settings", "cost_overrun_warn_pct") or 5)
        out = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r or not flt(poi.rate):
                continue
            cs = cost_sheet_for(r.sales_order, r.style_item)
            if not cs:
                continue
            names = [(poi.item_name or "").strip().lower(), (r.get("fabric_description") or r.get("description") or "").strip().lower()]
            for cm in cs.materials:
                if not (cm.item and cm.item == poi.item_code) and (cm.description or "").strip().lower() not in names:
                    continue
                cost_rate = flt(cm.rate)
                if not cost_rate:
                    break
                # bring the costed rate to the PO's currency and unit: the costing may be in RMB per yard and the PO in USD per metre
                if (cm.price_currency or cs.currency) != doc.currency:
                    if doc.currency == cs.currency and flt(cm.exchange_rate):
                        cost_rate = cost_rate * flt(cm.exchange_rate)
                    else:
                        break
                cost_unit = cm.rate_uom or cm.uom
                if cost_unit != poi.uom:
                    if cost_unit == "Yard" and poi.uom == "Meter":
                        cost_rate = cost_rate / 0.9144
                    elif cost_unit == "Meter" and poi.uom == "Yard":
                        cost_rate = cost_rate * 0.9144
                    else:
                        break
                if flt(poi.rate) > cost_rate * (1 + limit / 100):
                    out.append("Row %s: rate %s is more than %s%% above the costed %s." % (poi.idx, poi.rate, limit, flt(cost_rate, 4)))
                break
        return out


    def stamp_po(doc):
        """Booked / PI / ETD milestones for every style x colour on the order."""
        seen = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r:
                continue
            k = [r.sales_order, r.style_item, r.colour, poi.apparel_requisition_type]
            if k in seen:
                continue
            seen.append(k)
            so = k[0]
            style = k[1]
            colour = k[2]
            if k[3] == "FR":
                stamp_safe(so, style, colour, "FABRIC_BOOKED", frappe.utils.nowdate(), "Purchase Order", doc.name, False, False)
                if doc.get("apparel_mill_ready_date"):
                    stamp_safe(so, style, colour, "BULK_FABRIC_READY_MILL", doc.apparel_mill_ready_date, "Purchase Order", doc.name, False, False)
                if doc.get("apparel_etd_actual"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.apparel_etd_actual, "Purchase Order", doc.name, False, False)
                elif doc.get("apparel_etd_revised") or doc.get("apparel_etd_planned"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.get("apparel_etd_revised") or doc.apparel_etd_planned, "Purchase Order", doc.name, False, True)
            elif doc.get("apparel_pi_date"):
                stamp_safe(so, style, colour, "TRIM_PI", doc.apparel_pi_date, "Purchase Order", doc.name, False, False)
    cint = frappe.utils.cint
    getdate = frappe.utils.getdate
    for poi in doc.items:
        if poi.get("material_request_item") and not poi.get("apparel_requisition"):
            vals = frappe.db.get_value("Material Request Item", poi.material_request_item, list(COPY_FIELDS), as_dict=True) or {}
            for f in COPY_FIELDS:
                if vals.get(f):
                    poi.set(f, vals[f])
    if not doc.get("apparel_purchase_terms") and [p for p in doc.items if p.get("apparel_requisition")]:
        doc.apparel_purchase_terms = frappe.db.get_value("Supplier", doc.supplier, "apparel_purchase_terms") or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
    if cint(doc.get("apparel_approval_override")) and (doc.is_new() or doc.has_value_changed("apparel_approval_override")):
        if not is_manager():
            frappe.throw("Only an Apparel Merchandising Manager can override the approval hold.")
        if not (doc.get("apparel_approval_override_reason") or "").strip():
            frappe.throw("Enter the reason for overriding the approval hold.")
    plan = doc.get("apparel_etd_planned")
    eta = doc.get("apparel_eta")
    actual = doc.get("apparel_etd_actual")
    if plan and eta and getdate(plan) > getdate(eta):
        frappe.throw("ETD (plan) cannot be after the ETA.")
    if actual and getdate(actual) > getdate(frappe.utils.nowdate()):
        frappe.throw("ETD (actual) cannot be in the future.")
    for msg in hold_blockers(doc) + cost_warnings(doc):
        frappe.msgprint(msg, indicator="orange", title="Apparel check")


run(doc)

# Purchase Order, Before Submit: while a buyer approval is missing the order is held (when the setting says Block); a manager may override with a reason.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers of the Purchase Order hooks (overrides/purchase_order.py): the requisition row behind a PO row, approval-hold messages, cost warnings. Needs lib_samples.py, lib_mat.py.
    COPY_FIELDS = ("apparel_requisition_type", "apparel_requisition", "apparel_requisition_item", "apparel_style_no", "apparel_colour", "apparel_hold_reason")


    def my_roles():
        return (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))


    def is_manager():
        return bool([r for r in my_roles() if r in MANAGER_ROLES])


    def requisition_row(poi):
        """The FR / TR row behind a PO row (or None)."""
        if not poi.get("apparel_requisition"):
            return None
        dt = "Fabric Requisition Item" if poi.apparel_requisition_type == "FR" else "Trim Requisition Item"
        wording = "fabric_description" if poi.apparel_requisition_type == "FR" else "description"
        return frappe.db.get_value(dt, {"parent": poi.apparel_requisition, "material_request_item": poi.get("material_request_item")}, ["sales_order", "style_item", "colour", wording], as_dict=True)


    def hold_blockers(doc):
        """Messages for rows whose lab dip (FR) or trim approval (TR) is still missing, re-checked now."""
        out = []
        for poi in doc.items:
            if not poi.get("apparel_hold_reason"):
                continue
            r = requisition_row(poi)
            if not r:
                continue
            if poi.apparel_requisition_type == "FR":
                stype = "Lab Dip"
                colour = r.colour
            else:
                stype = "Bulk Trim"
                colour = None
            ap = approval_info(r.sales_order, r.style_item, stype, colour, frappe.db.get_value("Sales Order", r.sales_order, "customer"))
            if not ap[1]:
                out.append("Row %s (%s): %s is %s." % (poi.idx, poi.item_code, stype, ap[0]))
        return out


    def cost_warnings(doc):
        """PO rate against the Cost Sheet material rate (the line is found through the requisition row; yard/metre and the costing currency are converted)."""
        flt = frappe.utils.flt
        limit = flt(frappe.db.get_single_value("Apparel Settings", "cost_overrun_warn_pct") or 5)
        out = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r or not flt(poi.rate):
                continue
            cs = cost_sheet_for(r.sales_order, r.style_item)
            if not cs:
                continue
            names = [(poi.item_name or "").strip().lower(), (r.get("fabric_description") or r.get("description") or "").strip().lower()]
            for cm in cs.materials:
                if not (cm.item and cm.item == poi.item_code) and (cm.description or "").strip().lower() not in names:
                    continue
                cost_rate = flt(cm.rate)
                if not cost_rate:
                    break
                # bring the costed rate to the PO's currency and unit: the costing may be in RMB per yard and the PO in USD per metre
                if (cm.price_currency or cs.currency) != doc.currency:
                    if doc.currency == cs.currency and flt(cm.exchange_rate):
                        cost_rate = cost_rate * flt(cm.exchange_rate)
                    else:
                        break
                cost_unit = cm.rate_uom or cm.uom
                if cost_unit != poi.uom:
                    if cost_unit == "Yard" and poi.uom == "Meter":
                        cost_rate = cost_rate / 0.9144
                    elif cost_unit == "Meter" and poi.uom == "Yard":
                        cost_rate = cost_rate * 0.9144
                    else:
                        break
                if flt(poi.rate) > cost_rate * (1 + limit / 100):
                    out.append("Row %s: rate %s is more than %s%% above the costed %s." % (poi.idx, poi.rate, limit, flt(cost_rate, 4)))
                break
        return out


    def stamp_po(doc):
        """Booked / PI / ETD milestones for every style x colour on the order."""
        seen = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r:
                continue
            k = [r.sales_order, r.style_item, r.colour, poi.apparel_requisition_type]
            if k in seen:
                continue
            seen.append(k)
            so = k[0]
            style = k[1]
            colour = k[2]
            if k[3] == "FR":
                stamp_safe(so, style, colour, "FABRIC_BOOKED", frappe.utils.nowdate(), "Purchase Order", doc.name, False, False)
                if doc.get("apparel_mill_ready_date"):
                    stamp_safe(so, style, colour, "BULK_FABRIC_READY_MILL", doc.apparel_mill_ready_date, "Purchase Order", doc.name, False, False)
                if doc.get("apparel_etd_actual"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.apparel_etd_actual, "Purchase Order", doc.name, False, False)
                elif doc.get("apparel_etd_revised") or doc.get("apparel_etd_planned"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.get("apparel_etd_revised") or doc.apparel_etd_planned, "Purchase Order", doc.name, False, True)
            elif doc.get("apparel_pi_date"):
                stamp_safe(so, style, colour, "TRIM_PI", doc.apparel_pi_date, "Purchase Order", doc.name, False, False)
    mode = frappe.db.get_single_value("Apparel Settings", "hold_po_until_approval") or "Warn"
    blockers = hold_blockers(doc)
    if blockers and mode == "Block":
        if frappe.utils.cint(doc.get("apparel_approval_override")) and (doc.get("apparel_approval_override_reason") or "").strip() and is_manager():
            return
        frappe.throw("This order is on hold until the buyer approvals are in:<br>• " + "<br>• ".join(blockers), title="Approval hold")


run(doc)

# Purchase Order, After Submit / After Save (Submitted Document): the requisitions' ordered quantities and status are refreshed, and booked / PI / ETD are stamped.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers of the Purchase Order hooks (overrides/purchase_order.py): the requisition row behind a PO row, approval-hold messages, cost warnings. Needs lib_samples.py, lib_mat.py.
    COPY_FIELDS = ("apparel_requisition_type", "apparel_requisition", "apparel_requisition_item", "apparel_style_no", "apparel_colour", "apparel_hold_reason")


    def my_roles():
        return (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))


    def is_manager():
        return bool([r for r in my_roles() if r in MANAGER_ROLES])


    def requisition_row(poi):
        """The FR / TR row behind a PO row (or None)."""
        if not poi.get("apparel_requisition"):
            return None
        dt = "Fabric Requisition Item" if poi.apparel_requisition_type == "FR" else "Trim Requisition Item"
        wording = "fabric_description" if poi.apparel_requisition_type == "FR" else "description"
        return frappe.db.get_value(dt, {"parent": poi.apparel_requisition, "material_request_item": poi.get("material_request_item")}, ["sales_order", "style_item", "colour", wording], as_dict=True)


    def hold_blockers(doc):
        """Messages for rows whose lab dip (FR) or trim approval (TR) is still missing, re-checked now."""
        out = []
        for poi in doc.items:
            if not poi.get("apparel_hold_reason"):
                continue
            r = requisition_row(poi)
            if not r:
                continue
            if poi.apparel_requisition_type == "FR":
                stype = "Lab Dip"
                colour = r.colour
            else:
                stype = "Bulk Trim"
                colour = None
            ap = approval_info(r.sales_order, r.style_item, stype, colour, frappe.db.get_value("Sales Order", r.sales_order, "customer"))
            if not ap[1]:
                out.append("Row %s (%s): %s is %s." % (poi.idx, poi.item_code, stype, ap[0]))
        return out


    def cost_warnings(doc):
        """PO rate against the Cost Sheet material rate (the line is found through the requisition row; yard/metre and the costing currency are converted)."""
        flt = frappe.utils.flt
        limit = flt(frappe.db.get_single_value("Apparel Settings", "cost_overrun_warn_pct") or 5)
        out = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r or not flt(poi.rate):
                continue
            cs = cost_sheet_for(r.sales_order, r.style_item)
            if not cs:
                continue
            names = [(poi.item_name or "").strip().lower(), (r.get("fabric_description") or r.get("description") or "").strip().lower()]
            for cm in cs.materials:
                if not (cm.item and cm.item == poi.item_code) and (cm.description or "").strip().lower() not in names:
                    continue
                cost_rate = flt(cm.rate)
                if not cost_rate:
                    break
                # bring the costed rate to the PO's currency and unit: the costing may be in RMB per yard and the PO in USD per metre
                if (cm.price_currency or cs.currency) != doc.currency:
                    if doc.currency == cs.currency and flt(cm.exchange_rate):
                        cost_rate = cost_rate * flt(cm.exchange_rate)
                    else:
                        break
                cost_unit = cm.rate_uom or cm.uom
                if cost_unit != poi.uom:
                    if cost_unit == "Yard" and poi.uom == "Meter":
                        cost_rate = cost_rate / 0.9144
                    elif cost_unit == "Meter" and poi.uom == "Yard":
                        cost_rate = cost_rate * 0.9144
                    else:
                        break
                if flt(poi.rate) > cost_rate * (1 + limit / 100):
                    out.append("Row %s: rate %s is more than %s%% above the costed %s." % (poi.idx, poi.rate, limit, flt(cost_rate, 4)))
                break
        return out


    def stamp_po(doc):
        """Booked / PI / ETD milestones for every style x colour on the order."""
        seen = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r:
                continue
            k = [r.sales_order, r.style_item, r.colour, poi.apparel_requisition_type]
            if k in seen:
                continue
            seen.append(k)
            so = k[0]
            style = k[1]
            colour = k[2]
            if k[3] == "FR":
                stamp_safe(so, style, colour, "FABRIC_BOOKED", frappe.utils.nowdate(), "Purchase Order", doc.name, False, False)
                if doc.get("apparel_mill_ready_date"):
                    stamp_safe(so, style, colour, "BULK_FABRIC_READY_MILL", doc.apparel_mill_ready_date, "Purchase Order", doc.name, False, False)
                if doc.get("apparel_etd_actual"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.apparel_etd_actual, "Purchase Order", doc.name, False, False)
                elif doc.get("apparel_etd_revised") or doc.get("apparel_etd_planned"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.get("apparel_etd_revised") or doc.apparel_etd_planned, "Purchase Order", doc.name, False, True)
            elif doc.get("apparel_pi_date"):
                stamp_safe(so, style, colour, "TRIM_PI", doc.apparel_pi_date, "Purchase Order", doc.name, False, False)
    refresh_for_documents(doc)
    stamp_po(doc)


run(doc)

# Purchase Order, After Submit / After Save (Submitted Document): the requisitions' ordered quantities and status are refreshed, and booked / PI / ETD are stamped.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers of the Purchase Order hooks (overrides/purchase_order.py): the requisition row behind a PO row, approval-hold messages, cost warnings. Needs lib_samples.py, lib_mat.py.
    COPY_FIELDS = ("apparel_requisition_type", "apparel_requisition", "apparel_requisition_item", "apparel_style_no", "apparel_colour", "apparel_hold_reason")


    def my_roles():
        return (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))


    def is_manager():
        return bool([r for r in my_roles() if r in MANAGER_ROLES])


    def requisition_row(poi):
        """The FR / TR row behind a PO row (or None)."""
        if not poi.get("apparel_requisition"):
            return None
        dt = "Fabric Requisition Item" if poi.apparel_requisition_type == "FR" else "Trim Requisition Item"
        wording = "fabric_description" if poi.apparel_requisition_type == "FR" else "description"
        return frappe.db.get_value(dt, {"parent": poi.apparel_requisition, "material_request_item": poi.get("material_request_item")}, ["sales_order", "style_item", "colour", wording], as_dict=True)


    def hold_blockers(doc):
        """Messages for rows whose lab dip (FR) or trim approval (TR) is still missing, re-checked now."""
        out = []
        for poi in doc.items:
            if not poi.get("apparel_hold_reason"):
                continue
            r = requisition_row(poi)
            if not r:
                continue
            if poi.apparel_requisition_type == "FR":
                stype = "Lab Dip"
                colour = r.colour
            else:
                stype = "Bulk Trim"
                colour = None
            ap = approval_info(r.sales_order, r.style_item, stype, colour, frappe.db.get_value("Sales Order", r.sales_order, "customer"))
            if not ap[1]:
                out.append("Row %s (%s): %s is %s." % (poi.idx, poi.item_code, stype, ap[0]))
        return out


    def cost_warnings(doc):
        """PO rate against the Cost Sheet material rate (the line is found through the requisition row; yard/metre and the costing currency are converted)."""
        flt = frappe.utils.flt
        limit = flt(frappe.db.get_single_value("Apparel Settings", "cost_overrun_warn_pct") or 5)
        out = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r or not flt(poi.rate):
                continue
            cs = cost_sheet_for(r.sales_order, r.style_item)
            if not cs:
                continue
            names = [(poi.item_name or "").strip().lower(), (r.get("fabric_description") or r.get("description") or "").strip().lower()]
            for cm in cs.materials:
                if not (cm.item and cm.item == poi.item_code) and (cm.description or "").strip().lower() not in names:
                    continue
                cost_rate = flt(cm.rate)
                if not cost_rate:
                    break
                # bring the costed rate to the PO's currency and unit: the costing may be in RMB per yard and the PO in USD per metre
                if (cm.price_currency or cs.currency) != doc.currency:
                    if doc.currency == cs.currency and flt(cm.exchange_rate):
                        cost_rate = cost_rate * flt(cm.exchange_rate)
                    else:
                        break
                cost_unit = cm.rate_uom or cm.uom
                if cost_unit != poi.uom:
                    if cost_unit == "Yard" and poi.uom == "Meter":
                        cost_rate = cost_rate / 0.9144
                    elif cost_unit == "Meter" and poi.uom == "Yard":
                        cost_rate = cost_rate * 0.9144
                    else:
                        break
                if flt(poi.rate) > cost_rate * (1 + limit / 100):
                    out.append("Row %s: rate %s is more than %s%% above the costed %s." % (poi.idx, poi.rate, limit, flt(cost_rate, 4)))
                break
        return out


    def stamp_po(doc):
        """Booked / PI / ETD milestones for every style x colour on the order."""
        seen = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r:
                continue
            k = [r.sales_order, r.style_item, r.colour, poi.apparel_requisition_type]
            if k in seen:
                continue
            seen.append(k)
            so = k[0]
            style = k[1]
            colour = k[2]
            if k[3] == "FR":
                stamp_safe(so, style, colour, "FABRIC_BOOKED", frappe.utils.nowdate(), "Purchase Order", doc.name, False, False)
                if doc.get("apparel_mill_ready_date"):
                    stamp_safe(so, style, colour, "BULK_FABRIC_READY_MILL", doc.apparel_mill_ready_date, "Purchase Order", doc.name, False, False)
                if doc.get("apparel_etd_actual"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.apparel_etd_actual, "Purchase Order", doc.name, False, False)
                elif doc.get("apparel_etd_revised") or doc.get("apparel_etd_planned"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.get("apparel_etd_revised") or doc.apparel_etd_planned, "Purchase Order", doc.name, False, True)
            elif doc.get("apparel_pi_date"):
                stamp_safe(so, style, colour, "TRIM_PI", doc.apparel_pi_date, "Purchase Order", doc.name, False, False)
    refresh_for_documents(doc)
    stamp_po(doc)


run(doc)

# Purchase Order, After Cancel: the requisitions are refreshed and the stamps cleared.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    refresh_for_documents(doc)
    unstamp_safe("Purchase Order", doc.name)


run(doc)

# API arinox_fabric_requisition_refresh_quantities: recompute ordered, received, accepted and rejected quantities and the status of one approved requisition
# (requisition_type FR or TR, name). The tower runs the after-submit rules of an inspection on a read of the ERP made before that submit, so the
# quantities a rule computes from the submitted inspections are stale; this runs afterwards, when the inspection is in the database.
def main():
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    requisition_type = frappe.form_dict.get("requisition_type")
    name = frappe.form_dict.get("name")
    dt = "Fabric Requisition" if requisition_type == "FR" else "Trim Requisition"
    if not frappe.db.exists(dt, name):
        frappe.throw("%s %s does not exist." % (dt, name))
    frappe.get_doc(dt, name).check_permission("write")
    doc = refresh_requisition(requisition_type, name)
    if not doc:
        frappe.throw("Only an approved requisition has quantities to refresh.")
    frappe.flags.arinox_result = {"name": doc.name, "status": doc.status, "lines": [{"accepted": r.accepted_qty, "received": r.received_qty, "ordered": r.ordered_qty, "rejected": r.rejected_qty} for r in doc.items]}


main()

# Purchase Receipt, Before Save: goods from a requisition are received into the inspection warehouse; the received quantity is checked against the order's quantity band.
def run(doc):
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    flt = frappe.utils.flt
    notes = []
    for pri in doc.items:
        if not pri.get("purchase_order_item"):
            continue
        poi = frappe.db.get_value("Purchase Order Item", pri.purchase_order_item,
                                  ["name", "parent", "stock_qty", "schedule_date", "conversion_factor", "apparel_requisition", "apparel_requisition_type", "qty"], as_dict=True)
        if not poi or not poi.apparel_requisition:
            continue
        kind = "Fabric" if poi.apparel_requisition_type == "FR" else "Trim"
        if not pri.warehouse:
            pri.warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier", "status"], as_dict=True)
        terms = terms_for(po.apparel_purchase_terms, po.supplier)
        if not terms:
            continue
        ordered = flt(poi.stock_qty)
        already = flt(frappe.db.get_value("Purchase Order Item", poi.name, "received_qty")) * flt(poi.conversion_factor)
        this = flt(pri.stock_qty) if pri.get("stock_qty") else flt(pri.qty) * (flt(pri.conversion_factor) or 1)
        cumulative = already + this
        tol = qty_tolerance(terms, ordered)
        upper = ordered * (1 + tol / 100)
        lower = ordered * (1 - tol / 100)
        if cumulative > upper + 0.0005:
            excess = flt(cumulative - upper, 2)
            if terms.extra_qty_policy == "Reject":
                frappe.throw("Row %s: %s received against %s ordered is over the +%s%% band by %s." % (pri.idx, flt(cumulative, 2), flt(ordered, 2), tol, excess))
            note = "Row %s: %s over the +%s%% band." % (pri.idx, excess, tol)
            if terms.extra_qty_policy == "Accept Unpaid":
                note = note + " The excess must not be invoiced."
            notes.append(note)
        if po.status == "Closed" and cumulative < lower - 0.0005:
            notes.append("Row %s: short by %s against the order (below the -%s%% band)." % (pri.idx, flt(lower - cumulative, 2), tol))
    doc.apparel_qty_band_note = "\n".join(notes) if notes else None


run(doc)

# Purchase Receipt, Before Submit: a fabric row from an FR needs its roll list; each fabric roll is tracked.
def run(doc):
    for pri in doc.items:
        if not pri.get("purchase_order_item"):
            continue
        kind = frappe.db.get_value("Purchase Order Item", pri.purchase_order_item, "apparel_requisition_type")
        if kind == "FR" and frappe.db.get_value("Item", pri.item_code, "has_batch_no") and not (pri.get("serial_and_batch_bundle") or pri.get("batch_no")):
            frappe.throw("Row %s (%s): import the roll list before submitting. Each fabric roll is tracked." % (pri.idx, pri.item_code))


run(doc)

# Purchase Receipt, After Submit: late delivery under the PO terms is stored (days, penalty %, amount; no accounting entry), then the requisitions are refreshed and
# FABRIC_IN_HOUSE / TRIMS_IN_HOUSE stamped (in progress until everything is received).
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    flt = frappe.utils.flt
    getdate = frappe.utils.getdate
    worst = 0
    terms_doc = None
    value = 0.0
    rows = []
    for pri in doc.items:
        if not pri.get("purchase_order_item"):
            continue
        poi = frappe.db.get_value("Purchase Order Item", pri.purchase_order_item, ["name", "parent", "schedule_date", "apparel_requisition", "apparel_requisition_type"], as_dict=True)
        if poi and poi.apparel_requisition:
            rows.append([pri, poi])
    for pr in rows:
        pri = pr[0]
        poi = pr[1]
        po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier", "apparel_etd_actual"], as_dict=True)
        terms = terms_for(po.apparel_purchase_terms, po.supplier)
        arrival = po.apparel_etd_actual or doc.posting_date
        days = frappe.utils.date_diff(getdate(arrival), getdate(poi.schedule_date)) if poi.schedule_date else 0
        if days > worst:
            worst = days
            terms_doc = terms
        if days > 0:
            value = value + flt(pri.net_amount)
    if rows:
        pen = delay_penalty(terms_doc, worst)
        doc.db_set({"apparel_delay_days": max(worst, 0), "apparel_penalty_pct": pen[0], "apparel_penalty_amount": flt(value * pen[0] / 100, 2)}, update_modified=False)
        if pen[1] == "Cancel or Discount" and pen[0]:
            doc.db_set("apparel_qty_band_note", ((doc.apparel_qty_band_note or "") + "\n" + "Delay of %s days: the order may be cancelled or discounted %s%%." % (worst, pen[0])).strip(), update_modified=False)
    seen = []
    for pr in rows:
        t = pr[1].apparel_requisition_type
        n = pr[1].apparel_requisition
        if [t, n] in seen:
            continue
        seen.append([t, n])
        req = refresh_requisition(t, n)
        if not req:
            continue
        code = "FABRIC_IN_HOUSE" if t == "FR" else "TRIMS_IN_HOUSE"
        done = req.status == "Received"
        keys = []
        for r in req.items:
            k = [r.sales_order, r.style_item, (r.colour or "").strip()]
            if k in keys or flt(r.received_qty) <= 0:
                continue
            keys.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour or None, code, frappe.utils.nowdate(), "Purchase Receipt", req.name, not done, False)


run(doc)

# Purchase Receipt, After Cancel: the requisitions are refreshed again and the stamps cleared.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    seen = []
    for pri in doc.items:
        if not pri.get("purchase_order_item"):
            continue
        poi = frappe.db.get_value("Purchase Order Item", pri.purchase_order_item, ["apparel_requisition", "apparel_requisition_type"], as_dict=True)
        if poi and poi.apparel_requisition and [poi.apparel_requisition_type, poi.apparel_requisition] not in seen:
            seen.append([poi.apparel_requisition_type, poi.apparel_requisition])
            refresh_requisition(poi.apparel_requisition_type, poi.apparel_requisition)
    unstamp_safe("Purchase Receipt", doc.name)


run(doc)

# API arinox_rolls_import_roll_list: a Batch per roll and the bundle for one row of a draft Purchase Receipt. `rolls` is a JSON list or pasted text
# ('roll no, dye lot, length[, width]' per line). The roll total must equal the row quantity unless update_row_qty is set.
def main():
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    flt = frappe.utils.flt
    f = frappe.form_dict
    pr = frappe.get_doc("Purchase Receipt", f.get("pr_name"))
    pr.check_permission("write")
    if pr.docstatus != 0:
        frappe.throw("Roll lists can only be imported into a draft receipt.")
    row_name = f.get("row_name")
    row = None
    for r in pr.items:
        if r.name == row_name:
            row = r
    if not row:
        frappe.throw("Row not found on %s." % pr.name)
    if not frappe.db.get_value("Item", row.item_code, "has_batch_no"):
        frappe.throw("%s is not batch tracked, so it has no rolls." % row.item_code)
    rolls = f.get("rolls")
    if isinstance(rolls, str):
        try:
            rolls = json.loads(rolls)
        except Exception:
            parsed = []
            for line in rolls.splitlines():
                s = line.strip().replace("\t", ",").replace(";", ",")
                parts = [p.strip() for p in s.split(",") if p.strip()]
                if len(parts) < 3:
                    s2 = s
                    while "  " in s2:
                        s2 = s2.replace("  ", ",")
                    parts = [p.strip() for p in s2.split(",") if p.strip()]
                if len(parts) < 3:
                    continue
                try:
                    length = float(parts[2])
                except Exception:
                    continue
                width = None
                if len(parts) > 3:
                    try:
                        width = float(parts[3])
                    except Exception:
                        width = None
                parsed.append({"roll_no": parts[0], "dye_lot": parts[1], "length": length, "width_cm": width})
            rolls = parsed
    clean = []
    seen = []
    for r in rolls:
        roll_no = str(r.get("roll_no") or "").strip()
        if not roll_no:
            frappe.throw("Every roll needs a roll number.")
        if roll_no.upper() in seen:
            frappe.throw("Roll number %s appears twice in the list." % roll_no)
        seen.append(roll_no.upper())
        length = flt(r.get("length"))
        if length <= 0:
            frappe.throw("Roll %s: the length must be more than zero." % roll_no)
        clean.append({"roll_no": roll_no, "dye_lot": (r.get("dye_lot") or "").strip(), "length": length, "width_cm": flt(r.get("width_cm")) or None})
    if not clean:
        frappe.throw("The roll list is empty.")
    stock_uom = frappe.db.get_value("Item", row.item_code, "stock_uom")
    gsm = frappe.db.get_value("Item", row.item_code, "apparel_fabric_gsm")
    length_uom = f.get("length_uom") or "Meter"
    total = 0
    for r in clean:
        r["metres"] = to_metres(r["length"], length_uom, gsm, r["width_cm"] or frappe.db.get_value("Item", row.item_code, "apparel_fabric_width_cm"))
        total = total + r["metres"]
    stock_qty = flt(row.stock_qty) or flt(row.qty) * (flt(row.conversion_factor) or 1)
    if abs(total - stock_qty) > max(0.005 * stock_qty, 0.01):
        if not frappe.utils.cint(f.get("update_row_qty")):
            frappe.throw("The roll list adds up to %s %s but the receipt row says %s. Fix the list, or change the row quantity." % (flt(total, 2), stock_uom, flt(stock_qty, 2)))
        row.qty = total / (flt(row.conversion_factor) or 1)
        row.received_qty = row.qty + flt(row.rejected_qty)
        pr.save()
        for r in pr.items:
            if r.name == row_name:
                row = r
    # a re-import replaces the draft bundle and the batches this receipt made
    old_bundle = row.get("serial_and_batch_bundle")
    if old_bundle:
        old = frappe.get_doc("Serial and Batch Bundle", old_bundle)
        if old.docstatus != 0:
            frappe.throw("Row %s already has a submitted roll bundle." % row.idx)
        old_batches = [e.batch_no for e in old.entries if e.batch_no]
        row.db_set({"serial_and_batch_bundle": None, "use_serial_batch_fields": 0})
        frappe.delete_doc("Serial and Batch Bundle", old_bundle, ignore_permissions=True, force=True)
        for b in old_batches:
            if frappe.db.exists("Batch", b) and frappe.db.get_value("Batch", b, "reference_name") == pr.name:
                frappe.delete_doc("Batch", b, ignore_permissions=True, force=True)
    entries = []
    for r in clean:
        bid = ("%s-%s" % (pr.name, r["roll_no"]))[:140]
        if frappe.db.exists("Batch", bid):
            frappe.throw("Batch %s already exists. Roll numbers must be unique within a receipt." % bid)
        b = frappe.get_doc({"doctype": "Batch", "batch_id": bid, "item": row.item_code, "supplier": pr.supplier, "reference_doctype": "Purchase Receipt", "reference_name": pr.name,
                            "apparel_roll_no": r["roll_no"], "apparel_dye_lot": r["dye_lot"], "apparel_ticket_length": r["metres"], "apparel_width_cm": r["width_cm"],
                            "apparel_inspection_status": "Uninspected"})
        b.flags.ignore_permissions = True
        b.insert()
        entries.append({"batch_no": b.name, "qty": flt(r["metres"], 6), "warehouse": row.warehouse})
    bundle = frappe.get_doc({"doctype": "Serial and Batch Bundle", "item_code": row.item_code, "warehouse": row.warehouse, "type_of_transaction": "Inward",
                             "voucher_type": "Purchase Receipt", "voucher_no": pr.name, "voucher_detail_no": row.name, "company": pr.company, "posting_date": pr.posting_date,
                             "posting_time": pr.posting_time, "has_batch_no": 1, "entries": entries})
    bundle.flags.ignore_permissions = True
    bundle.insert()
    row.db_set({"serial_and_batch_bundle": bundle.name, "use_serial_batch_fields": 0, "batch_no": None})
    frappe.flags.arinox_result = {"rolls": len(entries), "total": flt(total, 2), "bundle": bundle.name}


main()

# Fabric Inspection, Before Save: the receipt row, the rolls, defects -> points (4-point system), per-roll result, shrinkage, and the lot decision (sampling, average points, rejected rolls).
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers of the Purchase Order hooks (overrides/purchase_order.py): the requisition row behind a PO row, approval-hold messages, cost warnings. Needs lib_samples.py, lib_mat.py.
    COPY_FIELDS = ("apparel_requisition_type", "apparel_requisition", "apparel_requisition_item", "apparel_style_no", "apparel_colour", "apparel_hold_reason")


    def my_roles():
        return (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))


    def is_manager():
        return bool([r for r in my_roles() if r in MANAGER_ROLES])


    def requisition_row(poi):
        """The FR / TR row behind a PO row (or None)."""
        if not poi.get("apparel_requisition"):
            return None
        dt = "Fabric Requisition Item" if poi.apparel_requisition_type == "FR" else "Trim Requisition Item"
        wording = "fabric_description" if poi.apparel_requisition_type == "FR" else "description"
        return frappe.db.get_value(dt, {"parent": poi.apparel_requisition, "material_request_item": poi.get("material_request_item")}, ["sales_order", "style_item", "colour", wording], as_dict=True)


    def hold_blockers(doc):
        """Messages for rows whose lab dip (FR) or trim approval (TR) is still missing, re-checked now."""
        out = []
        for poi in doc.items:
            if not poi.get("apparel_hold_reason"):
                continue
            r = requisition_row(poi)
            if not r:
                continue
            if poi.apparel_requisition_type == "FR":
                stype = "Lab Dip"
                colour = r.colour
            else:
                stype = "Bulk Trim"
                colour = None
            ap = approval_info(r.sales_order, r.style_item, stype, colour, frappe.db.get_value("Sales Order", r.sales_order, "customer"))
            if not ap[1]:
                out.append("Row %s (%s): %s is %s." % (poi.idx, poi.item_code, stype, ap[0]))
        return out


    def cost_warnings(doc):
        """PO rate against the Cost Sheet material rate (the line is found through the requisition row; yard/metre and the costing currency are converted)."""
        flt = frappe.utils.flt
        limit = flt(frappe.db.get_single_value("Apparel Settings", "cost_overrun_warn_pct") or 5)
        out = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r or not flt(poi.rate):
                continue
            cs = cost_sheet_for(r.sales_order, r.style_item)
            if not cs:
                continue
            names = [(poi.item_name or "").strip().lower(), (r.get("fabric_description") or r.get("description") or "").strip().lower()]
            for cm in cs.materials:
                if not (cm.item and cm.item == poi.item_code) and (cm.description or "").strip().lower() not in names:
                    continue
                cost_rate = flt(cm.rate)
                if not cost_rate:
                    break
                # bring the costed rate to the PO's currency and unit: the costing may be in RMB per yard and the PO in USD per metre
                if (cm.price_currency or cs.currency) != doc.currency:
                    if doc.currency == cs.currency and flt(cm.exchange_rate):
                        cost_rate = cost_rate * flt(cm.exchange_rate)
                    else:
                        break
                cost_unit = cm.rate_uom or cm.uom
                if cost_unit != poi.uom:
                    if cost_unit == "Yard" and poi.uom == "Meter":
                        cost_rate = cost_rate / 0.9144
                    elif cost_unit == "Meter" and poi.uom == "Yard":
                        cost_rate = cost_rate * 0.9144
                    else:
                        break
                if flt(poi.rate) > cost_rate * (1 + limit / 100):
                    out.append("Row %s: rate %s is more than %s%% above the costed %s." % (poi.idx, poi.rate, limit, flt(cost_rate, 4)))
                break
        return out


    def stamp_po(doc):
        """Booked / PI / ETD milestones for every style x colour on the order."""
        seen = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r:
                continue
            k = [r.sales_order, r.style_item, r.colour, poi.apparel_requisition_type]
            if k in seen:
                continue
            seen.append(k)
            so = k[0]
            style = k[1]
            colour = k[2]
            if k[3] == "FR":
                stamp_safe(so, style, colour, "FABRIC_BOOKED", frappe.utils.nowdate(), "Purchase Order", doc.name, False, False)
                if doc.get("apparel_mill_ready_date"):
                    stamp_safe(so, style, colour, "BULK_FABRIC_READY_MILL", doc.apparel_mill_ready_date, "Purchase Order", doc.name, False, False)
                if doc.get("apparel_etd_actual"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.apparel_etd_actual, "Purchase Order", doc.name, False, False)
                elif doc.get("apparel_etd_revised") or doc.get("apparel_etd_planned"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.get("apparel_etd_revised") or doc.apparel_etd_planned, "Purchase Order", doc.name, False, True)
            elif doc.get("apparel_pi_date"):
                stamp_safe(so, style, colour, "TRIM_PI", doc.apparel_pi_date, "Purchase Order", doc.name, False, False)
    # shared helpers from materials/inspection.py: the 4-point fabric system, sampling, lot decision, trim AQL, and the steps both inspections share (receipt context,
    # Quality Inspection, Stock Entry). Needs lib_mat.py and lib_purchasing.py.
    def defect_points(length_in, always_four):
        """Points for one defect by its length in inches: up to 3 = 1, over 3 to 6 = 2, over 6 to 9 = 3, over 9 = 4. Holes (and any code marked 'always 4') take 4 points."""
        if always_four:
            return 4
        n = frappe.utils.flt(length_in)
        if n <= 3:
            return 1
        if n <= 6:
            return 2
        if n <= 9:
            return 3
        return 4


    def roll_points(defects):
        """Total points of one roll. `defects` = list of [yard_position, points]. No more than 4 points count in one yard; a defect with no yard number counts on its own."""
        by_yard = {}
        loose = 0
        for d in defects:
            if d[0] in (None, "", 0):
                loose = loose + d[1]
            else:
                by_yard[d[0]] = by_yard.get(d[0], 0) + d[1]
        return loose + sum([min(by_yard[y], 4) for y in by_yard])


    def points_per_100_linear(total_points, inspected_m):
        yards = frappe.utils.flt(inspected_m) / YARD_M
        return frappe.utils.flt(total_points) * 100 / yards if yards else 0.0


    def points_per_100_square(total_points, inspected_m, width_cm):
        """points x 3600 / (inspected yards x width in inches)."""
        yards = frappe.utils.flt(inspected_m) / YARD_M
        width_in = frappe.utils.flt(width_cm) / 2.54
        return frappe.utils.flt(total_points) * 3600 / (yards * width_in) if yards and width_in else 0.0


    def sampling_pct(bands, total_m):
        """Inspect % for a lot of `total_m` metres. Band to_length 0 = no upper limit. 100 when no band matches."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_length_m)):
            if flt(b.from_length_m) <= flt(total_m) and (not flt(b.to_length_m) or flt(total_m) <= flt(b.to_length_m)):
                return flt(b.inspect_pct)
        return 100.0


    def lot_decision(avg_points, threshold, rejected_rolls, inspected_rolls, total_rolls, max_rejected_pct, on_hold):
        """Pass / Fail / Re-inspect 100% / Hold. A sample that fails sends the lot to 100% inspection; once every roll has been inspected a failing lot is Fail."""
        flt = frappe.utils.flt
        if on_hold:
            return "Hold"
        rejected_pct = rejected_rolls * 100 / inspected_rolls if inspected_rolls else 0
        failing = flt(avg_points) > flt(threshold) or rejected_pct > flt(max_rejected_pct)
        if not failing:
            return "Pass"
        return "Re-inspect 100%" if inspected_rolls < total_rolls else "Fail"


    def roll_disposition(inspected, roll_result, lot_result):
        """What happens to a roll's stock: Accepted, Accepted by Lot, Rejected or Hold."""
        if inspected:
            return {"Accept": "Accepted", "Reject": "Rejected"}.get(roll_result, "Hold")
        return "Accepted by Lot" if lot_result == "Pass" else "Hold"


    def width_impact(avg_actual_cm, required_cm, net_qty_m):
        """Extra metres needed when the fabric is narrower than the cuttable width the consumption was based on."""
        flt = frappe.utils.flt
        if not flt(avg_actual_cm) or not flt(required_cm) or flt(avg_actual_cm) >= flt(required_cm):
            return 0.0
        return flt(net_qty_m) * (flt(required_cm) / flt(avg_actual_cm) - 1)


    def trim_sample(plan, received_qty):
        """[sample size, accept max, reject min] of a Trim Sampling Plan for a lot. Percent plans have no accept numbers."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        received_qty = flt(received_qty)
        if plan.method == "Percent":
            return [max(1, frappe.utils.ceil(received_qty * flt(plan.inspect_pct) / 100)) if received_qty else 0, None, None]
        if received_qty <= cint(plan.full_inspect_up_to):
            return [received_qty, None, None]
        rows = sorted(plan.rows, key=lambda r: cint(r.lot_from))
        pick = None
        for r in rows:
            if cint(r.lot_from) <= received_qty <= cint(r.lot_to):
                pick = r
                break
        if not pick and rows:
            pick = rows[-1]
        if not pick:
            return [received_qty, None, None]
        return [min(flt(pick.sample_size), received_qty), cint(pick.accept_max), cint(pick.reject_min)]


    def trim_result(plan, defective, inspected, reject_min, size_mixup):
        """Pass or Fail. A size mix-up always fails. AQL: fail at the reject number. Percent: fail above the plan's limit."""
        flt = frappe.utils.flt
        if size_mixup:
            return "Fail"
        if plan.method == "AQL Table" and reject_min is not None:
            return "Fail" if frappe.utils.cint(defective) >= frappe.utils.cint(reject_min) else "Pass"
        pct = flt(defective) * 100 / flt(inspected) if flt(inspected) else 0
        limit = plan.get("max_defective_pct")
        return "Fail" if pct > flt(5 if limit is None else limit) else "Pass"


    def receipt_context(pr_name, row_name, kind):
        """Everything an inspection needs about one Purchase Receipt row of an FR (fabric) or TR (trim)."""
        pr = frappe.db.get_value("Purchase Receipt", pr_name, ["name", "docstatus", "company", "supplier", "posting_date", "currency"], as_dict=True)
        if not pr:
            frappe.throw("Purchase Receipt %s does not exist." % pr_name)
        if pr.docstatus != 1:
            frappe.throw("Purchase Receipt %s is not submitted. Inspect goods that have been received." % pr_name)
        row = frappe.db.get_value("Purchase Receipt Item", {"name": row_name, "parent": pr_name},
                                  ["name", "item_code", "warehouse", "stock_qty", "qty", "uom", "conversion_factor", "purchase_order", "purchase_order_item", "serial_and_batch_bundle", "net_amount"], as_dict=True)
        if not row:
            frappe.throw("Row %s is not on %s." % (row_name, pr_name))
        ctx = {"pr": pr, "row": row, "requisition": None, "requisition_type": None, "mri": None, "so_list": [], "styles": [], "customer": None, "terms": None,
               "purchase_order": None, "colour": None, "required_width": None}
        if row.purchase_order_item:
            poi = frappe.db.get_value("Purchase Order Item", row.purchase_order_item, ["parent", "material_request_item", "apparel_requisition_type", "apparel_requisition"], as_dict=True)
            ctx["mri"] = poi.material_request_item
            ctx["requisition_type"] = poi.apparel_requisition_type
            ctx["requisition"] = poi.apparel_requisition
            ctx["purchase_order"] = poi.parent
            po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier"], as_dict=True)
            ctx["terms"] = terms_for(po.apparel_purchase_terms, po.supplier)
        want = "FR" if kind == "Fabric" else "TR"
        if ctx["requisition_type"] and ctx["requisition_type"] != want:
            frappe.throw("This receipt row came from a %s; use the %s inspection." % (ctx["requisition_type"], "trim" if want == "FR" else "fabric"))
        if ctx["requisition"]:
            dt = "Fabric Requisition" if want == "FR" else "Trim Requisition"
            fields = ["sales_order", "style_no", "colour", "style_item"] + (["cuttable_width_cm"] if want == "FR" else [])
            req_rows = frappe.get_all(dt + " Item", filters={"parent": ctx["requisition"], "material_request_item": ctx["mri"]}, fields=fields)
            sos = []
            styles = []
            for r in req_rows:
                if r.sales_order not in sos:
                    sos.append(r.sales_order)
                if r.style_no and r.style_no not in styles:
                    styles.append(r.style_no)
            ctx["so_list"] = sorted(sos)
            ctx["styles"] = sorted(styles)
            ctx["colour"] = req_rows[0].colour if req_rows else None
            ctx["required_width"] = req_rows[0].get("cuttable_width_cm") if req_rows else None
            ctx["customer"] = frappe.db.get_value(dt, ctx["requisition"], "customer")
        return ctx


    def append_red_flag(requisition_type, name, text):
        dt = "Fabric Requisition" if requisition_type == "FR" else "Trim Requisition"
        if not name or not frappe.db.exists(dt, name):
            return
        cur = frappe.db.get_value(dt, name, "red_flags") or ""
        if text not in cur:
            frappe.db.set_value(dt, name, "red_flags", (cur + "\n" + text).strip(), update_modified=False)


    def make_quality_inspection(ctx, item_code, accepted, readings, sample_size, remarks):
        """Incoming Quality Inspection against the receipt: manual statuses, submitted. `readings` = [[parameter, value, status], ...]."""
        for p in ("Average Points per 100 Linear Yards", "Worst Roll Points per 100", "Average Width (cm)", "Shrinkage Warp %", "Shrinkage Weft %", "Trim Defective %", "Trim Size Mix-up"):
            if not frappe.db.exists("Quality Inspection Parameter", p):
                frappe.get_doc({"doctype": "Quality Inspection Parameter", "parameter": p}).insert(ignore_permissions=True)
        # ERPNext refuses a Quality Inspection for an item that is not flagged "Inspection Required before Purchase" (the dev suite runs in test mode, which skips that check)
        # The flag is set only while the inspection is made, so later receipts of the item are not blocked waiting for one.
        was_flagged = frappe.db.get_value("Item", item_code, "inspection_required_before_purchase")
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 1)
        qi = frappe.new_doc("Quality Inspection")
        qi.update({"inspection_type": "Incoming", "reference_type": "Purchase Receipt", "reference_name": ctx["pr"].name, "item_code": item_code, "report_date": frappe.utils.nowdate(),
                   "sample_size": sample_size, "inspected_by": frappe.session.user, "manual_inspection": 1, "status": "Accepted" if accepted else "Rejected", "remarks": remarks,
                   "child_row_reference": ctx["row"].name})
        for rd in readings:
            qi.append("readings", {"specification": rd[0], "value": "", "reading_value": str(rd[1]), "manual_inspection": 1, "numeric": 0, "status": rd[2]})
        qi.flags.ignore_permissions = True
        qi.insert()
        qi.submit()
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 0)
        return qi.name


    def make_stock_entry(ctx, rows, submit):
        """Move stock out of the inspection warehouse. `rows` = list of dict(item_code, qty, target, batch_no). Returns the Stock Entry name, or None when nothing moves."""
        rows = [r for r in rows if frappe.utils.flt(r["qty"]) > 0 and r["target"]]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = ctx["pr"].company
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": ctx["row"].warehouse, "t_warehouse": r["target"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = "Inspection release for %s" % ctx["pr"].name
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_linked(doctype, name):
        if name and frappe.db.exists(doctype, name):
            d = frappe.get_doc(doctype, name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc(doctype, name, ignore_permissions=True, force=True)
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    ctx = receipt_context(doc.purchase_receipt, doc.purchase_receipt_item, "Fabric")
    doc.company = ctx["pr"].company
    doc.supplier = ctx["pr"].supplier
    doc.purchase_order = ctx["purchase_order"]
    doc.fabric_requisition = ctx["requisition"]
    doc.fabric_item = ctx["row"].item_code
    doc.customer = ctx["customer"]
    doc.sales_orders = ", ".join(ctx["so_list"])
    doc.style_nos = ", ".join(ctx["styles"])
    doc.colour = doc.colour or ctx["colour"]
    if not flt(doc.required_width_cm):
        doc.required_width_cm = flt(ctx["required_width"]) or flt(frappe.db.get_value("Item", ctx["row"].item_code, "apparel_fabric_width_cm"))
    doc.points_basis = frappe.db.get_single_value("Apparel Settings", "fabric_points_basis") or "Per 100 Linear Yards"
    terms = ctx["terms"]
    if not flt(doc.points_threshold):
        doc.points_threshold = flt(terms.points_threshold) if terms and flt(terms.points_threshold) else flt(frappe.db.get_single_value("Apparel Settings", "fabric_points_threshold") or 20)
    window = cint(terms.claim_window_days) if terms else 0
    doc.claim_deadline = frappe.utils.add_days(ctx["pr"].posting_date, window) if window else None
    if not doc.inspected_by:
        doc.inspected_by = frappe.session.user
    if cint(doc.result_override):
        if not is_manager():
            frappe.throw("Only an Apparel Merchandising Manager can override the inspection rules.")
        if not (doc.override_reason or "").strip():
            frappe.throw("Enter the reason for overriding the inspection rules.")
    if not doc.rolls:
        frappe.throw("Load the rolls first (Tools > Load Rolls from Receipt).")

    # ---- rolls must be the ones received on this row
    bundle = ctx["row"].serial_and_batch_bundle
    allowed = []
    if bundle:
        allowed = [e.batch_no for e in frappe.get_all("Serial and Batch Entry", filters={"parent": bundle}, fields=["batch_no"]) if e.batch_no]
    seen = []
    for r in doc.rolls:
        if r.batch not in allowed:
            frappe.throw("Row %s: batch %s was not received on this receipt row." % (r.idx, r.batch))
        if r.batch in seen:
            frappe.throw("Row %s: batch %s is listed twice." % (r.idx, r.batch))
        seen.append(r.batch)
        b = frappe.db.get_value("Batch", r.batch, ["apparel_roll_no", "apparel_dye_lot", "apparel_ticket_length"], as_dict=True)
        r.roll_no = b.apparel_roll_no
        r.dye_lot = b.apparel_dye_lot
        r.ticket_length = flt(b.apparel_ticket_length)
        if not flt(r.actual_length):
            r.actual_length = r.ticket_length
        r.length_variance = flt(r.actual_length) - flt(r.ticket_length)
    doc.total_rolls = len(doc.rolls)
    doc.total_received_m = sum([flt(r.ticket_length) for r in doc.rolls])
    roll_nos = [r.roll_no for r in doc.rolls]
    for d in doc.defects:
        if d.roll_no not in roll_nos:
            frappe.throw("Defect row %s: roll %s is not in the roll list." % (d.idx, d.roll_no))

    # ---- defects -> points
    always = {}
    for c in frappe.get_all("Fabric Defect Code", fields=["name", "always_four_points"]):
        always[c.name] = cint(c.always_four_points)
    for d in doc.defects:
        if flt(d.defect_length_in) <= 0 and not always.get(d.defect_code):
            frappe.throw("Defect row %s: enter the defect length in inches." % d.idx)
        d.points = defect_points(d.defect_length_in, always.get(d.defect_code))

    # ---- rolls
    threshold = flt(doc.points_threshold)
    square = doc.points_basis == "Per 100 Square Yards"
    widths = []
    for r in doc.rolls:
        if not cint(r.inspected):
            r.total_points = 0
            r.points_per_100 = 0
            r.roll_result = r.roll_result if r.roll_result == "Hold" else None
            continue
        if not flt(r.inspected_length_m):
            r.inspected_length_m = flt(r.actual_length)
        if flt(r.inspected_length_m) > flt(r.actual_length) + 0.005:
            frappe.throw("Row %s: inspected length %s m is more than the roll (%s m)." % (r.idx, r.inspected_length_m, r.actual_length))
        mine = [[d.yard_position, d.points] for d in doc.defects if d.roll_no == r.roll_no]
        r.total_points = roll_points(mine)
        width = [flt(w) for w in (r.width_start_cm, r.width_middle_cm, r.width_end_cm) if flt(w)]
        avg_w = sum(width) / len(width) if width else 0
        if avg_w:
            widths.append(avg_w)
        r.width_required_cm = flt(r.width_required_cm) or flt(doc.required_width_cm)
        r.width_ok = 1 if (not width or min(width) + 0.5 >= flt(r.width_required_cm)) else 0
        if square:
            r.points_per_100 = flt(points_per_100_square(r.total_points, r.inspected_length_m, avg_w or r.width_required_cm), 2)
        else:
            r.points_per_100 = flt(points_per_100_linear(r.total_points, r.inspected_length_m), 2)
        auto = "Reject" if r.points_per_100 > threshold else "Accept"
        if r.roll_result == "Hold":
            pass
        elif auto == "Reject" or not r.roll_result:
            r.roll_result = auto      # a roll over the threshold cannot be accepted
    doc.avg_actual_width_cm = flt(sum(widths) / len(widths), 1) if widths else 0

    # ---- shrinkage
    limit = flt(frappe.db.get_single_value("Apparel Settings", "max_shrinkage_pct"))
    over = []
    for r in doc.shrinkage:
        for d in ("warp", "weft", "bias"):
            before = flt(r.get("before_" + d))
            after = flt(r.get("after_" + d))
            r.set("shrink_" + d + "_pct", round((after - before) / before * 100, 2) if before else 0)
        if limit and (abs(flt(r.get("shrink_warp_pct"))) > limit or abs(flt(r.get("shrink_weft_pct"))) > limit):
            over.append(r.roll_no or r.idx)
    if over:
        frappe.msgprint("Shrinkage above %s%% on: %s" % (limit, ", ".join([str(x) for x in over])), indicator="orange")

    # ---- lot
    bands = frappe.get_all("Fabric Sampling Band", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, fields=["from_length_m", "to_length_m", "inspect_pct"])
    doc.sampling_pct = sampling_pct(bands, doc.total_received_m)
    doc.required_inspect_m = flt(doc.total_received_m * doc.sampling_pct / 100, 2)
    done = [r for r in doc.rolls if cint(r.inspected)]
    doc.inspected_rolls = len(done)
    doc.inspected_m = flt(sum([flt(r.inspected_length_m) for r in done]), 2)
    doc.inspected_pct = flt(doc.inspected_m * 100 / doc.total_received_m, 2) if flt(doc.total_received_m) else 0
    pts = sum([cint(r.total_points) for r in done])
    doc.avg_points = flt(points_per_100_linear(pts, doc.inspected_m), 2)
    w = flt(doc.avg_actual_width_cm) or flt(doc.required_width_cm)
    doc.avg_points_sq = flt(points_per_100_square(pts, doc.inspected_m, w), 2)
    doc.rejected_rolls = len([r for r in done if r.roll_result == "Reject"])
    bands_found = []
    for r in doc.rolls:
        sb = (r.shade_band or "").strip()
        if sb and sb not in bands_found:
            bands_found.append(sb)
    doc.shade_bands_found = ", ".join(sorted(bands_found))
    basis_value = doc.avg_points_sq if doc.points_basis == "Per 100 Square Yards" else doc.avg_points
    mr = frappe.db.get_single_value("Apparel Settings", "max_rejected_rolls_pct")
    doc.lot_result = lot_decision(basis_value, doc.points_threshold, doc.rejected_rolls, doc.inspected_rolls, doc.total_rolls, flt(mr if mr is not None else 10), cint(doc.on_hold))
    accepted = 0.0
    hold = 0.0
    rejected = 0.0
    for r in doc.rolls:
        disp = roll_disposition(cint(r.inspected), r.roll_result, doc.lot_result)
        if disp in ("Accepted", "Accepted by Lot"):
            accepted = accepted + flt(r.ticket_length)
        elif disp == "Rejected":
            rejected = rejected + flt(r.ticket_length)
        else:
            hold = hold + flt(r.ticket_length)
    doc.accepted_m = flt(accepted, 2)
    doc.rejected_m = flt(rejected, 2)
    doc.hold_m = flt(hold, 2)


run(doc)

# Fabric Inspection, Before Submit: the required sample was inspected and a failed sample went to 100% (unless a manager overrides).
def run(doc):
    flt = frappe.utils.flt
    override = frappe.utils.cint(doc.result_override)
    if flt(doc.inspected_m) + 0.005 < flt(doc.required_inspect_m) and not override:
        frappe.throw("Inspect at least %s m (%s%% of %s m). %s m inspected so far." % (doc.required_inspect_m, doc.sampling_pct, flt(doc.total_received_m, 2), doc.inspected_m))
    if doc.lot_result == "Re-inspect 100%" and not override:
        frappe.throw("The sample failed. Inspect every roll before submitting, or have a manager override.")


run(doc)

# Fabric Inspection, After Submit: the result is written to every roll (Batch), the Quality Inspection and the Stock Entry that releases accepted rolls and moves rejected
# ones are made, the requisition gets its red flags and quantities, and FABRIC_QC_PASSED is stamped.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers from materials/inspection.py: the 4-point fabric system, sampling, lot decision, trim AQL, and the steps both inspections share (receipt context,
    # Quality Inspection, Stock Entry). Needs lib_mat.py and lib_purchasing.py.
    def defect_points(length_in, always_four):
        """Points for one defect by its length in inches: up to 3 = 1, over 3 to 6 = 2, over 6 to 9 = 3, over 9 = 4. Holes (and any code marked 'always 4') take 4 points."""
        if always_four:
            return 4
        n = frappe.utils.flt(length_in)
        if n <= 3:
            return 1
        if n <= 6:
            return 2
        if n <= 9:
            return 3
        return 4


    def roll_points(defects):
        """Total points of one roll. `defects` = list of [yard_position, points]. No more than 4 points count in one yard; a defect with no yard number counts on its own."""
        by_yard = {}
        loose = 0
        for d in defects:
            if d[0] in (None, "", 0):
                loose = loose + d[1]
            else:
                by_yard[d[0]] = by_yard.get(d[0], 0) + d[1]
        return loose + sum([min(by_yard[y], 4) for y in by_yard])


    def points_per_100_linear(total_points, inspected_m):
        yards = frappe.utils.flt(inspected_m) / YARD_M
        return frappe.utils.flt(total_points) * 100 / yards if yards else 0.0


    def points_per_100_square(total_points, inspected_m, width_cm):
        """points x 3600 / (inspected yards x width in inches)."""
        yards = frappe.utils.flt(inspected_m) / YARD_M
        width_in = frappe.utils.flt(width_cm) / 2.54
        return frappe.utils.flt(total_points) * 3600 / (yards * width_in) if yards and width_in else 0.0


    def sampling_pct(bands, total_m):
        """Inspect % for a lot of `total_m` metres. Band to_length 0 = no upper limit. 100 when no band matches."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_length_m)):
            if flt(b.from_length_m) <= flt(total_m) and (not flt(b.to_length_m) or flt(total_m) <= flt(b.to_length_m)):
                return flt(b.inspect_pct)
        return 100.0


    def lot_decision(avg_points, threshold, rejected_rolls, inspected_rolls, total_rolls, max_rejected_pct, on_hold):
        """Pass / Fail / Re-inspect 100% / Hold. A sample that fails sends the lot to 100% inspection; once every roll has been inspected a failing lot is Fail."""
        flt = frappe.utils.flt
        if on_hold:
            return "Hold"
        rejected_pct = rejected_rolls * 100 / inspected_rolls if inspected_rolls else 0
        failing = flt(avg_points) > flt(threshold) or rejected_pct > flt(max_rejected_pct)
        if not failing:
            return "Pass"
        return "Re-inspect 100%" if inspected_rolls < total_rolls else "Fail"


    def roll_disposition(inspected, roll_result, lot_result):
        """What happens to a roll's stock: Accepted, Accepted by Lot, Rejected or Hold."""
        if inspected:
            return {"Accept": "Accepted", "Reject": "Rejected"}.get(roll_result, "Hold")
        return "Accepted by Lot" if lot_result == "Pass" else "Hold"


    def width_impact(avg_actual_cm, required_cm, net_qty_m):
        """Extra metres needed when the fabric is narrower than the cuttable width the consumption was based on."""
        flt = frappe.utils.flt
        if not flt(avg_actual_cm) or not flt(required_cm) or flt(avg_actual_cm) >= flt(required_cm):
            return 0.0
        return flt(net_qty_m) * (flt(required_cm) / flt(avg_actual_cm) - 1)


    def trim_sample(plan, received_qty):
        """[sample size, accept max, reject min] of a Trim Sampling Plan for a lot. Percent plans have no accept numbers."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        received_qty = flt(received_qty)
        if plan.method == "Percent":
            return [max(1, frappe.utils.ceil(received_qty * flt(plan.inspect_pct) / 100)) if received_qty else 0, None, None]
        if received_qty <= cint(plan.full_inspect_up_to):
            return [received_qty, None, None]
        rows = sorted(plan.rows, key=lambda r: cint(r.lot_from))
        pick = None
        for r in rows:
            if cint(r.lot_from) <= received_qty <= cint(r.lot_to):
                pick = r
                break
        if not pick and rows:
            pick = rows[-1]
        if not pick:
            return [received_qty, None, None]
        return [min(flt(pick.sample_size), received_qty), cint(pick.accept_max), cint(pick.reject_min)]


    def trim_result(plan, defective, inspected, reject_min, size_mixup):
        """Pass or Fail. A size mix-up always fails. AQL: fail at the reject number. Percent: fail above the plan's limit."""
        flt = frappe.utils.flt
        if size_mixup:
            return "Fail"
        if plan.method == "AQL Table" and reject_min is not None:
            return "Fail" if frappe.utils.cint(defective) >= frappe.utils.cint(reject_min) else "Pass"
        pct = flt(defective) * 100 / flt(inspected) if flt(inspected) else 0
        limit = plan.get("max_defective_pct")
        return "Fail" if pct > flt(5 if limit is None else limit) else "Pass"


    def receipt_context(pr_name, row_name, kind):
        """Everything an inspection needs about one Purchase Receipt row of an FR (fabric) or TR (trim)."""
        pr = frappe.db.get_value("Purchase Receipt", pr_name, ["name", "docstatus", "company", "supplier", "posting_date", "currency"], as_dict=True)
        if not pr:
            frappe.throw("Purchase Receipt %s does not exist." % pr_name)
        if pr.docstatus != 1:
            frappe.throw("Purchase Receipt %s is not submitted. Inspect goods that have been received." % pr_name)
        row = frappe.db.get_value("Purchase Receipt Item", {"name": row_name, "parent": pr_name},
                                  ["name", "item_code", "warehouse", "stock_qty", "qty", "uom", "conversion_factor", "purchase_order", "purchase_order_item", "serial_and_batch_bundle", "net_amount"], as_dict=True)
        if not row:
            frappe.throw("Row %s is not on %s." % (row_name, pr_name))
        ctx = {"pr": pr, "row": row, "requisition": None, "requisition_type": None, "mri": None, "so_list": [], "styles": [], "customer": None, "terms": None,
               "purchase_order": None, "colour": None, "required_width": None}
        if row.purchase_order_item:
            poi = frappe.db.get_value("Purchase Order Item", row.purchase_order_item, ["parent", "material_request_item", "apparel_requisition_type", "apparel_requisition"], as_dict=True)
            ctx["mri"] = poi.material_request_item
            ctx["requisition_type"] = poi.apparel_requisition_type
            ctx["requisition"] = poi.apparel_requisition
            ctx["purchase_order"] = poi.parent
            po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier"], as_dict=True)
            ctx["terms"] = terms_for(po.apparel_purchase_terms, po.supplier)
        want = "FR" if kind == "Fabric" else "TR"
        if ctx["requisition_type"] and ctx["requisition_type"] != want:
            frappe.throw("This receipt row came from a %s; use the %s inspection." % (ctx["requisition_type"], "trim" if want == "FR" else "fabric"))
        if ctx["requisition"]:
            dt = "Fabric Requisition" if want == "FR" else "Trim Requisition"
            fields = ["sales_order", "style_no", "colour", "style_item"] + (["cuttable_width_cm"] if want == "FR" else [])
            req_rows = frappe.get_all(dt + " Item", filters={"parent": ctx["requisition"], "material_request_item": ctx["mri"]}, fields=fields)
            sos = []
            styles = []
            for r in req_rows:
                if r.sales_order not in sos:
                    sos.append(r.sales_order)
                if r.style_no and r.style_no not in styles:
                    styles.append(r.style_no)
            ctx["so_list"] = sorted(sos)
            ctx["styles"] = sorted(styles)
            ctx["colour"] = req_rows[0].colour if req_rows else None
            ctx["required_width"] = req_rows[0].get("cuttable_width_cm") if req_rows else None
            ctx["customer"] = frappe.db.get_value(dt, ctx["requisition"], "customer")
        return ctx


    def append_red_flag(requisition_type, name, text):
        dt = "Fabric Requisition" if requisition_type == "FR" else "Trim Requisition"
        if not name or not frappe.db.exists(dt, name):
            return
        cur = frappe.db.get_value(dt, name, "red_flags") or ""
        if text not in cur:
            frappe.db.set_value(dt, name, "red_flags", (cur + "\n" + text).strip(), update_modified=False)


    def make_quality_inspection(ctx, item_code, accepted, readings, sample_size, remarks):
        """Incoming Quality Inspection against the receipt: manual statuses, submitted. `readings` = [[parameter, value, status], ...]."""
        for p in ("Average Points per 100 Linear Yards", "Worst Roll Points per 100", "Average Width (cm)", "Shrinkage Warp %", "Shrinkage Weft %", "Trim Defective %", "Trim Size Mix-up"):
            if not frappe.db.exists("Quality Inspection Parameter", p):
                frappe.get_doc({"doctype": "Quality Inspection Parameter", "parameter": p}).insert(ignore_permissions=True)
        # ERPNext refuses a Quality Inspection for an item that is not flagged "Inspection Required before Purchase" (the dev suite runs in test mode, which skips that check)
        # The flag is set only while the inspection is made, so later receipts of the item are not blocked waiting for one.
        was_flagged = frappe.db.get_value("Item", item_code, "inspection_required_before_purchase")
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 1)
        qi = frappe.new_doc("Quality Inspection")
        qi.update({"inspection_type": "Incoming", "reference_type": "Purchase Receipt", "reference_name": ctx["pr"].name, "item_code": item_code, "report_date": frappe.utils.nowdate(),
                   "sample_size": sample_size, "inspected_by": frappe.session.user, "manual_inspection": 1, "status": "Accepted" if accepted else "Rejected", "remarks": remarks,
                   "child_row_reference": ctx["row"].name})
        for rd in readings:
            qi.append("readings", {"specification": rd[0], "value": "", "reading_value": str(rd[1]), "manual_inspection": 1, "numeric": 0, "status": rd[2]})
        qi.flags.ignore_permissions = True
        qi.insert()
        qi.submit()
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 0)
        return qi.name


    def make_stock_entry(ctx, rows, submit):
        """Move stock out of the inspection warehouse. `rows` = list of dict(item_code, qty, target, batch_no). Returns the Stock Entry name, or None when nothing moves."""
        rows = [r for r in rows if frappe.utils.flt(r["qty"]) > 0 and r["target"]]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = ctx["pr"].company
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": ctx["row"].warehouse, "t_warehouse": r["target"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = "Inspection release for %s" % ctx["pr"].name
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_linked(doctype, name):
        if name and frappe.db.exists(doctype, name):
            d = frappe.get_doc(doctype, name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc(doctype, name, ignore_permissions=True, force=True)
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    ctx = receipt_context(doc.purchase_receipt, doc.purchase_receipt_item, "Fabric")
    for r in doc.rolls:
        disp = roll_disposition(cint(r.inspected), r.roll_result, doc.lot_result)
        frappe.db.set_value("Batch", r.batch, {"apparel_inspection_status": disp, "apparel_fabric_inspection": doc.name, "apparel_shade_band": r.shade_band or "",
                                               "apparel_actual_length": r.actual_length, "apparel_points_per_100": r.points_per_100,
                                               "apparel_width_cm": flt(r.width_middle_cm) or flt(r.width_start_cm)}, update_modified=False)
    by_roll = {}
    for r in doc.rolls:
        by_roll[r.roll_no] = r.batch
    for s in doc.shrinkage:
        b = by_roll.get(s.roll_no)
        if b:
            frappe.db.set_value("Batch", b, {"apparel_shrinkage_warp_pct": s.shrink_warp_pct, "apparel_shrinkage_weft_pct": s.shrink_weft_pct}, update_modified=False)

    accepted = doc.lot_result == "Pass"
    inspected = [flt(r.points_per_100) for r in doc.rolls if cint(r.inspected)]
    worst = max(inspected) if inspected else 0
    warp = max([abs(flt(s.shrink_warp_pct)) for s in doc.shrinkage]) if doc.shrinkage else 0
    weft = max([abs(flt(s.shrink_weft_pct)) for s in doc.shrinkage]) if doc.shrinkage else 0
    limit = flt(frappe.db.get_single_value("Apparel Settings", "max_shrinkage_pct"))
    readings = [["Average Points per 100 Linear Yards", flt(doc.avg_points, 2), "Accepted" if flt(doc.avg_points) <= flt(doc.points_threshold) else "Rejected"],
                ["Worst Roll Points per 100", flt(worst, 2), "Accepted" if worst <= flt(doc.points_threshold) else "Rejected"]]
    if doc.avg_actual_width_cm:
        readings.append(["Average Width (cm)", doc.avg_actual_width_cm, "Accepted" if flt(doc.avg_actual_width_cm) >= flt(doc.required_width_cm) - 0.5 else "Rejected"])
    if doc.shrinkage:
        readings.append(["Shrinkage Warp %", warp, "Rejected" if limit and warp > limit else "Accepted"])
        readings.append(["Shrinkage Weft %", weft, "Rejected" if limit and weft > limit else "Accepted"])
    qi = make_quality_inspection(ctx, doc.fabric_item, accepted, readings, doc.inspected_rolls, doc.remarks)
    store = company_warehouse("store_warehouse_fabric", doc.company)
    reject = company_warehouse("rejected_warehouse", doc.company)
    rows = []
    for r in doc.rolls:
        disp = roll_disposition(cint(r.inspected), r.roll_result, doc.lot_result)
        if disp in ("Accepted", "Accepted by Lot"):
            rows.append({"item_code": doc.fabric_item, "qty": r.ticket_length, "target": store, "batch_no": r.batch})
        elif disp == "Rejected":
            rows.append({"item_code": doc.fabric_item, "qty": r.ticket_length, "target": reject, "batch_no": r.batch})
    se = make_stock_entry(ctx, rows, cint(frappe.db.get_single_value("Apparel Settings", "submit_inspection_stock_entry")))
    doc.db_set({"quality_inspection": qi, "stock_entry": se})

    if doc.fabric_requisition:
        short = width_impact(doc.avg_actual_width_cm, doc.required_width_cm, doc.accepted_m + doc.rejected_m + doc.hold_m)
        doc.db_set("width_shortfall_m", flt(short, 2))
        if short > 0:
            append_red_flag("FR", doc.fabric_requisition, "%s: fabric is narrower (%s cm vs %s cm cuttable width). About %s m more will be needed." %
                            (doc.name, doc.avg_actual_width_cm, doc.required_width_cm, flt(short, 0)))
        if len((doc.shade_bands_found or "").split(", ")) > 1:
            append_red_flag("FR", doc.fabric_requisition, "%s: more than one shade band (%s). Cut by shade band." % (doc.name, doc.shade_bands_found))
        req = refresh_requisition("FR", doc.fabric_requisition)
        if req:
            need = frappe.db.get_single_value("Apparel Settings", "material_gate_min_pct") or 100
            full = {}
            anyq = {}
            keys = []
            for r in req.items:
                k = "%s|%s|%s" % (r.sales_order, r.style_item, r.colour or "")
                if k not in keys:
                    keys.append(k)
                    full[k] = True
                    anyq[k] = False
                    full[k + "#"] = [r.sales_order, r.style_item, r.colour]
                full[k] = full[k] and (flt(r.accepted_qty) + 0.0005 >= flt(r.net_qty) * flt(need) / 100)
                if flt(r.accepted_qty) > 0:
                    anyq[k] = True
            for k in keys:
                if full[k] or anyq[k]:
                    v = full[k + "#"]
                    stamp_safe(v[0], v[1], v[2], "FABRIC_QC_PASSED", doc.inspection_date, "Fabric Inspection", doc.name, not full[k], False)


run(doc)

# Fabric Inspection, After Cancel: the stock entry and quality inspection are cancelled, the rolls are uninspected again, the requisition refreshed, the stamp cleared.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers from materials/inspection.py: the 4-point fabric system, sampling, lot decision, trim AQL, and the steps both inspections share (receipt context,
    # Quality Inspection, Stock Entry). Needs lib_mat.py and lib_purchasing.py.
    def defect_points(length_in, always_four):
        """Points for one defect by its length in inches: up to 3 = 1, over 3 to 6 = 2, over 6 to 9 = 3, over 9 = 4. Holes (and any code marked 'always 4') take 4 points."""
        if always_four:
            return 4
        n = frappe.utils.flt(length_in)
        if n <= 3:
            return 1
        if n <= 6:
            return 2
        if n <= 9:
            return 3
        return 4


    def roll_points(defects):
        """Total points of one roll. `defects` = list of [yard_position, points]. No more than 4 points count in one yard; a defect with no yard number counts on its own."""
        by_yard = {}
        loose = 0
        for d in defects:
            if d[0] in (None, "", 0):
                loose = loose + d[1]
            else:
                by_yard[d[0]] = by_yard.get(d[0], 0) + d[1]
        return loose + sum([min(by_yard[y], 4) for y in by_yard])


    def points_per_100_linear(total_points, inspected_m):
        yards = frappe.utils.flt(inspected_m) / YARD_M
        return frappe.utils.flt(total_points) * 100 / yards if yards else 0.0


    def points_per_100_square(total_points, inspected_m, width_cm):
        """points x 3600 / (inspected yards x width in inches)."""
        yards = frappe.utils.flt(inspected_m) / YARD_M
        width_in = frappe.utils.flt(width_cm) / 2.54
        return frappe.utils.flt(total_points) * 3600 / (yards * width_in) if yards and width_in else 0.0


    def sampling_pct(bands, total_m):
        """Inspect % for a lot of `total_m` metres. Band to_length 0 = no upper limit. 100 when no band matches."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_length_m)):
            if flt(b.from_length_m) <= flt(total_m) and (not flt(b.to_length_m) or flt(total_m) <= flt(b.to_length_m)):
                return flt(b.inspect_pct)
        return 100.0


    def lot_decision(avg_points, threshold, rejected_rolls, inspected_rolls, total_rolls, max_rejected_pct, on_hold):
        """Pass / Fail / Re-inspect 100% / Hold. A sample that fails sends the lot to 100% inspection; once every roll has been inspected a failing lot is Fail."""
        flt = frappe.utils.flt
        if on_hold:
            return "Hold"
        rejected_pct = rejected_rolls * 100 / inspected_rolls if inspected_rolls else 0
        failing = flt(avg_points) > flt(threshold) or rejected_pct > flt(max_rejected_pct)
        if not failing:
            return "Pass"
        return "Re-inspect 100%" if inspected_rolls < total_rolls else "Fail"


    def roll_disposition(inspected, roll_result, lot_result):
        """What happens to a roll's stock: Accepted, Accepted by Lot, Rejected or Hold."""
        if inspected:
            return {"Accept": "Accepted", "Reject": "Rejected"}.get(roll_result, "Hold")
        return "Accepted by Lot" if lot_result == "Pass" else "Hold"


    def width_impact(avg_actual_cm, required_cm, net_qty_m):
        """Extra metres needed when the fabric is narrower than the cuttable width the consumption was based on."""
        flt = frappe.utils.flt
        if not flt(avg_actual_cm) or not flt(required_cm) or flt(avg_actual_cm) >= flt(required_cm):
            return 0.0
        return flt(net_qty_m) * (flt(required_cm) / flt(avg_actual_cm) - 1)


    def trim_sample(plan, received_qty):
        """[sample size, accept max, reject min] of a Trim Sampling Plan for a lot. Percent plans have no accept numbers."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        received_qty = flt(received_qty)
        if plan.method == "Percent":
            return [max(1, frappe.utils.ceil(received_qty * flt(plan.inspect_pct) / 100)) if received_qty else 0, None, None]
        if received_qty <= cint(plan.full_inspect_up_to):
            return [received_qty, None, None]
        rows = sorted(plan.rows, key=lambda r: cint(r.lot_from))
        pick = None
        for r in rows:
            if cint(r.lot_from) <= received_qty <= cint(r.lot_to):
                pick = r
                break
        if not pick and rows:
            pick = rows[-1]
        if not pick:
            return [received_qty, None, None]
        return [min(flt(pick.sample_size), received_qty), cint(pick.accept_max), cint(pick.reject_min)]


    def trim_result(plan, defective, inspected, reject_min, size_mixup):
        """Pass or Fail. A size mix-up always fails. AQL: fail at the reject number. Percent: fail above the plan's limit."""
        flt = frappe.utils.flt
        if size_mixup:
            return "Fail"
        if plan.method == "AQL Table" and reject_min is not None:
            return "Fail" if frappe.utils.cint(defective) >= frappe.utils.cint(reject_min) else "Pass"
        pct = flt(defective) * 100 / flt(inspected) if flt(inspected) else 0
        limit = plan.get("max_defective_pct")
        return "Fail" if pct > flt(5 if limit is None else limit) else "Pass"


    def receipt_context(pr_name, row_name, kind):
        """Everything an inspection needs about one Purchase Receipt row of an FR (fabric) or TR (trim)."""
        pr = frappe.db.get_value("Purchase Receipt", pr_name, ["name", "docstatus", "company", "supplier", "posting_date", "currency"], as_dict=True)
        if not pr:
            frappe.throw("Purchase Receipt %s does not exist." % pr_name)
        if pr.docstatus != 1:
            frappe.throw("Purchase Receipt %s is not submitted. Inspect goods that have been received." % pr_name)
        row = frappe.db.get_value("Purchase Receipt Item", {"name": row_name, "parent": pr_name},
                                  ["name", "item_code", "warehouse", "stock_qty", "qty", "uom", "conversion_factor", "purchase_order", "purchase_order_item", "serial_and_batch_bundle", "net_amount"], as_dict=True)
        if not row:
            frappe.throw("Row %s is not on %s." % (row_name, pr_name))
        ctx = {"pr": pr, "row": row, "requisition": None, "requisition_type": None, "mri": None, "so_list": [], "styles": [], "customer": None, "terms": None,
               "purchase_order": None, "colour": None, "required_width": None}
        if row.purchase_order_item:
            poi = frappe.db.get_value("Purchase Order Item", row.purchase_order_item, ["parent", "material_request_item", "apparel_requisition_type", "apparel_requisition"], as_dict=True)
            ctx["mri"] = poi.material_request_item
            ctx["requisition_type"] = poi.apparel_requisition_type
            ctx["requisition"] = poi.apparel_requisition
            ctx["purchase_order"] = poi.parent
            po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier"], as_dict=True)
            ctx["terms"] = terms_for(po.apparel_purchase_terms, po.supplier)
        want = "FR" if kind == "Fabric" else "TR"
        if ctx["requisition_type"] and ctx["requisition_type"] != want:
            frappe.throw("This receipt row came from a %s; use the %s inspection." % (ctx["requisition_type"], "trim" if want == "FR" else "fabric"))
        if ctx["requisition"]:
            dt = "Fabric Requisition" if want == "FR" else "Trim Requisition"
            fields = ["sales_order", "style_no", "colour", "style_item"] + (["cuttable_width_cm"] if want == "FR" else [])
            req_rows = frappe.get_all(dt + " Item", filters={"parent": ctx["requisition"], "material_request_item": ctx["mri"]}, fields=fields)
            sos = []
            styles = []
            for r in req_rows:
                if r.sales_order not in sos:
                    sos.append(r.sales_order)
                if r.style_no and r.style_no not in styles:
                    styles.append(r.style_no)
            ctx["so_list"] = sorted(sos)
            ctx["styles"] = sorted(styles)
            ctx["colour"] = req_rows[0].colour if req_rows else None
            ctx["required_width"] = req_rows[0].get("cuttable_width_cm") if req_rows else None
            ctx["customer"] = frappe.db.get_value(dt, ctx["requisition"], "customer")
        return ctx


    def append_red_flag(requisition_type, name, text):
        dt = "Fabric Requisition" if requisition_type == "FR" else "Trim Requisition"
        if not name or not frappe.db.exists(dt, name):
            return
        cur = frappe.db.get_value(dt, name, "red_flags") or ""
        if text not in cur:
            frappe.db.set_value(dt, name, "red_flags", (cur + "\n" + text).strip(), update_modified=False)


    def make_quality_inspection(ctx, item_code, accepted, readings, sample_size, remarks):
        """Incoming Quality Inspection against the receipt: manual statuses, submitted. `readings` = [[parameter, value, status], ...]."""
        for p in ("Average Points per 100 Linear Yards", "Worst Roll Points per 100", "Average Width (cm)", "Shrinkage Warp %", "Shrinkage Weft %", "Trim Defective %", "Trim Size Mix-up"):
            if not frappe.db.exists("Quality Inspection Parameter", p):
                frappe.get_doc({"doctype": "Quality Inspection Parameter", "parameter": p}).insert(ignore_permissions=True)
        # ERPNext refuses a Quality Inspection for an item that is not flagged "Inspection Required before Purchase" (the dev suite runs in test mode, which skips that check)
        # The flag is set only while the inspection is made, so later receipts of the item are not blocked waiting for one.
        was_flagged = frappe.db.get_value("Item", item_code, "inspection_required_before_purchase")
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 1)
        qi = frappe.new_doc("Quality Inspection")
        qi.update({"inspection_type": "Incoming", "reference_type": "Purchase Receipt", "reference_name": ctx["pr"].name, "item_code": item_code, "report_date": frappe.utils.nowdate(),
                   "sample_size": sample_size, "inspected_by": frappe.session.user, "manual_inspection": 1, "status": "Accepted" if accepted else "Rejected", "remarks": remarks,
                   "child_row_reference": ctx["row"].name})
        for rd in readings:
            qi.append("readings", {"specification": rd[0], "value": "", "reading_value": str(rd[1]), "manual_inspection": 1, "numeric": 0, "status": rd[2]})
        qi.flags.ignore_permissions = True
        qi.insert()
        qi.submit()
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 0)
        return qi.name


    def make_stock_entry(ctx, rows, submit):
        """Move stock out of the inspection warehouse. `rows` = list of dict(item_code, qty, target, batch_no). Returns the Stock Entry name, or None when nothing moves."""
        rows = [r for r in rows if frappe.utils.flt(r["qty"]) > 0 and r["target"]]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = ctx["pr"].company
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": ctx["row"].warehouse, "t_warehouse": r["target"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = "Inspection release for %s" % ctx["pr"].name
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_linked(doctype, name):
        if name and frappe.db.exists(doctype, name):
            d = frappe.get_doc(doctype, name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc(doctype, name, ignore_permissions=True, force=True)
    cancel_linked("Stock Entry", doc.stock_entry)
    cancel_linked("Quality Inspection", doc.quality_inspection)
    for r in doc.rolls:
        frappe.db.set_value("Batch", r.batch, {"apparel_inspection_status": "Uninspected", "apparel_fabric_inspection": None, "apparel_points_per_100": 0}, update_modified=False)
    doc.db_set({"stock_entry": None, "quality_inspection": None})
    if doc.fabric_requisition:
        refresh_requisition("FR", doc.fabric_requisition)
    unstamp_safe("Fabric Inspection", doc.name)


run(doc)

# API arinox_fabric_inspection_load_rolls: one roll row per batch received on the receipt row (appended to the form's rolls).
def main():
    d = json.loads(frappe.form_dict.get("doc") or "{}")
    row = frappe.db.get_value("Purchase Receipt Item", {"name": d.get("purchase_receipt_item"), "parent": d.get("purchase_receipt")}, ["serial_and_batch_bundle"], as_dict=True)
    if not row:
        frappe.throw("Row %s is not on %s." % (d.get("purchase_receipt_item"), d.get("purchase_receipt")))
    batches = []
    if row.serial_and_batch_bundle:
        batches = [e.batch_no for e in frappe.get_all("Serial and Batch Entry", filters={"parent": row.serial_and_batch_bundle}, fields=["batch_no"]) if e.batch_no]
    rolls = list(d.get("rolls") or [])
    have = [r.get("batch") for r in rolls]
    for b in sorted(batches):
        if b not in have:
            rolls.append({"batch": b, "inspected": 1})
    frappe.flags.arinox_result = {"arinox_doc": {"rolls": rolls}, "count": len(rolls)}


main()

# API arinox_fabric_inspection_make_purchase_return: purchase return of the rejected rolls, taken from the rejected warehouse. Answers the draft return (unsaved).
def main():
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers from materials/inspection.py: the 4-point fabric system, sampling, lot decision, trim AQL, and the steps both inspections share (receipt context,
    # Quality Inspection, Stock Entry). Needs lib_mat.py and lib_purchasing.py.
    def defect_points(length_in, always_four):
        """Points for one defect by its length in inches: up to 3 = 1, over 3 to 6 = 2, over 6 to 9 = 3, over 9 = 4. Holes (and any code marked 'always 4') take 4 points."""
        if always_four:
            return 4
        n = frappe.utils.flt(length_in)
        if n <= 3:
            return 1
        if n <= 6:
            return 2
        if n <= 9:
            return 3
        return 4


    def roll_points(defects):
        """Total points of one roll. `defects` = list of [yard_position, points]. No more than 4 points count in one yard; a defect with no yard number counts on its own."""
        by_yard = {}
        loose = 0
        for d in defects:
            if d[0] in (None, "", 0):
                loose = loose + d[1]
            else:
                by_yard[d[0]] = by_yard.get(d[0], 0) + d[1]
        return loose + sum([min(by_yard[y], 4) for y in by_yard])


    def points_per_100_linear(total_points, inspected_m):
        yards = frappe.utils.flt(inspected_m) / YARD_M
        return frappe.utils.flt(total_points) * 100 / yards if yards else 0.0


    def points_per_100_square(total_points, inspected_m, width_cm):
        """points x 3600 / (inspected yards x width in inches)."""
        yards = frappe.utils.flt(inspected_m) / YARD_M
        width_in = frappe.utils.flt(width_cm) / 2.54
        return frappe.utils.flt(total_points) * 3600 / (yards * width_in) if yards and width_in else 0.0


    def sampling_pct(bands, total_m):
        """Inspect % for a lot of `total_m` metres. Band to_length 0 = no upper limit. 100 when no band matches."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_length_m)):
            if flt(b.from_length_m) <= flt(total_m) and (not flt(b.to_length_m) or flt(total_m) <= flt(b.to_length_m)):
                return flt(b.inspect_pct)
        return 100.0


    def lot_decision(avg_points, threshold, rejected_rolls, inspected_rolls, total_rolls, max_rejected_pct, on_hold):
        """Pass / Fail / Re-inspect 100% / Hold. A sample that fails sends the lot to 100% inspection; once every roll has been inspected a failing lot is Fail."""
        flt = frappe.utils.flt
        if on_hold:
            return "Hold"
        rejected_pct = rejected_rolls * 100 / inspected_rolls if inspected_rolls else 0
        failing = flt(avg_points) > flt(threshold) or rejected_pct > flt(max_rejected_pct)
        if not failing:
            return "Pass"
        return "Re-inspect 100%" if inspected_rolls < total_rolls else "Fail"


    def roll_disposition(inspected, roll_result, lot_result):
        """What happens to a roll's stock: Accepted, Accepted by Lot, Rejected or Hold."""
        if inspected:
            return {"Accept": "Accepted", "Reject": "Rejected"}.get(roll_result, "Hold")
        return "Accepted by Lot" if lot_result == "Pass" else "Hold"


    def width_impact(avg_actual_cm, required_cm, net_qty_m):
        """Extra metres needed when the fabric is narrower than the cuttable width the consumption was based on."""
        flt = frappe.utils.flt
        if not flt(avg_actual_cm) or not flt(required_cm) or flt(avg_actual_cm) >= flt(required_cm):
            return 0.0
        return flt(net_qty_m) * (flt(required_cm) / flt(avg_actual_cm) - 1)


    def trim_sample(plan, received_qty):
        """[sample size, accept max, reject min] of a Trim Sampling Plan for a lot. Percent plans have no accept numbers."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        received_qty = flt(received_qty)
        if plan.method == "Percent":
            return [max(1, frappe.utils.ceil(received_qty * flt(plan.inspect_pct) / 100)) if received_qty else 0, None, None]
        if received_qty <= cint(plan.full_inspect_up_to):
            return [received_qty, None, None]
        rows = sorted(plan.rows, key=lambda r: cint(r.lot_from))
        pick = None
        for r in rows:
            if cint(r.lot_from) <= received_qty <= cint(r.lot_to):
                pick = r
                break
        if not pick and rows:
            pick = rows[-1]
        if not pick:
            return [received_qty, None, None]
        return [min(flt(pick.sample_size), received_qty), cint(pick.accept_max), cint(pick.reject_min)]


    def trim_result(plan, defective, inspected, reject_min, size_mixup):
        """Pass or Fail. A size mix-up always fails. AQL: fail at the reject number. Percent: fail above the plan's limit."""
        flt = frappe.utils.flt
        if size_mixup:
            return "Fail"
        if plan.method == "AQL Table" and reject_min is not None:
            return "Fail" if frappe.utils.cint(defective) >= frappe.utils.cint(reject_min) else "Pass"
        pct = flt(defective) * 100 / flt(inspected) if flt(inspected) else 0
        limit = plan.get("max_defective_pct")
        return "Fail" if pct > flt(5 if limit is None else limit) else "Pass"


    def receipt_context(pr_name, row_name, kind):
        """Everything an inspection needs about one Purchase Receipt row of an FR (fabric) or TR (trim)."""
        pr = frappe.db.get_value("Purchase Receipt", pr_name, ["name", "docstatus", "company", "supplier", "posting_date", "currency"], as_dict=True)
        if not pr:
            frappe.throw("Purchase Receipt %s does not exist." % pr_name)
        if pr.docstatus != 1:
            frappe.throw("Purchase Receipt %s is not submitted. Inspect goods that have been received." % pr_name)
        row = frappe.db.get_value("Purchase Receipt Item", {"name": row_name, "parent": pr_name},
                                  ["name", "item_code", "warehouse", "stock_qty", "qty", "uom", "conversion_factor", "purchase_order", "purchase_order_item", "serial_and_batch_bundle", "net_amount"], as_dict=True)
        if not row:
            frappe.throw("Row %s is not on %s." % (row_name, pr_name))
        ctx = {"pr": pr, "row": row, "requisition": None, "requisition_type": None, "mri": None, "so_list": [], "styles": [], "customer": None, "terms": None,
               "purchase_order": None, "colour": None, "required_width": None}
        if row.purchase_order_item:
            poi = frappe.db.get_value("Purchase Order Item", row.purchase_order_item, ["parent", "material_request_item", "apparel_requisition_type", "apparel_requisition"], as_dict=True)
            ctx["mri"] = poi.material_request_item
            ctx["requisition_type"] = poi.apparel_requisition_type
            ctx["requisition"] = poi.apparel_requisition
            ctx["purchase_order"] = poi.parent
            po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier"], as_dict=True)
            ctx["terms"] = terms_for(po.apparel_purchase_terms, po.supplier)
        want = "FR" if kind == "Fabric" else "TR"
        if ctx["requisition_type"] and ctx["requisition_type"] != want:
            frappe.throw("This receipt row came from a %s; use the %s inspection." % (ctx["requisition_type"], "trim" if want == "FR" else "fabric"))
        if ctx["requisition"]:
            dt = "Fabric Requisition" if want == "FR" else "Trim Requisition"
            fields = ["sales_order", "style_no", "colour", "style_item"] + (["cuttable_width_cm"] if want == "FR" else [])
            req_rows = frappe.get_all(dt + " Item", filters={"parent": ctx["requisition"], "material_request_item": ctx["mri"]}, fields=fields)
            sos = []
            styles = []
            for r in req_rows:
                if r.sales_order not in sos:
                    sos.append(r.sales_order)
                if r.style_no and r.style_no not in styles:
                    styles.append(r.style_no)
            ctx["so_list"] = sorted(sos)
            ctx["styles"] = sorted(styles)
            ctx["colour"] = req_rows[0].colour if req_rows else None
            ctx["required_width"] = req_rows[0].get("cuttable_width_cm") if req_rows else None
            ctx["customer"] = frappe.db.get_value(dt, ctx["requisition"], "customer")
        return ctx


    def append_red_flag(requisition_type, name, text):
        dt = "Fabric Requisition" if requisition_type == "FR" else "Trim Requisition"
        if not name or not frappe.db.exists(dt, name):
            return
        cur = frappe.db.get_value(dt, name, "red_flags") or ""
        if text not in cur:
            frappe.db.set_value(dt, name, "red_flags", (cur + "\n" + text).strip(), update_modified=False)


    def make_quality_inspection(ctx, item_code, accepted, readings, sample_size, remarks):
        """Incoming Quality Inspection against the receipt: manual statuses, submitted. `readings` = [[parameter, value, status], ...]."""
        for p in ("Average Points per 100 Linear Yards", "Worst Roll Points per 100", "Average Width (cm)", "Shrinkage Warp %", "Shrinkage Weft %", "Trim Defective %", "Trim Size Mix-up"):
            if not frappe.db.exists("Quality Inspection Parameter", p):
                frappe.get_doc({"doctype": "Quality Inspection Parameter", "parameter": p}).insert(ignore_permissions=True)
        # ERPNext refuses a Quality Inspection for an item that is not flagged "Inspection Required before Purchase" (the dev suite runs in test mode, which skips that check)
        # The flag is set only while the inspection is made, so later receipts of the item are not blocked waiting for one.
        was_flagged = frappe.db.get_value("Item", item_code, "inspection_required_before_purchase")
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 1)
        qi = frappe.new_doc("Quality Inspection")
        qi.update({"inspection_type": "Incoming", "reference_type": "Purchase Receipt", "reference_name": ctx["pr"].name, "item_code": item_code, "report_date": frappe.utils.nowdate(),
                   "sample_size": sample_size, "inspected_by": frappe.session.user, "manual_inspection": 1, "status": "Accepted" if accepted else "Rejected", "remarks": remarks,
                   "child_row_reference": ctx["row"].name})
        for rd in readings:
            qi.append("readings", {"specification": rd[0], "value": "", "reading_value": str(rd[1]), "manual_inspection": 1, "numeric": 0, "status": rd[2]})
        qi.flags.ignore_permissions = True
        qi.insert()
        qi.submit()
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 0)
        return qi.name


    def make_stock_entry(ctx, rows, submit):
        """Move stock out of the inspection warehouse. `rows` = list of dict(item_code, qty, target, batch_no). Returns the Stock Entry name, or None when nothing moves."""
        rows = [r for r in rows if frappe.utils.flt(r["qty"]) > 0 and r["target"]]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = ctx["pr"].company
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": ctx["row"].warehouse, "t_warehouse": r["target"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = "Inspection release for %s" % ctx["pr"].name
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_linked(doctype, name):
        if name and frappe.db.exists(doctype, name):
            d = frappe.get_doc(doctype, name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc(doctype, name, ignore_permissions=True, force=True)
    flt = frappe.utils.flt
    fi = frappe.get_doc("Fabric Inspection", frappe.form_dict.get("inspection"))
    fi.check_permission("read")
    frappe.new_doc("Purchase Receipt").check_permission("create")
    if fi.docstatus != 1:
        frappe.throw("Submit the inspection first.")
    rejected = [r for r in fi.rolls if roll_disposition(frappe.utils.cint(r.inspected), r.roll_result, fi.lot_result) == "Rejected"]
    if not rejected:
        frappe.throw("No rolls were rejected.")
    ret = frappe.call("erpnext.stock.doctype.purchase_receipt.purchase_receipt.make_purchase_return", source_name=fi.purchase_receipt)
    template = None
    for i in ret.items:
        if i.item_code == fi.fabric_item:
            template = i
            break
    if not template:
        frappe.throw("The fabric item is not on the receipt.")
    proto = template.as_dict()
    ret.set("items", [])
    reject_wh = company_warehouse("rejected_warehouse", fi.company)
    for r in rejected:
        line = dict(proto)
        for k in ("name", "idx", "serial_and_batch_bundle", "rejected_serial_and_batch_bundle", "creation", "modified"):
            line.pop(k, None)
        line.update({"qty": -flt(r.ticket_length), "received_qty": -flt(r.ticket_length), "stock_qty": -flt(r.ticket_length), "batch_no": r.batch, "use_serial_batch_fields": 1,
                     "warehouse": reject_wh, "rejected_qty": 0, "rejected_warehouse": None})
        ret.append("items", line)
    frappe.flags.arinox_result = ret.as_dict()


main()

# Trim Inspection, Before Save: the receipt row, the sampling plan sets the sample size, defects -> defective %, the result (Pass / Fail / Hold) and the accepted / rejected quantities.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers of the Purchase Order hooks (overrides/purchase_order.py): the requisition row behind a PO row, approval-hold messages, cost warnings. Needs lib_samples.py, lib_mat.py.
    COPY_FIELDS = ("apparel_requisition_type", "apparel_requisition", "apparel_requisition_item", "apparel_style_no", "apparel_colour", "apparel_hold_reason")


    def my_roles():
        return (frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role"))


    def is_manager():
        return bool([r for r in my_roles() if r in MANAGER_ROLES])


    def requisition_row(poi):
        """The FR / TR row behind a PO row (or None)."""
        if not poi.get("apparel_requisition"):
            return None
        dt = "Fabric Requisition Item" if poi.apparel_requisition_type == "FR" else "Trim Requisition Item"
        wording = "fabric_description" if poi.apparel_requisition_type == "FR" else "description"
        return frappe.db.get_value(dt, {"parent": poi.apparel_requisition, "material_request_item": poi.get("material_request_item")}, ["sales_order", "style_item", "colour", wording], as_dict=True)


    def hold_blockers(doc):
        """Messages for rows whose lab dip (FR) or trim approval (TR) is still missing, re-checked now."""
        out = []
        for poi in doc.items:
            if not poi.get("apparel_hold_reason"):
                continue
            r = requisition_row(poi)
            if not r:
                continue
            if poi.apparel_requisition_type == "FR":
                stype = "Lab Dip"
                colour = r.colour
            else:
                stype = "Bulk Trim"
                colour = None
            ap = approval_info(r.sales_order, r.style_item, stype, colour, frappe.db.get_value("Sales Order", r.sales_order, "customer"))
            if not ap[1]:
                out.append("Row %s (%s): %s is %s." % (poi.idx, poi.item_code, stype, ap[0]))
        return out


    def cost_warnings(doc):
        """PO rate against the Cost Sheet material rate (the line is found through the requisition row; yard/metre and the costing currency are converted)."""
        flt = frappe.utils.flt
        limit = flt(frappe.db.get_single_value("Apparel Settings", "cost_overrun_warn_pct") or 5)
        out = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r or not flt(poi.rate):
                continue
            cs = cost_sheet_for(r.sales_order, r.style_item)
            if not cs:
                continue
            names = [(poi.item_name or "").strip().lower(), (r.get("fabric_description") or r.get("description") or "").strip().lower()]
            for cm in cs.materials:
                if not (cm.item and cm.item == poi.item_code) and (cm.description or "").strip().lower() not in names:
                    continue
                cost_rate = flt(cm.rate)
                if not cost_rate:
                    break
                # bring the costed rate to the PO's currency and unit: the costing may be in RMB per yard and the PO in USD per metre
                if (cm.price_currency or cs.currency) != doc.currency:
                    if doc.currency == cs.currency and flt(cm.exchange_rate):
                        cost_rate = cost_rate * flt(cm.exchange_rate)
                    else:
                        break
                cost_unit = cm.rate_uom or cm.uom
                if cost_unit != poi.uom:
                    if cost_unit == "Yard" and poi.uom == "Meter":
                        cost_rate = cost_rate / 0.9144
                    elif cost_unit == "Meter" and poi.uom == "Yard":
                        cost_rate = cost_rate * 0.9144
                    else:
                        break
                if flt(poi.rate) > cost_rate * (1 + limit / 100):
                    out.append("Row %s: rate %s is more than %s%% above the costed %s." % (poi.idx, poi.rate, limit, flt(cost_rate, 4)))
                break
        return out


    def stamp_po(doc):
        """Booked / PI / ETD milestones for every style x colour on the order."""
        seen = []
        for poi in doc.items:
            r = requisition_row(poi)
            if not r:
                continue
            k = [r.sales_order, r.style_item, r.colour, poi.apparel_requisition_type]
            if k in seen:
                continue
            seen.append(k)
            so = k[0]
            style = k[1]
            colour = k[2]
            if k[3] == "FR":
                stamp_safe(so, style, colour, "FABRIC_BOOKED", frappe.utils.nowdate(), "Purchase Order", doc.name, False, False)
                if doc.get("apparel_mill_ready_date"):
                    stamp_safe(so, style, colour, "BULK_FABRIC_READY_MILL", doc.apparel_mill_ready_date, "Purchase Order", doc.name, False, False)
                if doc.get("apparel_etd_actual"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.apparel_etd_actual, "Purchase Order", doc.name, False, False)
                elif doc.get("apparel_etd_revised") or doc.get("apparel_etd_planned"):
                    stamp_safe(so, style, colour, "FABRIC_ETD", doc.get("apparel_etd_revised") or doc.apparel_etd_planned, "Purchase Order", doc.name, False, True)
            elif doc.get("apparel_pi_date"):
                stamp_safe(so, style, colour, "TRIM_PI", doc.apparel_pi_date, "Purchase Order", doc.name, False, False)
    # shared helpers from materials/inspection.py: the 4-point fabric system, sampling, lot decision, trim AQL, and the steps both inspections share (receipt context,
    # Quality Inspection, Stock Entry). Needs lib_mat.py and lib_purchasing.py.
    def defect_points(length_in, always_four):
        """Points for one defect by its length in inches: up to 3 = 1, over 3 to 6 = 2, over 6 to 9 = 3, over 9 = 4. Holes (and any code marked 'always 4') take 4 points."""
        if always_four:
            return 4
        n = frappe.utils.flt(length_in)
        if n <= 3:
            return 1
        if n <= 6:
            return 2
        if n <= 9:
            return 3
        return 4


    def roll_points(defects):
        """Total points of one roll. `defects` = list of [yard_position, points]. No more than 4 points count in one yard; a defect with no yard number counts on its own."""
        by_yard = {}
        loose = 0
        for d in defects:
            if d[0] in (None, "", 0):
                loose = loose + d[1]
            else:
                by_yard[d[0]] = by_yard.get(d[0], 0) + d[1]
        return loose + sum([min(by_yard[y], 4) for y in by_yard])


    def points_per_100_linear(total_points, inspected_m):
        yards = frappe.utils.flt(inspected_m) / YARD_M
        return frappe.utils.flt(total_points) * 100 / yards if yards else 0.0


    def points_per_100_square(total_points, inspected_m, width_cm):
        """points x 3600 / (inspected yards x width in inches)."""
        yards = frappe.utils.flt(inspected_m) / YARD_M
        width_in = frappe.utils.flt(width_cm) / 2.54
        return frappe.utils.flt(total_points) * 3600 / (yards * width_in) if yards and width_in else 0.0


    def sampling_pct(bands, total_m):
        """Inspect % for a lot of `total_m` metres. Band to_length 0 = no upper limit. 100 when no band matches."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_length_m)):
            if flt(b.from_length_m) <= flt(total_m) and (not flt(b.to_length_m) or flt(total_m) <= flt(b.to_length_m)):
                return flt(b.inspect_pct)
        return 100.0


    def lot_decision(avg_points, threshold, rejected_rolls, inspected_rolls, total_rolls, max_rejected_pct, on_hold):
        """Pass / Fail / Re-inspect 100% / Hold. A sample that fails sends the lot to 100% inspection; once every roll has been inspected a failing lot is Fail."""
        flt = frappe.utils.flt
        if on_hold:
            return "Hold"
        rejected_pct = rejected_rolls * 100 / inspected_rolls if inspected_rolls else 0
        failing = flt(avg_points) > flt(threshold) or rejected_pct > flt(max_rejected_pct)
        if not failing:
            return "Pass"
        return "Re-inspect 100%" if inspected_rolls < total_rolls else "Fail"


    def roll_disposition(inspected, roll_result, lot_result):
        """What happens to a roll's stock: Accepted, Accepted by Lot, Rejected or Hold."""
        if inspected:
            return {"Accept": "Accepted", "Reject": "Rejected"}.get(roll_result, "Hold")
        return "Accepted by Lot" if lot_result == "Pass" else "Hold"


    def width_impact(avg_actual_cm, required_cm, net_qty_m):
        """Extra metres needed when the fabric is narrower than the cuttable width the consumption was based on."""
        flt = frappe.utils.flt
        if not flt(avg_actual_cm) or not flt(required_cm) or flt(avg_actual_cm) >= flt(required_cm):
            return 0.0
        return flt(net_qty_m) * (flt(required_cm) / flt(avg_actual_cm) - 1)


    def trim_sample(plan, received_qty):
        """[sample size, accept max, reject min] of a Trim Sampling Plan for a lot. Percent plans have no accept numbers."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        received_qty = flt(received_qty)
        if plan.method == "Percent":
            return [max(1, frappe.utils.ceil(received_qty * flt(plan.inspect_pct) / 100)) if received_qty else 0, None, None]
        if received_qty <= cint(plan.full_inspect_up_to):
            return [received_qty, None, None]
        rows = sorted(plan.rows, key=lambda r: cint(r.lot_from))
        pick = None
        for r in rows:
            if cint(r.lot_from) <= received_qty <= cint(r.lot_to):
                pick = r
                break
        if not pick and rows:
            pick = rows[-1]
        if not pick:
            return [received_qty, None, None]
        return [min(flt(pick.sample_size), received_qty), cint(pick.accept_max), cint(pick.reject_min)]


    def trim_result(plan, defective, inspected, reject_min, size_mixup):
        """Pass or Fail. A size mix-up always fails. AQL: fail at the reject number. Percent: fail above the plan's limit."""
        flt = frappe.utils.flt
        if size_mixup:
            return "Fail"
        if plan.method == "AQL Table" and reject_min is not None:
            return "Fail" if frappe.utils.cint(defective) >= frappe.utils.cint(reject_min) else "Pass"
        pct = flt(defective) * 100 / flt(inspected) if flt(inspected) else 0
        limit = plan.get("max_defective_pct")
        return "Fail" if pct > flt(5 if limit is None else limit) else "Pass"


    def receipt_context(pr_name, row_name, kind):
        """Everything an inspection needs about one Purchase Receipt row of an FR (fabric) or TR (trim)."""
        pr = frappe.db.get_value("Purchase Receipt", pr_name, ["name", "docstatus", "company", "supplier", "posting_date", "currency"], as_dict=True)
        if not pr:
            frappe.throw("Purchase Receipt %s does not exist." % pr_name)
        if pr.docstatus != 1:
            frappe.throw("Purchase Receipt %s is not submitted. Inspect goods that have been received." % pr_name)
        row = frappe.db.get_value("Purchase Receipt Item", {"name": row_name, "parent": pr_name},
                                  ["name", "item_code", "warehouse", "stock_qty", "qty", "uom", "conversion_factor", "purchase_order", "purchase_order_item", "serial_and_batch_bundle", "net_amount"], as_dict=True)
        if not row:
            frappe.throw("Row %s is not on %s." % (row_name, pr_name))
        ctx = {"pr": pr, "row": row, "requisition": None, "requisition_type": None, "mri": None, "so_list": [], "styles": [], "customer": None, "terms": None,
               "purchase_order": None, "colour": None, "required_width": None}
        if row.purchase_order_item:
            poi = frappe.db.get_value("Purchase Order Item", row.purchase_order_item, ["parent", "material_request_item", "apparel_requisition_type", "apparel_requisition"], as_dict=True)
            ctx["mri"] = poi.material_request_item
            ctx["requisition_type"] = poi.apparel_requisition_type
            ctx["requisition"] = poi.apparel_requisition
            ctx["purchase_order"] = poi.parent
            po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier"], as_dict=True)
            ctx["terms"] = terms_for(po.apparel_purchase_terms, po.supplier)
        want = "FR" if kind == "Fabric" else "TR"
        if ctx["requisition_type"] and ctx["requisition_type"] != want:
            frappe.throw("This receipt row came from a %s; use the %s inspection." % (ctx["requisition_type"], "trim" if want == "FR" else "fabric"))
        if ctx["requisition"]:
            dt = "Fabric Requisition" if want == "FR" else "Trim Requisition"
            fields = ["sales_order", "style_no", "colour", "style_item"] + (["cuttable_width_cm"] if want == "FR" else [])
            req_rows = frappe.get_all(dt + " Item", filters={"parent": ctx["requisition"], "material_request_item": ctx["mri"]}, fields=fields)
            sos = []
            styles = []
            for r in req_rows:
                if r.sales_order not in sos:
                    sos.append(r.sales_order)
                if r.style_no and r.style_no not in styles:
                    styles.append(r.style_no)
            ctx["so_list"] = sorted(sos)
            ctx["styles"] = sorted(styles)
            ctx["colour"] = req_rows[0].colour if req_rows else None
            ctx["required_width"] = req_rows[0].get("cuttable_width_cm") if req_rows else None
            ctx["customer"] = frappe.db.get_value(dt, ctx["requisition"], "customer")
        return ctx


    def append_red_flag(requisition_type, name, text):
        dt = "Fabric Requisition" if requisition_type == "FR" else "Trim Requisition"
        if not name or not frappe.db.exists(dt, name):
            return
        cur = frappe.db.get_value(dt, name, "red_flags") or ""
        if text not in cur:
            frappe.db.set_value(dt, name, "red_flags", (cur + "\n" + text).strip(), update_modified=False)


    def make_quality_inspection(ctx, item_code, accepted, readings, sample_size, remarks):
        """Incoming Quality Inspection against the receipt: manual statuses, submitted. `readings` = [[parameter, value, status], ...]."""
        for p in ("Average Points per 100 Linear Yards", "Worst Roll Points per 100", "Average Width (cm)", "Shrinkage Warp %", "Shrinkage Weft %", "Trim Defective %", "Trim Size Mix-up"):
            if not frappe.db.exists("Quality Inspection Parameter", p):
                frappe.get_doc({"doctype": "Quality Inspection Parameter", "parameter": p}).insert(ignore_permissions=True)
        # ERPNext refuses a Quality Inspection for an item that is not flagged "Inspection Required before Purchase" (the dev suite runs in test mode, which skips that check)
        # The flag is set only while the inspection is made, so later receipts of the item are not blocked waiting for one.
        was_flagged = frappe.db.get_value("Item", item_code, "inspection_required_before_purchase")
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 1)
        qi = frappe.new_doc("Quality Inspection")
        qi.update({"inspection_type": "Incoming", "reference_type": "Purchase Receipt", "reference_name": ctx["pr"].name, "item_code": item_code, "report_date": frappe.utils.nowdate(),
                   "sample_size": sample_size, "inspected_by": frappe.session.user, "manual_inspection": 1, "status": "Accepted" if accepted else "Rejected", "remarks": remarks,
                   "child_row_reference": ctx["row"].name})
        for rd in readings:
            qi.append("readings", {"specification": rd[0], "value": "", "reading_value": str(rd[1]), "manual_inspection": 1, "numeric": 0, "status": rd[2]})
        qi.flags.ignore_permissions = True
        qi.insert()
        qi.submit()
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 0)
        return qi.name


    def make_stock_entry(ctx, rows, submit):
        """Move stock out of the inspection warehouse. `rows` = list of dict(item_code, qty, target, batch_no). Returns the Stock Entry name, or None when nothing moves."""
        rows = [r for r in rows if frappe.utils.flt(r["qty"]) > 0 and r["target"]]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = ctx["pr"].company
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": ctx["row"].warehouse, "t_warehouse": r["target"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = "Inspection release for %s" % ctx["pr"].name
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_linked(doctype, name):
        if name and frappe.db.exists(doctype, name):
            d = frappe.get_doc(doctype, name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc(doctype, name, ignore_permissions=True, force=True)
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    ctx = receipt_context(doc.purchase_receipt, doc.purchase_receipt_item, "Trim")
    doc.company = ctx["pr"].company
    doc.supplier = ctx["pr"].supplier
    doc.trim_item = ctx["row"].item_code
    doc.purchase_order = ctx["purchase_order"]
    doc.trim_requisition = ctx["requisition"]
    doc.customer = ctx["customer"]
    doc.style_nos = ", ".join(ctx["styles"])
    doc.received_qty = flt(ctx["row"].stock_qty)
    doc.material_description = doc.material_description or frappe.db.get_value("Item", doc.trim_item, "item_name")
    if cint(doc.result_override):
        if not is_manager():
            frappe.throw("Only an Apparel Merchandising Manager can override the inspection rules.")
        if not (doc.override_reason or "").strip():
            frappe.throw("Enter the reason for overriding the inspection rules.")
    plan_name = doc.sampling_plan or frappe.db.get_single_value("Apparel Settings", "default_trim_sampling_plan")
    if not plan_name:
        frappe.throw("Choose a sampling plan, or set a default in Apparel Settings.")
    doc.sampling_plan = plan_name
    plan = frappe.get_doc("Trim Sampling Plan", plan_name)
    sm = trim_sample(plan, doc.received_qty)
    doc.sample_size = sm[0]
    doc.accept_max = sm[1]
    doc.reject_min = sm[2]
    if flt(doc.inspected_qty) <= 0:
        frappe.throw("Enter the quantity inspected.")
    if flt(doc.inspected_qty) > doc.received_qty + 0.0001:
        frappe.throw("Inspected qty cannot be more than the received qty (%s)." % doc.received_qty)
    doc.defective_qty = sum([cint(d.count) for d in doc.defects])
    if flt(doc.defective_qty) > flt(doc.inspected_qty):
        frappe.throw("More defects (%s) than pieces inspected (%s)." % (doc.defective_qty, doc.inspected_qty))
    doc.defective_pct = flt(doc.defective_qty * 100 / flt(doc.inspected_qty), 2)
    mixup = len([d for d in doc.defects if (d.defect_type or "").lower().replace("-", " ") == "size mix up" and cint(d.count)]) > 0
    held = doc.result == "Hold"
    doc.result = "Hold" if held else trim_result(plan, doc.defective_qty, doc.inspected_qty, doc.reject_min, mixup)
    if doc.result == "Pass":
        doc.rejected_qty = flt(doc.defective_qty)
        doc.accepted_qty = flt(doc.received_qty - doc.defective_qty)
    elif doc.result == "Fail":
        doc.rejected_qty = flt(doc.received_qty)
        doc.accepted_qty = 0
    else:
        doc.rejected_qty = 0
        doc.accepted_qty = 0
    doc.rejected_pct = flt(doc.rejected_qty * 100 / doc.received_qty, 2) if doc.received_qty else 0


run(doc)

# Trim Inspection, Before Submit: at least the sample size was inspected (unless a manager overrides).
def run(doc):
    flt = frappe.utils.flt
    if flt(doc.inspected_qty) + 0.0001 < flt(doc.sample_size) and not frappe.utils.cint(doc.result_override):
        frappe.throw("Inspect at least %s pieces for this lot (%s inspected)." % (flt(doc.sample_size), flt(doc.inspected_qty)))


run(doc)

# Trim Inspection, After Submit: the Quality Inspection and the Stock Entry (accepted to store, rejected to the rejected warehouse), then the requisition is refreshed and TRIMS_QC_PASSED stamped.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers from materials/inspection.py: the 4-point fabric system, sampling, lot decision, trim AQL, and the steps both inspections share (receipt context,
    # Quality Inspection, Stock Entry). Needs lib_mat.py and lib_purchasing.py.
    def defect_points(length_in, always_four):
        """Points for one defect by its length in inches: up to 3 = 1, over 3 to 6 = 2, over 6 to 9 = 3, over 9 = 4. Holes (and any code marked 'always 4') take 4 points."""
        if always_four:
            return 4
        n = frappe.utils.flt(length_in)
        if n <= 3:
            return 1
        if n <= 6:
            return 2
        if n <= 9:
            return 3
        return 4


    def roll_points(defects):
        """Total points of one roll. `defects` = list of [yard_position, points]. No more than 4 points count in one yard; a defect with no yard number counts on its own."""
        by_yard = {}
        loose = 0
        for d in defects:
            if d[0] in (None, "", 0):
                loose = loose + d[1]
            else:
                by_yard[d[0]] = by_yard.get(d[0], 0) + d[1]
        return loose + sum([min(by_yard[y], 4) for y in by_yard])


    def points_per_100_linear(total_points, inspected_m):
        yards = frappe.utils.flt(inspected_m) / YARD_M
        return frappe.utils.flt(total_points) * 100 / yards if yards else 0.0


    def points_per_100_square(total_points, inspected_m, width_cm):
        """points x 3600 / (inspected yards x width in inches)."""
        yards = frappe.utils.flt(inspected_m) / YARD_M
        width_in = frappe.utils.flt(width_cm) / 2.54
        return frappe.utils.flt(total_points) * 3600 / (yards * width_in) if yards and width_in else 0.0


    def sampling_pct(bands, total_m):
        """Inspect % for a lot of `total_m` metres. Band to_length 0 = no upper limit. 100 when no band matches."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_length_m)):
            if flt(b.from_length_m) <= flt(total_m) and (not flt(b.to_length_m) or flt(total_m) <= flt(b.to_length_m)):
                return flt(b.inspect_pct)
        return 100.0


    def lot_decision(avg_points, threshold, rejected_rolls, inspected_rolls, total_rolls, max_rejected_pct, on_hold):
        """Pass / Fail / Re-inspect 100% / Hold. A sample that fails sends the lot to 100% inspection; once every roll has been inspected a failing lot is Fail."""
        flt = frappe.utils.flt
        if on_hold:
            return "Hold"
        rejected_pct = rejected_rolls * 100 / inspected_rolls if inspected_rolls else 0
        failing = flt(avg_points) > flt(threshold) or rejected_pct > flt(max_rejected_pct)
        if not failing:
            return "Pass"
        return "Re-inspect 100%" if inspected_rolls < total_rolls else "Fail"


    def roll_disposition(inspected, roll_result, lot_result):
        """What happens to a roll's stock: Accepted, Accepted by Lot, Rejected or Hold."""
        if inspected:
            return {"Accept": "Accepted", "Reject": "Rejected"}.get(roll_result, "Hold")
        return "Accepted by Lot" if lot_result == "Pass" else "Hold"


    def width_impact(avg_actual_cm, required_cm, net_qty_m):
        """Extra metres needed when the fabric is narrower than the cuttable width the consumption was based on."""
        flt = frappe.utils.flt
        if not flt(avg_actual_cm) or not flt(required_cm) or flt(avg_actual_cm) >= flt(required_cm):
            return 0.0
        return flt(net_qty_m) * (flt(required_cm) / flt(avg_actual_cm) - 1)


    def trim_sample(plan, received_qty):
        """[sample size, accept max, reject min] of a Trim Sampling Plan for a lot. Percent plans have no accept numbers."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        received_qty = flt(received_qty)
        if plan.method == "Percent":
            return [max(1, frappe.utils.ceil(received_qty * flt(plan.inspect_pct) / 100)) if received_qty else 0, None, None]
        if received_qty <= cint(plan.full_inspect_up_to):
            return [received_qty, None, None]
        rows = sorted(plan.rows, key=lambda r: cint(r.lot_from))
        pick = None
        for r in rows:
            if cint(r.lot_from) <= received_qty <= cint(r.lot_to):
                pick = r
                break
        if not pick and rows:
            pick = rows[-1]
        if not pick:
            return [received_qty, None, None]
        return [min(flt(pick.sample_size), received_qty), cint(pick.accept_max), cint(pick.reject_min)]


    def trim_result(plan, defective, inspected, reject_min, size_mixup):
        """Pass or Fail. A size mix-up always fails. AQL: fail at the reject number. Percent: fail above the plan's limit."""
        flt = frappe.utils.flt
        if size_mixup:
            return "Fail"
        if plan.method == "AQL Table" and reject_min is not None:
            return "Fail" if frappe.utils.cint(defective) >= frappe.utils.cint(reject_min) else "Pass"
        pct = flt(defective) * 100 / flt(inspected) if flt(inspected) else 0
        limit = plan.get("max_defective_pct")
        return "Fail" if pct > flt(5 if limit is None else limit) else "Pass"


    def receipt_context(pr_name, row_name, kind):
        """Everything an inspection needs about one Purchase Receipt row of an FR (fabric) or TR (trim)."""
        pr = frappe.db.get_value("Purchase Receipt", pr_name, ["name", "docstatus", "company", "supplier", "posting_date", "currency"], as_dict=True)
        if not pr:
            frappe.throw("Purchase Receipt %s does not exist." % pr_name)
        if pr.docstatus != 1:
            frappe.throw("Purchase Receipt %s is not submitted. Inspect goods that have been received." % pr_name)
        row = frappe.db.get_value("Purchase Receipt Item", {"name": row_name, "parent": pr_name},
                                  ["name", "item_code", "warehouse", "stock_qty", "qty", "uom", "conversion_factor", "purchase_order", "purchase_order_item", "serial_and_batch_bundle", "net_amount"], as_dict=True)
        if not row:
            frappe.throw("Row %s is not on %s." % (row_name, pr_name))
        ctx = {"pr": pr, "row": row, "requisition": None, "requisition_type": None, "mri": None, "so_list": [], "styles": [], "customer": None, "terms": None,
               "purchase_order": None, "colour": None, "required_width": None}
        if row.purchase_order_item:
            poi = frappe.db.get_value("Purchase Order Item", row.purchase_order_item, ["parent", "material_request_item", "apparel_requisition_type", "apparel_requisition"], as_dict=True)
            ctx["mri"] = poi.material_request_item
            ctx["requisition_type"] = poi.apparel_requisition_type
            ctx["requisition"] = poi.apparel_requisition
            ctx["purchase_order"] = poi.parent
            po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier"], as_dict=True)
            ctx["terms"] = terms_for(po.apparel_purchase_terms, po.supplier)
        want = "FR" if kind == "Fabric" else "TR"
        if ctx["requisition_type"] and ctx["requisition_type"] != want:
            frappe.throw("This receipt row came from a %s; use the %s inspection." % (ctx["requisition_type"], "trim" if want == "FR" else "fabric"))
        if ctx["requisition"]:
            dt = "Fabric Requisition" if want == "FR" else "Trim Requisition"
            fields = ["sales_order", "style_no", "colour", "style_item"] + (["cuttable_width_cm"] if want == "FR" else [])
            req_rows = frappe.get_all(dt + " Item", filters={"parent": ctx["requisition"], "material_request_item": ctx["mri"]}, fields=fields)
            sos = []
            styles = []
            for r in req_rows:
                if r.sales_order not in sos:
                    sos.append(r.sales_order)
                if r.style_no and r.style_no not in styles:
                    styles.append(r.style_no)
            ctx["so_list"] = sorted(sos)
            ctx["styles"] = sorted(styles)
            ctx["colour"] = req_rows[0].colour if req_rows else None
            ctx["required_width"] = req_rows[0].get("cuttable_width_cm") if req_rows else None
            ctx["customer"] = frappe.db.get_value(dt, ctx["requisition"], "customer")
        return ctx


    def append_red_flag(requisition_type, name, text):
        dt = "Fabric Requisition" if requisition_type == "FR" else "Trim Requisition"
        if not name or not frappe.db.exists(dt, name):
            return
        cur = frappe.db.get_value(dt, name, "red_flags") or ""
        if text not in cur:
            frappe.db.set_value(dt, name, "red_flags", (cur + "\n" + text).strip(), update_modified=False)


    def make_quality_inspection(ctx, item_code, accepted, readings, sample_size, remarks):
        """Incoming Quality Inspection against the receipt: manual statuses, submitted. `readings` = [[parameter, value, status], ...]."""
        for p in ("Average Points per 100 Linear Yards", "Worst Roll Points per 100", "Average Width (cm)", "Shrinkage Warp %", "Shrinkage Weft %", "Trim Defective %", "Trim Size Mix-up"):
            if not frappe.db.exists("Quality Inspection Parameter", p):
                frappe.get_doc({"doctype": "Quality Inspection Parameter", "parameter": p}).insert(ignore_permissions=True)
        # ERPNext refuses a Quality Inspection for an item that is not flagged "Inspection Required before Purchase" (the dev suite runs in test mode, which skips that check)
        # The flag is set only while the inspection is made, so later receipts of the item are not blocked waiting for one.
        was_flagged = frappe.db.get_value("Item", item_code, "inspection_required_before_purchase")
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 1)
        qi = frappe.new_doc("Quality Inspection")
        qi.update({"inspection_type": "Incoming", "reference_type": "Purchase Receipt", "reference_name": ctx["pr"].name, "item_code": item_code, "report_date": frappe.utils.nowdate(),
                   "sample_size": sample_size, "inspected_by": frappe.session.user, "manual_inspection": 1, "status": "Accepted" if accepted else "Rejected", "remarks": remarks,
                   "child_row_reference": ctx["row"].name})
        for rd in readings:
            qi.append("readings", {"specification": rd[0], "value": "", "reading_value": str(rd[1]), "manual_inspection": 1, "numeric": 0, "status": rd[2]})
        qi.flags.ignore_permissions = True
        qi.insert()
        qi.submit()
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 0)
        return qi.name


    def make_stock_entry(ctx, rows, submit):
        """Move stock out of the inspection warehouse. `rows` = list of dict(item_code, qty, target, batch_no). Returns the Stock Entry name, or None when nothing moves."""
        rows = [r for r in rows if frappe.utils.flt(r["qty"]) > 0 and r["target"]]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = ctx["pr"].company
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": ctx["row"].warehouse, "t_warehouse": r["target"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = "Inspection release for %s" % ctx["pr"].name
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_linked(doctype, name):
        if name and frappe.db.exists(doctype, name):
            d = frappe.get_doc(doctype, name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc(doctype, name, ignore_permissions=True, force=True)
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    ctx = receipt_context(doc.purchase_receipt, doc.purchase_receipt_item, "Trim")
    ok = doc.result == "Pass"
    mixup = len([d for d in doc.defects if (d.defect_type or "").lower().replace("-", " ") == "size mix up" and cint(d.count)]) > 0
    qi = make_quality_inspection(ctx, doc.trim_item, ok, [["Trim Defective %", doc.defective_pct, "Accepted" if ok else "Rejected"],
                                                          ["Trim Size Mix-up", "Yes" if mixup else "No", "Rejected" if mixup else "Accepted"]], doc.inspected_qty, doc.remarks)
    store = company_warehouse("store_warehouse_trim", doc.company)
    reject = company_warehouse("rejected_warehouse", doc.company)
    se = make_stock_entry(ctx, [{"item_code": doc.trim_item, "qty": doc.accepted_qty, "target": store}, {"item_code": doc.trim_item, "qty": doc.rejected_qty, "target": reject}],
                          cint(frappe.db.get_single_value("Apparel Settings", "submit_inspection_stock_entry")))
    doc.db_set({"quality_inspection": qi, "stock_entry": se})
    if not doc.trim_requisition:
        return
    req = refresh_requisition("TR", doc.trim_requisition)
    if not req:
        return
    need = frappe.db.get_single_value("Apparel Settings", "material_gate_min_pct") or 100
    full = {}
    keys = []
    vals = {}
    for r in req.items:
        k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip())
        if k not in keys:
            keys.append(k)
            full[k] = True
            vals[k] = [r.sales_order, r.style_item, (r.colour or "").strip()]
        full[k] = full[k] and flt(r.accepted_qty) + 0.0005 >= flt(r.net_qty) * flt(need) / 100
    for k in keys:
        stamp_safe(vals[k][0], vals[k][1], vals[k][2] or None, "TRIMS_QC_PASSED", doc.received_date, "Trim Inspection", doc.name, not full[k], False)


run(doc)

# Trim Inspection, After Cancel: stock entry and quality inspection cancelled, the requisition refreshed, the stamp cleared.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from materials/purchasing.py: supplier terms (quantity bands, late-delivery penalty) and the roll-up of purchase, receipt and inspection
    # quantities back to the requisitions. Needs lib_mat.py. Row keys and the status rule of both requisitions live here too.
    def fr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), r.material_role or "", r.fabric_item or ""])


    def tr_row_key(r):
        return "|".join([r.sales_order or "", r.style_item or "", (r.colour or "").strip().upper(), (r.size or "").strip().upper(), r.trim_category or "",
                         r.trim_item or r.description or "", (r.trim_colour or "").strip().upper()])


    def requisition_status(doc):
        """The status of a requisition from its docstatus and its lines."""
        flt = frappe.utils.flt
        if doc.docstatus == 0:
            return "Draft"
        if doc.docstatus == 2:
            return "Cancelled"
        if doc.status == "Superseded":
            return "Superseded"
        need = [r for r in doc.items if flt(r.net_qty) > 0]
        if not need or len([r for r in need if flt(r.received_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Received"
        if [r for r in need if flt(r.received_qty) > 0]:
            return "Partly Received"
        if len([r for r in need if flt(r.ordered_qty) + 0.0005 >= flt(r.net_qty)]) == len(need):
            return "Ordered"
        if [r for r in need if flt(r.ordered_qty) > 0]:
            return "Partly Ordered"
        return "Approved"


    def pick_band(bands, qty):
        """The Purchase Qty Band row covering `qty` (to_qty 0 = no upper limit); None when no band applies."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_qty)):
            if flt(b.from_qty) <= flt(qty) and (not flt(b.to_qty) or flt(qty) <= flt(b.to_qty)):
                return b
        return None


    def qty_tolerance(terms, ordered_qty):
        if not terms:
            return 0.0
        b = pick_band(terms.qty_bands, ordered_qty)
        return frappe.utils.flt(b.tolerance_pct) if b else 0.0


    def delay_penalty(terms, delay_days):
        """[penalty %, action] for a delay under `terms`. Days <= 0 or inside a 0% band return 0."""
        cint = frappe.utils.cint
        if not terms or cint(delay_days) <= 0:
            return [0.0, None]
        for b in sorted(terms.delay_bands, key=lambda b: cint(b.from_days)):
            if cint(b.from_days) <= cint(delay_days) and (not cint(b.to_days) or cint(delay_days) <= cint(b.to_days)):
                return [frappe.utils.flt(b.penalty_pct), b.action]
        return [0.0, None]


    def terms_for(po_or_supplier_terms, supplier):
        """The terms doc: the explicit one, else the supplier's, else the default in Apparel Settings."""
        name = po_or_supplier_terms or (frappe.db.get_value("Supplier", supplier, "apparel_purchase_terms") if supplier else None) or frappe.db.get_single_value("Apparel Settings", "default_purchase_terms")
        return frappe.get_doc("Material Purchase Terms", name) if name else None


    def key_totals(requisition_type, chain, key):
        """[ordered, received] in stock units for a line key across a revision chain, from the purchase orders that reference its Material Request rows."""
        rows = frappe.db.sql("select coalesce(sum(p.stock_qty), 0), coalesce(sum(p.received_qty * p.conversion_factor), 0) from `tabPurchase Order Item` p "
                             "join `tabPurchase Order` o on o.name = p.parent join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where o.docstatus = 1 and m.apparel_requisition_type = %s and m.apparel_requisition in %s and m.apparel_requisition_item = %s",
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def inspection_totals(requisition_type, chain, key):
        """[accepted, rejected] in stock units for a line key, from the submitted inspections of the goods received for it."""
        if requisition_type == "FR":
            table = "Fabric Inspection"
            acc = "i.accepted_m"
            rej = "i.rejected_m"
        else:
            table = "Trim Inspection"
            acc = "i.accepted_qty"
            rej = "i.rejected_qty"
        rows = frappe.db.sql("select coalesce(sum(%s), 0), coalesce(sum(%s), 0) from `tab%s` i join `tabPurchase Receipt Item` r on r.name = i.purchase_receipt_item "
                             "join `tabPurchase Order Item` p on p.name = r.purchase_order_item join `tabMaterial Request Item` m on m.name = p.material_request_item "
                             "where i.docstatus = 1 and m.apparel_requisition_type = %%s and m.apparel_requisition in %%s and m.apparel_requisition_item = %%s" % (acc, rej, table),
                             (requisition_type, tuple(chain), key))
        return [frappe.utils.flt(rows[0][0]), frappe.utils.flt(rows[0][1])]


    def refresh_requisition(requisition_type, name):
        """Recompute ordered and received quantities and the status of one requisition; returns the document (None when not approved)."""
        if requisition_type == "FR":
            dt = "Fabric Requisition"
            prev_field = "previous_fr"
            key_of = fr_row_key
        else:
            dt = "Trim Requisition"
            prev_field = "previous_tr"
            key_of = tr_row_key
        if not frappe.db.exists(dt, name):
            return None
        doc = frappe.get_doc(dt, name)
        if doc.docstatus != 1:
            return None
        chain = revision_chain(dt, prev_field, name)
        for r in doc.items:
            ot = key_totals(requisition_type, chain, key_of(r))
            it = inspection_totals(requisition_type, chain, key_of(r))
            r.db_set({"ordered_qty": ot[0], "received_qty": ot[1], "accepted_qty": it[0], "rejected_qty": it[1]}, update_modified=False)
            r.ordered_qty = ot[0]
            r.received_qty = ot[1]
            r.accepted_qty = it[0]
            r.rejected_qty = it[1]
        status = requisition_status(doc)
        doc.status = status
        doc.db_set("status", status, update_modified=False)
        return doc


    def refresh_for_documents(doc):
        """Refresh every requisition referenced by the items of a PO, PR or inspection document; returns a list of [type, name]."""
        seen = []
        for it in doc.get("items") or []:
            t = it.get("apparel_requisition_type")
            n = it.get("apparel_requisition")
            if not (t and n) and it.get("material_request_item"):
                v = frappe.db.get_value("Material Request Item", it.material_request_item, ["apparel_requisition_type", "apparel_requisition"])
                if v:
                    t = v[0]
                    n = v[1]
            if t in ("FR", "TR") and n and [t, n] not in seen:
                seen.append([t, n])
                refresh_requisition(t, n)
        return seen
    # shared helpers from materials/inspection.py: the 4-point fabric system, sampling, lot decision, trim AQL, and the steps both inspections share (receipt context,
    # Quality Inspection, Stock Entry). Needs lib_mat.py and lib_purchasing.py.
    def defect_points(length_in, always_four):
        """Points for one defect by its length in inches: up to 3 = 1, over 3 to 6 = 2, over 6 to 9 = 3, over 9 = 4. Holes (and any code marked 'always 4') take 4 points."""
        if always_four:
            return 4
        n = frappe.utils.flt(length_in)
        if n <= 3:
            return 1
        if n <= 6:
            return 2
        if n <= 9:
            return 3
        return 4


    def roll_points(defects):
        """Total points of one roll. `defects` = list of [yard_position, points]. No more than 4 points count in one yard; a defect with no yard number counts on its own."""
        by_yard = {}
        loose = 0
        for d in defects:
            if d[0] in (None, "", 0):
                loose = loose + d[1]
            else:
                by_yard[d[0]] = by_yard.get(d[0], 0) + d[1]
        return loose + sum([min(by_yard[y], 4) for y in by_yard])


    def points_per_100_linear(total_points, inspected_m):
        yards = frappe.utils.flt(inspected_m) / YARD_M
        return frappe.utils.flt(total_points) * 100 / yards if yards else 0.0


    def points_per_100_square(total_points, inspected_m, width_cm):
        """points x 3600 / (inspected yards x width in inches)."""
        yards = frappe.utils.flt(inspected_m) / YARD_M
        width_in = frappe.utils.flt(width_cm) / 2.54
        return frappe.utils.flt(total_points) * 3600 / (yards * width_in) if yards and width_in else 0.0


    def sampling_pct(bands, total_m):
        """Inspect % for a lot of `total_m` metres. Band to_length 0 = no upper limit. 100 when no band matches."""
        flt = frappe.utils.flt
        for b in sorted(bands, key=lambda b: flt(b.from_length_m)):
            if flt(b.from_length_m) <= flt(total_m) and (not flt(b.to_length_m) or flt(total_m) <= flt(b.to_length_m)):
                return flt(b.inspect_pct)
        return 100.0


    def lot_decision(avg_points, threshold, rejected_rolls, inspected_rolls, total_rolls, max_rejected_pct, on_hold):
        """Pass / Fail / Re-inspect 100% / Hold. A sample that fails sends the lot to 100% inspection; once every roll has been inspected a failing lot is Fail."""
        flt = frappe.utils.flt
        if on_hold:
            return "Hold"
        rejected_pct = rejected_rolls * 100 / inspected_rolls if inspected_rolls else 0
        failing = flt(avg_points) > flt(threshold) or rejected_pct > flt(max_rejected_pct)
        if not failing:
            return "Pass"
        return "Re-inspect 100%" if inspected_rolls < total_rolls else "Fail"


    def roll_disposition(inspected, roll_result, lot_result):
        """What happens to a roll's stock: Accepted, Accepted by Lot, Rejected or Hold."""
        if inspected:
            return {"Accept": "Accepted", "Reject": "Rejected"}.get(roll_result, "Hold")
        return "Accepted by Lot" if lot_result == "Pass" else "Hold"


    def width_impact(avg_actual_cm, required_cm, net_qty_m):
        """Extra metres needed when the fabric is narrower than the cuttable width the consumption was based on."""
        flt = frappe.utils.flt
        if not flt(avg_actual_cm) or not flt(required_cm) or flt(avg_actual_cm) >= flt(required_cm):
            return 0.0
        return flt(net_qty_m) * (flt(required_cm) / flt(avg_actual_cm) - 1)


    def trim_sample(plan, received_qty):
        """[sample size, accept max, reject min] of a Trim Sampling Plan for a lot. Percent plans have no accept numbers."""
        flt = frappe.utils.flt
        cint = frappe.utils.cint
        received_qty = flt(received_qty)
        if plan.method == "Percent":
            return [max(1, frappe.utils.ceil(received_qty * flt(plan.inspect_pct) / 100)) if received_qty else 0, None, None]
        if received_qty <= cint(plan.full_inspect_up_to):
            return [received_qty, None, None]
        rows = sorted(plan.rows, key=lambda r: cint(r.lot_from))
        pick = None
        for r in rows:
            if cint(r.lot_from) <= received_qty <= cint(r.lot_to):
                pick = r
                break
        if not pick and rows:
            pick = rows[-1]
        if not pick:
            return [received_qty, None, None]
        return [min(flt(pick.sample_size), received_qty), cint(pick.accept_max), cint(pick.reject_min)]


    def trim_result(plan, defective, inspected, reject_min, size_mixup):
        """Pass or Fail. A size mix-up always fails. AQL: fail at the reject number. Percent: fail above the plan's limit."""
        flt = frappe.utils.flt
        if size_mixup:
            return "Fail"
        if plan.method == "AQL Table" and reject_min is not None:
            return "Fail" if frappe.utils.cint(defective) >= frappe.utils.cint(reject_min) else "Pass"
        pct = flt(defective) * 100 / flt(inspected) if flt(inspected) else 0
        limit = plan.get("max_defective_pct")
        return "Fail" if pct > flt(5 if limit is None else limit) else "Pass"


    def receipt_context(pr_name, row_name, kind):
        """Everything an inspection needs about one Purchase Receipt row of an FR (fabric) or TR (trim)."""
        pr = frappe.db.get_value("Purchase Receipt", pr_name, ["name", "docstatus", "company", "supplier", "posting_date", "currency"], as_dict=True)
        if not pr:
            frappe.throw("Purchase Receipt %s does not exist." % pr_name)
        if pr.docstatus != 1:
            frappe.throw("Purchase Receipt %s is not submitted. Inspect goods that have been received." % pr_name)
        row = frappe.db.get_value("Purchase Receipt Item", {"name": row_name, "parent": pr_name},
                                  ["name", "item_code", "warehouse", "stock_qty", "qty", "uom", "conversion_factor", "purchase_order", "purchase_order_item", "serial_and_batch_bundle", "net_amount"], as_dict=True)
        if not row:
            frappe.throw("Row %s is not on %s." % (row_name, pr_name))
        ctx = {"pr": pr, "row": row, "requisition": None, "requisition_type": None, "mri": None, "so_list": [], "styles": [], "customer": None, "terms": None,
               "purchase_order": None, "colour": None, "required_width": None}
        if row.purchase_order_item:
            poi = frappe.db.get_value("Purchase Order Item", row.purchase_order_item, ["parent", "material_request_item", "apparel_requisition_type", "apparel_requisition"], as_dict=True)
            ctx["mri"] = poi.material_request_item
            ctx["requisition_type"] = poi.apparel_requisition_type
            ctx["requisition"] = poi.apparel_requisition
            ctx["purchase_order"] = poi.parent
            po = frappe.db.get_value("Purchase Order", poi.parent, ["apparel_purchase_terms", "supplier"], as_dict=True)
            ctx["terms"] = terms_for(po.apparel_purchase_terms, po.supplier)
        want = "FR" if kind == "Fabric" else "TR"
        if ctx["requisition_type"] and ctx["requisition_type"] != want:
            frappe.throw("This receipt row came from a %s; use the %s inspection." % (ctx["requisition_type"], "trim" if want == "FR" else "fabric"))
        if ctx["requisition"]:
            dt = "Fabric Requisition" if want == "FR" else "Trim Requisition"
            fields = ["sales_order", "style_no", "colour", "style_item"] + (["cuttable_width_cm"] if want == "FR" else [])
            req_rows = frappe.get_all(dt + " Item", filters={"parent": ctx["requisition"], "material_request_item": ctx["mri"]}, fields=fields)
            sos = []
            styles = []
            for r in req_rows:
                if r.sales_order not in sos:
                    sos.append(r.sales_order)
                if r.style_no and r.style_no not in styles:
                    styles.append(r.style_no)
            ctx["so_list"] = sorted(sos)
            ctx["styles"] = sorted(styles)
            ctx["colour"] = req_rows[0].colour if req_rows else None
            ctx["required_width"] = req_rows[0].get("cuttable_width_cm") if req_rows else None
            ctx["customer"] = frappe.db.get_value(dt, ctx["requisition"], "customer")
        return ctx


    def append_red_flag(requisition_type, name, text):
        dt = "Fabric Requisition" if requisition_type == "FR" else "Trim Requisition"
        if not name or not frappe.db.exists(dt, name):
            return
        cur = frappe.db.get_value(dt, name, "red_flags") or ""
        if text not in cur:
            frappe.db.set_value(dt, name, "red_flags", (cur + "\n" + text).strip(), update_modified=False)


    def make_quality_inspection(ctx, item_code, accepted, readings, sample_size, remarks):
        """Incoming Quality Inspection against the receipt: manual statuses, submitted. `readings` = [[parameter, value, status], ...]."""
        for p in ("Average Points per 100 Linear Yards", "Worst Roll Points per 100", "Average Width (cm)", "Shrinkage Warp %", "Shrinkage Weft %", "Trim Defective %", "Trim Size Mix-up"):
            if not frappe.db.exists("Quality Inspection Parameter", p):
                frappe.get_doc({"doctype": "Quality Inspection Parameter", "parameter": p}).insert(ignore_permissions=True)
        # ERPNext refuses a Quality Inspection for an item that is not flagged "Inspection Required before Purchase" (the dev suite runs in test mode, which skips that check)
        # The flag is set only while the inspection is made, so later receipts of the item are not blocked waiting for one.
        was_flagged = frappe.db.get_value("Item", item_code, "inspection_required_before_purchase")
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 1)
        qi = frappe.new_doc("Quality Inspection")
        qi.update({"inspection_type": "Incoming", "reference_type": "Purchase Receipt", "reference_name": ctx["pr"].name, "item_code": item_code, "report_date": frappe.utils.nowdate(),
                   "sample_size": sample_size, "inspected_by": frappe.session.user, "manual_inspection": 1, "status": "Accepted" if accepted else "Rejected", "remarks": remarks,
                   "child_row_reference": ctx["row"].name})
        for rd in readings:
            qi.append("readings", {"specification": rd[0], "value": "", "reading_value": str(rd[1]), "manual_inspection": 1, "numeric": 0, "status": rd[2]})
        qi.flags.ignore_permissions = True
        qi.insert()
        qi.submit()
        if not was_flagged:
            frappe.db.set_value("Item", item_code, "inspection_required_before_purchase", 0)
        return qi.name


    def make_stock_entry(ctx, rows, submit):
        """Move stock out of the inspection warehouse. `rows` = list of dict(item_code, qty, target, batch_no). Returns the Stock Entry name, or None when nothing moves."""
        rows = [r for r in rows if frappe.utils.flt(r["qty"]) > 0 and r["target"]]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = ctx["pr"].company
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": ctx["row"].warehouse, "t_warehouse": r["target"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = "Inspection release for %s" % ctx["pr"].name
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_linked(doctype, name):
        if name and frappe.db.exists(doctype, name):
            d = frappe.get_doc(doctype, name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc(doctype, name, ignore_permissions=True, force=True)
    cancel_linked("Stock Entry", doc.stock_entry)
    cancel_linked("Quality Inspection", doc.quality_inspection)
    doc.db_set({"stock_entry": None, "quality_inspection": None})
    if doc.trim_requisition:
        refresh_requisition("TR", doc.trim_requisition)
    unstamp_safe("Trim Inspection", doc.name)


run(doc)

# Cut Plan, Before Save: the card is issued and open, the fabric and colour are on it, lays and ratios are consistent, marker consumption against the card's, red flags.
def run(doc):
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
