            if frappe.utils.flt(r.get("qty")) <= 0:
                frappe.throw("Roll %s: enter the metres to issue (above zero)." % (b.apparel_roll_no or r["batch_no"]))
            items.append({"item_code": b.item, "qty": frappe.utils.flt(r["qty"]), "s_warehouse": src, "t_warehouse": dst, "batch_no": r["batch_no"]})
        name = make_transfer(card.company, items, "Fabric Issue", card.name, "Fabric issued to cutting for %s" % card.name, True)
        refresh_issued(card.name)
        return name
    card = frappe.form_dict.get("card")
    roles = frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
    c = frappe.get_doc("Production Card", card)
    if "Apparel Production User" not in roles:
        c.check_permission("write")
    rolls = frappe.form_dict.get("rolls")
    rolls = json.loads(rolls) if isinstance(rolls, str) else rolls
    frappe.flags.arinox_result = issue_fabric_entry(card, rolls)


main()

# Lay Report, Before Save: card and colour, the cut plan's marker and ratios, the manager override, the rolls (accepted, in Cutting WIP, one shade band, width and shrinkage spread),
# sizes, rejected panels, purpose (re-cut), pairing of lining with shell, totals and consumption.
def run(doc):
    # shared helpers from production/cutting.py and production/stock.py: roll suggestion for a cut plan, bundle numbering for a lay, kit components, and the Stock Entries
    # of the production floor (fabric issue, remnant return). Needs lib_mat.py (to_metres) for the cut plan only.
    OK_STATUS = ("Accepted", "Accepted by Lot")


    def setting(field):
        return frappe.db.get_single_value("Apparel Settings", field)


    def roll_available(batch, warehouse, item_code):
        """Metres of a roll (Batch) in a warehouse. 0 when the warehouse is unknown."""
        if not warehouse:
            return 0
        return frappe.utils.flt(frappe.call("erpnext.stock.doctype.batch.batch.get_batch_qty", batch_no=batch, warehouse=warehouse, item_code=item_code))


    def roll_info(batch):
        b = frappe.db.get_value("Batch", batch, ["item", "apparel_roll_no", "apparel_dye_lot", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status",
                                                  "apparel_shrinkage_warp_pct", "apparel_shrinkage_weft_pct"], as_dict=True)
        if not b:
            frappe.throw("Roll %s not found." % batch)
        return b


    def required_components(card, colour):
        """Fabric roles that make up a garment of this colour on the production card (Shell, Lining, ...)."""
        roles = frappe.get_all("Production Card Fabric", filters={"parent": card, "colour": colour}, pluck="material_role")
        out = []
        for r in (roles or ["Shell"]):
            if r not in out:
                out.append(r)
        return sorted(out)


    def suggest_rolls(plan_name):
        """Allocate the rolls in the Cutting WIP warehouse to the lays of a cut plan: group by shade band, then width, then longest roll first. Nothing is saved."""
        flt = frappe.utils.flt
        plan = frappe.get_doc("Cut Plan", plan_name)
        wh = setting("cutting_wip_warehouse")
        pool = []
        for b in frappe.get_all("Batch", filters={"item": plan.fabric_item, "disabled": 0},
                                fields=["name", "apparel_roll_no", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status", "apparel_dye_lot"]):
            if b.apparel_inspection_status not in OK_STATUS:
                continue
            avail = roll_available(b.name, wh, plan.fabric_item)
            if avail > 0:
                pool.append({"batch": b.name, "roll_no": b.apparel_roll_no, "shade": b.apparel_shade_band or "", "width": flt(b.apparel_width_cm), "length": avail, "dye_lot": b.apparel_dye_lot})
        out = []
        short = []
        spread = flt(setting("max_width_spread_cm") or 1)
        for lay in sorted(plan.lays, key=lambda l: l.lay_no):
            need = flt(lay.planned_plies) * flt(lay.marker_length_m)
            cands = [r for r in pool if (not (lay.shade_band or "").strip() or r["shade"] == lay.shade_band)
                     and (not flt(lay.width_group_cm) or abs(r["width"] - flt(lay.width_group_cm)) <= spread)
                     and (not flt(lay.marker_width_cm) or not r["width"] or r["width"] >= flt(lay.marker_width_cm))]
            if not (lay.shade_band or "").strip() and cands:    # no shade named: keep to the shade band of the longest roll
                first = sorted(cands, key=lambda r: -r["length"])[0]
                cands = [r for r in cands if r["shade"] == first["shade"] and abs(r["width"] - first["width"]) <= spread]
            cands = sorted(cands, key=lambda r: -r["length"])
            taken = []
            got = 0.0
            for r in cands:
                if got >= need - 1e-9:
                    break
                use = min(r["length"], need - got)
                plies = int(frappe.utils.floor(use / flt(lay.marker_length_m))) if flt(lay.marker_length_m) else 0
                if plies <= 0:
                    continue
                metres = plies * flt(lay.marker_length_m)
                taken.append({"batch": r["batch"], "roll_no": r["roll_no"], "plies": plies, "metres": round(metres, 3), "shade": r["shade"], "width": r["width"]})
                got = got + metres
                r["length"] = r["length"] - metres
            out.append({"lay_no": lay.lay_no, "needed_m": round(need, 3), "allocated_m": round(got, 3), "rolls": taken})
            if got < need - 1e-9:
                short.append({"lay_no": lay.lay_no, "short_m": round(need - got, 3)})
        left = [{"batch": r["batch"], "roll_no": r["roll_no"], "metres": round(r["length"], 3), "shade": r["shade"]} for r in pool if r["length"] > 1e-9]
        return {"lays": out, "unallocated": left, "short": short}


    def next_ply(card):
        """First free ply number on a production card (sticker numbers never repeat on a card)."""
        return frappe.utils.cint(frappe.db.sql("select ifnull(max(ply_to), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1


    def chunks(first, last, size):
        """Ply ranges [[from, to], ...] of at most `size` plies covering first..last."""
        size = max(frappe.utils.cint(size), 1)
        out = []
        a = first
        while a <= last:
            b = min(a + size - 1, last)
            out.append([a, b])
            a = b + 1
        return out


    def new_bundle(lay, card, size, body, ply_from, ply_to, qty, rolls, kit_key, short, bundle_no):
        if bundle_no is None:
            bundle_no = frappe.utils.cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1
        d = frappe.get_doc({"doctype": "Cut Bundle", "production_card": card, "lay_report": lay.name, "colour": lay.colour, "size": size, "component": lay.component or "Shell",
                            "purpose": lay.purpose, "bundle_no": bundle_no, "body_no": body, "ply_from": ply_from, "ply_to": ply_to, "qty": qty, "shade_band": lay.shade_band,
                            "roll_nos": rolls, "kit_key": kit_key, "status": "Cut", "is_short": frappe.utils.cint(short)})
        d.insert(ignore_permissions=True)
        return d.name


    def make_bundles(lay):
        """Create the Cut Bundles of a submitted Lay Report. A paired (lining, pocketing) lay mirrors the ply ranges of its shell lay so every component of a garment
        carries the same ply number. Returns the bundle names."""
        cint = frappe.utils.cint
        card = lay.production_card
        size_bundle = cint(frappe.db.get_value("Production Card", card, "bundle_size")) or cint(setting("bundle_size")) or 20
        rolls = ", ".join([r.roll_no or r.batch for r in lay.rolls])
        names = []
        if lay.paired_with:
            src = frappe.get_all("Cut Bundle", filters={"lay_report": lay.paired_with, "status": ["!=", "Voided"]}, order_by="bundle_no",
                                 fields=["size", "body_no", "ply_from", "ply_to", "qty", "kit_key", "is_short", "bundle_no"])
            for b in src:
                names.append(new_bundle(lay, card, b.size, b.body_no, b.ply_from, b.ply_to, b.qty, rolls, b.kit_key, b.is_short, None))
            return names
        first = next_ply(card)
        plies = cint(lay.total_plies)
        last = first + plies - 1
        n = cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0])
        for s in lay.sizes:
            for body in range(1, max(cint(s.ratio), 1) + 1):
                for ab in chunks(first, last, size_bundle):
                    qty = ab[1] - ab[0] + 1
                    key = "%s|%s|%s-%s|%s" % (lay.colour, s.size, ab[0], ab[1], body)
                    n = n + 1
                    names.append(new_bundle(lay, card, s.size, body, ab[0], ab[1], qty, rolls, key, 1 if qty < size_bundle else 0, n))
        return names


    def void_bundles(lay_name):
        """Cancel of a lay: bundles are voided (their numbers are never reused). Blocked once any bundle left the cutting room."""
        moved = frappe.get_all("Cut Bundle", filters={"lay_report": lay_name, "status": ["not in", ("Cut", "Voided")]}, pluck="name")
        if moved:
            frappe.throw("Bundles %s have already left the cutting room. Take them back before cancelling the lay." % ", ".join(moved[:5]))
        for n in frappe.get_all("Cut Bundle", filters={"lay_report": lay_name}, pluck="name"):
            frappe.db.set_value("Cut Bundle", n, "status", "Voided", update_modified=False)


    def kit_missing(bundle_names):
        """For shell bundles about to go to a line: the kit keys whose lining / pocketing bundles are missing."""
        missing = []
        for n in bundle_names:
            b = frappe.db.get_value("Cut Bundle", n, ["production_card", "colour", "component", "kit_key"], as_dict=True)
            if b.component != "Shell":
                continue
            for comp in required_components(b.production_card, b.colour):
                if comp == "Shell":
                    continue
                if not frappe.db.exists("Cut Bundle", {"production_card": b.production_card, "kit_key": b.kit_key, "component": comp, "status": ["!=", "Voided"]}):
                    missing.append("%s (%s)" % (b.kit_key, comp))
        return missing


    def make_transfer(company, rows, kind, card, remarks, submit):
        """Material Transfer for `rows` = dicts(item_code, qty, s_warehouse, t_warehouse, batch_no). Returns the name, or None when nothing moves.
        The entry is tagged with the production card and the kind so reports can sum it."""
        rows = [r for r in rows if frappe.utils.flt(r.get("qty")) > 0]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = company
        se.apparel_production_card = card
        se.apparel_issue_kind = kind
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": r["s_warehouse"], "t_warehouse": r["t_warehouse"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = remarks
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_entry(name):
        if name and frappe.db.exists("Stock Entry", name):
            d = frappe.get_doc("Stock Entry", name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc("Stock Entry", name, ignore_permissions=True, force=True)


    def moved_qty(card, kind, item_code):
        """Quantity moved by submitted entries of this kind for a production card (optionally one item)."""
        cond = ""
        args = [card, kind]
        if item_code:
            cond = " and d.item_code = %s"
            args.append(item_code)
        return frappe.utils.flt(frappe.db.sql("select ifnull(sum(d.qty), 0) from `tabStock Entry Detail` d join `tabStock Entry` s on s.name = d.parent "
                                              "where s.docstatus = 1 and s.apparel_production_card = %s and s.apparel_issue_kind = %s" + cond, tuple(args))[0][0])


    def refresh_issued(card):
        """Write the issued metres onto the fabric rows of an issued card."""
        done = []
        for row in frappe.get_all("Production Card Fabric", filters={"parent": card}, fields=["name", "fabric_item"], order_by="idx"):
            if not row.fabric_item or row.fabric_item in done:
                continue
            done.append(row.fabric_item)
            frappe.db.set_value("Production Card Fabric", row.name, "issued_m", moved_qty(card, "Fabric Issue", row.fabric_item), update_modified=False)


    def issue_fabric_entry(card_name, rolls):
        """Issue rolls from the fabric store to Cutting WIP. rolls = [{batch_no, qty}]. Only accepted rolls leave the store."""
        card = frappe.get_doc("Production Card", card_name)
        if card.docstatus != 1:
            frappe.throw("Issue the production card first.")
        if not rolls:
            frappe.throw("Choose at least one roll to issue.")
        src = setting("store_warehouse_fabric")
        dst = setting("cutting_wip_warehouse")
        if not src or not dst:
            frappe.throw("Set the fabric store and Cutting WIP warehouses in Apparel Settings.")
        items = []
        fabrics = [f.fabric_item for f in card.fabrics]
        for r in rolls:
            b = frappe.db.get_value("Batch", r["batch_no"], ["item", "apparel_inspection_status", "apparel_roll_no"], as_dict=True)
            if not b:
                frappe.throw("Roll %s not found." % r["batch_no"])
            if b.apparel_inspection_status not in OK_STATUS:
                frappe.throw("Roll %s is %s. Only accepted rolls can be issued to cutting." % (b.apparel_roll_no or r["batch_no"], b.apparel_inspection_status or "not inspected"))
            if b.item not in fabrics:
                frappe.throw("Roll %s is %s, which is not a fabric of production card %s." % (b.apparel_roll_no or r["batch_no"], b.item, card.name))
            if frappe.utils.flt(r.get("qty")) <= 0:
                frappe.throw("Roll %s: enter the metres to issue (above zero)." % (b.apparel_roll_no or r["batch_no"]))
            items.append({"item_code": b.item, "qty": frappe.utils.flt(r["qty"]), "s_warehouse": src, "t_warehouse": dst, "batch_no": r["batch_no"]})
        name = make_transfer(card.company, items, "Fabric Issue", card.name, "Fabric issued to cutting for %s" % card.name, True)
        refresh_issued(card.name)
        return name
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    roles = frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
    MANAGER_ROLES = ("Apparel Production Manager", "Apparel Merchandising Manager", "System Manager")

    # ---- card
    card = frappe.db.get_value("Production Card", doc.production_card, ["docstatus", "status", "style_item", "sales_order", "company"], as_dict=True)
    if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
        frappe.throw("Production card %s must be issued and open." % doc.production_card)
    card_sizes = frappe.get_all("Production Card Line", filters={"parent": doc.production_card, "colour": doc.colour}, pluck="size")
    if not card_sizes:
        frappe.throw("Colour %s is not on production card %s." % (doc.colour, doc.production_card))
    if not frappe.db.exists("Production Card Fabric", {"parent": doc.production_card, "colour": doc.colour, "fabric_item": doc.fabric_item}):
        frappe.throw("%s is not a fabric of colour %s on production card %s." % (doc.fabric_item, doc.colour, doc.production_card))

    # ---- the cut plan
    plan_lay = None
    if not doc.cut_plan:
        if doc.purpose == "Bulk" and doc.component == "Shell":
            frappe.msgprint("No cut plan chosen. Ratios and the marker are taken from what you enter here.", indicator="orange")
    else:
        plan = frappe.get_doc("Cut Plan", doc.cut_plan)
        if plan.production_card != doc.production_card or (plan.colour or "").strip().upper() != (doc.colour or "").strip().upper():
            frappe.throw("Cut plan %s is for another production card or colour." % plan.name)
        if doc.purpose == "Bulk" and plan.status != "Released":
            frappe.throw("Cut plan %s is %s. Release it before bulk cutting." % (plan.name, plan.status))
        for l in plan.lays:
            if l.lay_no == doc.lay_no:
                plan_lay = l
        if not plan_lay:
            frappe.throw("Lay %s is not in cut plan %s." % (doc.lay_no, plan.name))
        ratios = {}
        for r in plan.ratios:
            if r.lay_no == doc.lay_no:
                ratios[r.size] = cint(r.ratio)
        if not doc.marker_length_m:
            doc.marker_length_m = plan_lay.marker_length_m
        if not doc.marker_width_cm:
            doc.marker_width_cm = plan_lay.marker_width_cm
        doc.marker_ref = doc.marker_ref or plan_lay.marker_ref
        doc.marker_efficiency_pct = doc.marker_efficiency_pct or plan_lay.marker_efficiency_pct
        if not doc.sizes:
            for s in ratios:
                doc.append("sizes", {"size": s, "ratio": ratios[s]})
        for s in doc.sizes:
            if s.size not in ratios:
                frappe.throw("Size %s is not in the ratios of lay %s of the cut plan." % (s.size, doc.lay_no))
            if cint(s.ratio) != ratios[s.size]:
                frappe.throw("Size %s: the ratio is %s in the cut plan, not %s." % (s.size, ratios[s.size], s.ratio))

    # ---- the gate override
    if cint(doc.gate_override) and (doc.is_new() or doc.has_value_changed("gate_override")):
        if not [r for r in roles if r in MANAGER_ROLES]:
            frappe.throw("Only a production manager can override the bulk gate.")
        if not (doc.gate_override_reason or "").strip():
            frappe.throw("Enter the reason for the override.")

    # ---- rolls
    if not doc.rolls:
        frappe.throw("Add the rolls laid.")
    wh = setting("cutting_wip_warehouse")
    spread_w = flt(setting("max_width_spread_cm") or 1)
    spread_s = flt(setting("max_shrinkage_spread_pct") or 3)
    washed = cint(frappe.db.get_value("Production Card", doc.production_card, "is_washed"))
    remnant_min = flt(setting("remnant_min_m") or 5)
    seen = []
    shades = []
    widths = []
    warp = []
    weft = []
    for r in doc.rolls:
        if r.batch in seen:
            frappe.throw("Roll %s appears twice in this lay." % r.batch)
        seen.append(r.batch)
        info = roll_info(r.batch)
        if info.item != doc.fabric_item:
            frappe.throw("Row %s: roll %s is %s, not %s." % (r.idx, info.apparel_roll_no or r.batch, info.item, doc.fabric_item))
        if info.apparel_inspection_status not in OK_STATUS:
            frappe.throw("Row %s: roll %s is %s. Only accepted rolls can be cut." % (r.idx, info.apparel_roll_no or r.batch, info.apparel_inspection_status or "not inspected"))
        r.roll_no = info.apparel_roll_no
        r.dye_lot = info.apparel_dye_lot
        r.shade_band = info.apparel_shade_band or ""
        r.width_cm = flt(info.apparel_width_cm)
        if (r.shade_band or "") not in shades:
            shades.append(r.shade_band or "")
        if r.width_cm:
            widths.append(r.width_cm)
        warp.append(flt(info.apparel_shrinkage_warp_pct))
        weft.append(flt(info.apparel_shrinkage_weft_pct))
        if cint(r.plies) <= 0:
            frappe.throw("Row %s: enter the number of plies." % r.idx)
        r.length_laid_m = round(cint(r.plies) * flt(doc.marker_length_m), 3)
        # metres of the roll still free: what is in Cutting WIP less what submitted lays already used
        stock = roll_available(r.batch, wh, doc.fabric_item)
        used_before = frappe.db.sql("select ifnull(sum(r.length_laid_m + ifnull(r.end_bit_m, 0) + ifnull(r.damage_m, 0)), 0) from `tabLay Roll` r join `tabLay Report` l on l.name = r.parent "
                                    "where r.batch = %s and l.docstatus = 1 and l.name != %s", (r.batch, doc.name or ""))[0][0]
        avail = round(max(stock - flt(used_before), 0), 3) if wh else 0
        r.roll_length_m = avail
        used = r.length_laid_m + flt(r.end_bit_m) + flt(r.damage_m)
        if wh and used > avail + 1e-6:
            frappe.throw("Row %s: roll %s has %s m left in %s, but this lay uses %s m. Issue the roll to cutting first." % (r.idx, info.apparel_roll_no or r.batch, round(avail, 3), wh, round(used, 3)))
        balance = round(max(avail - used, 0), 3) if wh else 0
        if 0 < balance < remnant_min:      # too short to keep: it becomes end bit
            r.end_bit_m = round(flt(r.end_bit_m) + balance, 3)
            balance = 0
        r.balance_returned_m = balance
        if flt(doc.marker_width_cm) and r.width_cm and r.width_cm < flt(doc.marker_width_cm):
            frappe.throw("Row %s: roll %s is %s cm wide, narrower than the %s cm marker." % (r.idx, info.apparel_roll_no or r.batch, r.width_cm, doc.marker_width_cm))
    if len(shades) > 1:
        frappe.throw("One lay holds one shade band. This lay mixes: %s. Cut each shade band in its own lay." % ", ".join(sorted([s or "(none)" for s in shades])))
    doc.shade_band = shades[0] if shades else ""
    if plan_lay and (plan_lay.shade_band or "").strip() and doc.shade_band != plan_lay.shade_band:
        frappe.throw("The cut plan wants shade %s in this lay; the rolls are shade %s." % (plan_lay.shade_band, doc.shade_band or "(none)"))
    if widths and max(widths) - min(widths) > spread_w:
        frappe.throw("The rolls in one lay must be within %s cm of each other in width (now %s to %s cm)." % (spread_w, min(widths), max(widths)))
    if warp and (max(warp) - min(warp) > spread_s or max(weft) - min(weft) > spread_s):
        msg = "Shrinkage of the rolls differs by more than %s%%. Cut rolls of similar shrinkage together." % spread_s
        if washed:
            frappe.throw(msg)
        frappe.msgprint(msg, indicator="orange")

    # ---- sizes
    if not doc.sizes:
        frappe.throw("Add the sizes and ratios cut.")
    total_plies = sum([cint(r.plies) for r in doc.rolls])
    seen_sizes = []
    for s in doc.sizes:
        if s.size not in card_sizes:
            frappe.throw("Size %s is not on production card %s for %s." % (s.size, doc.production_card, doc.colour))
        if s.size in seen_sizes:
            frappe.throw("Size %s appears twice." % s.size)
        seen_sizes.append(s.size)
        if cint(s.ratio) <= 0:
            frappe.throw("Size %s: pieces per ply must be above zero." % s.size)
        s.pieces_cut = total_plies * cint(s.ratio)

    # ---- panel rejects
    rejected = {}
    for r in doc.panel_rejects:
        if r.size not in seen_sizes:
            frappe.throw("Rejected panels: size %s is not cut in this lay." % r.size)
        if cint(r.qty) <= 0:
            frappe.throw("Rejected panels: enter the quantity.")
        rejected["s|" + r.size] = rejected.get("s|" + r.size, 0) + cint(r.qty)
    min_pct = flt(setting("panel_inspection_pct") or 100)
    for s in doc.sizes:
        s.panels_rejected = rejected.get("s|" + s.size, 0)
        if cint(s.panels_rejected) > cint(s.pieces_cut):
            frappe.throw("Size %s: more panels rejected than cut." % s.size)
        if cint(s.panels_checked) and cint(s.panels_checked) < cint(s.panels_rejected):
            frappe.throw("Size %s: panels checked cannot be fewer than panels rejected." % s.size)
        need = frappe.utils.ceil(cint(s.pieces_cut) * min_pct / 100.0)
        if doc.docstatus == 0 and cint(s.panels_checked) and cint(s.panels_checked) < need:
            frappe.msgprint("Size %s: %s panels checked, the setting asks for %s." % (s.size, s.panels_checked, need), indicator="orange")

    # ---- purpose
    if doc.purpose == "Re-cut":
        if not doc.recut_request:
            frappe.throw("A re-cut lay needs its Re-cut Request.")
        req = frappe.db.get_value("Recut Request", doc.recut_request, ["docstatus", "production_card", "colour", "size", "qty", "status", "source_roll", "different_roll_approved", "name"], as_dict=True)
        if not req or req.docstatus != 1 or req.status != "Open":
            frappe.throw("Re-cut Request %s must be submitted and open." % doc.recut_request)
        if req.production_card != doc.production_card or req.colour != doc.colour:
            frappe.throw("Re-cut Request %s is for another card or colour." % doc.recut_request)
        if [s.size for s in doc.sizes] != [req.size] or sum([cint(s.pieces_cut) for s in doc.sizes]) > cint(req.qty):
            frappe.throw("The re-cut lay must cut only size %s, at most %s pieces." % (req.size, req.qty))
        if req.source_roll and [r for r in doc.rolls if r.batch != req.source_roll] and not req.different_roll_approved:
            frappe.throw("The request names roll %s; cutting from another roll needs the approval box ticked on the request." % req.source_roll)
    elif doc.recut_request:
        frappe.throw("Only a re-cut lay can name a Re-cut Request.")

    # ---- pairing
    if doc.component == "Shell":
        if doc.paired_with:
            frappe.throw("A shell lay is not paired with another lay.")
    else:
        if not doc.paired_with:
            frappe.throw("A %s lay must be paired with its shell lay (so the ply numbers match)." % doc.component)
        shell = frappe.get_doc("Lay Report", doc.paired_with)
        if shell.docstatus != 1 or shell.component != "Shell" or shell.production_card != doc.production_card or shell.colour != doc.colour:
            frappe.throw("Paired lay %s must be a submitted shell lay of the same card and colour." % doc.paired_with)
        if cint(shell.total_plies) != total_plies:
            frappe.throw("Paired lay %s has %s plies; this lay has %s. They must match." % (shell.name, shell.total_plies, total_plies))
        mine = {}
        for s in doc.sizes:
            mine[s.size] = cint(s.ratio)
        theirs = {}
        for s in shell.sizes:
            theirs[s.size] = cint(s.ratio)
        if mine != theirs:
            frappe.throw("Size ratios must match the shell lay %s." % shell.name)

    # ---- totals
    doc.total_plies = total_plies
    doc.laid_m = round(sum([flt(r.length_laid_m) for r in doc.rolls]), 3)
    doc.pieces_cut = sum([cint(s.pieces_cut) for s in doc.sizes])
    doc.rejected_pieces = sum([cint(r.qty) for r in doc.panel_rejects])
    per_ply = sum([cint(s.ratio) for s in doc.sizes])
    doc.lay_consumption = round(doc.laid_m / doc.pieces_cut, 4) if doc.pieces_cut else 0
    doc.cad_consumption = round(flt(doc.marker_length_m) / per_ply, 4) if per_ply else 0
    doc.consumption_difference = round(doc.lay_consumption - doc.cad_consumption, 4)


run(doc)

# Lay Report, After Submit: the cut pieces go to the production ledger (CUT and CUT_REJECT of the shell fabric), plies are numbered into Cut Bundles, remnants go back to the
# store, the card moves to In Cutting, a re-cut request is marked Cut, and a bulk shell lay stamps PCD.
def run(doc):
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from production/cutting.py and production/stock.py: roll suggestion for a cut plan, bundle numbering for a lay, kit components, and the Stock Entries
    # of the production floor (fabric issue, remnant return). Needs lib_mat.py (to_metres) for the cut plan only.
    OK_STATUS = ("Accepted", "Accepted by Lot")


    def setting(field):
        return frappe.db.get_single_value("Apparel Settings", field)


    def roll_available(batch, warehouse, item_code):
        """Metres of a roll (Batch) in a warehouse. 0 when the warehouse is unknown."""
        if not warehouse:
            return 0
        return frappe.utils.flt(frappe.call("erpnext.stock.doctype.batch.batch.get_batch_qty", batch_no=batch, warehouse=warehouse, item_code=item_code))


    def roll_info(batch):
        b = frappe.db.get_value("Batch", batch, ["item", "apparel_roll_no", "apparel_dye_lot", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status",
                                                  "apparel_shrinkage_warp_pct", "apparel_shrinkage_weft_pct"], as_dict=True)
        if not b:
            frappe.throw("Roll %s not found." % batch)
        return b


    def required_components(card, colour):
        """Fabric roles that make up a garment of this colour on the production card (Shell, Lining, ...)."""
        roles = frappe.get_all("Production Card Fabric", filters={"parent": card, "colour": colour}, pluck="material_role")
        out = []
        for r in (roles or ["Shell"]):
            if r not in out:
                out.append(r)
        return sorted(out)


    def suggest_rolls(plan_name):
        """Allocate the rolls in the Cutting WIP warehouse to the lays of a cut plan: group by shade band, then width, then longest roll first. Nothing is saved."""
        flt = frappe.utils.flt
        plan = frappe.get_doc("Cut Plan", plan_name)
        wh = setting("cutting_wip_warehouse")
        pool = []
        for b in frappe.get_all("Batch", filters={"item": plan.fabric_item, "disabled": 0},
                                fields=["name", "apparel_roll_no", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status", "apparel_dye_lot"]):
            if b.apparel_inspection_status not in OK_STATUS:
                continue
            avail = roll_available(b.name, wh, plan.fabric_item)
            if avail > 0:
                pool.append({"batch": b.name, "roll_no": b.apparel_roll_no, "shade": b.apparel_shade_band or "", "width": flt(b.apparel_width_cm), "length": avail, "dye_lot": b.apparel_dye_lot})
        out = []
        short = []
        spread = flt(setting("max_width_spread_cm") or 1)
        for lay in sorted(plan.lays, key=lambda l: l.lay_no):
            need = flt(lay.planned_plies) * flt(lay.marker_length_m)
            cands = [r for r in pool if (not (lay.shade_band or "").strip() or r["shade"] == lay.shade_band)
                     and (not flt(lay.width_group_cm) or abs(r["width"] - flt(lay.width_group_cm)) <= spread)
                     and (not flt(lay.marker_width_cm) or not r["width"] or r["width"] >= flt(lay.marker_width_cm))]
            if not (lay.shade_band or "").strip() and cands:    # no shade named: keep to the shade band of the longest roll
                first = sorted(cands, key=lambda r: -r["length"])[0]
                cands = [r for r in cands if r["shade"] == first["shade"] and abs(r["width"] - first["width"]) <= spread]
            cands = sorted(cands, key=lambda r: -r["length"])
            taken = []
            got = 0.0
            for r in cands:
                if got >= need - 1e-9:
                    break
                use = min(r["length"], need - got)
                plies = int(frappe.utils.floor(use / flt(lay.marker_length_m))) if flt(lay.marker_length_m) else 0
                if plies <= 0:
                    continue
                metres = plies * flt(lay.marker_length_m)
                taken.append({"batch": r["batch"], "roll_no": r["roll_no"], "plies": plies, "metres": round(metres, 3), "shade": r["shade"], "width": r["width"]})
                got = got + metres
                r["length"] = r["length"] - metres
            out.append({"lay_no": lay.lay_no, "needed_m": round(need, 3), "allocated_m": round(got, 3), "rolls": taken})
            if got < need - 1e-9:
                short.append({"lay_no": lay.lay_no, "short_m": round(need - got, 3)})
        left = [{"batch": r["batch"], "roll_no": r["roll_no"], "metres": round(r["length"], 3), "shade": r["shade"]} for r in pool if r["length"] > 1e-9]
        return {"lays": out, "unallocated": left, "short": short}


    def next_ply(card):
        """First free ply number on a production card (sticker numbers never repeat on a card)."""
        return frappe.utils.cint(frappe.db.sql("select ifnull(max(ply_to), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1


    def chunks(first, last, size):
        """Ply ranges [[from, to], ...] of at most `size` plies covering first..last."""
        size = max(frappe.utils.cint(size), 1)
        out = []
        a = first
        while a <= last:
            b = min(a + size - 1, last)
            out.append([a, b])
            a = b + 1
        return out


    def new_bundle(lay, card, size, body, ply_from, ply_to, qty, rolls, kit_key, short, bundle_no):
        if bundle_no is None:
            bundle_no = frappe.utils.cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1
        d = frappe.get_doc({"doctype": "Cut Bundle", "production_card": card, "lay_report": lay.name, "colour": lay.colour, "size": size, "component": lay.component or "Shell",
                            "purpose": lay.purpose, "bundle_no": bundle_no, "body_no": body, "ply_from": ply_from, "ply_to": ply_to, "qty": qty, "shade_band": lay.shade_band,
                            "roll_nos": rolls, "kit_key": kit_key, "status": "Cut", "is_short": frappe.utils.cint(short)})
        d.insert(ignore_permissions=True)
        return d.name


    def make_bundles(lay):
        """Create the Cut Bundles of a submitted Lay Report. A paired (lining, pocketing) lay mirrors the ply ranges of its shell lay so every component of a garment
        carries the same ply number. Returns the bundle names."""
        cint = frappe.utils.cint
        card = lay.production_card
        size_bundle = cint(frappe.db.get_value("Production Card", card, "bundle_size")) or cint(setting("bundle_size")) or 20
        rolls = ", ".join([r.roll_no or r.batch for r in lay.rolls])
        names = []
        if lay.paired_with:
            src = frappe.get_all("Cut Bundle", filters={"lay_report": lay.paired_with, "status": ["!=", "Voided"]}, order_by="bundle_no",
                                 fields=["size", "body_no", "ply_from", "ply_to", "qty", "kit_key", "is_short", "bundle_no"])
            for b in src:
                names.append(new_bundle(lay, card, b.size, b.body_no, b.ply_from, b.ply_to, b.qty, rolls, b.kit_key, b.is_short, None))
            return names
        first = next_ply(card)
        plies = cint(lay.total_plies)
        last = first + plies - 1
        n = cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0])
        for s in lay.sizes:
            for body in range(1, max(cint(s.ratio), 1) + 1):
                for ab in chunks(first, last, size_bundle):
                    qty = ab[1] - ab[0] + 1
                    key = "%s|%s|%s-%s|%s" % (lay.colour, s.size, ab[0], ab[1], body)
                    n = n + 1
                    names.append(new_bundle(lay, card, s.size, body, ab[0], ab[1], qty, rolls, key, 1 if qty < size_bundle else 0, n))
        return names


    def void_bundles(lay_name):
        """Cancel of a lay: bundles are voided (their numbers are never reused). Blocked once any bundle left the cutting room."""
        moved = frappe.get_all("Cut Bundle", filters={"lay_report": lay_name, "status": ["not in", ("Cut", "Voided")]}, pluck="name")
        if moved:
            frappe.throw("Bundles %s have already left the cutting room. Take them back before cancelling the lay." % ", ".join(moved[:5]))
        for n in frappe.get_all("Cut Bundle", filters={"lay_report": lay_name}, pluck="name"):
            frappe.db.set_value("Cut Bundle", n, "status", "Voided", update_modified=False)


    def kit_missing(bundle_names):
        """For shell bundles about to go to a line: the kit keys whose lining / pocketing bundles are missing."""
        missing = []
        for n in bundle_names:
            b = frappe.db.get_value("Cut Bundle", n, ["production_card", "colour", "component", "kit_key"], as_dict=True)
            if b.component != "Shell":
                continue
            for comp in required_components(b.production_card, b.colour):
                if comp == "Shell":
                    continue
                if not frappe.db.exists("Cut Bundle", {"production_card": b.production_card, "kit_key": b.kit_key, "component": comp, "status": ["!=", "Voided"]}):
                    missing.append("%s (%s)" % (b.kit_key, comp))
        return missing


    def make_transfer(company, rows, kind, card, remarks, submit):
        """Material Transfer for `rows` = dicts(item_code, qty, s_warehouse, t_warehouse, batch_no). Returns the name, or None when nothing moves.
        The entry is tagged with the production card and the kind so reports can sum it."""
        rows = [r for r in rows if frappe.utils.flt(r.get("qty")) > 0]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = company
        se.apparel_production_card = card
        se.apparel_issue_kind = kind
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": r["s_warehouse"], "t_warehouse": r["t_warehouse"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = remarks
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_entry(name):
        if name and frappe.db.exists("Stock Entry", name):
            d = frappe.get_doc("Stock Entry", name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc("Stock Entry", name, ignore_permissions=True, force=True)


    def moved_qty(card, kind, item_code):
        """Quantity moved by submitted entries of this kind for a production card (optionally one item)."""
        cond = ""
        args = [card, kind]
        if item_code:
            cond = " and d.item_code = %s"
            args.append(item_code)
        return frappe.utils.flt(frappe.db.sql("select ifnull(sum(d.qty), 0) from `tabStock Entry Detail` d join `tabStock Entry` s on s.name = d.parent "
                                              "where s.docstatus = 1 and s.apparel_production_card = %s and s.apparel_issue_kind = %s" + cond, tuple(args))[0][0])


    def refresh_issued(card):
        """Write the issued metres onto the fabric rows of an issued card."""
        done = []
        for row in frappe.get_all("Production Card Fabric", filters={"parent": card}, fields=["name", "fabric_item"], order_by="idx"):
            if not row.fabric_item or row.fabric_item in done:
                continue
            done.append(row.fabric_item)
            frappe.db.set_value("Production Card Fabric", row.name, "issued_m", moved_qty(card, "Fabric Issue", row.fabric_item), update_modified=False)


    def issue_fabric_entry(card_name, rolls):
        """Issue rolls from the fabric store to Cutting WIP. rolls = [{batch_no, qty}]. Only accepted rolls leave the store."""
        card = frappe.get_doc("Production Card", card_name)
        if card.docstatus != 1:
            frappe.throw("Issue the production card first.")
        if not rolls:
            frappe.throw("Choose at least one roll to issue.")
        src = setting("store_warehouse_fabric")
        dst = setting("cutting_wip_warehouse")
        if not src or not dst:
            frappe.throw("Set the fabric store and Cutting WIP warehouses in Apparel Settings.")
        items = []
        fabrics = [f.fabric_item for f in card.fabrics]
        for r in rolls:
            b = frappe.db.get_value("Batch", r["batch_no"], ["item", "apparel_inspection_status", "apparel_roll_no"], as_dict=True)
            if not b:
                frappe.throw("Roll %s not found." % r["batch_no"])
            if b.apparel_inspection_status not in OK_STATUS:
                frappe.throw("Roll %s is %s. Only accepted rolls can be issued to cutting." % (b.apparel_roll_no or r["batch_no"], b.apparel_inspection_status or "not inspected"))
            if b.item not in fabrics:
                frappe.throw("Roll %s is %s, which is not a fabric of production card %s." % (b.apparel_roll_no or r["batch_no"], b.item, card.name))
            if frappe.utils.flt(r.get("qty")) <= 0:
                frappe.throw("Roll %s: enter the metres to issue (above zero)." % (b.apparel_roll_no or r["batch_no"]))
            items.append({"item_code": b.item, "qty": frappe.utils.flt(r["qty"]), "s_warehouse": src, "t_warehouse": dst, "batch_no": r["batch_no"]})
        name = make_transfer(card.company, items, "Fabric Issue", card.name, "Fabric issued to cutting for %s" % card.name, True)
        refresh_issued(card.name)
        return name
    cint = frappe.utils.cint
    card = frappe.db.get_value("Production Card", doc.production_card, ["company", "sales_order", "style_item", "status"], as_dict=True)
    override = bool(cint(doc.gate_override) and (doc.gate_override_reason or "").strip())
    rows = []
    if doc.component == "Shell":      # the garment count follows the shell fabric
        for s in doc.sizes:
            rows.append({"stage": "CUT", "colour": doc.colour, "size": s.size, "qty": cint(s.pieces_cut), "purpose": doc.purpose, "shade_band": doc.shade_band, "line": doc.line, "source_row": s.name})
        for r in doc.panel_rejects:
            rows.append({"stage": "CUT_REJECT", "colour": doc.colour, "size": r.size, "qty": cint(r.qty), "purpose": doc.purpose, "shade_band": doc.shade_band, "fault_source": r.fault_source,
                         "source_row": r.name})
    run_script("arinox_engine", action="post", card=doc.production_card, rows=json.dumps(rows), source_doctype="Lay Report", source_name=doc.name, posting_date=str(doc.lay_date),
               override=1 if override else 0, check=1)
    make_bundles(doc)
    wh_cut = setting("cutting_wip_warehouse")
    wh_store = setting("store_warehouse_fabric")
    if wh_cut and wh_store:
        back = [{"item_code": doc.fabric_item, "qty": frappe.utils.flt(r.balance_returned_m), "s_warehouse": wh_cut, "t_warehouse": wh_store, "batch_no": r.batch}
                for r in doc.rolls if frappe.utils.flt(r.balance_returned_m) > 0]
        name = make_transfer(card.company, back, "Remnant Return", doc.production_card, "Remnants of %s" % doc.name, True)
        if name:
            doc.db_set("remnant_entry", name)
    if frappe.db.get_value("Production Card", doc.production_card, "status") == "Issued":
        frappe.db.set_value("Production Card", doc.production_card, "status", "In Cutting", update_modified=False)
    if doc.purpose == "Re-cut" and doc.recut_request:
        frappe.db.set_value("Recut Request", doc.recut_request, "status", "Cut")
    if doc.purpose == "Bulk" and doc.component == "Shell":
        stamp_safe(card.sales_order, card.style_item, doc.colour, "PCD", doc.lay_date, "Lay Report", doc.name, False, False)


run(doc)

# Lay Report, After Cancel: bundles voided (their numbers never reused; blocked once a bundle left the cutting room), ledger rows removed, remnant entry cancelled,
# a re-cut request is open again, the PCD stamp cleared.
def run(doc):
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from production/cutting.py and production/stock.py: roll suggestion for a cut plan, bundle numbering for a lay, kit components, and the Stock Entries
    # of the production floor (fabric issue, remnant return). Needs lib_mat.py (to_metres) for the cut plan only.
    OK_STATUS = ("Accepted", "Accepted by Lot")


    def setting(field):
        return frappe.db.get_single_value("Apparel Settings", field)


    def roll_available(batch, warehouse, item_code):
        """Metres of a roll (Batch) in a warehouse. 0 when the warehouse is unknown."""
        if not warehouse:
            return 0
        return frappe.utils.flt(frappe.call("erpnext.stock.doctype.batch.batch.get_batch_qty", batch_no=batch, warehouse=warehouse, item_code=item_code))


    def roll_info(batch):
        b = frappe.db.get_value("Batch", batch, ["item", "apparel_roll_no", "apparel_dye_lot", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status",
                                                  "apparel_shrinkage_warp_pct", "apparel_shrinkage_weft_pct"], as_dict=True)
        if not b:
            frappe.throw("Roll %s not found." % batch)
        return b


    def required_components(card, colour):
        """Fabric roles that make up a garment of this colour on the production card (Shell, Lining, ...)."""
        roles = frappe.get_all("Production Card Fabric", filters={"parent": card, "colour": colour}, pluck="material_role")
        out = []
        for r in (roles or ["Shell"]):
            if r not in out:
                out.append(r)
        return sorted(out)


    def suggest_rolls(plan_name):
        """Allocate the rolls in the Cutting WIP warehouse to the lays of a cut plan: group by shade band, then width, then longest roll first. Nothing is saved."""
        flt = frappe.utils.flt
        plan = frappe.get_doc("Cut Plan", plan_name)
        wh = setting("cutting_wip_warehouse")
        pool = []
        for b in frappe.get_all("Batch", filters={"item": plan.fabric_item, "disabled": 0},
                                fields=["name", "apparel_roll_no", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status", "apparel_dye_lot"]):
            if b.apparel_inspection_status not in OK_STATUS:
                continue
            avail = roll_available(b.name, wh, plan.fabric_item)
            if avail > 0:
                pool.append({"batch": b.name, "roll_no": b.apparel_roll_no, "shade": b.apparel_shade_band or "", "width": flt(b.apparel_width_cm), "length": avail, "dye_lot": b.apparel_dye_lot})
        out = []
        short = []
        spread = flt(setting("max_width_spread_cm") or 1)
        for lay in sorted(plan.lays, key=lambda l: l.lay_no):
            need = flt(lay.planned_plies) * flt(lay.marker_length_m)
            cands = [r for r in pool if (not (lay.shade_band or "").strip() or r["shade"] == lay.shade_band)
                     and (not flt(lay.width_group_cm) or abs(r["width"] - flt(lay.width_group_cm)) <= spread)
                     and (not flt(lay.marker_width_cm) or not r["width"] or r["width"] >= flt(lay.marker_width_cm))]
            if not (lay.shade_band or "").strip() and cands:    # no shade named: keep to the shade band of the longest roll
                first = sorted(cands, key=lambda r: -r["length"])[0]
                cands = [r for r in cands if r["shade"] == first["shade"] and abs(r["width"] - first["width"]) <= spread]
            cands = sorted(cands, key=lambda r: -r["length"])
            taken = []
            got = 0.0
            for r in cands:
                if got >= need - 1e-9:
                    break
                use = min(r["length"], need - got)
                plies = int(frappe.utils.floor(use / flt(lay.marker_length_m))) if flt(lay.marker_length_m) else 0
                if plies <= 0:
                    continue
                metres = plies * flt(lay.marker_length_m)
                taken.append({"batch": r["batch"], "roll_no": r["roll_no"], "plies": plies, "metres": round(metres, 3), "shade": r["shade"], "width": r["width"]})
                got = got + metres
                r["length"] = r["length"] - metres
            out.append({"lay_no": lay.lay_no, "needed_m": round(need, 3), "allocated_m": round(got, 3), "rolls": taken})
            if got < need - 1e-9:
                short.append({"lay_no": lay.lay_no, "short_m": round(need - got, 3)})
        left = [{"batch": r["batch"], "roll_no": r["roll_no"], "metres": round(r["length"], 3), "shade": r["shade"]} for r in pool if r["length"] > 1e-9]
        return {"lays": out, "unallocated": left, "short": short}


    def next_ply(card):
        """First free ply number on a production card (sticker numbers never repeat on a card)."""
        return frappe.utils.cint(frappe.db.sql("select ifnull(max(ply_to), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1


    def chunks(first, last, size):
        """Ply ranges [[from, to], ...] of at most `size` plies covering first..last."""
        size = max(frappe.utils.cint(size), 1)
        out = []
        a = first
        while a <= last:
            b = min(a + size - 1, last)
            out.append([a, b])
            a = b + 1
        return out


    def new_bundle(lay, card, size, body, ply_from, ply_to, qty, rolls, kit_key, short, bundle_no):
        if bundle_no is None:
            bundle_no = frappe.utils.cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1
        d = frappe.get_doc({"doctype": "Cut Bundle", "production_card": card, "lay_report": lay.name, "colour": lay.colour, "size": size, "component": lay.component or "Shell",
                            "purpose": lay.purpose, "bundle_no": bundle_no, "body_no": body, "ply_from": ply_from, "ply_to": ply_to, "qty": qty, "shade_band": lay.shade_band,
                            "roll_nos": rolls, "kit_key": kit_key, "status": "Cut", "is_short": frappe.utils.cint(short)})
        d.insert(ignore_permissions=True)
        return d.name


    def make_bundles(lay):
        """Create the Cut Bundles of a submitted Lay Report. A paired (lining, pocketing) lay mirrors the ply ranges of its shell lay so every component of a garment
        carries the same ply number. Returns the bundle names."""
        cint = frappe.utils.cint
        card = lay.production_card
        size_bundle = cint(frappe.db.get_value("Production Card", card, "bundle_size")) or cint(setting("bundle_size")) or 20
        rolls = ", ".join([r.roll_no or r.batch for r in lay.rolls])
        names = []
        if lay.paired_with:
            src = frappe.get_all("Cut Bundle", filters={"lay_report": lay.paired_with, "status": ["!=", "Voided"]}, order_by="bundle_no",
                                 fields=["size", "body_no", "ply_from", "ply_to", "qty", "kit_key", "is_short", "bundle_no"])
            for b in src:
                names.append(new_bundle(lay, card, b.size, b.body_no, b.ply_from, b.ply_to, b.qty, rolls, b.kit_key, b.is_short, None))
            return names
        first = next_ply(card)
        plies = cint(lay.total_plies)
        last = first + plies - 1
        n = cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0])
        for s in lay.sizes:
            for body in range(1, max(cint(s.ratio), 1) + 1):
                for ab in chunks(first, last, size_bundle):
                    qty = ab[1] - ab[0] + 1
                    key = "%s|%s|%s-%s|%s" % (lay.colour, s.size, ab[0], ab[1], body)
                    n = n + 1
                    names.append(new_bundle(lay, card, s.size, body, ab[0], ab[1], qty, rolls, key, 1 if qty < size_bundle else 0, n))
        return names


    def void_bundles(lay_name):
        """Cancel of a lay: bundles are voided (their numbers are never reused). Blocked once any bundle left the cutting room."""
        moved = frappe.get_all("Cut Bundle", filters={"lay_report": lay_name, "status": ["not in", ("Cut", "Voided")]}, pluck="name")
        if moved:
            frappe.throw("Bundles %s have already left the cutting room. Take them back before cancelling the lay." % ", ".join(moved[:5]))
        for n in frappe.get_all("Cut Bundle", filters={"lay_report": lay_name}, pluck="name"):
            frappe.db.set_value("Cut Bundle", n, "status", "Voided", update_modified=False)


    def kit_missing(bundle_names):
        """For shell bundles about to go to a line: the kit keys whose lining / pocketing bundles are missing."""
        missing = []
        for n in bundle_names:
            b = frappe.db.get_value("Cut Bundle", n, ["production_card", "colour", "component", "kit_key"], as_dict=True)
            if b.component != "Shell":
                continue
            for comp in required_components(b.production_card, b.colour):
                if comp == "Shell":
                    continue
                if not frappe.db.exists("Cut Bundle", {"production_card": b.production_card, "kit_key": b.kit_key, "component": comp, "status": ["!=", "Voided"]}):
                    missing.append("%s (%s)" % (b.kit_key, comp))
        return missing


    def make_transfer(company, rows, kind, card, remarks, submit):
        """Material Transfer for `rows` = dicts(item_code, qty, s_warehouse, t_warehouse, batch_no). Returns the name, or None when nothing moves.
        The entry is tagged with the production card and the kind so reports can sum it."""
        rows = [r for r in rows if frappe.utils.flt(r.get("qty")) > 0]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = company
        se.apparel_production_card = card
        se.apparel_issue_kind = kind
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": r["s_warehouse"], "t_warehouse": r["t_warehouse"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = remarks
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_entry(name):
        if name and frappe.db.exists("Stock Entry", name):
            d = frappe.get_doc("Stock Entry", name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc("Stock Entry", name, ignore_permissions=True, force=True)


    def moved_qty(card, kind, item_code):
        """Quantity moved by submitted entries of this kind for a production card (optionally one item)."""
        cond = ""
        args = [card, kind]
        if item_code:
            cond = " and d.item_code = %s"
            args.append(item_code)
        return frappe.utils.flt(frappe.db.sql("select ifnull(sum(d.qty), 0) from `tabStock Entry Detail` d join `tabStock Entry` s on s.name = d.parent "
                                              "where s.docstatus = 1 and s.apparel_production_card = %s and s.apparel_issue_kind = %s" + cond, tuple(args))[0][0])


    def refresh_issued(card):
        """Write the issued metres onto the fabric rows of an issued card."""
        done = []
        for row in frappe.get_all("Production Card Fabric", filters={"parent": card}, fields=["name", "fabric_item"], order_by="idx"):
            if not row.fabric_item or row.fabric_item in done:
                continue
            done.append(row.fabric_item)
            frappe.db.set_value("Production Card Fabric", row.name, "issued_m", moved_qty(card, "Fabric Issue", row.fabric_item), update_modified=False)


    def issue_fabric_entry(card_name, rolls):
        """Issue rolls from the fabric store to Cutting WIP. rolls = [{batch_no, qty}]. Only accepted rolls leave the store."""
        card = frappe.get_doc("Production Card", card_name)
        if card.docstatus != 1:
            frappe.throw("Issue the production card first.")
        if not rolls:
            frappe.throw("Choose at least one roll to issue.")
        src = setting("store_warehouse_fabric")
        dst = setting("cutting_wip_warehouse")
        if not src or not dst:
            frappe.throw("Set the fabric store and Cutting WIP warehouses in Apparel Settings.")
        items = []
        fabrics = [f.fabric_item for f in card.fabrics]
        for r in rolls:
            b = frappe.db.get_value("Batch", r["batch_no"], ["item", "apparel_inspection_status", "apparel_roll_no"], as_dict=True)
            if not b:
                frappe.throw("Roll %s not found." % r["batch_no"])
            if b.apparel_inspection_status not in OK_STATUS:
                frappe.throw("Roll %s is %s. Only accepted rolls can be issued to cutting." % (b.apparel_roll_no or r["batch_no"], b.apparel_inspection_status or "not inspected"))
            if b.item not in fabrics:
                frappe.throw("Roll %s is %s, which is not a fabric of production card %s." % (b.apparel_roll_no or r["batch_no"], b.item, card.name))
            if frappe.utils.flt(r.get("qty")) <= 0:
                frappe.throw("Roll %s: enter the metres to issue (above zero)." % (b.apparel_roll_no or r["batch_no"]))
            items.append({"item_code": b.item, "qty": frappe.utils.flt(r["qty"]), "s_warehouse": src, "t_warehouse": dst, "batch_no": r["batch_no"]})
        name = make_transfer(card.company, items, "Fabric Issue", card.name, "Fabric issued to cutting for %s" % card.name, True)
        refresh_issued(card.name)
        return name
    void_bundles(doc.name)
    run_script("arinox_engine", action="unpost", source_doctype="Lay Report", source_name=doc.name)
    if doc.remnant_entry:
        cancel_entry(doc.remnant_entry)
        doc.db_set("remnant_entry", None)
    if doc.purpose == "Re-cut" and doc.recut_request:
        frappe.db.set_value("Recut Request", doc.recut_request, "status", "Open")
    unstamp_safe("Lay Report", doc.name)


run(doc)

# Recut Request, Before Save: only rejected, not yet replaced pieces can be re-cut; a roll of a different shade needs a production manager's approval.
def run(doc):
    cint = frappe.utils.cint
    card = frappe.db.get_value("Production Card", doc.production_card, ["docstatus", "status"], as_dict=True)
    if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
        frappe.throw("Production card %s must be issued and open." % doc.production_card)
    if not frappe.db.exists("Production Card Line", {"parent": doc.production_card, "colour": doc.colour, "size": doc.size}):
        frappe.throw("%s %s is not on production card %s." % (doc.colour, doc.size, doc.production_card))
    if cint(doc.qty) <= 0:
        frappe.throw("Enter the quantity to re-cut.")
    stages = ("CUT_REJECT", "SEW_REJECT", "SC_BACK_REJECT_VENDOR", "SC_BACK_REJECT_FACTORY", "FIN_REJECT")
    lost = frappe.db.sql("select ifnull(sum(qty), 0) from `tabProduction Movement` where production_card=%s and colour=%s and size=%s and stage in %s",
                         (doc.production_card, doc.colour, doc.size, stages))[0][0]
    asked = cint(frappe.db.sql("select ifnull(sum(qty), 0) from `tabRecut Request` where production_card=%s and colour=%s and size=%s and docstatus=1 and name != %s",
                               (doc.production_card, doc.colour, doc.size, doc.name or ""))[0][0])
    if cint(doc.qty) > lost - asked:
        frappe.throw("Only %s %s %s pieces are rejected and not yet replaced; cannot re-cut %s." % (max(lost - asked, 0), doc.colour, doc.size, doc.qty))
    if doc.source_roll:
        original = None
        if doc.replaces_lay:
            original = frappe.db.get_value("Lay Report", doc.replaces_lay, "shade_band")
        if doc.replaces_bundle:
            original = frappe.db.get_value("Cut Bundle", doc.replaces_bundle, "shade_band") or original
        shade = frappe.db.get_value("Batch", doc.source_roll, "apparel_shade_band")
        if original and shade and shade != original:
            if not cint(doc.different_roll_approved):
                frappe.throw("Roll %s is shade %s but the original panels are shade %s. Cut from the same roll, or have a manager approve a different roll." % (doc.source_roll, shade, original))
            roles = frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
            if not [r for r in roles if r in ("Apparel Production Manager", "System Manager")]:
                frappe.throw("Only a production manager can approve a roll of a different shade.")
        if cint(doc.different_roll_approved):
            doc.approved_by = frappe.session.user


run(doc)

# Cut Bundle, Before Save: a bundle quantity cannot be changed; void the lay and cut it again.
def run(doc):
    if not doc.is_new() and doc.has_value_changed("qty") and doc.status != "Voided":
        frappe.throw("A bundle quantity cannot be changed. Void the lay and cut it again.")


run(doc)

# Operation Bulletin, Before Save: totals of the timed operations, the daily and hourly target from the working minutes and expected efficiency, the pitch time, balance flags.
def run(doc):
    # shared helpers from production/sewing.py and production/maths.py (sewing part): the active operation bulletin, the learning-curve day, targets, efficiency, DHU, RFT.
    def active_ob(style_item):
        """The Operation Bulletin in force for a style (newest Active one), or None."""
        rows = frappe.get_all("Operation Bulletin", filters={"style_item": style_item, "status": "Active"}, order_by="version desc, creation desc", limit=1,
                              fields=["name", "total_sam", "operators", "working_minutes", "expected_efficiency_pct"])
        return rows[0] if rows else None


    def learning_day(line, style_item, on_date):
        """Day number of a style on a line, counted from its first Line Input there (1 on the first day)."""
        first = frappe.db.sql("select min(i.input_date) from `tabLine Input` i join `tabProduction Card` c on c.name = i.production_card "
                              "where i.docstatus = 1 and i.line = %s and c.style_item = %s", (line, style_item))[0][0]
        if not first:
            return 1
        return max(frappe.utils.date_diff(frappe.utils.getdate(on_date), frappe.utils.getdate(first)) + 1, 1)


    def curve():
        return [[r.day_no, r.pct_of_target] for r in frappe.get_all("Learning Curve Day", filters={"parent": "Apparel Settings", "parentfield": "learning_curve"}, fields=["day_no", "pct_of_target"])]


    def day_target(operators, working_minutes, efficiency_pct, total_sam):
        """Garments per day = operators x working minutes x efficiency / SAM."""
        if not total_sam:
            return 0.0
        return float(operators) * float(working_minutes) * (float(efficiency_pct) / 100.0) / float(total_sam)


    def hour_target(operators, working_minutes, efficiency_pct, total_sam):
        if not working_minutes:
            return 0.0
        return day_target(operators, working_minutes, efficiency_pct, total_sam) / (float(working_minutes) / 60.0)


    def pcs_per_machine_per_day(working_minutes, efficiency_pct, total_sam):
        if not total_sam:
            return 0.0
        return float(working_minutes) * (float(efficiency_pct) / 100.0) / float(total_sam)


    def operation_target_per_hour(sam, efficiency_pct):
        if not sam:
            return 0.0
        return 60.0 * (float(efficiency_pct) / 100.0) / float(sam)


    def pct_of(numerator, denominator):
        d = float(denominator or 0)
        if not d:
            return None
        return float(numerator or 0) / d * 100.0


    def learning_factor(day_no, crv):
        """crv: list of [day_no, pct_of_target]. Day beyond the table uses the last row; no table = 100 %."""
        rows = sorted([[int(d[0]), float(d[1])] for d in (crv or [])])
        if not rows:
            return 1.0
        chosen = rows[0][1]
        for d in rows:
            if day_no >= d[0]:
                chosen = d[1]
        return chosen / 100.0


    def traffic_colour(defects, rules):
        """rules: list of [colour, defects_from]. The highest threshold reached wins; below all = Green."""
        chosen = "Green"
        best = -1
        for r in rules or []:
            if defects >= int(r[1]) and int(r[1]) > best:
                chosen = r[0]
                best = int(r[1])
        return chosen


    def meas_compute(rows):
        """Up to five readings per point; in tolerance only when every reading is."""
        flt = frappe.utils.flt
        for m in rows:
            readings = [flt(v) for v in (m.actual, m.reading_2, m.reading_3, m.reading_4, m.reading_5) if v not in (None, "")]
            if not readings or m.spec is None:
                m.deviation = 0
                m.in_tolerance = 0
                continue
            devs = [round(x - flt(m.spec), 3) for x in readings]
            m.deviation = max(devs, key=abs)
            lo = -abs(flt(m.tol_minus))
            hi = abs(flt(m.tol_plus))
            m.in_tolerance = 1 if len([d for d in devs if lo <= d <= hi]) == len(devs) else 0
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    BAND = 0.15       # an operation within +-15 % of the pitch time is balanced
    if cint(doc.operators) <= 0:
        frappe.throw("Enter the number of operators.")
    minutes = cint(doc.working_minutes) or cint(frappe.db.get_single_value("Apparel Settings", "work_minutes_per_day") or 480)
    eff = flt(doc.expected_efficiency_pct) or flt(frappe.db.get_single_value("Apparel Settings", "planned_efficiency_pct") or 65)
    doc.working_minutes = minutes
    doc.expected_efficiency_pct = eff
    timed = []
    for o in doc.operations:
        if flt(o.machine_sam) < 0 or flt(o.manual_sam) < 0:
            frappe.throw("Row %s: a time cannot be negative." % o.idx)
        if flt(o.machine_sam) + flt(o.manual_sam) > 0:
            timed.append(o)
    doc.operation_count = len(timed)
    doc.sewing_sam = round(sum([flt(o.machine_sam) for o in timed]), 3)
    doc.manual_sam = round(sum([flt(o.manual_sam) for o in timed]), 3)
    doc.total_sam = round(doc.sewing_sam + doc.manual_sam, 3)
    doc.target_per_day = round(day_target(doc.operators, minutes, eff, doc.total_sam), 2)
    doc.target_per_hour = round(hour_target(doc.operators, minutes, eff, doc.total_sam), 2)
    doc.pcs_per_machine = round(pcs_per_machine_per_day(minutes, eff, doc.total_sam), 4)
    doc.pitch_time = round(doc.total_sam / len(timed), 3) if timed else 0
    for o in doc.operations:
        sam = flt(o.machine_sam) + flt(o.manual_sam)
        if sam <= 0:
            o.target_per_hr = 0
            o.operators_needed = 0
            o.pitch_flag = ""
            continue
        o.target_per_hr = round(operation_target_per_hour(sam, eff), 2)
        o.operators_needed = round(doc.target_per_hour / o.target_per_hr, 2) if o.target_per_hr else 0
        o.pitch_flag = "Above" if sam > doc.pitch_time * (1 + BAND) else ("Below" if sam < doc.pitch_time * (1 - BAND) else "")


run(doc)

# Line Input, Before Save: the card is open; each bundle belongs to it, is loadable (cut, or back from a panel process), has the right purpose and returned from any "before sewing" process;
# the line is the allocated one (warning); the kit of lining / pocketing bundles is complete (warn or block by setting).
def run(doc):
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from shipping/common.py: the fields every stage document copies from its production card, the open-card rule, and T&A stamping. Needs lib_mat.py (stamp_safe).
    def card_context(production_card):
        c = frappe.db.get_value("Production Card", production_card, ["sales_order", "sales_contract", "customer", "style_item", "company", "status", "docstatus", "line"], as_dict=True)
        return c or {}


    def require_open_card(production_card):
        card = card_context(production_card)
        if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
            frappe.throw("Production card %s must be issued and open." % production_card)
        return card


    def settings_value(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        return default if v in (None, "") else v


    def stamp_card(card, code, date, source_doctype, source_name, colours, partial):
        """Stamp a T&A milestone for every colour of the card's order. Never raises: a T&A fault must not stop shipping."""
        c = card_context(card)
        if not colours:
            colours = []
            for r in frappe.get_all("Production Card Line", filters={"parent": card}, fields=["colour"]):
                if r.colour not in colours:
                    colours.append(r.colour)
            colours = sorted(colours)
        for colour in colours:
            stamp_safe(c.sales_order, c.style_item, colour, code, date, source_doctype, source_name, partial, False)
    # shared helpers from production/cutting.py and production/stock.py: roll suggestion for a cut plan, bundle numbering for a lay, kit components, and the Stock Entries
    # of the production floor (fabric issue, remnant return). Needs lib_mat.py (to_metres) for the cut plan only.
    OK_STATUS = ("Accepted", "Accepted by Lot")


    def setting(field):
        return frappe.db.get_single_value("Apparel Settings", field)


    def roll_available(batch, warehouse, item_code):
        """Metres of a roll (Batch) in a warehouse. 0 when the warehouse is unknown."""
        if not warehouse:
            return 0
        return frappe.utils.flt(frappe.call("erpnext.stock.doctype.batch.batch.get_batch_qty", batch_no=batch, warehouse=warehouse, item_code=item_code))


    def roll_info(batch):
        b = frappe.db.get_value("Batch", batch, ["item", "apparel_roll_no", "apparel_dye_lot", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status",
                                                  "apparel_shrinkage_warp_pct", "apparel_shrinkage_weft_pct"], as_dict=True)
        if not b:
            frappe.throw("Roll %s not found." % batch)
        return b


    def required_components(card, colour):
        """Fabric roles that make up a garment of this colour on the production card (Shell, Lining, ...)."""
        roles = frappe.get_all("Production Card Fabric", filters={"parent": card, "colour": colour}, pluck="material_role")
        out = []
        for r in (roles or ["Shell"]):
            if r not in out:
                out.append(r)
        return sorted(out)


    def suggest_rolls(plan_name):
        """Allocate the rolls in the Cutting WIP warehouse to the lays of a cut plan: group by shade band, then width, then longest roll first. Nothing is saved."""
        flt = frappe.utils.flt
        plan = frappe.get_doc("Cut Plan", plan_name)
        wh = setting("cutting_wip_warehouse")
        pool = []
        for b in frappe.get_all("Batch", filters={"item": plan.fabric_item, "disabled": 0},
                                fields=["name", "apparel_roll_no", "apparel_shade_band", "apparel_width_cm", "apparel_inspection_status", "apparel_dye_lot"]):
            if b.apparel_inspection_status not in OK_STATUS:
                continue
            avail = roll_available(b.name, wh, plan.fabric_item)
            if avail > 0:
                pool.append({"batch": b.name, "roll_no": b.apparel_roll_no, "shade": b.apparel_shade_band or "", "width": flt(b.apparel_width_cm), "length": avail, "dye_lot": b.apparel_dye_lot})
        out = []
        short = []
        spread = flt(setting("max_width_spread_cm") or 1)
        for lay in sorted(plan.lays, key=lambda l: l.lay_no):
            need = flt(lay.planned_plies) * flt(lay.marker_length_m)
            cands = [r for r in pool if (not (lay.shade_band or "").strip() or r["shade"] == lay.shade_band)
                     and (not flt(lay.width_group_cm) or abs(r["width"] - flt(lay.width_group_cm)) <= spread)
                     and (not flt(lay.marker_width_cm) or not r["width"] or r["width"] >= flt(lay.marker_width_cm))]
            if not (lay.shade_band or "").strip() and cands:    # no shade named: keep to the shade band of the longest roll
                first = sorted(cands, key=lambda r: -r["length"])[0]
                cands = [r for r in cands if r["shade"] == first["shade"] and abs(r["width"] - first["width"]) <= spread]
            cands = sorted(cands, key=lambda r: -r["length"])
            taken = []
            got = 0.0
            for r in cands:
                if got >= need - 1e-9:
                    break
                use = min(r["length"], need - got)
                plies = int(frappe.utils.floor(use / flt(lay.marker_length_m))) if flt(lay.marker_length_m) else 0
                if plies <= 0:
                    continue
                metres = plies * flt(lay.marker_length_m)
                taken.append({"batch": r["batch"], "roll_no": r["roll_no"], "plies": plies, "metres": round(metres, 3), "shade": r["shade"], "width": r["width"]})
                got = got + metres
                r["length"] = r["length"] - metres
            out.append({"lay_no": lay.lay_no, "needed_m": round(need, 3), "allocated_m": round(got, 3), "rolls": taken})
            if got < need - 1e-9:
                short.append({"lay_no": lay.lay_no, "short_m": round(need - got, 3)})
        left = [{"batch": r["batch"], "roll_no": r["roll_no"], "metres": round(r["length"], 3), "shade": r["shade"]} for r in pool if r["length"] > 1e-9]
        return {"lays": out, "unallocated": left, "short": short}


    def next_ply(card):
        """First free ply number on a production card (sticker numbers never repeat on a card)."""
        return frappe.utils.cint(frappe.db.sql("select ifnull(max(ply_to), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1


    def chunks(first, last, size):
        """Ply ranges [[from, to], ...] of at most `size` plies covering first..last."""
        size = max(frappe.utils.cint(size), 1)
        out = []
        a = first
        while a <= last:
            b = min(a + size - 1, last)
            out.append([a, b])
            a = b + 1
        return out


    def new_bundle(lay, card, size, body, ply_from, ply_to, qty, rolls, kit_key, short, bundle_no):
        if bundle_no is None:
            bundle_no = frappe.utils.cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0]) + 1
        d = frappe.get_doc({"doctype": "Cut Bundle", "production_card": card, "lay_report": lay.name, "colour": lay.colour, "size": size, "component": lay.component or "Shell",
                            "purpose": lay.purpose, "bundle_no": bundle_no, "body_no": body, "ply_from": ply_from, "ply_to": ply_to, "qty": qty, "shade_band": lay.shade_band,
                            "roll_nos": rolls, "kit_key": kit_key, "status": "Cut", "is_short": frappe.utils.cint(short)})
        d.insert(ignore_permissions=True)
        return d.name


    def make_bundles(lay):
        """Create the Cut Bundles of a submitted Lay Report. A paired (lining, pocketing) lay mirrors the ply ranges of its shell lay so every component of a garment
        carries the same ply number. Returns the bundle names."""
        cint = frappe.utils.cint
        card = lay.production_card
        size_bundle = cint(frappe.db.get_value("Production Card", card, "bundle_size")) or cint(setting("bundle_size")) or 20
        rolls = ", ".join([r.roll_no or r.batch for r in lay.rolls])
        names = []
        if lay.paired_with:
            src = frappe.get_all("Cut Bundle", filters={"lay_report": lay.paired_with, "status": ["!=", "Voided"]}, order_by="bundle_no",
                                 fields=["size", "body_no", "ply_from", "ply_to", "qty", "kit_key", "is_short", "bundle_no"])
            for b in src:
                names.append(new_bundle(lay, card, b.size, b.body_no, b.ply_from, b.ply_to, b.qty, rolls, b.kit_key, b.is_short, None))
            return names
        first = next_ply(card)
        plies = cint(lay.total_plies)
        last = first + plies - 1
        n = cint(frappe.db.sql("select ifnull(max(bundle_no), 0) from `tabCut Bundle` where production_card = %s", (card,))[0][0])
        for s in lay.sizes:
            for body in range(1, max(cint(s.ratio), 1) + 1):
                for ab in chunks(first, last, size_bundle):
                    qty = ab[1] - ab[0] + 1
                    key = "%s|%s|%s-%s|%s" % (lay.colour, s.size, ab[0], ab[1], body)
                    n = n + 1
                    names.append(new_bundle(lay, card, s.size, body, ab[0], ab[1], qty, rolls, key, 1 if qty < size_bundle else 0, n))
        return names


    def void_bundles(lay_name):
        """Cancel of a lay: bundles are voided (their numbers are never reused). Blocked once any bundle left the cutting room."""
        moved = frappe.get_all("Cut Bundle", filters={"lay_report": lay_name, "status": ["not in", ("Cut", "Voided")]}, pluck="name")
        if moved:
            frappe.throw("Bundles %s have already left the cutting room. Take them back before cancelling the lay." % ", ".join(moved[:5]))
        for n in frappe.get_all("Cut Bundle", filters={"lay_report": lay_name}, pluck="name"):
            frappe.db.set_value("Cut Bundle", n, "status", "Voided", update_modified=False)


    def kit_missing(bundle_names):
        """For shell bundles about to go to a line: the kit keys whose lining / pocketing bundles are missing."""
        missing = []
        for n in bundle_names:
            b = frappe.db.get_value("Cut Bundle", n, ["production_card", "colour", "component", "kit_key"], as_dict=True)
            if b.component != "Shell":
                continue
            for comp in required_components(b.production_card, b.colour):
                if comp == "Shell":
                    continue
                if not frappe.db.exists("Cut Bundle", {"production_card": b.production_card, "kit_key": b.kit_key, "component": comp, "status": ["!=", "Voided"]}):
                    missing.append("%s (%s)" % (b.kit_key, comp))
        return missing


    def make_transfer(company, rows, kind, card, remarks, submit):
        """Material Transfer for `rows` = dicts(item_code, qty, s_warehouse, t_warehouse, batch_no). Returns the name, or None when nothing moves.
        The entry is tagged with the production card and the kind so reports can sum it."""
        rows = [r for r in rows if frappe.utils.flt(r.get("qty")) > 0]
        if not rows:
            return None
        se = frappe.new_doc("Stock Entry")
        se.stock_entry_type = "Material Transfer"
        se.purpose = "Material Transfer"
        se.company = company
        se.apparel_production_card = card
        se.apparel_issue_kind = kind
        for r in rows:
            line = {"item_code": r["item_code"], "qty": r["qty"], "s_warehouse": r["s_warehouse"], "t_warehouse": r["t_warehouse"]}
            if r.get("batch_no"):
                line["batch_no"] = r["batch_no"]
                line["use_serial_batch_fields"] = 1
            se.append("items", line)
        se.remarks = remarks
        se.flags.ignore_permissions = True
        se.insert()
        if submit:
            se.submit()
        return se.name


    def cancel_entry(name):
        if name and frappe.db.exists("Stock Entry", name):
            d = frappe.get_doc("Stock Entry", name)
            d.flags.ignore_permissions = True
            if d.docstatus == 1:
                d.cancel()
            elif d.docstatus == 0:
                frappe.delete_doc("Stock Entry", name, ignore_permissions=True, force=True)


    def moved_qty(card, kind, item_code):
        """Quantity moved by submitted entries of this kind for a production card (optionally one item)."""
        cond = ""
        args = [card, kind]
        if item_code:
            cond = " and d.item_code = %s"
            args.append(item_code)
        return frappe.utils.flt(frappe.db.sql("select ifnull(sum(d.qty), 0) from `tabStock Entry Detail` d join `tabStock Entry` s on s.name = d.parent "
                                              "where s.docstatus = 1 and s.apparel_production_card = %s and s.apparel_issue_kind = %s" + cond, tuple(args))[0][0])


    def refresh_issued(card):
        """Write the issued metres onto the fabric rows of an issued card."""
        done = []
        for row in frappe.get_all("Production Card Fabric", filters={"parent": card}, fields=["name", "fabric_item"], order_by="idx"):
            if not row.fabric_item or row.fabric_item in done:
                continue
            done.append(row.fabric_item)
            frappe.db.set_value("Production Card Fabric", row.name, "issued_m", moved_qty(card, "Fabric Issue", row.fabric_item), update_modified=False)


    def issue_fabric_entry(card_name, rolls):
        """Issue rolls from the fabric store to Cutting WIP. rolls = [{batch_no, qty}]. Only accepted rolls leave the store."""
        card = frappe.get_doc("Production Card", card_name)
        if card.docstatus != 1:
            frappe.throw("Issue the production card first.")
        if not rolls:
            frappe.throw("Choose at least one roll to issue.")
        src = setting("store_warehouse_fabric")
        dst = setting("cutting_wip_warehouse")
        if not src or not dst:
            frappe.throw("Set the fabric store and Cutting WIP warehouses in Apparel Settings.")
        items = []
        fabrics = [f.fabric_item for f in card.fabrics]
        for r in rolls:
            b = frappe.db.get_value("Batch", r["batch_no"], ["item", "apparel_inspection_status", "apparel_roll_no"], as_dict=True)
            if not b:
                frappe.throw("Roll %s not found." % r["batch_no"])
            if b.apparel_inspection_status not in OK_STATUS:
                frappe.throw("Roll %s is %s. Only accepted rolls can be issued to cutting." % (b.apparel_roll_no or r["batch_no"], b.apparel_inspection_status or "not inspected"))
            if b.item not in fabrics:
                frappe.throw("Roll %s is %s, which is not a fabric of production card %s." % (b.apparel_roll_no or r["batch_no"], b.item, card.name))
            if frappe.utils.flt(r.get("qty")) <= 0:
                frappe.throw("Roll %s: enter the metres to issue (above zero)." % (b.apparel_roll_no or r["batch_no"]))
            items.append({"item_code": b.item, "qty": frappe.utils.flt(r["qty"]), "s_warehouse": src, "t_warehouse": dst, "batch_no": r["batch_no"]})
        name = make_transfer(card.company, items, "Fabric Issue", card.name, "Fabric issued to cutting for %s" % card.name, True)
        refresh_issued(card.name)
        return name
    cint = frappe.utils.cint
    card = require_open_card(doc.production_card)
    require = cint(frappe.db.get_single_value("Apparel Settings", "require_bundle_on_input"))
    seen = []
    for r in doc.bundles:
        if r.bundle:
            if r.bundle in seen:
                frappe.throw("Bundle %s appears twice." % r.bundle)
            seen.append(r.bundle)
            b = frappe.db.get_value("Cut Bundle", r.bundle, ["production_card", "colour", "size", "qty", "component", "shade_band", "status", "purpose", "sewn_qty"], as_dict=True)
            if not b or b.production_card != doc.production_card:
                frappe.throw("Row %s: bundle %s belongs to another production card." % (r.idx, r.bundle))
            if b.status not in ("Cut", "Back") and not (doc.docstatus == 1):
                frappe.throw("Row %s: bundle %s is %s; only cut bundles (or bundles back from a panel process) can be loaded." % (r.idx, r.bundle, b.status))
            if b.purpose != doc.purpose:
                frappe.throw("Row %s: bundle %s is a %s bundle; this input is %s." % (r.idx, r.bundle, b.purpose, doc.purpose))
            before = [p for p in frappe.get_all("Production Card Process", filters={"parent": doc.production_card, "position": "Before Sewing"}, fields=["subcontract_process", "colour"])
                      if not (p.colour or "").strip() or (p.colour or "").strip().upper() == (b.colour or "").strip().upper()]
            if before and b.status != "Back":
                frappe.throw("Row %s: bundle %s must go to %s and come back before it is loaded." % (r.idx, r.bundle, ", ".join([p.subcontract_process for p in before])))
            r.colour = b.colour
            r.size = b.size
            r.qty = b.qty
            r.component = b.component
            r.shade_band = b.shade_band
        elif require:
            frappe.throw("Row %s: choose the bundle (Apparel Settings asks for bundles on every line input)." % r.idx)
        else:
            if not (r.colour and r.size and cint(r.qty) > 0):
                frappe.throw("Row %s: enter colour, size and quantity." % r.idx)
            if not frappe.db.exists("Production Card Line", {"parent": doc.production_card, "colour": r.colour, "size": r.size}):
                frappe.throw("Row %s: %s %s is not on production card %s." % (r.idx, r.colour, r.size, doc.production_card))
    doc.total_qty = sum([cint(r.qty) for r in doc.bundles if (r.component or "Shell") == "Shell"])
    fa = frappe.db.get_value("Factory Allocation", {"sales_order": card.sales_order}, "name")
    if fa:
        lines = []
        for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": card.style_item}, fields=["line"]):
            if r.line and r.line not in lines:
                lines.append(r.line)
        if lines and doc.line not in lines and doc.docstatus == 0:
            frappe.msgprint("Line %s is not the line allocated to this style (%s)." % (doc.line, ", ".join(sorted(lines))), indicator="orange")
    mode = frappe.db.get_single_value("Apparel Settings", "kit_check") or "Warn"
    if mode != "Off":
        missing = kit_missing([r.bundle for r in doc.bundles if r.bundle])
        if missing:
            msg = "Matching lining / pocketing bundles are missing for: %s" % ", ".join(missing[:6])
            if mode == "Block":
                frappe.throw(msg)
            frappe.msgprint(msg, indicator="orange")


run(doc)

