# Daily Line Report, Before Save: manpower and time, every output row on an open card, the bundle (when asked), and efficiency from the operation bulletin:
# produced minutes = output x SAM, available minutes = workers x (shift + overtime - downtime); the target follows the learning curve.
def run(doc):
    # shared helpers from shipping/common.py: the fields every stage document copies from its production card, the open-card rule, and T&A stamping. Needs lib_mat.py (stamp_safe).
    def card_context(production_card):
        c = frappe.db.get_value("Production Card", production_card, ["sales_order", "sales_contract", "customer", "style_item", "company", "status", "docstatus", "line"], as_dict=True)
        return c or {}


    def require_open_card(production_card):
        card = card_context(production_card)
        if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
            frappe.throw("Production card %s must be issued and open." % production_card)
        return card


    def settings_value(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        return default if v in (None, "") else v


    def stamp_card(card, code, date, source_doctype, source_name, colours, partial):
        """Stamp a T&A milestone for every colour of the card's order. Never raises: a T&A fault must not stop shipping."""
        c = card_context(card)
        if not colours:
            colours = []
            for r in frappe.get_all("Production Card Line", filters={"parent": card}, fields=["colour"]):
                if r.colour not in colours:
                    colours.append(r.colour)
            colours = sorted(colours)
        for colour in colours:
            stamp_safe(c.sales_order, c.style_item, colour, code, date, source_doctype, source_name, partial, False)
    # shared helpers from production/sewing.py and production/maths.py (sewing part): the active operation bulletin, the learning-curve day, targets, efficiency, DHU, RFT.
    def active_ob(style_item):
        """The Operation Bulletin in force for a style (newest Active one), or None."""
        rows = frappe.get_all("Operation Bulletin", filters={"style_item": style_item, "status": "Active"}, order_by="version desc, creation desc", limit=1,
                              fields=["name", "total_sam", "operators", "working_minutes", "expected_efficiency_pct"])
        return rows[0] if rows else None


    def learning_day(line, style_item, on_date):
        """Day number of a style on a line, counted from its first Line Input there (1 on the first day)."""
        first = frappe.db.sql("select min(i.input_date) from `tabLine Input` i join `tabProduction Card` c on c.name = i.production_card "
                              "where i.docstatus = 1 and i.line = %s and c.style_item = %s", (line, style_item))[0][0]
        if not first:
            return 1
        return max(frappe.utils.date_diff(frappe.utils.getdate(on_date), frappe.utils.getdate(first)) + 1, 1)


    def curve():
        return [[r.day_no, r.pct_of_target] for r in frappe.get_all("Learning Curve Day", filters={"parent": "Apparel Settings", "parentfield": "learning_curve"}, fields=["day_no", "pct_of_target"])]


    def day_target(operators, working_minutes, efficiency_pct, total_sam):
        """Garments per day = operators x working minutes x efficiency / SAM."""
        if not total_sam:
            return 0.0
        return float(operators) * float(working_minutes) * (float(efficiency_pct) / 100.0) / float(total_sam)


    def hour_target(operators, working_minutes, efficiency_pct, total_sam):
        if not working_minutes:
            return 0.0
        return day_target(operators, working_minutes, efficiency_pct, total_sam) / (float(working_minutes) / 60.0)


    def pcs_per_machine_per_day(working_minutes, efficiency_pct, total_sam):
        if not total_sam:
            return 0.0
        return float(working_minutes) * (float(efficiency_pct) / 100.0) / float(total_sam)


    def operation_target_per_hour(sam, efficiency_pct):
        if not sam:
            return 0.0
        return 60.0 * (float(efficiency_pct) / 100.0) / float(sam)


    def pct_of(numerator, denominator):
        d = float(denominator or 0)
        if not d:
            return None
        return float(numerator or 0) / d * 100.0


    def learning_factor(day_no, crv):
        """crv: list of [day_no, pct_of_target]. Day beyond the table uses the last row; no table = 100 %."""
        rows = sorted([[int(d[0]), float(d[1])] for d in (crv or [])])
        if not rows:
            return 1.0
        chosen = rows[0][1]
        for d in rows:
            if day_no >= d[0]:
                chosen = d[1]
        return chosen / 100.0


    def traffic_colour(defects, rules):
        """rules: list of [colour, defects_from]. The highest threshold reached wins; below all = Green."""
        chosen = "Green"
        best = -1
        for r in rules or []:
            if defects >= int(r[1]) and int(r[1]) > best:
                chosen = r[0]
                best = int(r[1])
        return chosen


    def meas_compute(rows):
        """Up to five readings per point; in tolerance only when every reading is."""
        flt = frappe.utils.flt
        for m in rows:
            readings = [flt(v) for v in (m.actual, m.reading_2, m.reading_3, m.reading_4, m.reading_5) if v not in (None, "")]
            if not readings or m.spec is None:
                m.deviation = 0
                m.in_tolerance = 0
                continue
            devs = [round(x - flt(m.spec), 3) for x in readings]
            m.deviation = max(devs, key=abs)
            lo = -abs(flt(m.tol_minus))
            hi = abs(flt(m.tol_plus))
            m.in_tolerance = 1 if len([d for d in devs if lo <= d <= hi]) == len(devs) else 0
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    if cint(doc.operators_present) <= 0:
        frappe.throw("Enter the operators present.")
    if min(cint(doc.overtime_minutes), cint(doc.downtime_minutes), cint(doc.helpers_present)) < 0:
        frappe.throw("Overtime, downtime and helpers cannot be negative.")
    if cint(doc.downtime_minutes) and not doc.downtime_reason:
        frappe.throw("Choose the downtime reason.")
    if not doc.outputs:
        frappe.throw("Enter the output.")
    styles = {}
    order = []
    require_bundle = cint(frappe.db.get_single_value("Apparel Settings", "require_bundle_on_output"))
    for r in doc.outputs:
        if cint(r.qty) <= 0:
            frappe.throw("Row %s: enter a quantity above zero." % r.idx)
        card = frappe.db.get_value("Production Card", r.production_card, ["docstatus", "status", "style_item"], as_dict=True)
        if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
            frappe.throw("Row %s: production card %s must be issued and open." % (r.idx, r.production_card))
        if not frappe.db.exists("Production Card Line", {"parent": r.production_card, "colour": r.colour, "size": r.size}):
            frappe.throw("Row %s: %s %s is not on production card %s." % (r.idx, r.colour, r.size, r.production_card))
        sk = "s|" + card.style_item
        if sk not in styles:
            styles[sk] = 0
            order.append(card.style_item)
        styles[sk] = styles[sk] + cint(r.qty)
        if not r.bundle:
            if require_bundle:
                frappe.throw("Row %s: choose the bundle (Apparel Settings asks for bundles on output)." % r.idx)
            continue
        b = frappe.db.get_value("Cut Bundle", r.bundle, ["production_card", "colour", "size", "qty", "sewn_qty", "rejected_qty", "status", "line", "component"], as_dict=True)
        if not b or b.production_card != r.production_card or b.colour != r.colour or b.size != r.size:
            frappe.throw("Row %s: bundle %s is not %s %s of card %s." % (r.idx, r.bundle, r.colour, r.size, r.production_card))
        if b.status != "Issued" and doc.docstatus == 0:
            frappe.throw("Row %s: bundle %s is %s; only a bundle loaded on a line can be reported." % (r.idx, r.bundle, b.status))
        if b.line and b.line != doc.line:
            frappe.throw("Row %s: bundle %s is on line %s, not %s." % (r.idx, r.bundle, b.line, doc.line))
        if cint(b.sewn_qty) + cint(b.rejected_qty) + cint(r.qty) > cint(b.qty) and doc.docstatus == 0:
            frappe.throw("Row %s: bundle %s has %s pieces; %s already reported." % (r.idx, r.bundle, b.qty, cint(b.sewn_qty) + cint(b.rejected_qty)))

    first_style = order[0]
    ob = active_ob(first_style)
    settings_minutes = cint(frappe.db.get_single_value("Apparel Settings", "work_minutes_per_day") or 480)
    doc.shift_minutes = cint(doc.shift_minutes) or (cint(ob.working_minutes) if ob else 0) or settings_minutes
    worked = max(doc.shift_minutes + cint(doc.overtime_minutes) - cint(doc.downtime_minutes), 0)
    doc.total_output = sum([cint(r.qty) for r in doc.outputs])
    produced = 0.0
    missing = []
    for style in order:
        o = active_ob(style)
        if not o or not flt(o.total_sam):
            missing.append(style)
            continue
        produced = produced + styles["s|" + style] * flt(o.total_sam)
    doc.produced_minutes = round(produced, 2)
    workers = cint(doc.operators_present) + cint(doc.helpers_present)      # the OB total SAM includes helper time
    doc.available_minutes = round(workers * worked, 2)
    doc.efficiency_pct = round(pct_of(produced, doc.available_minutes) or 0, 2)
    if missing and doc.docstatus == 0:
        frappe.msgprint("No active Operation Bulletin for %s: efficiency cannot include its output." % ", ".join(missing), indicator="orange")
    eff_plan = flt(ob.expected_efficiency_pct) if ob and flt(ob.expected_efficiency_pct) else flt(frappe.db.get_single_value("Apparel Settings", "planned_efficiency_pct") or 65)
    doc.learning_day = learning_day(doc.line, first_style, doc.report_date)
    factor = learning_factor(doc.learning_day, curve())
    doc.learning_factor_pct = round(factor * 100, 2)
    doc.target_qty = round(day_target(workers, worked, eff_plan, flt(ob.total_sam)) * factor, 1) if ob and flt(ob.total_sam) else 0
    doc.variance_to_target = round(doc.total_output - flt(doc.target_qty), 1)
    hourly = sum([cint(h.output_qty) for h in doc.hours])
    if doc.hours and hourly != doc.total_output and doc.docstatus == 0:
        frappe.msgprint("The hourly output (%s) does not add up to the day's output (%s)." % (hourly, doc.total_output), indicator="orange")


run(doc)

# Daily Line Report, After Submit: SEW_OUT goes to the ledger per card, and the bundles move (sewn quantity, Complete when fully reported).
def run(doc):
    cint = frappe.utils.cint
    by_card = {}
    order = []
    for r in doc.outputs:
        k = "c|" + r.production_card
        if k not in by_card:
            by_card[k] = []
            order.append(r.production_card)
        by_card[k].append({"stage": "SEW_OUT", "colour": r.colour, "size": r.size, "qty": cint(r.qty), "purpose": r.purpose or "Bulk", "line": doc.line, "source_row": r.name})
    for card in order:
        run_script("arinox_engine", action="post", card=card, rows=json.dumps(by_card["c|" + card]), source_doctype="Daily Line Report", source_name=doc.name,
                   posting_date=str(doc.report_date), override=0, check=1)
    for r in doc.outputs:
        if r.bundle:
            b = frappe.db.get_value("Cut Bundle", r.bundle, ["qty", "sewn_qty", "rejected_qty"], as_dict=True)
            sewn = max(cint(b.sewn_qty) + cint(r.qty), 0)
            frappe.db.set_value("Cut Bundle", r.bundle, {"sewn_qty": sewn, "status": "Complete" if sewn + cint(b.rejected_qty) >= cint(b.qty) else "Issued"})


run(doc)

# Daily Line Report, After Cancel: the ledger rows go and the bundle quantities are taken back.
def run(doc):
    cint = frappe.utils.cint
    run_script("arinox_engine", action="unpost", source_doctype="Daily Line Report", source_name=doc.name)
    for r in doc.outputs:
        if r.bundle:
            b = frappe.db.get_value("Cut Bundle", r.bundle, ["qty", "sewn_qty", "rejected_qty"], as_dict=True)
            sewn = max(cint(b.sewn_qty) - cint(r.qty), 0)
            frappe.db.set_value("Cut Bundle", r.bundle, {"sewn_qty": sewn, "status": "Complete" if sewn + cint(b.rejected_qty) >= cint(b.qty) else "Issued"})


run(doc)

