    def traffic_colour(defects, rules):
        """rules: list of [colour, defects_from]. The highest threshold reached wins; below all = Green."""
        chosen = "Green"
        best = -1
        for r in rules or []:
            if defects >= int(r[1]) and int(r[1]) > best:
                chosen = r[0]
                best = int(r[1])
        return chosen


    def meas_compute(rows):
        """Up to five readings per point; in tolerance only when every reading is."""
        flt = frappe.utils.flt
        for m in rows:
            readings = [flt(v) for v in (m.actual, m.reading_2, m.reading_3, m.reading_4, m.reading_5) if v not in (None, "")]
            if not readings or m.spec is None:
                m.deviation = 0
                m.in_tolerance = 0
                continue
            devs = [round(x - flt(m.spec), 3) for x in readings]
            m.deviation = max(devs, key=abs)
            lo = -abs(flt(m.tol_minus))
            hi = abs(flt(m.tol_plus))
            m.in_tolerance = 1 if len([d for d in devs if lo <= d <= hi]) == len(devs) else 0
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    FINISH = "Finishing"
    INLINE = "Inline (Traffic Light)"
    card = frappe.db.get_value("Production Card", doc.production_card, ["docstatus", "status"], as_dict=True)
    if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
        frappe.throw("Production card %s must be issued and open." % doc.production_card)
    for h in doc.hours:
        if cint(h.checked) < 0 or cint(h.passed) < 0 or cint(h.passed) > cint(h.checked):
            frappe.throw("Hour %s: passed cannot be more than checked, and neither can be negative." % h.hour_slot)
    doc.total_checked = sum([cint(h.checked) for h in doc.hours])
    doc.total_passed = sum([cint(h.passed) for h in doc.hours])
    doc.total_defects = sum([cint(d.qty) for d in doc.defects])
    for d in doc.defects:
        if cint(d.qty) <= 0:
            frappe.throw("Defect %s: enter a quantity above zero." % d.defect_code)
    doc.dhu = round(pct_of(doc.total_defects, doc.total_checked) or 0, 2)
    doc.defect_pct = round(pct_of(doc.total_checked - doc.total_passed, doc.total_checked) or 0, 2)
    doc.rft_pct = round(pct_of(doc.total_passed, doc.total_checked) or 0, 2)
    if doc.dhu > flt(frappe.db.get_single_value("Apparel Settings", "dhu_alert_threshold") or 5) and doc.docstatus == 0:
        frappe.msgprint("DHU %s is above the alert level." % doc.dhu, indicator="orange")
    for r in doc.dispositions:
        r.production_card = doc.production_card
        if cint(r.qty) <= 0:
            frappe.throw("Disposition row %s: enter a quantity above zero." % r.idx)
        if not frappe.db.exists("Production Card Line", {"parent": doc.production_card, "colour": r.colour, "size": r.size}):
            frappe.throw("Disposition row %s: %s %s is not on production card %s." % (r.idx, r.colour, r.size, doc.production_card))
        if r.disposition == "B-Grade" and doc.audit_type != FINISH:
            frappe.throw("Disposition row %s: B-grade is decided at finishing, not at %s." % (r.idx, doc.audit_type))
        if cint(r.replace) and r.disposition != "Reject":
            frappe.throw("Disposition row %s: only a rejected piece needs a re-cut." % r.idx)
        if cint(r.replace) and not r.defect_code:
            frappe.throw("Disposition row %s: choose the defect to raise the re-cut request." % r.idx)
    if doc.audit_type == FINISH:
        total = sum([cint(p.qty) for p in doc.passes])
        for p in doc.passes:
            if not frappe.db.exists("Production Card Line", {"parent": doc.production_card, "colour": p.colour, "size": p.size}):
                frappe.throw("Passed row %s: %s %s is not on production card %s." % (p.idx, p.colour, p.size, doc.production_card))
        if doc.hours and total != doc.total_passed:
            frappe.throw("The A-grade pieces by colour and size (%s) must equal the pieces passed in the hourly check (%s)." % (total, doc.total_passed))
    rules = [[r.colour, r.defects_from] for r in frappe.get_all("Traffic Light Rule", filters={"parent": "Apparel Settings", "parentfield": "traffic_light_rules"}, fields=["colour", "defects_from"])]
    reds = 0
    for t in doc.traffic:
        t.light = traffic_colour(cint(t.defects), rules)
        reds = reds + (1 if t.light == "Red" else 0)
    if reds and doc.docstatus == 0:
        frappe.msgprint("%s operator(s) are red. Retrain or re-set the operation before the next round." % reds, indicator="red")


run(doc)

# Line QC Report, After Submit: A-grade passes (finishing), rejects and B-grade go to the ledger; a rejected piece marked "replace" raises a Recut Request.
def run(doc):
    cint = frappe.utils.cint
    rows = []
    if doc.audit_type == "Finishing":
        for p in doc.passes:
            rows.append({"stage": "FIN_A", "colour": p.colour, "size": p.size, "qty": cint(p.qty), "line": doc.line, "source_row": p.name})
    for r in doc.dispositions:
        stage = None
        if r.disposition == "Reject":
            stage = "FIN_REJECT" if doc.audit_type == "Finishing" else "SEW_REJECT"
        elif r.disposition == "B-Grade":
            stage = "FIN_B"
        if stage:
            rows.append({"stage": stage, "colour": r.colour, "size": r.size, "qty": cint(r.qty), "line": doc.line, "fault_source": r.fault_source, "source_row": r.name})
    run_script("arinox_engine", action="post", card=doc.production_card, rows=json.dumps(rows), source_doctype="Line QC Report", source_name=doc.name, posting_date=str(doc.report_date),
               override=0, check=1)
    wanted = {}
    order = []
    for r in doc.dispositions:
        if cint(r.replace) and r.disposition == "Reject":
            k = "%s|%s|%s" % (r.colour, r.size, r.defect_code)
            if k not in wanted:
                wanted[k] = 0
                order.append(k)
            wanted[k] = wanted[k] + cint(r.qty)
    for k in order:
        p = k.split("|")
        d = frappe.get_doc({"doctype": "Recut Request", "production_card": doc.production_card, "colour": p[0], "size": p[1], "qty": wanted[k], "reason": p[2], "remarks": "Raised by %s" % doc.name})
        d.flags.ignore_permissions = True
        try:
            d.insert()
        except Exception:
            frappe.log_error(title="Recut request from QC report failed", message=frappe.get_traceback())


run(doc)

# Pilot Run, Before Save: the card is open; the PP meeting was held first (when required); colours are on the card; the pilot pieces (cut, sewn, washed, rejected) are read
# from the ledger; measurements; achieved efficiency and bottlenecks from the operations.
def run(doc):
    # shared helpers: the sample-approval rules (defaults, Apparel Settings rows, Sample Requirement overrides), the split-PO exemption,
    # the style dates a due date is counted from, and the scope of the samples that apply to an order (sample_approval.py)
    APPROVED = ("Approved", "Approved with Comments")
    GATE_OK = ("Approved", "Approved with Comments", "Not Required")
    MANAGER_ROLES = ("Apparel Merchandising Manager", "System Manager")
    # type: (gate, per_colour, due_basis, days_offset); used until Apparel Settings has its own rule rows. Same values as the seeded table.
    DEFAULT_RULES = {
        "Proto": ("No", 0, "PCD", 90), "Fit": ("Required", 0, "PCD", 45), "Size Set": ("If Raised", 0, "PCD", 30), "Lab Dip": ("Required", 1, "PCD", 60),
        "Strike Off": ("If Raised", 1, "PCD", 60), "Desk Loom": ("If Raised", 1, "PCD", 60), "Bulk Fabric": ("Required", 1, "PCD", 25),
        "Bulk Trim": ("Required", 0, "PCD", 25), "PP": ("Required", 0, "PCD", 14), "Garment Test (GPT)": ("If Raised", 0, "PCD", 14),
        "TOP": ("No", 1, "Ex-Factory", 10), "Salesman": ("No", 0, "PCD", 30), "Photo Sample": ("No", 0, "PCD", 30),
        "Customer Sample": ("No", 0, "After Fit Approval", 10), "Fabric Test (FPT)": ("If Raised", 1, "PCD", 21),
    }


    def norm(colour):
        return (colour or "").strip().upper()


    def make_rule(gate="No", per_colour=0, due_basis="PCD", days_before=0, qty=0, sample_size=None, split_po_exempt=0, chargeback_amount=0):
        return {"gate": gate or "No", "per_colour": frappe.utils.cint(per_colour), "due_basis": due_basis or "PCD", "days_before": frappe.utils.cint(days_before),
                "qty": frappe.utils.cint(qty), "sample_size": sample_size, "split_po_exempt": frappe.utils.cint(split_po_exempt),
                "chargeback_amount": frappe.utils.flt(chargeback_amount)}


    def get_rules(customer, sales_order, style_item):
        """sample type -> rule. Defaults, then Apparel Settings rows, then Sample Requirement overrides. Overrides are scoped to a customer,
        an order and/or a style; the most specific one wins field by field. A blank field in an override keeps the value below it."""
        rules = {}
        for t in DEFAULT_RULES:
            d = DEFAULT_RULES[t]
            rules[t] = make_rule(d[0], d[1], d[2], d[3])
        for r in frappe.get_all("Apparel Sample Rule", filters={"parent": "Apparel Settings", "parenttype": "Apparel Settings"}, order_by="idx asc",
                                fields=["sample_type", "gate", "per_colour", "due_basis", "days_before", "qty", "sample_size", "split_po_exempt", "chargeback_amount"]):
            rules[r.sample_type] = make_rule(r.gate, r.per_colour, r.due_basis, r.days_before, r.qty, r.sample_size, r.split_po_exempt, r.chargeback_amount)
        if sales_order and not customer:
            customer = frappe.db.get_value("Sales Order", sales_order, "customer")
        scored = []
        for q in frappe.get_all("Sample Requirement", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("sales_order", sales_order, 4), ("style_item", style_item, 2), ("customer", customer, 1)):
                if q.get(field):
                    if q.get(field) != value:
                        score = None
                        break
                    score += weight
            if score:
                scored.append([score, q])
        for entry in sorted(scored, key=lambda x: x[0]):
            q = entry[1]
            rule = rules.get(q.sample_type)
            if not rule:
                rule = make_rule()
                rules[q.sample_type] = rule
            if q.gate:
                rule["gate"] = q.gate
            if q.per_colour:
                rule["per_colour"] = 1 if q.per_colour == "Yes" else 0
            if q.due_basis:   # basis and offset travel together
                rule["due_basis"] = q.due_basis
                rule["days_before"] = frappe.utils.cint(q.days_before)
            if frappe.utils.cint(q.qty):
                rule["qty"] = frappe.utils.cint(q.qty)
            if q.sample_size:
                rule["sample_size"] = q.sample_size
            if frappe.utils.cint(q.split_po_exempt):
                rule["split_po_exempt"] = 1
            if frappe.utils.flt(q.chargeback_amount):
                rule["chargeback_amount"] = frappe.utils.flt(q.chargeback_amount)
        return rules


    def is_split_po(sales_order):
        """An order that ships to more than one destination."""
        dests = []
        for d in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, pluck="apparel_ship_to"):
            if (d or "").strip() and (d or "").strip().upper() not in dests:
                dests.append((d or "").strip().upper())
        return len(dests) > 1


    def effective_gate(rule, sales_order):
        """The gate after the split-PO exemption."""
        if rule["gate"] != "No" and rule["split_po_exempt"] and sales_order and is_split_po(sales_order):
            return "No"
        return rule["gate"]


    def scope_filters(sales_order, style_item):
        """Samples that apply to this order: this Sales Order's, or ones raised before any order existed."""
        return {"style_item": style_item, "sales_order": ["in", [sales_order, "", None]]}


    def get_style_dates(sales_order, style_item, colour):
        """[PCD, ex-factory, in-warehouse] for a style x colour. PCD from the Factory Allocation, then the contract line; the others from the Sales Order lines."""
        pcd = None
        ex_factory = None
        in_warehouse = None
        if not sales_order:
            return [pcd, ex_factory, in_warehouse]
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if not pcd and contract:
            for r in frappe.get_all("Sales Contract Item", filters={"parent": contract, "style_item": style_item}, fields=["colour", "pcd"], order_by="pcd"):
                if r.pcd and (not colour or norm(r.colour) == norm(colour)):
                    pcd = r.pcd
                    break
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, order_by="delivery_date",
                                 fields=["item_code", "apparel_colour", "delivery_date", "apparel_in_warehouse_date"]):
            if frappe.db.get_value("Item", it.item_code, "variant_of") == style_item or it.item_code == style_item:
                if colour and norm(it.apparel_colour) != norm(colour):
                    continue
                ex_factory = ex_factory or it.delivery_date
                in_warehouse = in_warehouse or it.apparel_in_warehouse_date
                if ex_factory and in_warehouse:
                    break
        return [pcd, ex_factory, in_warehouse]


    def fit_approved_on(sales_order, style_item):
        """Latest approval date of the Fit samples of this style that apply to the order."""
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = "Fit"
        f["status"] = ["in", list(APPROVED)]
        rows = [r for r in frappe.get_all("Sample Approval", filters=f, pluck="approved_on") if r]
        return max(rows) if rows else None
    # shared helpers from pp_meeting.py: the departments that must attend, the buyer comments still open on a style, and the open cutting actions
    def required_departments(meeting_type, is_washed):
        """Departments that must attend, from Apparel Settings (one per line). Washing joins when the garment is washed."""
        field = "pilot_required_departments" if meeting_type == "Pilot Run" else "pp_required_departments"
        default = "Cutting\nSewing\nQC\nCAD" if meeting_type == "Pilot Run" else "Planning\nPurchasing\nCutting\nSewing\nQC"
        names = [d.strip() for d in (frappe.db.get_single_value("Apparel Settings", field) or default).splitlines() if d.strip()]
        if frappe.utils.cint(is_washed) and meeting_type != "Pilot Run" and "Washing" not in names:
            names.append("Washing")
        return names


    def open_buyer_comments(sales_order, style_item):
        """Open comments on every sample of this style that applies to the order (each a dict)."""
        rows = []
        for s in frappe.get_all("Sample Approval", filters=scope_filters(sales_order, style_item), fields=["name", "sample_type", "colour"]):
            for c in frappe.get_all("Sample Approval Comment", filters={"parent": s.name, "parenttype": "Sample Approval", "status": "Open"},
                                    fields=["name", "category", "comment", "relevant_to_cutting"]):
                d = dict(c)
                d["sample_approval"] = s.name
                d["sample_type"] = s.sample_type
                d["colour"] = s.colour
                rows.append(d)
        return rows


    def cutting_actions_open(sales_order, style_item):
        """[PP meetings held, open cutting-related actions]. Actions of pilot runs count too; only a PP Meeting counts as the meeting being held."""
        open_rows = []
        all_meetings = frappe.get_all("PP Meeting", filters={"sales_order": sales_order, "style_item": style_item, "docstatus": 1}, fields=["name", "meeting_type"])
        meetings = [m for m in all_meetings if m.meeting_type == "PP Meeting"]
        for m in all_meetings:
            open_rows = open_rows + frappe.get_all("PP Meeting Action", filters={"parent": m.name, "relevant_to_cutting": 1, "status": "Open"}, fields=["comment"])
        return [meetings, open_rows]
    # shared helpers from production/sewing.py and production/maths.py (sewing part): the active operation bulletin, the learning-curve day, targets, efficiency, DHU, RFT.
    def active_ob(style_item):
        """The Operation Bulletin in force for a style (newest Active one), or None."""
        rows = frappe.get_all("Operation Bulletin", filters={"style_item": style_item, "status": "Active"}, order_by="version desc, creation desc", limit=1,
                              fields=["name", "total_sam", "operators", "working_minutes", "expected_efficiency_pct"])
        return rows[0] if rows else None


    def learning_day(line, style_item, on_date):
        """Day number of a style on a line, counted from its first Line Input there (1 on the first day)."""
        first = frappe.db.sql("select min(i.input_date) from `tabLine Input` i join `tabProduction Card` c on c.name = i.production_card "
                              "where i.docstatus = 1 and i.line = %s and c.style_item = %s", (line, style_item))[0][0]
        if not first:
            return 1
        return max(frappe.utils.date_diff(frappe.utils.getdate(on_date), frappe.utils.getdate(first)) + 1, 1)


    def curve():
        return [[r.day_no, r.pct_of_target] for r in frappe.get_all("Learning Curve Day", filters={"parent": "Apparel Settings", "parentfield": "learning_curve"}, fields=["day_no", "pct_of_target"])]


    def day_target(operators, working_minutes, efficiency_pct, total_sam):
        """Garments per day = operators x working minutes x efficiency / SAM."""
        if not total_sam:
            return 0.0
        return float(operators) * float(working_minutes) * (float(efficiency_pct) / 100.0) / float(total_sam)


    def hour_target(operators, working_minutes, efficiency_pct, total_sam):
        if not working_minutes:
            return 0.0
        return day_target(operators, working_minutes, efficiency_pct, total_sam) / (float(working_minutes) / 60.0)


    def pcs_per_machine_per_day(working_minutes, efficiency_pct, total_sam):
        if not total_sam:
            return 0.0
        return float(working_minutes) * (float(efficiency_pct) / 100.0) / float(total_sam)


    def operation_target_per_hour(sam, efficiency_pct):
        if not sam:
            return 0.0
        return 60.0 * (float(efficiency_pct) / 100.0) / float(sam)


    def pct_of(numerator, denominator):
        d = float(denominator or 0)
        if not d:
            return None
        return float(numerator or 0) / d * 100.0


    def learning_factor(day_no, crv):
        """crv: list of [day_no, pct_of_target]. Day beyond the table uses the last row; no table = 100 %."""
        rows = sorted([[int(d[0]), float(d[1])] for d in (crv or [])])
        if not rows:
            return 1.0
        chosen = rows[0][1]
        for d in rows:
            if day_no >= d[0]:
                chosen = d[1]
        return chosen / 100.0


    def traffic_colour(defects, rules):
        """rules: list of [colour, defects_from]. The highest threshold reached wins; below all = Green."""
        chosen = "Green"
        best = -1
        for r in rules or []:
            if defects >= int(r[1]) and int(r[1]) > best:
                chosen = r[0]
                best = int(r[1])
        return chosen


    def meas_compute(rows):
        """Up to five readings per point; in tolerance only when every reading is."""
        flt = frappe.utils.flt
        for m in rows:
            readings = [flt(v) for v in (m.actual, m.reading_2, m.reading_3, m.reading_4, m.reading_5) if v not in (None, "")]
            if not readings or m.spec is None:
                m.deviation = 0
                m.in_tolerance = 0
                continue
            devs = [round(x - flt(m.spec), 3) for x in readings]
            m.deviation = max(devs, key=abs)
            lo = -abs(flt(m.tol_minus))
            hi = abs(flt(m.tol_plus))
            m.in_tolerance = 1 if len([d for d in devs if lo <= d <= hi]) == len(devs) else 0
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    card = frappe.db.get_value("Production Card", doc.production_card, ["docstatus", "status", "sales_order", "style_item"], as_dict=True)
    if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
        frappe.throw("Production card %s must be issued and open." % doc.production_card)
    if frappe.db.get_single_value("Apparel Settings", "require_pp_meeting") and doc.is_new():
        held = cutting_actions_open(card.sales_order, card.style_item)
        if not held[0]:
            frappe.throw("The PP Meeting for this style has not been held yet. A pilot run follows the PP meeting.")
    card_colours = [(l.colour or "").strip().upper() for l in frappe.get_all("Production Card Line", filters={"parent": doc.production_card}, fields=["colour"])]
    seen = []
    for r in doc.colours:
        key = (r.colour or "").strip().upper()
        if key not in card_colours:
            frappe.throw("Row %s: colour %s is not on production card %s." % (r.idx, r.colour, doc.production_card))
        if key in seen:
            frappe.throw("Colour %s appears twice." % r.colour)
        seen.append(key)

    def total(colour, stages, process):
        cond = " and subcontract_process = %s" if process else ""
        args = [doc.production_card, colour, "Pilot", tuple(stages)] + ([process] if process else [])
        return cint(frappe.db.sql("select ifnull(sum(qty),0) from `tabProduction Movement` where production_card=%s and colour=%s and purpose=%s and stage in %s" + cond, tuple(args))[0][0])

    for r in doc.colours:
        r.cut_qty = total(r.colour, ["CUT"], None) - total(r.colour, ["CUT_REJECT"], None)
        r.sewn_qty = total(r.colour, ["SEW_OUT"], None)
        r.washed_qty = total(r.colour, ["SC_BACK_GOOD"], "Wash")
        r.rejected_qty = total(r.colour, ["CUT_REJECT", "SEW_REJECT", "SC_BACK_REJECT_VENDOR", "SC_BACK_REJECT_FACTORY", "FIN_REJECT"], None)
    meas_compute(doc.measurements)
    actual = sum([flt(o.actual_sam) for o in doc.operations if flt(o.actual_sam)])
    timed = sum([flt(o.planned_sam) for o in doc.operations if flt(o.actual_sam)])
    doc.achieved_efficiency_pct = round(timed / actual * 100, 2) if actual else 0
    doc.bottleneck_count = len([o for o in doc.operations if cint(o.bottleneck)])


run(doc)

# Pilot Run, Before Submit: a decision, by QA or a production manager; an approval needs the checks answered, pilot pieces sewn (and washed for a washed style) and
# out-of-tolerance measurements explained; any other decision needs notes.
def run(doc):
    cint = frappe.utils.cint
    APPROVE = ("Approved", "Approved with Comments")
    if not doc.decision:
        frappe.throw("Choose the decision (Approved, Approved with Comments, Rejected or Re-run) before submitting.")
    roles = frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
    if not [r for r in roles if r in ("Apparel QA", "Apparel Production Manager", "System Manager")]:
        frappe.throw("Only Apparel QA or a production manager can submit a pilot run decision.")
    if doc.decision in APPROVE:
        if not doc.checks:
            frappe.throw("Record the pilot run checks before approving.")
        unanswered = [c.check_item for c in doc.checks if not c.result]
        if unanswered:
            frappe.throw("Answer every check before approving: %s" % ", ".join(unanswered))
        no_action = [c.check_item for c in doc.checks if c.result == "No" and not (c.action_taken or "").strip()]
        if no_action:
            frappe.throw("Write the action taken for each failed check: %s" % ", ".join(no_action))
        if not [r for r in doc.colours if cint(r.sewn_qty)]:
