main()

# API arinox_shipment_make_delivery_notes: one draft Delivery Note per Sales Order on the shipment, quantities exactly as packed, each row tied to its packing list. Answers the names.
def main():
    # shared helpers from shipping/common.py: the fields every stage document copies from its production card, the open-card rule, and T&A stamping. Needs lib_mat.py (stamp_safe).
    def card_context(production_card):
        c = frappe.db.get_value("Production Card", production_card, ["sales_order", "sales_contract", "customer", "style_item", "company", "status", "docstatus", "line"], as_dict=True)
        return c or {}


    def require_open_card(production_card):
        card = card_context(production_card)
        if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
            frappe.throw("Production card %s must be issued and open." % production_card)
        return card


    def settings_value(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        return default if v in (None, "") else v


    def stamp_card(card, code, date, source_doctype, source_name, colours, partial):
        """Stamp a T&A milestone for every colour of the card's order. Never raises: a T&A fault must not stop shipping."""
        c = card_context(card)
        if not colours:
            colours = []
            for r in frappe.get_all("Production Card Line", filters={"parent": card}, fields=["colour"]):
                if r.colour not in colours:
                    colours.append(r.colour)
            colours = sorted(colours)
        for colour in colours:
            stamp_safe(c.sales_order, c.style_item, colour, code, date, source_doctype, source_name, partial, False)
    cint = frappe.utils.cint
    shipment = frappe.form_dict.get("shipment") or frappe.form_dict.get("name")
    doc = frappe.get_doc("Shipment", shipment)
    doc.check_permission("write")
    frappe.new_doc("Delivery Note").check_permission("create")
    if doc.docstatus == 2:
        frappe.throw("This shipment is cancelled.")
    made = []
    existing = [r.delivery_note for r in doc.shipment_delivery_note]
    by_order = {}
    order = []
    for r in doc.apparel_packing_lists:
        if not r.packing_list:
            continue
        so = frappe.db.get_value("Packing List", r.packing_list, "sales_order")
        if "o|" + so not in by_order:
            by_order["o|" + so] = []
            order.append(so)
        by_order["o|" + so].append(r.packing_list)
    for so in order:
        pls = by_order["o|" + so]
        if frappe.db.exists("Delivery Note Item", {"apparel_packing_list": ["in", pls], "docstatus": ["<", 2]}):
            frappe.throw("Sales order %s already has a delivery note for these packing lists." % so)
        dn = frappe.call("erpnext.selling.doctype.sales_order.sales_order.make_delivery_note", source_name=so)
        templates = {}
        for i in dn.items:
            templates["t|" + i.so_detail] = i.as_dict()
        fg = settings_value("fg_warehouse", None)
        items = []
        for pl in pls:
            card = frappe.db.get_value("Packing List", pl, "production_card")
            qty = {}
            keys = []
            for ct in frappe.get_all("Packing List Content", filters={"parent": pl}, fields=["sales_order_item", "pieces_total"]):
                if not ct.sales_order_item or not frappe.db.exists("Sales Order Item", ct.sales_order_item):
                    frappe.throw("Packing list %s has a carton row that is not tied to a Sales Order line. Open it and save the packing list again." % pl)
                if ct.sales_order_item not in keys:
                    keys.append(ct.sales_order_item)
                    qty[ct.sales_order_item] = 0
                qty[ct.sales_order_item] = qty[ct.sales_order_item] + cint(ct.pieces_total)
            for so_detail in keys:
                row = templates.get("t|" + so_detail)
                if row:
                    row = dict(row)
                else:
                    line = frappe.db.get_value("Sales Order Item", so_detail, ["item_code", "item_name", "description", "uom", "stock_uom", "conversion_factor", "rate", "warehouse"], as_dict=True)
                    row = dict(line)
                    row["doctype"] = "Delivery Note Item"
                for k in ("name", "parent", "parenttype", "parentfield", "idx", "creation", "modified", "owner", "modified_by", "docstatus"):
                    row.pop(k, None)
                row.update({"qty": qty[so_detail], "so_detail": so_detail, "against_sales_order": so, "apparel_packing_list": pl, "apparel_production_card": card})
                if fg:
                    row["warehouse"] = fg
                items.append(row)
        dn.set("items", items)
        dn.apparel_shipment = shipment
        c = frappe.db.get_value("Sales Order", so, "apparel_sales_contract")
        dn.apparel_sales_contract = c or None
        if doc.incoterm:
            dn.incoterm = doc.incoterm
        if doc.apparel_forwarder:
            dn.transporter = doc.apparel_forwarder
        dn.lr_no = doc.apparel_booking_no
        dn.run_method("set_missing_values")
        dn.run_method("calculate_taxes_and_totals")
        dn.insert()
        made.append(dn.name)
        if dn.name not in existing:
            doc.append("shipment_delivery_note", {"delivery_note": dn.name, "grand_total": dn.grand_total})
    doc.flags.ignore_validate_update_after_submit = True
    doc.save()
    frappe.flags.arinox_result = made


main()

# API arinox_freight_allocated_costs: the shipment's cost shared over the orders on board (by CBM at sea, by chargeable weight by air). Answers [[contract, share, cost]], basis, cost.
def main():
    # shared helpers from shipping/common.py: the fields every stage document copies from its production card, the open-card rule, and T&A stamping. Needs lib_mat.py (stamp_safe).
    def card_context(production_card):
        c = frappe.db.get_value("Production Card", production_card, ["sales_order", "sales_contract", "customer", "style_item", "company", "status", "docstatus", "line"], as_dict=True)
        return c or {}


    def require_open_card(production_card):
        card = card_context(production_card)
        if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
            frappe.throw("Production card %s must be issued and open." % production_card)
        return card


    def settings_value(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        return default if v in (None, "") else v


    def stamp_card(card, code, date, source_doctype, source_name, colours, partial):
        """Stamp a T&A milestone for every colour of the card's order. Never raises: a T&A fault must not stop shipping."""
        c = card_context(card)
        if not colours:
            colours = []
            for r in frappe.get_all("Production Card Line", filters={"parent": card}, fields=["colour"]):
                if r.colour not in colours:
                    colours.append(r.colour)
            colours = sorted(colours)
        for colour in colours:
            stamp_safe(c.sales_order, c.style_item, colour, code, date, source_doctype, source_name, partial, False)
    # shared helpers from shipping/shipment.py and freight.py: the shipment status from its dates and documents, the freight estimate / actual, and the allocation of freight over
    # the orders on board. Needs lib_shipping.py (settings_value).
    def over_short_pct(shipped, ordered):
        if not float(ordered or 0):
            return None
        return (float(shipped) - float(ordered)) / float(ordered) * 100.0


    def refresh_status(shipment):
        if not frappe.db.exists("Shipment", shipment):
            return
        d = frappe.db.get_value("Shipment", shipment, ["apparel_ship_status", "apparel_booking_no", "apparel_on_board_date", "apparel_arrival_date", "apparel_delivery_date"], as_dict=True)
        if d.apparel_ship_status in ("On Hold", "Closed"):
            return        # set by a person; the dates and documents do not reopen it
        cleared = frappe.db.exists("Shipment Declaration", {"parent": shipment, "status": "Cleared"})
        handed = frappe.db.exists("Delivery Note", {"apparel_shipment": shipment, "docstatus": 1})
        prepared = frappe.db.exists("Sales Invoice", {"apparel_shipment": shipment, "docstatus": ["<", 2]})
        if d.apparel_delivery_date:
            status = "Delivered"
        elif d.apparel_arrival_date:
            status = "Arrived"
        elif d.apparel_on_board_date:
            status = "On Board"
        elif cleared:
            status = "Customs Cleared"
        elif handed:
            status = "Cargo Handed Over"
        elif prepared:
            status = "Documents Prepared"
        elif d.apparel_booking_no:
            status = "Booked"
        else:
            status = "Planned"
        if status != d.apparel_ship_status:
            frappe.db.set_value("Shipment", shipment, "apparel_ship_status", status, update_modified=False)


    def refresh_costs(shipment):
        """Estimate (the chosen quote), actual (the forwarder's invoices not cancelled) and the gap, written onto the shipment."""
        flt = frappe.utils.flt
        if not frappe.db.exists("Shipment", shipment):
            return
        quote = frappe.db.get_value("Shipment", shipment, "apparel_freight_quote")
        estimate = flt(frappe.db.get_value("Supplier Quotation", quote, "base_grand_total")) if quote else 0
        actual = flt(frappe.db.sql("select ifnull(sum(base_grand_total), 0) from `tabPurchase Invoice` where apparel_shipment = %s and docstatus < 2 and ifnull(is_return, 0) = 0", (shipment,))[0][0])
        pct = over_short_pct(actual, estimate) if estimate and actual else 0
        frappe.db.set_value("Shipment", shipment, {"apparel_estimate_total": estimate, "apparel_actual_total": actual, "apparel_cost_variance_pct": round(pct or 0, 2)}, update_modified=False)
        limit = flt(settings_value("freight_estimate_variance_pct", 10))
        if estimate and actual and abs(pct or 0) > limit:
            frappe.msgprint("Forwarder bills are %s %s %% against the quote (%s vs %s)." % ("over" if pct > 0 else "under", round(abs(pct), 1), actual, estimate), indicator="orange", title="Freight cost")


    def allocation_basis(shipment):
        """Share of a shipment's cost per order: by CBM at sea, by chargeable weight by air. Returns [{contract: share}, basis field]."""
        flt = frappe.utils.flt
        mode = frappe.db.get_value("Shipment", shipment, "apparel_mode")
        rows = frappe.get_all("Shipment Packing List", filters={"parent": shipment}, fields=["packing_list", "sales_contract", "cbm", "gross_kg"])
        use = "gross_kg" if mode == "Air" else "cbm"
        total = sum([flt(r.get(use)) for r in rows])
        out = {}
        for r in rows:
            key = r.sales_contract or frappe.db.get_value("Packing List", r.packing_list, "sales_order")
            out[key] = out.get(key, 0) + (flt(r.get(use)) / total if total else 1.0 / len(rows))
        return [out, use]


    def allocated_costs(shipment):
        """[[contract, share, cost], ...], basis field, cost: the shipment's actual cost (estimate while no bill has arrived) shared by the basis."""
        flt = frappe.utils.flt
        d = frappe.db.get_value("Shipment", shipment, ["apparel_estimate_total", "apparel_actual_total"], as_dict=True)
        cost = flt(d.apparel_actual_total) or flt(d.apparel_estimate_total)
        ab = allocation_basis(shipment)
        return [[k, round(ab[0][k], 6), round(cost * ab[0][k], 2)] for k in sorted(ab[0])], ab[1], cost
    shipment = frappe.form_dict.get("shipment")
    frappe.get_doc("Shipment", shipment).check_permission("read")
    res = allocated_costs(shipment)
    frappe.flags.arinox_result = {"rows": res[0], "basis": res[1], "cost": res[2]}


main()

# Delivery Note, After Submit: the day it leaves the factory stamps EX_FACTORY for each card on it, and the shipment status moves on.
def run(doc):
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from shipping/common.py: the fields every stage document copies from its production card, the open-card rule, and T&A stamping. Needs lib_mat.py (stamp_safe).
    def card_context(production_card):
        c = frappe.db.get_value("Production Card", production_card, ["sales_order", "sales_contract", "customer", "style_item", "company", "status", "docstatus", "line"], as_dict=True)
        return c or {}


    def require_open_card(production_card):
        card = card_context(production_card)
        if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
            frappe.throw("Production card %s must be issued and open." % production_card)
        return card


    def settings_value(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        return default if v in (None, "") else v


    def stamp_card(card, code, date, source_doctype, source_name, colours, partial):
        """Stamp a T&A milestone for every colour of the card's order. Never raises: a T&A fault must not stop shipping."""
        c = card_context(card)
        if not colours:
            colours = []
            for r in frappe.get_all("Production Card Line", filters={"parent": card}, fields=["colour"]):
                if r.colour not in colours:
                    colours.append(r.colour)
            colours = sorted(colours)
        for colour in colours:
            stamp_safe(c.sales_order, c.style_item, colour, code, date, source_doctype, source_name, partial, False)
    # shared helpers from shipping/shipment.py and freight.py: the shipment status from its dates and documents, the freight estimate / actual, and the allocation of freight over
    # the orders on board. Needs lib_shipping.py (settings_value).
    def over_short_pct(shipped, ordered):
        if not float(ordered or 0):
            return None
        return (float(shipped) - float(ordered)) / float(ordered) * 100.0


    def refresh_status(shipment):
        if not frappe.db.exists("Shipment", shipment):
            return
        d = frappe.db.get_value("Shipment", shipment, ["apparel_ship_status", "apparel_booking_no", "apparel_on_board_date", "apparel_arrival_date", "apparel_delivery_date"], as_dict=True)
        if d.apparel_ship_status in ("On Hold", "Closed"):
            return        # set by a person; the dates and documents do not reopen it
        cleared = frappe.db.exists("Shipment Declaration", {"parent": shipment, "status": "Cleared"})
        handed = frappe.db.exists("Delivery Note", {"apparel_shipment": shipment, "docstatus": 1})
        prepared = frappe.db.exists("Sales Invoice", {"apparel_shipment": shipment, "docstatus": ["<", 2]})
        if d.apparel_delivery_date:
            status = "Delivered"
        elif d.apparel_arrival_date:
            status = "Arrived"
        elif d.apparel_on_board_date:
            status = "On Board"
        elif cleared:
            status = "Customs Cleared"
        elif handed:
            status = "Cargo Handed Over"
        elif prepared:
            status = "Documents Prepared"
        elif d.apparel_booking_no:
            status = "Booked"
        else:
            status = "Planned"
        if status != d.apparel_ship_status:
            frappe.db.set_value("Shipment", shipment, "apparel_ship_status", status, update_modified=False)


    def refresh_costs(shipment):
        """Estimate (the chosen quote), actual (the forwarder's invoices not cancelled) and the gap, written onto the shipment."""
        flt = frappe.utils.flt
        if not frappe.db.exists("Shipment", shipment):
            return
        quote = frappe.db.get_value("Shipment", shipment, "apparel_freight_quote")
        estimate = flt(frappe.db.get_value("Supplier Quotation", quote, "base_grand_total")) if quote else 0
        actual = flt(frappe.db.sql("select ifnull(sum(base_grand_total), 0) from `tabPurchase Invoice` where apparel_shipment = %s and docstatus < 2 and ifnull(is_return, 0) = 0", (shipment,))[0][0])
        pct = over_short_pct(actual, estimate) if estimate and actual else 0
        frappe.db.set_value("Shipment", shipment, {"apparel_estimate_total": estimate, "apparel_actual_total": actual, "apparel_cost_variance_pct": round(pct or 0, 2)}, update_modified=False)
        limit = flt(settings_value("freight_estimate_variance_pct", 10))
        if estimate and actual and abs(pct or 0) > limit:
            frappe.msgprint("Forwarder bills are %s %s %% against the quote (%s vs %s)." % ("over" if pct > 0 else "under", round(abs(pct), 1), actual, estimate), indicator="orange", title="Freight cost")


    def allocation_basis(shipment):
        """Share of a shipment's cost per order: by CBM at sea, by chargeable weight by air. Returns [{contract: share}, basis field]."""
        flt = frappe.utils.flt
        mode = frappe.db.get_value("Shipment", shipment, "apparel_mode")
        rows = frappe.get_all("Shipment Packing List", filters={"parent": shipment}, fields=["packing_list", "sales_contract", "cbm", "gross_kg"])
        use = "gross_kg" if mode == "Air" else "cbm"
        total = sum([flt(r.get(use)) for r in rows])
        out = {}
        for r in rows:
            key = r.sales_contract or frappe.db.get_value("Packing List", r.packing_list, "sales_order")
            out[key] = out.get(key, 0) + (flt(r.get(use)) / total if total else 1.0 / len(rows))
        return [out, use]


    def allocated_costs(shipment):
        """[[contract, share, cost], ...], basis field, cost: the shipment's actual cost (estimate while no bill has arrived) shared by the basis."""
        flt = frappe.utils.flt
        d = frappe.db.get_value("Shipment", shipment, ["apparel_estimate_total", "apparel_actual_total"], as_dict=True)
        cost = flt(d.apparel_actual_total) or flt(d.apparel_estimate_total)
        ab = allocation_basis(shipment)
        return [[k, round(ab[0][k], 6), round(cost * ab[0][k], 2)] for k in sorted(ab[0])], ab[1], cost
    if not [it for it in doc.items if it.get("apparel_packing_list")]:
        return
    cards = []
    for it in doc.items:
        c = it.get("apparel_production_card")
        if c and c not in cards:
            cards.append(c)
    for card in cards:
        stamp_card(card, "EX_FACTORY", doc.posting_date, "Delivery Note", doc.name, None, False)
    if doc.get("apparel_shipment"):
        refresh_status(doc.apparel_shipment)


run(doc)

# Delivery Note, After Cancel: the EX_FACTORY stamp is cleared and the shipment status refreshed.
def run(doc):
    # shared helpers from materials/common.py: unit conversion, allowance rules, approvals lookup, stock claims, Material Request creation, roll-ups, T&A stamping.
    # Needs lib_samples.py included first (rules). No regular expressions or math module in the sandbox, so widths are parsed by hand.
    YARD_M = 0.9144
    ALIASES = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd", "yard": "yd", "yards": "yd",
               "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}


    def uom_kind(uom):
        return ALIASES.get((uom or "").strip().lower())


    def to_metres(qty, uom, gsm, width_cm):
        """Quantity of fabric in `uom` to metres. kg needs GSM and cuttable width: m = kg*1000 / (gsm * width_m)."""
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(qty)
        if kind == "yd":
            return flt(qty) * YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return flt(qty) * 1000 / (flt(gsm) * flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def from_metres(metres, uom, gsm, width_cm):
        flt = frappe.utils.flt
        kind = uom_kind(uom)
        if kind == "m":
            return flt(metres)
        if kind == "yd":
            return flt(metres) / YARD_M
        if kind == "kg":
            if not flt(gsm) or not flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert metres to kg.")
            return flt(metres) * (flt(gsm) * flt(width_cm) / 100) / 1000
        frappe.throw("Cannot convert metres to UOM %s." % uom)


    def numbers_in(text):
        """[[number, end_index], ...] for every number in the text."""
        out = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and (text[j].isdigit() or (text[j] == "." and j + 1 < n and text[j + 1].isdigit())):
                    j = j + 1
                out.append([float(text[i:j]), j])
                i = j
            else:
                i = i + 1
        return out


    def parse_width_cm(text):
        """'132CM', 'CW 152 cm', '57"', '56in' -> cm. None when no width is found."""
        if not text:
            return None
        t = str(text).strip().lower()
        nums = numbers_in(t)
        if not nums:
            return None
        for nm in nums:
            rest = t[nm[1]:].lstrip()
            if rest.startswith("cm"):
                return nm[0]
            if rest.startswith('"') or rest.startswith("inch") or (rest.startswith("in") and not rest[2:3].isalpha()):
                return round(nm[0] * 2.54, 1)
        return nums[0][0]


    def cw_in(text):
        """The number after 'CW' in a fabric description, or None."""
        t = (text or "").lower()
        k = t.find("cw")
        while k >= 0:
            rest = t[k + 2:].lstrip()
            nums = numbers_in(rest[:12])
            if nums and rest[:1].isdigit():
                return nums[0][0]
            k = t.find("cw", k + 2)
        return None


    def round_up_to_pack(qty, pack_size):
        flt = frappe.utils.flt
        qty = flt(qty)
        if flt(pack_size) > 0 and qty > 0:
            return frappe.utils.ceil(round(qty / flt(pack_size), 9)) * flt(pack_size)
        return qty


    def fr_material_types():
        raw = frappe.db.get_single_value("Apparel Settings", "fr_material_types") or "Fabric\nLining\nContrast Fabric"
        return [t.strip() for t in raw.splitlines() if t.strip()]


    def get_allowance(material_type, trim_category, customer, item_group):
        """Most specific enabled Material Allowance Rule: customer 4, trim category 2, material type 1, item group 1 -> {allowance_pct, pack_size, min_order_qty}."""
        best = None
        best_score = 0
        for r in frappe.get_all("Material Allowance Rule", filters={"enabled": 1}, fields=["*"]):
            score = 0
            for field, value, weight in (("customer", customer, 4), ("trim_category", trim_category, 2), ("material_type", material_type, 1), ("item_group", item_group, 1)):
                if r.get(field):
                    if r.get(field) != value:
                        score = None
                        break
                    score += weight
            if score and score > best_score:
                best = r
                best_score = score
        if not best:
            return {"allowance_pct": 0, "pack_size": 0, "min_order_qty": 0}
        return {"allowance_pct": frappe.utils.flt(best.allowance_pct), "pack_size": frappe.utils.flt(best.pack_size), "min_order_qty": frappe.utils.flt(best.min_order_qty)}


    def tech_pack_for(style_item):
        name = frappe.db.get_value("Tech Pack", {"style_item": style_item, "docstatus": 1}, "name", order_by="creation desc")
        return frappe.get_doc("Tech Pack", name) if name else None


    def style_of(item_code):
        return frappe.db.get_value("Item", item_code, "variant_of") or item_code


    def cost_sheet_for(sales_order, style_item):
        for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code", "apparel_cost_sheet"]):
            if it.apparel_cost_sheet and style_of(it.item_code) == style_item:
                return frappe.get_doc("Cost Sheet", it.apparel_cost_sheet)
        return None


    def colour_matches(material_colour, garment_colour, all_colours):
        """A Tech Pack material row with a colour belongs to that garment colour only; blank belongs to all."""
        mc = (material_colour or "").strip().upper()
        if not mc:
            return True
        if mc == (garment_colour or "").strip().upper():
            return True
        return mc not in [(c or "").strip().upper() for c in all_colours]


    def approval_info(sales_order, style_item, sample_type, colour, customer):
        """[status text, ok] for one sample type of a style x colour on an order. ok = the gate would let it pass."""
        rule = get_rules(customer, sales_order, style_item).get(sample_type)
        gate = effective_gate(rule, sales_order) if rule else "No"
        f = scope_filters(sales_order, style_item)
        f["sample_type"] = sample_type
        rows = frappe.get_all("Sample Approval", filters=f, fields=["name", "status", "colour"])
        if rule and rule["per_colour"]:
            rows = [r for r in rows if not (r.colour or "").strip() or norm(r.colour) == norm(colour)]
        if not rows:
            return ["Not Required", True] if gate == "No" else ["Not Raised", gate != "Required"]
        bad = [r for r in rows if r.status not in GATE_OK]
        if bad:
            return [bad[0].status, False]
        return ["Approved", True]


    def free_stock(item_code, warehouse, parent_dt, child_dt, exclude):
        """Actual stock minus the stock already claimed by other approved requisitions (not superseded, not cancelled)."""
        flt = frappe.utils.flt
        if not item_code or not warehouse:
            return 0.0
        actual = flt(frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse}, "actual_qty"))
        item_field = "fabric_item" if parent_dt == "Fabric Requisition" else "trim_item"
        claimed = frappe.db.sql("select coalesce(sum(c.stock_used), 0) from `tab%s` c join `tab%s` p on p.name = c.parent where c.%s = %%s and c.stock_warehouse = %%s "
                                "and p.docstatus = 1 and p.status != 'Superseded' and p.name != %%s" % (child_dt, parent_dt, item_field), (item_code, warehouse, exclude or ""))[0][0]
        return actual - flt(claimed)


    def item_has_uom(item_code, uom):
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        return uom == stock_uom or bool(frappe.db.exists("UOM Conversion Detail", {"parent": item_code, "uom": uom}))


    def mr_line(item_code, qty_stock, order_uom, order_qty):
        """[qty, uom, conversion_factor] for a Material Request row: the order UOM when the item has it, else stock UOM."""
        flt = frappe.utils.flt
        stock_uom = frappe.db.get_value("Item", item_code, "stock_uom")
        if order_uom and order_uom != stock_uom and flt(order_qty) > 0 and item_has_uom(item_code, order_uom):
            cf = flt(frappe.db.get_value("UOM Conversion Detail", {"parent": item_code, "uom": order_uom}, "conversion_factor")) or 1
            return [flt(order_qty), order_uom, cf]
        return [flt(qty_stock), stock_uom, 1]


    def company_warehouse(field, company):
        """The warehouse named in Apparel Settings `field`, or its equivalent in `company` (created when missing)."""
        wh = frappe.db.get_single_value("Apparel Settings", field)
        if not wh or not company:
            return wh
        wc = frappe.db.get_value("Warehouse", wh, ["company", "warehouse_name"])
        if wc[0] == company:
            return wh
        abbr = frappe.db.get_value("Company", company, "abbr")
        name = "%s - %s" % (wc[1], abbr)
        if not frappe.db.exists("Warehouse", name):
            frappe.get_doc({"doctype": "Warehouse", "warehouse_name": wc[1], "company": company}).insert(ignore_permissions=True)
        return name


    def create_material_requests(doc, lines, requisition_type, kind):
        """Group `lines` by (supplier, customer-provided) and make one Material Request per group. Returns the names."""
        cint = frappe.utils.cint
        getdate = frappe.utils.getdate
        if not lines:
            return []
        warehouse = company_warehouse("inspection_warehouse_fabric" if kind == "Fabric" else "inspection_warehouse_trim", doc.company)
        groups = {}
        order = []
        for ln in lines:
            k = "%s|%s" % (ln.get("supplier") or "", cint(ln.get("customer_provided")))
            if k not in groups:
                groups[k] = []
                order.append(k)
            groups[k].append(ln)
        names = []
        for k in order:
            rows = groups[k]
            supplier = rows[0].get("supplier") or ""
            provided = cint(rows[0].get("customer_provided"))
            mr = frappe.new_doc("Material Request")
            mr.material_request_type = "Customer Provided" if provided else "Purchase"
            mr.company = doc.company
            mr.transaction_date = frappe.utils.nowdate()
            dated = [getdate(r["required_by"]) for r in rows if r.get("required_by")]
            mr.schedule_date = min(dated) if dated else frappe.utils.nowdate()
            if provided:
                mr.customer = doc.customer
            mr.title = ("%s %s" % (doc.name, supplier or "no supplier"))[:140]
            for r in rows:
                mr.append("items", {"item_code": r["item_code"], "qty": r["qty"], "uom": r["uom"], "conversion_factor": r.get("conversion_factor") or 1,
                                    "schedule_date": r.get("required_by") or mr.schedule_date, "warehouse": warehouse, "sales_order": r.get("sales_order"),
                                    "description": (r.get("description") or "")[:500] or None, "apparel_requisition_type": requisition_type, "apparel_requisition": doc.name,
                                    "apparel_requisition_item": r["key"], "apparel_style_no": r.get("style_no"), "apparel_colour": r.get("colour"),
                                    "apparel_hold_reason": r.get("hold_reason")})
            mr.flags.ignore_permissions = True
            mr.insert()
            if cint(frappe.db.get_single_value("Apparel Settings", "auto_submit_material_request")):
                mr.submit()
            names.append(mr.name)
        return names


    def requested_so_far(requisition_type, chain_names, key):
        """Stock qty already requested for this line key by every document in the revision chain."""
        if not chain_names:
            return 0.0
        rows = frappe.db.sql("select coalesce(sum(i.stock_qty), 0) from `tabMaterial Request Item` i join `tabMaterial Request` m on m.name = i.parent "
                             "where i.apparel_requisition_type = %s and i.apparel_requisition in %s and i.apparel_requisition_item = %s and m.docstatus < 2",
                             (requisition_type, tuple(chain_names), key))
        return frappe.utils.flt(rows[0][0])


    def revision_chain(doctype, previous_field, name):
        """Names of this document and every earlier revision."""
        chain = []
        cur = name
        while cur and cur not in chain:
            chain.append(cur)
            cur = frappe.db.get_value(doctype, cur, previous_field)
        return chain


    def stamp_safe(sales_order, style_item, colour, code, date, source_doctype, source_name, partial, planned):
        """Stamp a T&A milestone. Never raises: a T&A problem must not block a purchase, a receipt or a requisition."""
        try:
            run_script("arinox_tna", action="stamp", sales_order=sales_order, style_item=style_item, colour=colour, code=code, date=str(date), source_doctype=source_doctype,
                       source_name=source_name, partial=1 if partial else 0, planned=1 if planned else 0)
        except Exception:
            frappe.log_error(title="T&A stamp failed", message=frappe.get_traceback())


    def stamp_safe_requisition(doc, code):
        """Stamp `code` for every style x colour on a requisition."""
        seen = []
        for r in doc.items:
            k = "%s|%s|%s" % (r.sales_order, r.style_item, (r.colour or "").strip().upper())
            if k in seen:
                continue
            seen.append(k)
            stamp_safe(r.sales_order, r.style_item, r.colour, code, frappe.utils.nowdate(), doc.doctype, doc.name, False, False)


    def unstamp_safe(doctype, name):
        try:
            run_script("arinox_tna", action="unstamp", source_doctype=doctype, source_name=name)
        except Exception:
            frappe.log_error(title="T&A unstamp failed", message=frappe.get_traceback())
    # shared helpers from shipping/common.py: the fields every stage document copies from its production card, the open-card rule, and T&A stamping. Needs lib_mat.py (stamp_safe).
    def card_context(production_card):
        c = frappe.db.get_value("Production Card", production_card, ["sales_order", "sales_contract", "customer", "style_item", "company", "status", "docstatus", "line"], as_dict=True)
        return c or {}


    def require_open_card(production_card):
        card = card_context(production_card)
        if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
            frappe.throw("Production card %s must be issued and open." % production_card)
        return card


    def settings_value(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        return default if v in (None, "") else v


    def stamp_card(card, code, date, source_doctype, source_name, colours, partial):
        """Stamp a T&A milestone for every colour of the card's order. Never raises: a T&A fault must not stop shipping."""
        c = card_context(card)
        if not colours:
            colours = []
            for r in frappe.get_all("Production Card Line", filters={"parent": card}, fields=["colour"]):
                if r.colour not in colours:
                    colours.append(r.colour)
            colours = sorted(colours)
        for colour in colours:
            stamp_safe(c.sales_order, c.style_item, colour, code, date, source_doctype, source_name, partial, False)
    # shared helpers from shipping/shipment.py and freight.py: the shipment status from its dates and documents, the freight estimate / actual, and the allocation of freight over
    # the orders on board. Needs lib_shipping.py (settings_value).
    def over_short_pct(shipped, ordered):
        if not float(ordered or 0):
            return None
        return (float(shipped) - float(ordered)) / float(ordered) * 100.0


    def refresh_status(shipment):
        if not frappe.db.exists("Shipment", shipment):
            return
        d = frappe.db.get_value("Shipment", shipment, ["apparel_ship_status", "apparel_booking_no", "apparel_on_board_date", "apparel_arrival_date", "apparel_delivery_date"], as_dict=True)
        if d.apparel_ship_status in ("On Hold", "Closed"):
            return        # set by a person; the dates and documents do not reopen it
        cleared = frappe.db.exists("Shipment Declaration", {"parent": shipment, "status": "Cleared"})
        handed = frappe.db.exists("Delivery Note", {"apparel_shipment": shipment, "docstatus": 1})
        prepared = frappe.db.exists("Sales Invoice", {"apparel_shipment": shipment, "docstatus": ["<", 2]})
        if d.apparel_delivery_date:
            status = "Delivered"
        elif d.apparel_arrival_date:
            status = "Arrived"
        elif d.apparel_on_board_date:
            status = "On Board"
        elif cleared:
            status = "Customs Cleared"
        elif handed:
            status = "Cargo Handed Over"
        elif prepared:
            status = "Documents Prepared"
        elif d.apparel_booking_no:
            status = "Booked"
        else:
            status = "Planned"
        if status != d.apparel_ship_status:
            frappe.db.set_value("Shipment", shipment, "apparel_ship_status", status, update_modified=False)


    def refresh_costs(shipment):
        """Estimate (the chosen quote), actual (the forwarder's invoices not cancelled) and the gap, written onto the shipment."""
        flt = frappe.utils.flt
        if not frappe.db.exists("Shipment", shipment):
            return
        quote = frappe.db.get_value("Shipment", shipment, "apparel_freight_quote")
        estimate = flt(frappe.db.get_value("Supplier Quotation", quote, "base_grand_total")) if quote else 0
        actual = flt(frappe.db.sql("select ifnull(sum(base_grand_total), 0) from `tabPurchase Invoice` where apparel_shipment = %s and docstatus < 2 and ifnull(is_return, 0) = 0", (shipment,))[0][0])
        pct = over_short_pct(actual, estimate) if estimate and actual else 0
        frappe.db.set_value("Shipment", shipment, {"apparel_estimate_total": estimate, "apparel_actual_total": actual, "apparel_cost_variance_pct": round(pct or 0, 2)}, update_modified=False)
        limit = flt(settings_value("freight_estimate_variance_pct", 10))
        if estimate and actual and abs(pct or 0) > limit:
            frappe.msgprint("Forwarder bills are %s %s %% against the quote (%s vs %s)." % ("over" if pct > 0 else "under", round(abs(pct), 1), actual, estimate), indicator="orange", title="Freight cost")


    def allocation_basis(shipment):
        """Share of a shipment's cost per order: by CBM at sea, by chargeable weight by air. Returns [{contract: share}, basis field]."""
        flt = frappe.utils.flt
        mode = frappe.db.get_value("Shipment", shipment, "apparel_mode")
        rows = frappe.get_all("Shipment Packing List", filters={"parent": shipment}, fields=["packing_list", "sales_contract", "cbm", "gross_kg"])
        use = "gross_kg" if mode == "Air" else "cbm"
        total = sum([flt(r.get(use)) for r in rows])
        out = {}
        for r in rows:
            key = r.sales_contract or frappe.db.get_value("Packing List", r.packing_list, "sales_order")
            out[key] = out.get(key, 0) + (flt(r.get(use)) / total if total else 1.0 / len(rows))
        return [out, use]


    def allocated_costs(shipment):
        """[[contract, share, cost], ...], basis field, cost: the shipment's actual cost (estimate while no bill has arrived) shared by the basis."""
        flt = frappe.utils.flt
        d = frappe.db.get_value("Shipment", shipment, ["apparel_estimate_total", "apparel_actual_total"], as_dict=True)
        cost = flt(d.apparel_actual_total) or flt(d.apparel_estimate_total)
        ab = allocation_basis(shipment)
        return [[k, round(ab[0][k], 6), round(cost * ab[0][k], 2)] for k in sorted(ab[0])], ab[1], cost
    if not [it for it in doc.items if it.get("apparel_packing_list")]:
        return
    unstamp_safe("Delivery Note", doc.name)
    if doc.get("apparel_shipment"):
        refresh_status(doc.apparel_shipment)


run(doc)

