# Buyer Claim, Before Save: against a submitted buyer invoice (not the group invoice); the amount, the pieces, the cap at the CIF value of the pieces, and the contract's claim window.
def run(doc):
    # shared helpers from shipping/common.py: the fields every stage document copies from its production card, the open-card rule, and T&A stamping. Needs lib_mat.py (stamp_safe).
    def card_context(production_card):
        c = frappe.db.get_value("Production Card", production_card, ["sales_order", "sales_contract", "customer", "style_item", "company", "status", "docstatus", "line"], as_dict=True)
        return c or {}


    def require_open_card(production_card):
        card = card_context(production_card)
        if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
            frappe.throw("Production card %s must be issued and open." % production_card)
        return card


    def settings_value(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        return default if v in (None, "") else v


    def stamp_card(card, code, date, source_doctype, source_name, colours, partial):
        """Stamp a T&A milestone for every colour of the card's order. Never raises: a T&A fault must not stop shipping."""
        c = card_context(card)
        if not colours:
            colours = []
            for r in frappe.get_all("Production Card Line", filters={"parent": card}, fields=["colour"]):
                if r.colour not in colours:
                    colours.append(r.colour)
            colours = sorted(colours)
        for colour in colours:
            stamp_safe(c.sales_order, c.style_item, colour, code, date, source_doctype, source_name, partial, False)
    # shared helpers of the Buyer Claim: the claim window against arrival, and syncing the invoice's dispute flag. Needs lib_shipping.py.
    NO_WINDOW = ("Chargeback", "Concession")


    def window_check(claim_type, arrival, on_date, quality_days, quantity_days):
        """[days allowed, days since arrival, ok]. A claim after the window needs a reason to be accepted."""
        cint = frappe.utils.cint
        if claim_type in NO_WINDOW:
            return [0, 0, True]
        allowed = cint(quality_days if claim_type in ("Quality", "Wrong Item", "Other") else quantity_days)
        if not arrival or not allowed:
            return [allowed, 0, True]
        since = frappe.utils.date_diff(frappe.utils.getdate(on_date), frappe.utils.getdate(arrival))
        return [allowed, since, since <= allowed]


    def sync_invoice(claim):
        """While a claim is undecided or being settled, the invoice is Disputed so no reminders go out."""
        if not claim.sales_invoice:
            return
        open_claims = frappe.db.count("Buyer Claim", {"sales_invoice": claim.sales_invoice, "docstatus": ["<", 2], "status": ["in", ["Open", "Under Review"]], "name": ["!=", claim.name if claim.docstatus == 2 else ""]})
        frappe.db.set_value("Sales Invoice", claim.sales_invoice, "apparel_dispute_reason", ("Open claim %s" % claim.name) if open_claims else "", update_modified=False)
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    si = frappe.db.get_value("Sales Invoice", doc.sales_invoice, ["docstatus", "apparel_sales_contract", "apparel_shipment", "net_total", "total_qty", "is_internal_customer", "company"], as_dict=True)
    if not si or si.docstatus != 1:
        frappe.throw("Invoice %s must be submitted." % doc.sales_invoice)
    if cint(si.is_internal_customer):
        frappe.throw("Claims are raised against the buyer's invoice, not the group invoice.")
    doc.sales_contract = si.apparel_sales_contract
    doc.shipment = si.apparel_shipment
    if flt(doc.claimed_amount) <= 0:
        frappe.throw("Enter the amount claimed.")
    for r in doc.rows:
        if cint(r.pieces) <= 0:
            frappe.throw("Claim row %s: enter the pieces." % r.idx)
    pieces = sum([cint(r.pieces) for r in doc.rows])
    unit = flt(si.net_total) / flt(si.total_qty) if flt(si.total_qty) else 0
    doc.cap_amount = round(unit * pieces, 2) if pieces else flt(si.net_total)
    arrival = None
    if doc.shipment:
        arrival = frappe.db.get_value("Shipment", doc.shipment, "apparel_arrival_date") or frappe.db.get_value("Shipment", doc.shipment, "apparel_delivery_date")
    doc.arrival_date = arrival
    q = 0
    n = 0
    if doc.sales_contract and frappe.db.exists("Sales Contract", doc.sales_contract):
        v = frappe.db.get_value("Sales Contract", doc.sales_contract, ["quality_claim_days", "quantity_claim_days"])
        q = v[0]
        n = v[1]
    wc = window_check(doc.claim_type, arrival, doc.reported_on or frappe.utils.nowdate(), q, n)
    doc.window_days = wc[0]
    doc.days_since_arrival = wc[1]
    doc.window_note = "" if wc[2] else "Reported %s days after arrival; the contract allows %s." % (wc[1], wc[0])
    if doc.docstatus == 0 and doc.settlement == "Credit Note" and not doc.rows and doc.claim_type not in NO_WINDOW:
        frappe.msgprint("Add the pieces claimed so the cap can be worked out.", indicator="orange")
    if doc.evidence is None and doc.claim_type not in NO_WINDOW and cint(settings_value("claim_requires_evidence", 1)) and doc.docstatus == 0:
        frappe.msgprint("Attach the buyer's evidence (photos or report) before accepting the claim.", indicator="orange")


run(doc)

# Buyer Claim, Before Submit: an accepted claim needs the amount and the settlement; outside the window or above the cap it needs a manager and a reason; an undecided claim cannot be submitted.
def run(doc):
    flt = frappe.utils.flt
    if doc.status in ("Accepted", "Partly Accepted"):
        if flt(doc.accepted_amount) <= 0:
            frappe.throw("Enter the amount accepted.")
        if not doc.settlement:
            frappe.throw("Choose how it is settled.")
        outside = bool(doc.window_note) or flt(doc.accepted_amount) > flt(doc.cap_amount) + 0.005
        if outside:
            roles = frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
            if not [r for r in roles if r in ("Accounts Manager", "Apparel Merchandising Manager", "System Manager")]:
                frappe.throw("Accepting outside the claim window or above the cap needs a manager.")
            if not (doc.override_reason or "").strip():
                frappe.throw("Write why this is accepted outside the window or above the cap.")
    elif doc.status == "Open":
        frappe.throw("Decide the claim before submitting: Under Review is saved as a draft, then Accepted, Partly Accepted or Rejected.")


run(doc)

