# API arinox_production_card_get_production_context: everything an agent needs to draft production cards for an order.
def main():
    # shared helpers: the order matrix and style dates (production_card.order_matrix, sample_approval.get_style_dates)
    def order_matrix(sales_order, style_item):
        """({(colour, size): {order_qty, tolerance_pct}}, earliest ex-factory date, [buyer POs]) for one style on an order."""
        cells = {}
        ex_factory = None
        pos = []
        for it in frappe.get_all("Sales Order Item", {"parent": sales_order},
                                 ["item_code", "qty", "apparel_colour", "apparel_size", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            if style != style_item:
                continue
            key = ((it.apparel_colour or "").strip(), (it.apparel_size or "").strip())
            if key not in cells:
                cells[key] = {"order_qty": 0, "tolerance_pct": 0}
            cells[key]["order_qty"] = cells[key]["order_qty"] + int(it.qty or 0)
            cells[key]["tolerance_pct"] = max(frappe.utils.flt(cells[key]["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not ex_factory or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(ex_factory)):
                ex_factory = frappe.utils.getdate(it.delivery_date)
            if it.apparel_buyer_po and it.apparel_buyer_po not in pos:
                pos.append(it.apparel_buyer_po)
        return cells, ex_factory, pos


    def get_pcd(sales_order, style_item):
        """Planned cut date from the Factory Allocation, then the contract line."""
        if not sales_order:
            return None
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", {"parent": fa, "style_item": style_item}, ["pcd"], order_by="pcd"):
                if r.pcd:
                    return r.pcd
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if contract:
            for r in frappe.get_all("Sales Contract Item", {"parent": contract, "style_item": style_item}, ["pcd"], order_by="pcd"):
                if r.pcd:
                    return r.pcd
        return None


    def setting(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        if v is None or v == "":
            return default
        return v
    flt = frappe.utils.flt
    cint = frappe.utils.cint
    sales_order = frappe.form_dict.get("sales_order")
    frappe.get_doc("Sales Order", sales_order).check_permission("read")
    styles = []
    for it in frappe.get_all("Sales Order Item", filters={"parent": sales_order}, fields=["item_code"]):
        s = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
        if s not in styles:
            styles.append(s)
    fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name") or ""
    out = []
    for style in styles:
        m = order_matrix(sales_order, style)
        cells = m[0]
        cards = frappe.get_all("Production Card", filters={"sales_order": sales_order, "style_item": style, "docstatus": 1, "status": ["not in", ("Superseded", "Cancelled")]}, order_by="creation desc", limit=1)
        out.append({"style_item": style, "ex_factory_date": str(m[1]) if m[1] else None, "buyer_pos": m[2],
                    "lines": [{"colour": k[0], "size": k[1], "order_qty": cells[k]["order_qty"], "tolerance_pct": cells[k]["tolerance_pct"]} for k in sorted(cells)],
                    "card": cards[0].name if cards else None,
                    "fabric_requisitions": frappe.get_all("Fabric Requisition Item", filters={"sales_order": sales_order, "style_item": style, "docstatus": 1}, fields=["parent", "colour", "net_qty", "accepted_qty"]),
                    "trim_requisitions": frappe.get_all("Trim Requisition Item", filters={"sales_order": sales_order, "style_item": style, "docstatus": 1}, fields=["parent", "trim_category", "colour", "net_qty"]),
                    "allocation": frappe.get_all("Factory Allocation Line", filters={"parent": fa, "style_item": style}, fields=["colour", "factory", "line", "pcd", "sewing_start", "sewing_end"])})
    frappe.flags.arinox_result = {"sales_order": sales_order, "styles": out, "defaults": {"extra_cut_pct": flt(setting("default_extra_cut_pct", 5)), "bundle_size": cint(setting("bundle_size", 20))}}


main()

# API arinox_production_card_save_production_card: create or update a DRAFT production card (validation runs). Never submits.
def main():
    data = frappe.form_dict.get("data")
    data = json.loads(data) if isinstance(data, str) else data
    if data.get("name") and frappe.db.exists("Production Card", data["name"]):
        doc = frappe.get_doc("Production Card", data["name"])
        if doc.docstatus != 0:
            frappe.throw("Only a draft production card can be changed here.")
        doc.check_permission("write")
        for k in data:
            if k not in ("name", "doctype", "docstatus"):
                doc.set(k, data[k])
    else:
        frappe.new_doc("Production Card").check_permission("create")
        d = dict(data)
        d["doctype"] = "Production Card"
        doc = frappe.get_doc(d)
    doc.save()
    frappe.flags.arinox_result = {"name": doc.name, "red_flags": doc.red_flags, "planned_cut_total": sum([frappe.utils.cint(r.planned_cut_qty) for r in doc.lines])}


main()

# API arinox_cost_sheet_get_costing_context: one call for the AI costing agent: the parameter that applies, its rates, the cost head library, and the most similar submitted costings.
def main():
    # shared helpers: cost heads, the costing parameter that applies, and the charge rows built from it (cost_sheet.py)
    def get_cost_heads():
        return frappe.get_all("Cost Head", filters={"enabled": 1}, fields=["name", "head_group", "calc_type", "material_scope", "sequence", "is_mandatory"], order_by="sequence asc")


    def find_costing_parameter(customer, product_type, on_date, currency):
        """Most specific enabled parameter valid on the date: customer+type > customer > type > generic."""
        on = frappe.utils.getdate(on_date or frappe.utils.nowdate())
        filters = {"enabled": 1, "effective_from": ["<=", on]}
        if currency:
            filters["currency"] = currency
        rows = frappe.get_all("Costing Parameter", filters=filters, fields=["name", "customer", "product_type", "effective_from", "effective_to"], order_by="effective_from desc")
        best = None
        best_score = -1
        for r in rows:
            if r.effective_to and frappe.utils.getdate(r.effective_to) < on:
                continue
            if r.customer and r.customer != customer:
                continue
            if r.product_type and r.product_type != product_type:
                continue
            score = (2 if r.customer else 0) + (1 if r.product_type else 0)
            if score > best_score:
                best = r.name
                best_score = score
        return best


    def charge_rows(param):
        """One charge row per enabled non-material cost head, with the parameter's rates."""
        rates = {}
        if param:
            for r in frappe.get_all("Costing Parameter Rate", filters={"parent": param, "parenttype": "Costing Parameter"}, fields=["cost_head", "rate", "not_applicable"]):
                rates[r.cost_head] = r
        out = []
        for head in get_cost_heads():
            if head.calc_type == "From Materials":
                continue
            r = rates.get(head.name)
            out.append({"cost_head": head.name, "calc_type": head.calc_type, "sequence": head.sequence, "head_group": head.head_group,
                        "rate": frappe.utils.flt(r.rate) if r else 0, "not_applicable": r.not_applicable if r else 0, "source": "Parameter" if r else "Manual"})
        return out
    customer = frappe.form_dict.get("customer")
    product_type = frappe.form_dict.get("product_type")
    style_no = frappe.form_dict.get("style_no")
    tech_pack = frappe.form_dict.get("tech_pack")
    frappe.new_doc("Cost Sheet").check_permission("read")
    if tech_pack:
        tp = frappe.get_doc("Tech Pack", tech_pack)
        tp.check_permission("read")
        product_type = product_type or tp.product_type
        style_no = style_no or tp.style_no
    param_name = find_costing_parameter(customer, product_type, frappe.utils.nowdate(), frappe.form_dict.get("currency"))
    param = frappe.get_doc("Costing Parameter", param_name).as_dict() if param_name else None
    filters = {"docstatus": 1, "customer": customer}
    if product_type:
        filters["product_type"] = product_type
    prev = frappe.get_all("Cost Sheet", filters=filters, order_by="costing_date desc", limit=20,
                          fields=["name", "style_no", "style_name", "costing_date", "currency", "material_cost", "subtotal", "quoted_price", "margin_pct", "order_qty", "revision_no"])
    for p in prev:
        p["agreed_price"] = frappe.db.get_value("Price Negotiation Style", {"cost_sheet": p.name, "style_status": "Agreed"}, "agreed_price")
        p["same_style"] = bool(style_no and p.style_no == style_no)
    prev = sorted(prev, key=lambda p: not p["same_style"])
    frappe.flags.arinox_result = {"costing_parameter": param, "margin_floor_pct": (param or {}).get("margin_floor_pct") or frappe.db.get_single_value("Apparel Settings", "default_margin_floor_pct"),
                                  "cost_heads": get_cost_heads(), "previous_costings": prev}


main()

# API arinox_ledger_rebuild_movements: recompute the ledger of one card from its submitted source documents (a repair tool; System Manager only). Answers the rows written.
# Each source document's rows are built here exactly as its own After Submit script builds them; the ledger is rewritten without the flow check.
def main():
    cint = frappe.utils.cint
    flt = frappe.utils.flt
    card = frappe.form_dict.get("card")
    roles = frappe.get_all("Role", pluck="name") if frappe.session.user == "Administrator" else frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
    if "System Manager" not in roles:
        frappe.throw("Only a System Manager can rebuild the ledger.")
    frappe.get_doc("Production Card", card).check_permission("read")
    for mv in frappe.get_all("Production Movement", filters={"production_card": card}, pluck="name"):
        frappe.delete_doc("Production Movement", mv, force=1, ignore_permissions=True)
    written = [0]

    def post(rows, dt, name, date):
        if not rows:
            return
        run_script("arinox_engine", action="post", card=card, rows=json.dumps(rows), source_doctype=dt, source_name=name, posting_date=str(date), override=0, check=0)
        written[0] = written[0] + len(rows)

    for n in frappe.get_all("Production Adjustment", filters={"production_card": card, "docstatus": 1}, pluck="name"):
        d = frappe.get_doc("Production Adjustment", n)
        post([{"stage": d.stage, "colour": d.colour, "size": d.size, "qty": flt(d.qty), "purpose": d.purpose or "Bulk", "process": d.subcontract_process, "source_row": d.name}], d.doctype, d.name, d.posting_date)
    for n in frappe.get_all("Lay Report", filters={"production_card": card, "docstatus": 1}, pluck="name"):
        d = frappe.get_doc("Lay Report", n)
        rows = []
        if d.component == "Shell":
            for s in d.sizes:
                rows.append({"stage": "CUT", "colour": d.colour, "size": s.size, "qty": cint(s.pieces_cut), "purpose": d.purpose, "shade_band": d.shade_band, "line": d.line, "source_row": s.name})
            for r in d.panel_rejects:
                rows.append({"stage": "CUT_REJECT", "colour": d.colour, "size": r.size, "qty": cint(r.qty), "purpose": d.purpose, "shade_band": d.shade_band, "fault_source": r.fault_source, "source_row": r.name})
        post(rows, d.doctype, d.name, d.lay_date)
    for n in frappe.get_all("Line Input", filters={"production_card": card, "docstatus": 1}, pluck="name"):
        d = frappe.get_doc("Line Input", n)
        post([{"stage": "SEW_IN", "colour": r.colour, "size": r.size, "qty": cint(r.qty), "purpose": d.purpose, "line": d.line, "shade_band": r.shade_band, "source_row": r.name}
              for r in d.bundles if (r.component or "Shell") == "Shell"], d.doctype, d.name, d.input_date)
    for n in frappe.db.sql("select distinct parent from `tabDaily Line Report Output` where production_card = %s", (card,), pluck=True):
        d = frappe.get_doc("Daily Line Report", n)
        if d.docstatus != 1:
            continue
        post([{"stage": "SEW_OUT", "colour": r.colour, "size": r.size, "qty": cint(r.qty), "purpose": r.purpose or "Bulk", "line": d.line, "source_row": r.name}
              for r in d.outputs if r.production_card == card], d.doctype, d.name, d.report_date)
    for n in frappe.get_all("Line QC Report", filters={"production_card": card, "docstatus": 1}, pluck="name"):
        d = frappe.get_doc("Line QC Report", n)
        rows = []
        if d.audit_type == "Finishing":
            for p in d.passes:
                rows.append({"stage": "FIN_A", "colour": p.colour, "size": p.size, "qty": cint(p.qty), "line": d.line, "source_row": p.name})
        for r in d.dispositions:
            stage = None
            if r.disposition == "Reject":
                stage = "FIN_REJECT" if d.audit_type == "Finishing" else "SEW_REJECT"
            elif r.disposition == "B-Grade":
                stage = "FIN_B"
            if stage:
                rows.append({"stage": stage, "colour": r.colour, "size": r.size, "qty": cint(r.qty), "line": d.line, "fault_source": r.fault_source, "source_row": r.name})
        post(rows, d.doctype, d.name, d.report_date)
    for n in frappe.get_all("Subcontract Challan", filters={"production_card": card, "docstatus": 1}, pluck="name"):
        d = frappe.get_doc("Subcontract Challan", n)
        post([{"stage": "SC_OUT", "colour": r.colour, "size": r.size, "qty": r.qty, "process": d.subcontract_process, "supplier": d.supplier, "shade_band": r.shade_band, "source_row": r.name}
              for r in d.rows], d.doctype, d.name, d.challan_date)
    for n in frappe.db.sql("select distinct parent from `tabSubcontract Return Row` where production_card = %s", (card,), pluck=True):
        d = frappe.get_doc("Subcontract Return", n)
        if d.docstatus != 1:
            continue
        rows = []
        for r in d.rows:
            base = {"colour": r.colour, "size": r.size, "process": d.subcontract_process, "supplier": d.supplier, "shade_band": r.shade_band, "source_row": r.name}
            if r.good_qty:
                x = dict(base)
                x.update({"stage": "SC_BACK_GOOD", "qty": r.good_qty})
                rows.append(x)
            if r.reject_vendor_qty:
                x = dict(base)
                x.update({"stage": "SC_BACK_REJECT_VENDOR", "qty": r.reject_vendor_qty, "fault_source": "Subcontractor"})
                rows.append(x)
            if r.reject_factory_qty:
                x = dict(base)
                x.update({"stage": "SC_BACK_REJECT_FACTORY", "qty": r.reject_factory_qty, "fault_source": (frappe.db.get_value("Apparel Defect Code", r.defect_code, "fault_source") if r.defect_code else None) or "Unknown"})
                rows.append(x)
        post(rows, d.doctype, d.name, d.return_date)
    for n in frappe.get_all("Finishing Receipt", filters={"production_card": card, "docstatus": 1}, pluck="name"):
        d = frappe.get_doc("Finishing Receipt", n)
        post([{"stage": "FIN_IN", "colour": r.colour, "size": r.size, "qty": r.qty, "line": d.line, "supplier": d.supplier, "shade_band": r.shade_band, "source_row": r.name} for r in d.rows],
             d.doctype, d.name, d.receipt_date)
    for n in frappe.get_all("Packing List", filters={"production_card": card, "docstatus": 1}, pluck="name"):
        d = frappe.get_doc("Packing List", n)
        sums = {}
        order = []
        for ct in d.contents:
            k = ct.colour + "\t" + ct.size
            if k not in sums:
                sums[k] = 0
                order.append(k)
            sums[k] = sums[k] + cint(ct.pieces_total)
        post([{"stage": "PACKED", "colour": k.split("\t")[0], "size": k.split("\t")[1], "qty": sums[k]} for k in order], d.doctype, d.name, d.packing_date)
    # Delivery Notes are ERPNext documents: their rows carry the card
    for n in frappe.db.sql("select distinct parent from `tabDelivery Note Item` where apparel_production_card = %s and docstatus = 1", (card,), pluck=True):
        d = frappe.get_doc("Delivery Note", n)
        sums = {}
        order = []
        for it in d.items:
            if it.get("apparel_production_card") != card or not it.get("so_detail"):
                continue
            cs = frappe.db.get_value("Sales Order Item", it.so_detail, ["apparel_colour", "apparel_size"])
            k = cs[0] + "\t" + cs[1]
            if k not in sums:
                sums[k] = 0
                order.append(k)
            sums[k] = sums[k] + cint(it.stock_qty or it.qty)
        post([{"stage": "SHIPPED", "colour": k.split("\t")[0], "size": k.split("\t")[1], "qty": sums[k]} for k in order], d.doctype, d.name, d.posting_date)
    frappe.flags.arinox_result = written[0]


main()
